typedef struct {
    char mac_entity_id[18];
    char *supported_protocols;
    int *vlan_tags;
    int vlan_count;
} MacConfig;

MacConfig* create_mac_config(char *mac_entity_id, char *protocols[], int vlan_tags[], int vlan_count) {
    MacConfig *config = (MacConfig*)malloc(sizeof(MacConfig));
    strncpy(config->mac_entity_id, mac_entity_id, 18);
    config->supported_protocols = (char*)malloc(strlen(protocols[0]) + 1);
    strcpy(config->supported_protocols, protocols[0]);
    config->vlan_tags = (int*)malloc(vlan_count * sizeof(int));
    memcpy(config->vlan_tags, vlan_tags, vlan_count * sizeof(int));
    config->vlan_count = vlan_count;
    return config;
}

void free_mac_config(MacConfig *config) {
    free(config->supported_protocols);
    free(config->vlan_tags);
    free(config);
}

typedef struct {
    MacConfig **configs;
    int count;
    pthread_mutex_t lock;
} MacConfigManager;

MacConfigManager* init_mac_config_manager() {
    MacConfigManager *manager = (MacConfigManager*)malloc(sizeof(MacConfigManager));
    manager->configs = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void add_mac_config(MacConfigManager *manager, MacConfig *config) {
    pthread_mutex_lock(&manager->lock);
    manager->configs = realloc(manager->configs, (manager->count + 1) * sizeof(MacConfig*));
    manager->configs[manager->count] = config;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
}

MacConfig* get_mac_config_by_id(MacConfigManager *manager, char *mac_entity_id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (strcmp(manager->configs[i]->mac_entity_id, mac_entity_id) == 0) {
            MacConfig *config = manager->configs[i];
            pthread_mutex_unlock(&manager->lock);
            return config;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void update_mac_config(MacConfigManager *manager, char *mac_entity_id, MacConfig *new_config) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (strcmp(manager->configs[i]->mac_entity_id, mac_entity_id) == 0) {
            free_mac_config(manager->configs[i]);
            manager->configs[i] = new_config;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void sync_configs_with_service(MacConfigManager *manager, char *service_url) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");

        // Prepare JSON payload for API call
        char json_payload[1024];
        snprintf(json_payload, sizeof(json_payload), "{\"configs\": [");
        for (int i = 0; i < manager->count; i++) {
            if (i > 0) snprintf(json_payload + strlen(json_payload), sizeof(json_payload) - strlen(json_payload), ", ");
            snprintf(json_payload + strlen(json_payload), sizeof(json_payload) - strlen(json_payload), "{\"mac_entity_id\": \"%s\", \"supported_protocols\": \"%s\", \"vlan_tags\": [%d]}",
                     manager->configs[i]->mac_entity_id,
                     manager->configs[i]->supported_protocols,
                     manager->configs[i]->vlan_tags[0]);
        }
        snprintf(json_payload + strlen(json_payload), sizeof(json_payload) - strlen(json_payload), "]}");

        curl_easy_setopt(curl, CURLOPT_URL, service_url);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);

        res = curl_easy_perform(curl);

        // Check for errors
        if(res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
}

void free_mac_config_manager(MacConfigManager *manager) {
    for (int i = 0; i < manager->count; i++) {
        free_mac_config(manager->configs[i]);
    }
    free(manager->configs);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
