#define MAX_RECORDS 10000000

typedef struct {
    int value;
    char* metadata;
} Record;

Record** records;
long* offsets;
int* keys;
size_t size;

void init_records(size_t num_records) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Error: Number of records exceeds maximum limit.\n");
        exit(EXIT_FAILURE);
    }

    records = malloc(num_records * sizeof(Record*));
    offsets = malloc(num_records * sizeof(long));
    keys = malloc(num_records * sizeof(int));

    if (!records || !offsets || !keys) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    size = num_records;
}

void init_record(Record* record, int value, const char* metadata) {
    record->value = value;
    if (metadata) {
        record->metadata = strdup(metadata);
    } else {
        record->metadata = NULL;
    }
}

void generate_random_records(size_t start_index, size_t end_index, int min_value, int max_value) {
    for (size_t i = start_index; i < end_index; ++i) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }
        generate_random_int(&records[i]->value, min_value, max_value);
        records[i]->metadata = NULL;
    }
}

void free_records() {
    for (size_t i = 0; i < size; ++i) {
        if (records[i]) {
            free(records[i]);
            records[i] = NULL;
        }
    }

    free(records);
    records = NULL;

    free(offsets);
    offsets = NULL;

    free(keys);
    keys = NULL;
}

void generate_random_int(int* value, int min_value, int max_value) {
    if (!RAND_bytes((unsigned char*)value, sizeof(*value))) {
        fprintf(stderr, "Error: Failed to generate random number.\n");
        exit(EXIT_FAILURE);
    }

    *value = (int)(*value % (max_value - min_value + 1)) + min_value;
}

void log_operation(const char* operation, const char* details) {
    time_t now = time(NULL);
    printf("[%s] Operation: %s, Details: %s\n", ctime(&now), operation, details);
}

int main() {
    size_t num_records = 10000000;
    int min_value = 1;
    int max_value = 100;

    init_records(num_records);

    generate_random_records(0, num_records, min_value, max_value);

    for (size_t i = 0; i < num_records; ++i) {
        log_operation("Record Initialized", records[i]->metadata ? records[i]->metadata : "NULL");
    }

    free_records();

    return 0;
}
