#define MAX_FILE_PATH 256
#define BUFFER_SIZE 1024

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
} IntList;

IntList *int_list_init(size_t initial_capacity) {
    IntList *list = malloc(sizeof(IntList));
    if (list == NULL) return NULL;
    list->data = malloc(initial_capacity * sizeof(int));
    if (list->data == NULL) {
        free(list);
        return NULL;
    }
    list->size = 0;
    list->capacity = initial_capacity;
    return list;
}

void int_list_append(IntList *list, int value) {
    if (list->size >= list->capacity) {
        list->capacity *= 2;
        list->data = realloc(list->data, list->capacity * sizeof(int));
        if (list->data == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
    }
    list->data[list->size++] = value;
}

void int_list_free(IntList *list) {
    free(list->data);
    free(list);
}

void* file_reader_thread(void *arg) {
    IntList **list_ptr = (IntList **)arg;
    IntList *list = *list_ptr;

    FILE *file = fopen("large_file.txt", "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, file)) {
        int value = atoi(buffer);
        if (value > INT_MAX || value < INT_MIN) {
            fprintf(stderr, "Integer overflow detected\n");
            exit(EXIT_FAILURE);
        }
        int_list_append(list, value);
    }

    fclose(file);
    return NULL;
}

