    if (!list) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    pthread_t file_reader_tid, api_fetcher_tid;

    if (pthread_create(&file_reader_tid, NULL, file_reader_thread, &list) != 0) {
        perror("Failed to create file reader thread");
        int_list_free(list);
        return EXIT_FAILURE;
    }
    if (pthread_create(&api_fetcher_tid, NULL, api_fetcher_thread, NULL) != 0) {
        perror("Failed to create API fetcher thread");
