['```python
import json
import threading
import logging
from datetime import datetime
import requests
from abc import ABC, abstractmethod

# Configuration Schema for validation
config_schema = {
    "type": "object",
    "properties": {
        "environment": {"type": "string"},
        "variables": {"type": "object", "additionalProperties": {"type": "string"}}
    },
    "required": ["environment", "variables"]
}

# Logger setup
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class ConfigManager(ABC):
    @abstractmethod
    def load_config(self, environment: str) -> dict:
        pass

    @abstractmethod
    def update_config(self, new_config: dict) -> None:
        pass

    @abstractmethod
    def save_config(self) -> None:
        pass

class LocalConfigManager(ConfigManager):
    def __init__(self, config_path: str):
        self.config_path = config_path
        self.lock = threading.Lock()

    def load_config(self, environment: str) -> dict:
        with open(self.config_path, 'r') as file:
            config_data = json.load(file)
        return next((item for item in config_data if item['environment'] == environment), None)

    def update_config(self, new_config: dict) -> None:
        with self.lock:
            with open(self.config_path, 'r') as file:
                config_data = json.load(file)
            for item in config_data:
                if item['environment'] == new_config['environment']:
                    item.update(new_config)
                    break
            else:
                config_data.append(new_config)
            with open(self.config_path, 'w') as file:
                json.dump(config_data, file, indent=4)

    def save_config(self) -> None:
        pass  # No action needed for local storage

class RemoteConfigManager(ConfigManager):
    def __init__(self, api_url: str, lock_manager):
        self.api_url = api_url
        self.lock_manager = lock_manager

    def load_config(self, environment: str) -> dict:
        response = requests.get(f"{self.api_url}/{environment}")
        if response.status_code == 200:
            return response.json()
        else:
            logger.error(f"Failed to fetch config for {environment}: {response.status_code}")
            return None

    def update_config(self, new_config: dict) -> None:
        with self.lock_manager.lock:
            response = requests.put(f"{self.api_url}/{new_config['environment']}", json=new_config)
            if response.status_code != 204:
                logger.error(f"Failed to update config for {new_config['environment']}: {response.status_code}")

class ConfigLockManager:
    def __init__(self):
        self.lock = threading.Lock()

    def acquire_lock(self) -> None:
        self.lock.acquire()

    def release_lock(self) -> None:
        self.lock.release()

# Example usage
def main():
    lock_manager = ConfigLockManager()
    config_manager = RemoteConfigManager("http://example.com/api/config", lock_manager)

    # Load and update configuration
    current_config = config_manager.load_config("production")
    if current_config:
        new_config = {
            "environment": "production",
            "variables": {"new_variable": "new_value"}
        }
        config_manager.update_config(new_config)

    # Log the updated configuration
    logger.info(f"Updated Configuration: {config_manager.load_config('production')}")

if __name__ == "__main__":
    main()
```

This code provides a basic framework for managing configurations in a distributed web application. It includes classes for loading, updating, and saving configurations locally or remotely, along with a lock manager to handle concurrency. The example usage demonstrates how to load and update a configuration, ensuring thread safety during the process.']

