#include <openssl/evp.h>
#include <openssl/rand.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_KEY_LENGTH 32
#define MAX_IV_LENGTH 16

typedef struct {
    EVP_CIPHER_CTX *ctx;
    int cipher_type;
} EncryptionContext;

int init_encryption_context(EncryptionContext *ctx, const char *algorithm, int mode) {
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) return -1;

    if (mode == 0) { // Encrypt
        if (!EVP_EncryptInit_ex(ctx->ctx, EVP_get_cipherbyname(algorithm), NULL, NULL, NULL)) {
            EVP_CIPHER_CTX_free(ctx->ctx);
            return -1;
        }
    } else { // Decrypt
        if (!EVP_DecryptInit_ex(ctx->ctx, EVP_get_cipherbyname(algorithm), NULL, NULL, NULL)) {
            EVP_CIPHER_CTX_free(ctx->ctx);
            return -1;
        }
    }

    ctx->cipher_type = mode;
    return 0;
}

int encrypt_data(EncryptionContext *ctx, unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    if (ctx->cipher_type != 0) return -1; // Check for encryption mode

    int len, ciphertext_len;
    if (!EVP_EncryptUpdate(ctx->ctx, ciphertext, &len, plaintext, plaintext_len)) return -1;
    ciphertext_len = len;

    if (!EVP_EncryptFinal_ex(ctx->ctx, ciphertext + len, &len)) return -1;
    ciphertext_len += len;

    return ciphertext_len;
}

int decrypt_data(EncryptionContext *ctx, unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    if (ctx->cipher_type != 1) return -1; // Check for decryption mode

    int len, plaintext_len;
    if (!EVP_DecryptUpdate(ctx->ctx, plaintext, &len, ciphertext, ciphertext_len)) return -1;
    plaintext_len = len;

    if (!EVP_DecryptFinal_ex(ctx->ctx, plaintext + len, &len)) return -1;
    plaintext_len += len;

    return plaintext_len;
}

void cleanup_encryption_context(EncryptionContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
}

int main() {
    EncryptionContext ctx;
    unsigned char key[MAX_KEY_LENGTH], iv[MAX_IV_LENGTH];
    unsigned char plaintext[] = "This is a secret message";
    unsigned char ciphertext[128];
    int ciphertext_len, decrypted_text_len, decrypted_text[128];

    // Initialize encryption context with AES-256-CBC
    if (init_encryption_context(&ctx, "aes-256-cbc", 0) != 0) {
        fprintf(stderr, "Failed to initialize encryption context.\n");
        return 1;
    }

    // Generate random key and IV
    if (!RAND_bytes(key, sizeof(key)) || !RAND_bytes(iv, sizeof(iv))) {
        fprintf(stderr, "Failed to generate random bytes.\n");
        cleanup_encryption_context(&ctx);
        return 1;
    }

    // Encrypt data
    ciphertext_len = encrypt_data(&ctx, plaintext, strlen((char *)plaintext), ciphertext);
    if (ciphertext_len < 0) {
        fprintf(stderr, "Encryption failed.\n");
        cleanup_encryption_context(&ctx);
        return 1;
    }

    // Decrypt data
    decrypted_text_len = decrypt_data(&ctx, ciphertext, ciphertext_len, (unsigned char *)decrypted_text);
    if (decrypted_text_len < 0) {
        fprintf(stderr, "Decryption failed.\n");
        cleanup_encryption_context(&ctx);
        return 1;
    }

    // Clean up
    cleanup_encryption_context(&ctx);

    // Output results
    printf("Encrypted: %.*s\n", ciphertext_len, ciphertext);
    printf("Decrypted: %.*s\n", decrypted_text_len, (char *)decrypted_text);

    return 0;
}
