#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

// Define semaphore structure
typedef struct {
    sem_t *mutex;
    int available_permits;
} Semaphore;

// Initialize semaphore from configuration
Semaphore* init_semaphore(int initial_value) {
    Semaphore *sem = (Semaphore*)malloc(sizeof(Semaphore));
    if (!sem) return NULL;

    sem->mutex = (sem_t*)malloc(sizeof(sem_t));
    if (!sem->mutex) {
        free(sem);
        return NULL;
    }

    if (sem_init(sem->mutex, 0, 1) != 0) { // Initialize mutex to protect semaphore state
        free(sem->mutex);
        free(sem);
        return NULL;
    }

    sem->available_permits = initial_value;
    return sem;
}

// Destroy the semaphore
void destroy_semaphore(Semaphore *sem) {
    if (sem) {
        sem_destroy(sem->mutex);
        free(sem->mutex);
        free(sem);
    }
}

// Wait on the semaphore
int semaphore_wait(Semaphore *sem) {
    pthread_mutex_lock(sem->mutex); // Lock to ensure atomicity
    while (sem->available_permits == 0) {
        pthread_cond_wait(sem->cond, sem->mutex); // Block until available permits
    }
    sem->available_permits--;
    pthread_mutex_unlock(sem->mutex);
    return 0;
}

// Signal the semaphore
int semaphore_signal(Semaphore *sem) {
    pthread_mutex_lock(sem->mutex); // Lock to ensure atomicity
    sem->available_permits++;
    pthread_cond_signal(sem->cond); // Unblock one waiting thread
    pthread_mutex_unlock(sem->mutex);
    return 0;
}
```

