#include <thread>
#include <mutex>
#include <future>
#include <stdexcept>

class RandomService {
public:
    RandomService() : rng(std::random_device{}()) {}

    int generateRandomInt(int min, int max) {
        std::lock_guard<std::mutex> lock(mutex_);
        return std::uniform_int_distribution<>(min, max)(rng);
    }

    double generateRandomDouble(double min, double max) {
        std::lock_guard<std::mutex> lock(mutex_);
        return std::uniform_real_distribution<>(min, max)(rng);
    }

    double generateGaussian(double mean = 0.0, double stddev = 1.0) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::normal_distribution<> dist(mean, stddev);
        return dist(rng);
    }

private:
    std::mt19937 rng;
    std::mutex mutex_;
};

int main() {
    RandomService rs;

    // Example usage
    int randomInt = rs.generateRandomInt(1, 100);
    double randomDouble = rs.generateRandomDouble(0.0, 1.0);
    double gaussianNumber = rs.generateGaussian();

    std::cout << "Random Int: " << randomInt << std::endl;
    std::cout << "Random Double: " << randomDouble << std::endl;
    std::cout << "Gaussian Number: " << gaussianNumber << std::endl;

    return 0;
}
