using System;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class DatabaseManager
{
    public IDataReader ExecuteSqlCommandAsync(string connectionString, string sqlCommand, List<SqlParameter> parameters, Action<IDataReader> resultCallback)
    {
        // Validate input parameters
        if (string.IsNullOrEmpty(connectionString) || string.IsNullOrEmpty(sqlCommand) || parameters == null || resultCallback == null)
        {
            return null;
        }

        try
        {
            using (SqlConnection connection = new SqlConnection(connectionString))
            {
                SqlCommand command = new SqlCommand(sqlCommand, connection);
                command.Parameters.AddRange(parameters.ToArray());

                connection.Open();
                IDataReader reader = command.ExecuteReader();

                Task.Run(() => resultCallback(reader));

                return reader;
            }
        }
