public interface IDatabaseConnectionPoolManager
{
    Task<DbConnection> GetConnectionAsync(string connectionString);
    void ReturnConnection(DbConnection connection);
}

public class DatabaseConnectionPoolManager : IDatabaseConnectionPoolManager
{
    private readonly Dictionary<string, Queue<DbConnection>> _poolDictionary = new Dictionary<string, Queue<DbConnection>>();
    private readonly Dictionary<string, object> _syncObjects = new Dictionary<string, object>();
    private readonly ExternalMonitoringApi _monitoringApi;

    public DatabaseConnectionPoolManager(ExternalMonitoringApi monitoringApi)
    {
        _monitoringApi = monitoringApi;
    }

    public async Task<DbConnection> GetConnectionAsync(string connectionString)
    {
        lock (_syncObjects.GetOrAdd(connectionString, _ => new object()))
        {
            if (!_poolDictionary.ContainsKey(connectionString))
                _poolDictionary[connectionString] = new Queue<DbConnection>();

            var pool = _poolDictionary[connectionString];
            if (pool.Count > 0)
                return pool.Dequeue();
        }

        try
        {
            var connection = CreateNewConnection(connectionString);
            await MonitorConnectionHealth(connection, connectionString);
            return connection;
        }
        catch (Exception ex)
        {
            LogError(ex);
            throw;
        }
    }

    public void ReturnConnection(DbConnection connection)
    {
        lock (_syncObjects.GetOrAdd(connection.ConnectionString, _ => new object()))
        {
            var pool = _poolDictionary[connection.ConnectionString];
            if (ShouldReturnToPool(connection))
                pool.Enqueue(connection);
        }
    }

