using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using System.Xml.XPath;

public class XmlService
{
    private readonly HttpClient _httpClient;
    private readonly XPathNavigator _schemaNavigator;
    private readonly Dictionary<string, XPathNavigator> _cache;
    private readonly int _maxCacheSize;
    private readonly TimeSpan _cacheExpirationTime;

    public XmlService(HttpClient httpClient, string schemaXml, int maxCacheSize = 1000, int cacheExpirationMinutes = 60)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _schemaNavigator = XPathDocument.Parse(schemaXml).CreateNavigator();
        _cache = new Dictionary<string, XPathNavigator>();
        _maxCacheSize = maxCacheSize;
        _cacheExpirationTime = TimeSpan.FromMinutes(cacheExpirationMinutes);
    }

    public async Task<XPathNavigator> GetFirstElementAsync(string url, string xpathExpression)
    {
        var xml = await FetchXmlAsync(url);
        return ParseXml(xml, xpathExpression);
    }

    private async Task<string> FetchXmlAsync(string url)
    {
        using (var response = await _httpClient.GetAsync(url, HttpCompletionOption.ResponseHeadersRead))
        {
            response.EnsureSuccessStatusCode();
            response.Content.Headers.TryGetValues("Content-Type", out var contentTypes);
            if (contentTypes == null || !contentTypes.Contains("application/xml"))
                throw new InvalidOperationException("Response is not in expected format.");

            return await response.Content.ReadAsStringAsync();
        }
    }

    private XPathNavigator ParseXml(string xml, string xpathExpression)
    {
        if (_cache.TryGetValue(xml, out var cachedNavigator))
        {
            return cachedNavigator;
        }

        var navigator = XPathDocument.Parse(xml).CreateNavigator();

        if (!navigator.SelectSingleNode(xpathExpression, _schemaNavigator) == null)
        {
            EnsureCacheSize();
            _cache[xml] = navigator.Clone();
        }

        return navigator.SelectSingleNode(xpathExpression, _schemaNavigator);
    }

    private void EnsureCacheSize()
    {
        if (_cache.Count >= _maxCacheSize)
        {
            var oldestEntry = _cache.FirstOrDefault(kvp => kvp.Value.GetLastAccessTimeUtc() == _cache.Values.Min(n => n.GetLastAccessTimeUtc()));
            _cache.Remove(oldestEntry.Key);
        }
    }
}
