use Slim\Factory\AppFactory;
use Monolog\Logger;
use Monolog\Handler\StreamHandler;

require __DIR__ . '/vendor/autoload.php';

$app = AppFactory::create();

// Configure Monolog
$log = new Logger('main');
$log->pushHandler(new StreamHandler(__DIR__ . '/logs/app.log', Logger::DEBUG));

// Middleware for logging requests
$app->add(function (Request $request, Response $response, callable $next) use ($log) {
    $log->info("Received request: " . $request->getMethod() . ' ' . $request->getUri());
    return $next($request, $response);
});

// Middleware for validating inputs
$app->add(function (Request $request, Response $response, callable $next) {
    $data = json_decode($request->getBody(), true);
    if (!isset($data['name']) || !isset($data['email']) || !isset($data['password'])) {
        return $response->withJson(['status' => 'error', 'message' => 'Missing required fields'], 400);
    }
    if (filter_var($data['email'], FILTER_VALIDATE_EMAIL) === false) {
        return $response->withJson(['status' => 'error', 'message' => 'Invalid email'], 400);
    }
    return $next($request, $response);
});

// Route for creating or updating user profiles
$app->post('/user', function (Request $request, Response $response) {
    $data = json_decode($request->getBody(), true);
    $action = isset($data['action']) ? $data['action'] : 'create';

    if ($action === 'delete') {
        // Delete user logic here
        $log->info("User deleted: ID " . $data['id']);
        return $response->withJson(['status' => 'success'], 200);
    } else {
        // Create or update user logic here
        $log->info("User " . ($data['id'] ? 'updated' : 'created') . ": ID " . $data['id']);
        return $response->withJson(['status' => 'success'], 201);
    }
});

$app->run();
