struct SensorData {
    // Define data structure for sensor data here
};

class SensorDataProcessor {
private:
    std::queue<SensorData> dataQueue;
    std::mutex queueMutex;
    std::condition_variable condVar;
    bool running;

public:
    SensorDataProcessor() : running(true) {}

    void startProcessing() {
        std::thread([this]() {
            while (running) {
                std::unique_lock<std::mutex> lock(queueMutex);
                condVar.wait(lock, [this] { return !dataQueue.empty() || !running; });
                if (!dataQueue.empty()) {
                    SensorData data = dataQueue.front();
                    dataQueue.pop();
                    lock.unlock();

                    // Process sensor data here
                    std::cout << "Processing data: " << data /* or other relevant details */ << std::endl;
                }
            }
        }).detach();
    }

    void addData(const SensorData& data) {
        std::lock_guard<std::mutex> lock(queueMutex);
        dataQueue.push(data);
        condVar.notify_one();
    }

    void stopProcessing() {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            running = false;
        }
        condVar.notify_all();
    }
};

