const fs = require('fs').promises;
const path = require('path');
const axios = require('axios');

// Constants
const API_URL = 'https://api.example.com/validate';
const MAX_CONCURRENCY = 5;
const RETRY_LIMIT = 3;

// Caching mechanism for API results
const apiCache = new Map();

async function fetchApi(url, data) {
    if (apiCache.has(data)) {
        return apiCache.get(data);
    }

    let retries = RETRY_LIMIT;
    while (retries > 0) {
        try {
            const response = await axios.post(url, data);
            apiCache.set(data, response.data);
            return response.data;
        } catch (error) {
            if (axios.isAxiosError(error)) {
                console.error(`API error: ${error.response.status} - ${error.response.statusText}`);
            }
            retries--;
            if (retries === 0) {
                throw new Error('API request failed after multiple attempts');
            }
        }
    }
}

async function processFile(filePath) {
    try {
        const fileContent = await fs.readFile(filePath, 'utf8');
        const data = JSON.parse(fileContent);

        // Validate data with external API
        const validationResult = await fetchApi(API_URL, data);
        if (!validationResult.valid) {
            throw new Error(`Validation failed: ${JSON.stringify(validationResult.errors)}`);
        }

        // Transform data to standardized schema
        const transformedData = transformData(data);

        return transformedData;
    } catch (error) {
        console.error(`Error processing file ${filePath}:`, error);
        return null;
    }
}

function transformData(data) {
    // Implement your data transformation logic here
    // Fallback strategies for unknown or unsupported formats
    return data; // Placeholder
}

async function processFilesInDirectory(directoryPath) {
    const files = await fs.readdir(directoryPath);
    const filePaths = files.map(file => path.join(directoryPath, file));

    const promises = [];
    const semaphore = new Semaphore(MAX_CONCURRENCY);

    for (const filePath of filePaths) {
        semaphore.acquire();
        promises.push(processFile(filePath).then(() => semaphore.release()));
    }

    await Promise.all(promises);
}

class Semaphore {
    constructor(maxConcurrent) {
        this.maxConcurrent = maxConcurrent;
        this.count = 0;
        this.queue = [];
    }

    async acquire() {
        while (this.count >= this.maxConcurrent) {
            await new Promise(resolve => this.queue.push(resolve));
        }
        this.count++;
    }

    release() {
        if (this.queue.length > 0) {
            const resolve = this.queue.shift();
            resolve();
        } else {
            this.count--;
        }
    }
}

// Example usage
(async () => {
    try {
        await processFilesInDirectory('/path/to/json/files');
    } catch (error) {
        console.error('Error processing files:', error);
    }
})();
