async function getLibraryVersion(libraryName) {
  try {
    const response = await axios.get(`https://api.example.com/versions?library=${libraryName}`, {
      headers: { 'Authorization': `Bearer ${API_KEY}` }
    });
    return response.data.version;
  } catch (error) {
