    return null;
  }
}

// Function to process incoming data and count library mentions
async function processText(data) {
  const matches = _.flatten(_.map(REGEX_CONFIG, regex => data.match(regex)));
  const libraryCounts = _.countBy(matches);

  for (const [libraryName, count] of Object.entries(libraryCounts)) {
    redisClient.setex(`version:${libraryName}`, 3600, await getLibraryVersion(libraryName));
  }

  return libraryCounts;
}

