  let minifiedHtml = '';

  const scriptPromises = scriptObjects.map(async (script) => {
    if (!isValidScript(script)) {
      console.error('Invalid script object:', script);
      return;
    }

    try {
      await loadScript(script);
      concurrentScripts--;
      updateMinificationMetric();

      return `<script type="${script.type}">${script.code}</script>`;
    } catch (error) {
      console.error('Failed to load script:', error);
      return '';
    }
