  while (concurrentScripts < MAX_CONCURRENT_SCRIPTS && scriptPromises.length > 0) {
    const scriptPromise = scriptPromises.shift();
    concurrentScripts++;

    minifiedHtml += await scriptPromise;
  }

  return Promise.all(scriptPromises)
    .then(results => results.join(''))
    .then(html => {
      if (html.length >= MINIFY_THRESHOLD) {
        return minifyHTML(html);
      }
      return html;
    });
}

