// Define AngularJS module
angular.module('refreshServiceModule', [])
    .factory('RefreshService', function ($http, $q, $log) {
        const cache = {};
        const bookRegex = /\b(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Ruth|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Isaiahu|Jeremiah|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\b/gi;

        function fetchData(url, resourceId) {
            return $http.get(url)
                .then(response => {
                    cache[resourceId] = response.data;
                    return response.data;
                })
                .catch(error => {
                    $log.error(`Failed to fetch data for resource ${resourceId}:`, error);
                    throw error;
                });
        }

        function refreshFields(fieldIds, urls) {
            const promises = fieldIds.map((fieldId, index) => {
                const resourceId = fieldId.replace('field-', '');
                const url = urls[resourceId];
                if (cache[resourceId]) {
                    return $q.resolve(cache[resourceId]);
                } else {
                    return fetchData(url, resourceId);
                }
            });

            return $q.all(promises)
                .then(results => {
                    fieldIds.forEach((fieldId, index) => {
                        const fieldValue = results[index];
                        $(`#${fieldId}`).text(fieldValue);
                    });
                })
                .catch(error => {
                    $log.error('Failed to refresh fields:', error);
                    throw error;
                });
        }

        function extractBooks(text) {
            return text.match(bookRegex) || [];
        }

        function countBooks(text) {
            const books = extractBooks(text);
            const bookCounts = {};
            books.forEach(book => {
                bookCounts[book] = (bookCounts[book] || 0) + 1;
            });
            return bookCounts;
        }

        return {
            refreshFields: refreshFields,
            countBooks: countBooks
        };
    });

// Example usage in controller
angular.module('appControllerModule', ['refreshServiceModule'])
    .controller('AppController', function ($scope, RefreshService) {
        $scope.refreshFields = function () {
            const fieldIds = ['field-1', 'field-2', 'field-3']; // Example IDs
            const urls = {
                '1': '/api/resource1',
                '2': '/api/resource2',
                '3': '/api/resource3'
            };
            RefreshService.refreshFields(fieldIds, urls)
                .then(() => $log.info('Refresh successful'))
                .catch(error => $log.error('Failed to refresh fields', error));
        };

        $scope.extractAndCountBooks = function (text) {
            const bookCounts = RefreshService.countBooks(text);
            console.log(bookCounts);
        };
    });
