    let retryCount = 0;

    async function fetchEvents() {
        try {
            const response = await axios.get(API_URL);
            return response.data.events;
        } catch (error) {
            if (error.response) {
                // Handle HTTP errors here
            } else if (error.request) {
                // Handle network request errors here
            } else {
                // Handle unexpected errors here
            }
            throw error;
        }
    }

    async function processEvents(events) {
        for (const event of events) {
            // Process each event
            eventCache.set(event.id, event);
        }
    }

    function handleNetworkDisruption() {
        retryCount++;
        const delay = Math.pow(2, retryCount) * 100; // Exponential backoff
        setTimeout(fetchEvents, delay);
    }

    async function mainLoop() {
        while (!paused) {
            try {
                const events = await fetchEvents();
                await processEvents(events);
                retryCount = 0;
            } catch (error) {
                handleNetworkDisruption();
            }
        }
    }

    // Initialize default theme directory
    initDefaultThemeDir();

    // Parse PNG file from cache root
    parsePngFileFromCache(PNG_FILE_PATH);

    return mainLoop;
}

