#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <json-c/json.h>

typedef struct {
    CURL *handle;
    char *data;
    size_t size;
} CurlData;

size_t curlWriteCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    CurlData *mem = (CurlData *)userp;

    mem->data = realloc(mem->data, mem->size + realsize + 1);
    if (mem->data == NULL) {
        fprintf(stderr, "Failed to allocate memory for data\n");
        return 0;
    }
    memcpy(&(mem->data[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->data[mem->size] = 0;

    return realsize;
}

int loadResourceBundleAndCopyData(const char *url, size_t chunkSize, void **buffer, size_t *numItems) {
    CURL *curl;
    CURLcode res;
    CurlData data;

    memset(&data, 0, sizeof(CurlData));
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, curlWriteCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &data);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            curl_easy_cleanup(curl);
            curl_global_cleanup();
            return -1;
        }

        json_object *json_obj = json_tokener_parse(data.data);
        if (!json_obj) {
            fprintf(stderr, "Invalid JSON format\n");
            free(data.data);
            curl_easy_cleanup(curl);
            curl_global_cleanup();
            return -2;
        }

        *numItems = json_object_array_length(json_obj);
        *buffer = malloc(chunkSize * (*numItems));
        if (*buffer == NULL) {
            fprintf(stderr, "Failed to allocate memory for buffer\n");
            json_object_put(json_obj);
            free(data.data);
            curl_easy_cleanup(curl);
            curl_global_cleanup();
            return -3;
        }

        for (size_t i = 0; i < *numItems; i++) {
            json_object *item = json_object_array_get_idx(json_obj, i);
            // Copy data from item to buffer
            memcpy((*buffer) + (i * chunkSize), json_object_get_string(item), chunkSize);
        }

        json_object_put(json_obj);
        free(data.data);
        curl_easy_cleanup(curl);
        curl_global_cleanup();
    } else {
        fprintf(stderr, "Failed to initialize libcurl\n");
        return -4;
    }

    return 0;
}
