        this.modules = {};
        this.moduleCache = new Map();
    }

    async loadModule(modulePath) {
        if (!this.moduleCache.has(modulePath)) {
            const module = await import(modulePath);
            this.moduleCache.set(modulePath, module.default || module);
        }
        return this.moduleCache.get(modulePath);
    }

    getModule(moduleName) {
        return this.modules[moduleName];
    }
}

// configManager.js
class ConfigManager {
    constructor(moduleCache, refreshInterval) {
        this.moduleCache = moduleCache;
        this.refreshInterval = refreshInterval;
        this.config = {};
    }

    async updateConfig(newConfig) {
        Object.assign(this.config, newConfig);

        for (const moduleName in this.config.reloadOnChange) {
            const modulesToReload = this.config.reloadOnChange[moduleName];
            for (const module of modulesToReload) {
                await this.moduleCache.loadModule(module);
            }
        }

        // Notify modules about config changes
        for (const moduleName in this.modules) {
            if (this.modules[moduleName].onConfigUpdate) {
                this.modules[moduleName].onConfigUpdate(this.config);
            }
        }
    }

    onModuleLoaded(moduleName, moduleInstance) {
        this.modules[moduleName] = moduleInstance;
        if (moduleInstance.onConfigChange) {
            moduleInstance.onConfigChange = (newConfig) => {
                this.updateConfig(newConfig);
            };
        }
    }
}

