from typing import Dict, Optional
import requests
from functools import lru_cache, wraps
from time import sleep
from datetime import datetime

# Define a decorator for implementing exponential backoff with retries
def retry_with_exponential_backoff(max_retries: int, initial_delay: float):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            delay = initial_delay
            for attempt in range(max_retries + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempt == max_retries:
                        raise
                    sleep(delay)
                    delay *= 2
        return wrapper
    return decorator

# Define a class for the token management system
class TokenManager:
    def __init__(self, idp_urls: Dict[str, str], cache_size: int = 100):
        self.idp_urls = idp_urls
        self.cache = lru_cache(maxsize=cache_size)(self._query_idp)

    @retry_with_exponential_backoff(max_retries=3, initial_delay=0.5)
    def _query_idp(self, user_id: str, token: str) -> Dict:
        for idp_name, url in self.idp_urls.items():
            response = requests.post(url, json={'user_id': user_id, 'token': token})
            if response.status_code == 200:
                return response.json()
            else:
                raise Exception(f"Failed to query {idp_name} for user {user_id}")

    @cache
    def validate_token(self, user_id: str, token: str) -> bool:
        result = self._query_idp(user_id, token)
        return result['is_valid'] and result['exp'] > datetime.now().timestamp()

# Example usage
idp_urls = {
    'IdP1': 'https://idp1.example.com/validate',
    'IdP2': 'https://idp2.example.com/validate'
}
token_manager = TokenManager(idp_urls)
is_valid = token_manager.validate_token('user123', 'abc123')
print(is_valid)
