        // Handle monitoring errors
    }

    private void handleStartError(Exception e) {
        monitorPlatform.log("Start error: " + e.getMessage());
        // Handle process start errors
    }

    private void handleStopError(Exception e) {
        monitorPlatform.log("Stop error: " + e.getMessage());
        // Handle process stop errors
    }

    public void stop() {
        scheduler.shutdown();
        try {
            if (!scheduler.awaitTermination(60, TimeUnit.SECONDS)) {
                scheduler.shutdownNow();
            }
        } catch (InterruptedException e) {
            scheduler.shutdownNow();
        }
    }

