<?php

class ClinicManager {
    private $dbConnection;
    private $semaphore;

    public function __construct($dbConfig, $semaphoreThreshold) {
        // Initialize database connection
        $this->dbConnection = new mysqli($dbConfig['host'], $dbConfig['user'], $dbConfig['password'], $dbConfig['dbname']);
        if ($this->dbConnection->connect_error) {
            throw new Exception("Database connection failed: " . $this->dbConnection->connect_error);
        }

        // Initialize semaphore
        $this->semaphore = sem_get($semaphoreThreshold, 1, 0666 | SEM_UNLINK_ON_RELEASE);
        if ($this->semaphore === false) {
            throw new Exception("Failed to create semaphore");
        }
    }

    public function updateClinicStatus($clinicId, $newStatus, $clientIp) {
        if (!sem_acquire($this->semaphore)) {
            throw new Exception("Semaphore acquisition failed");
        }

        try {
            // Prepare SQL query
            $sql = "UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = NOW() WHERE clinic_id = ?";
            $stmt = $this->dbConnection->prepare($sql);
            if (!$stmt) {
                throw new Exception("Failed to prepare statement: " . $this->dbConnection->error);
            }

            // Bind parameters
            $stmt->bind_param("ssi", $newStatus, $clientIp, $clinicId);

            // Execute query
            if ($stmt->execute()) {
                $logMessage = "Clinic ID: $clinicId updated to status: $newStatus by IP: $clientIp";
                // Log the update for auditing
                error_log($logMessage);
            } else {
                throw new Exception("Failed to execute statement: " . $stmt->error);
            }
        } finally {
            sem_release($this->semaphore);
        }
    }

    public function __destruct() {
        if ($this->dbConnection) {
            $this->dbConnection->close();
        }
        if ($this->semaphore) {
            sem_destroy($this->semaphore);
        }
    }
}

// Example usage
try {
    $dbConfig = [
        'host' => 'localhost',
        'user' => 'root',
        'password' => '',
        'dbname' => 'clinic_db'
    ];
    $semaphoreThreshold = 10; // Adjust based on system load
    $manager = new ClinicManager($dbConfig, $semaphoreThreshold);
    $manager->updateClinicStatus(123, 'Open', $_SERVER['REMOTE_ADDR']);
} catch (Exception $e) {
    echo "Error: " . $e->getMessage();
}
?>
