<?php

class SessionManager {
    private $sessionStore;
    private $apiClients;

    public function __construct($sessionStore, array $apiClients) {
        $this->sessionStore = $sessionStore;
        $this->apiClients = $apiClients;
    }

    public function generateSessionId($userId) {
        return uniqid() . '-' . bin2hex(random_bytes(16));
    }

    public function startSession($userId) {
        $sessionId = $this->generateSessionId($userId);
        $this->sessionStore->set($sessionId, ['user_id' => $userId]);
        return $sessionId;
    }

    public function validateSession($sessionId) {
        foreach ($this->apiClients as $client) {
            try {
                if ($client->isValidSession($sessionId)) {
                    return true;
                }
            } catch (ApiException $e) {
                if ($e->isTransient()) {
                    continue;
                }
                throw $e;
            }
        }
        return false;
    }

    public function endSession($sessionId) {
        $this->sessionStore->delete($sessionId);
    }
}

interface SessionStore {
    public function set($key, $value);
    public function get($key);
    public function delete($key);
}

class RedisSessionStore implements SessionStore {
    private $redis;

    public function __construct(Redis $redis) {
        $this->redis = $redis;
    }

    public function set($key, $value) {
        $this->redis->setex($key, 3600, json_encode($value));
    }

    public function get($key) {
        $data = $this->redis->get($key);
        return $data ? json_decode($data, true) : null;
    }

    public function delete($key) {
        $this->redis->del($key);
    }
}

interface ApiClient {
    public function isValidSession($sessionId): bool;
    public function isTransient(): bool;
}

class ExternalApiValidator implements ApiClient {
    private $client;

    public function __construct(Client $client) {
        $this->client = $client;
    }

    public function isValidSession($sessionId): bool {
        // Make API request to validate session
        return (bool)$this->client->request('GET', '/validate-session', [
            'query' => ['session_id' => $sessionId]
        ])->getBody();
    }

    public function isTransient(): bool {
        // Check if the error was transient
        return false;
    }
}

// Usage example:
$redis = new Redis();
$redis->connect('127.0.0.1', 6379);

$sessionStore = new RedisSessionStore($redis);
$apiClients = [
    new ExternalApiValidator(new Client()),
    // Add more API clients as needed
];

$sessionManager = new SessionManager($sessionStore, $apiClients);

$userId = 'user123';
$sessionId = $sessionManager->startSession($userId);
echo "Generated session ID: $sessionId\n";

if ($sessionManager->validateSession($sessionId)) {
    echo "Session is valid.\n";
} else {
    echo "Session is invalid.\n";
}

$sessionManager->endSession($sessionId);
?>
