class AuthService {
    private $client;

    public function __construct() {
        $this->client = new \GuzzleHttp\Client();
    }

    public function authenticateUser($code) {
        try {
            $response = $this->client->post('https://oauth.example.com/token', [
                'form_params' => [
                    'grant_type' => 'authorization_code',
                    'code' => $code,
                    'redirect_uri' => 'http://yourdomain.com/callback',
                    'client_id' => OAUTH_CLIENT_ID,
                    'client_secret' => OAUTH_CLIENT_SECRET
                ]
            ]);

            $data = json_decode($response->getBody(), true);
            return $this->handleTokenResponse($data, false);
        } catch (\Exception $e) {
            // Log error and retry with exponential backoff
            sleep(2); // Simplified backoff for demonstration
            return $this->authenticateUser($code);
        }
    }

    private function handleTokenResponse($data, $isRetry = false) {
        if (!isset($data['access_token'])) {
            if (!$isRetry && isset($data['error']) && $data['error'] === 'invalid_grant') {
                // Handle specific error and retry
                return $this->authenticateUser($code);
            }
            throw new \Exception('Authentication failed');
        }

        $accessToken = $data['access_token'];
        $refreshToken = isset($data['refresh_token']) ? $data['refresh_token'] : null;
        $tokenType = $data['token_type'];
        $expiresIn = $data['expires_in'];

        // Store token in Redis with expiration
        $redis = RedisConnection::getInstance()->getConnection();
        $redis->setex("access:$accessToken", $expiresIn, json_encode([
            'refreshToken' => $refreshToken,
            'tokenType' => $tokenType,
            'expiry' => time() + $expiresIn
        ]));

        // Log successful authentication
        logAuth('success', ['accessToken' => $accessToken]);

        return [
            'access_token' => $accessToken,
            'refresh_token' => $refreshToken,
            'token_type' => $tokenType,
            'expires_in' => $expiresIn
        ];
    }

    public function refreshAccessToken($refreshToken) {
        try {
            $response = $this->client->post('https://oauth.example.com/token', [
                'form_params' => [
                    'grant_type' => 'refresh_token',
                    'refresh_token' => $refreshToken,
                    'client_id' => OAUTH_CLIENT_ID,
                    'client_secret' => OAUTH_CLIENT_SECRET
                ]
            ]);

            $data = json_decode($response->getBody(), true);
            return $this->handleTokenResponse($data, false);
        } catch (\Exception $e) {
            // Log error and retry with exponential backoff
            sleep(2); // Simplified backoff for demonstration
            return $this->refreshAccessToken($refreshToken);
        }
    }

    public function revokeAccessToken($accessToken) {
