    void updateCooldown(const std::string& message) {
        std::cout << message << std::endl;
    }

    void showHitAnimation(bool hit) {
        if (hit) {
            std::cout << "Hit Animation" << std::endl;
        } else {
            std::cout << "Miss Animation" << std::endl;
        }
    }
};

class CombatSystem {
private:
    AttackDatabase db;
    GameUI ui;
    std::vector<int> attackIds; // List of attack IDs
    std::atomic<bool> isRunning{false};
    std::mutex mtx;
    std::condition_variable cv;

public:
    CombatSystem() {
        // Initialize with some attack IDs
        for (int i = 1; i <= 5; ++i) {
            attackIds.push_back(i);
        }
    }

    void start() {
        isRunning.store(true);
        std::thread([this]() {
            while (isRunning.load()) {
                performAttack();
                std::this_thread::sleep_for(std::chrono::seconds(rand() % 5 + 1));
            }
        }).detach();
    }

    void stop() {
        isRunning.store(false);
        cv.notify_all();
    }

private:
    void performAttack() {
        std::lock_guard<std::mutex> lock(mtx);
        int selectedId = selectAttack();
        std::string details = db.getAttackDetails(selectedId);
        bool hit = simulateHit(details);
        ui.updateCooldown("Cooldown started");
        ui.showHitAnimation(hit);
    }

    int selectAttack() {
        return attackIds[rand() % attackIds.size()];
    }

    bool simulateHit(const std::string& details) {
        // Simulate a random hit or miss
        return rand() % 2 == 0;
    }
};

int main() {
    CombatSystem combatSystem;
    combatSystem.start();
    std::this_thread::sleep_for(std::chrono::seconds(10));
    combatSystem.stop();
    return 0;
}
