['```csharp
using System;

public class DynamicRandomValueGenerator
{
    private readonly double minValue;
    private readonly double maxValue;

    public DynamicRandomValueGenerator(double minValue, double maxValue)
    {
        if (minValue >= maxValue)
            throw new ArgumentException("minValue must be less than maxValue");

        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GetRandomFloat()
    {
        return (float)(minValue + (maxValue - minValue) * Random.Shared.NextDouble());
    }

    public float GetRandomExclusiveFloat(double exclusiveMax)
    {
        if (exclusiveMax <= minValue)
            throw new ArgumentException("exclusiveMax must be greater than minValue");

        return (float)(minValue + (exclusiveMax - minValue) * Random.Shared.NextDouble());
    }

    public int GetRandomInt()
    {
        try
        {
            var min = Convert.ToInt32(minValue);
            var max = Convert.ToInt32(maxValue);
            return Random.Shared.Next(min, max + 1);
        }
        catch (OverflowException)
        {
            throw new ArgumentException("Range too large for int");
        }
    }

    public int GetRandomExclusiveInt(int exclusiveMax)
    {
        if (exclusiveMax <= minValue)
            throw new ArgumentException("exclusiveMax must be greater than minValue");

        try
        {
            var min = Convert.ToInt32(minValue);
            return Random.Shared.Next(min, exclusiveMax);
        }
        catch (OverflowException)
        {
            throw new ArgumentException("Range too large for int");
        }
    }
}
