// string_repeater.c
#include "string_repeater.h"
#include <stdlib.h>
#include <string.h>

static FILE* log_file = NULL;

void init_logger() {
    log_file = fopen("repetition_log.txt", "w");
}

void log_repetition(const char* original, const char* repeated, size_t limit, RepetitionStatus status) {
    if (log_file != NULL) {
        fprintf(log_file, "Original: %s, Repeated: %s, Limit: %zu, Status: %s\n", 
                original, repeated, limit, status == STATUS_COMPLETED ? "Completed" : "Truncated");
        fflush(log_file);
    }
}

char* repeat_string(const char* input, size_t times, size_t max_size) {
    if (input == NULL || max_size == 0) return NULL;

    size_t input_len = strlen(input);
    if (input_len == 0 || times <= 1) return strdup(input);

    size_t total_len = input_len * times;
    if (total_len > max_size) {
        char* result = (char*)malloc(max_size + 3);
        if (result != NULL) {
            strncpy(result, input, max_size - 3);
            strcat(result, "...");
            log_repetition(input, result, max_size, STATUS_TRUNCATED);
            return result;
        }
    } else {
        char* result = (char*)malloc(total_len + 1);
        if (result != NULL) {
            for (size_t i = 0; i < times; ++i) {
                strcat(result, input);
            }
            log_repetition(input, result, max_size, STATUS_COMPLETED);
            return result;
        }
    }

    // Error handling
    clean_up();
    return NULL;
}

void clean_up() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}
