// Define a structure for image metadata
typedef struct {
    int width;
    int height;
    char compression_type[50];
} ImageMetadata;

// Function to process JPEG images in a streaming fashion
int process_jpeg(const char* filename, ImageMetadata** metadata) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        return -1; // Error opening file
    }

    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);

    jpeg_stdio_src(&cinfo, file);
    jpeg_read_header(&cinfo, TRUE);
    jpeg_start_decompress(&cinfo);

    *metadata = (ImageMetadata*)malloc(sizeof(ImageMetadata));
    (*metadata)->width = cinfo.output_width;
    (*metadata)->height = cinfo.output_height;

    // Extract compression type
    strcpy((*metadata)->compression_type, cinfo.jpeg_version < 1.2 ? "Baseline" : "Progressive");

    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);

    fclose(file);
    return 0; // Success
}

// Function to free allocated metadata
void free_metadata(ImageMetadata* metadata) {
    if (metadata) {
        free(metadata);
    }
}
