// filename_generator.c

#include "filename_generator.h"
#include <stdlib.h>
#include <string.h>
#include <time.h>

struct FilenameGenerator {
    char* template;
    int file_type_id;
};

FilenameGenerator* fg_create(const char* template, int file_type_id) {
    FilenameGenerator* generator = (FilenameGenerator*)malloc(sizeof(FilenameGenerator));
    if (!generator) return NULL;

    generator->template = strdup(template);
    generator->file_type_id = file_type_id;

    return generator;
}

void fg_destroy(FilenameGenerator* generator) {
    if (!generator) return;
    free(generator->template);
    free(generator);
}

char* fg_generate_filename(FilenameGenerator* generator) {
    char* timestamp = generate_timestamp();
    if (timestamp) {
        return replace_in_template(generator->template, "%Y%m%d", timestamp);
    } else {
        static int sequence_number = 0;
        char buffer[50];
        snprintf(buffer, sizeof(buffer), "%d", __sync_fetch_and_add(&sequence_number, 1));
        return generate_filename_with_suffix(buffer, generator->file_type_id);
    }
}

static char* generate_timestamp() {
    time_t now = time(NULL);
    struct tm* tm_struct = localtime(&now);
    if (!tm_struct) return NULL;

    char timestamp[9];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d", tm_struct);

    // Validate timestamp format
    if (strncmp(timestamp, "19700101", 8) < 0 || strncmp(timestamp, "21001231", 8) > 0) {
        return NULL;
    }

    return strdup(timestamp);
}

static char* replace_in_template(const char* template, const char* key, const char* value) {
    size_t key_len = strlen(key);
    size_t value_len = strlen(value);

    char* result = (char*)malloc(strlen(template) + value_len - key_len + 1);
    if (!result) return NULL;

    const char* src = template;
    char* dst = result;

    while (*src) {
        if (strncmp(src, key, key_len) == 0) {
            strcpy(dst, value);
            dst += value_len;
            src += key_len;
        } else {
            *dst++ = *src++;
        }
    }

    *dst = '\0';
    return result;
}

static char* generate_filename_with_suffix(const char* sequence_number, int file_type_id) {
    const char* suffixes[] = {".txt", ".log", ".csv"};
    if (file_type_id < 0 || file_type_id >= sizeof(suffixes)/sizeof(suffixes[0])) return NULL;

    size_t number_len = strlen(sequence_number);
    size_t suffix_len = strlen(suffixes[file_type_id]);
    char* filename = (char*)malloc(number_len + suffix_len + 1);
    if (!filename) return NULL;

    strcpy(filename, sequence_number);
    strcat(filename, suffixes[file_type_id]);

    return filename;
}
