void derive_key(const char *password, unsigned char *key) {
    unsigned char salt[16];
    if (!RAND_bytes(salt, sizeof(salt))) {
        // Handle error
    }
    PKCS5_PBKDF2_HMAC_SHA256(password, strlen(password), salt, PBKDF2_ITERATIONS, KEY_SIZE, key);
}

void encrypt(const unsigned char *key, const unsigned char *iv, const unsigned char *plaintext, int plaintext_len,
             unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        // Handle error
    }
    int len;
    if (!EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        // Handle error
    }
    int ciphertext_len = len;
    if (!EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        // Handle error
    }
    ciphertext_len += len;
    EVP_CIPHER_CTX_free(ctx);
}

void decrypt(const unsigned char *key, const unsigned char *iv, const unsigned char *ciphertext, int ciphertext_len,
             unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        // Handle error
    }
    int len;
    if (!EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        // Handle error
    }
    int plaintext_len = len;
    if (!EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
        // Handle error
    }
    plaintext_len += len;
    EVP_CIPHER_CTX_free(ctx);
}

int main() {
    unsigned char key[KEY_SIZE];
    unsigned char iv[IV_SIZE];
    unsigned char plaintext[] = "Hello, World!";
    unsigned char ciphertext[128];

    derive_key("password", key);
    if (!RAND_bytes(iv, IV_SIZE)) {
        // Handle error
    }

    encrypt(key, iv, plaintext, strlen((char *)plaintext), ciphertext);

    unsigned char decryptedtext[128];
    decrypt(key, iv, ciphertext, strlen((char *)ciphertext), decryptedtext);

    printf("Decrypted text: %s\n", decryptedtext);
    return 0;
}
