#include <filesystem>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <fstream>

namespace fs = std::filesystem;

struct ImageProcessingTask {
    fs::path inputPath;
    fs::path outputPath;
};

class ThreadPool {
public:
    ThreadPool(size_t threads) : stop(false) {
        for(size_t i = 0; i < threads; ++i)
            workers.emplace_back([this] {
                for(;;) {
                    ImageProcessingTask task;
                    {
                        std::unique_lock<std::mutex> lock(this->queue_mutex);
                        this->condition.wait(lock, [this]{ return this->stop || !this->tasks.empty(); });
                        if(this->stop && this->tasks.empty())
                            return;
                        task = std::move(this->tasks.front());
                        this->tasks.pop();
                    }
                    try {
                        // Call third-party library to convert image to PDF
                        convertImageToPDF(task.inputPath, task.outputPath);
                    } catch (const std::exception& e) {
                        logError(e.what(), task.inputPath.filename().string());
                    }
                }
            });
    }

    template<class F, class... Args>
    void enqueue(F&& f, Args&&... args) {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            if(stop)
                throw std::runtime_error("enqueue on stopped ThreadPool");
            tasks.emplace(std::bind(std::forward<F>(f), std::forward<Args>(args)...));
        }
        condition.notify_one();
    }

    ~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        condition.notify_all();
        for(std::thread &worker: workers)
            worker.join();
    }

private:
    void convertImageToPDF(const fs::path& inputPath, const fs::path& outputPath) {
        // Implementation of third-party library call
    }

    void logError(const std::string& error, const std::string& imageName) {
        // Log error details including timestamp
    }

    std::vector<std::thread> workers;
    std::queue<ImageProcessingTask> tasks;
    std::mutex queue_mutex;
    std::condition_variable condition;
    bool stop;
};

void processDirectory(const fs::path& inputDir, const fs::path& outputDir, size_t maxThreads) {
    ThreadPool pool(maxThreads);

    for (const auto& entry : fs::directory_iterator(inputDir)) {
        if (entry.is_regular_file()) {
            std::string extension = entry.path().extension().string();
            if (extension == ".jpg" || extension == ".png") { // Add more extensions as needed
                pool.enqueue([](const ImageProcessingTask& task) {
                    // Task execution happens here
                }, ImageProcessingTask{entry.path(), outputDir / (entry.path().stem() + ".pdf")});
            }
        }
    }

    pool.join();
}

int main(int argc, char* argv[]) {
    if (argc < 5) {
        std::cerr << "Usage: program <input_dir> <output_dir> <max_threads>" << std::endl;
        return 1;
    }

    fs::path inputDir(argv[1]);
    fs::path outputDir(argv[2]);
    size_t maxThreads = std::stoul(argv[3]);

    processDirectory(inputDir, outputDir, maxThreads);

    return 0;
}
