#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>

// Define a structure for the command and its associated information
typedef struct {
    char *command;
    pid_t pid;
    int status;
    void (*callback)(int, const char*);
} Command;

// Function to execute a command asynchronously
int execute_command(const char *command, void (*callback)(int, const char*)) {
    Command cmd = {strdup(command), 0, 0, callback};
    cmd.pid = fork();

    if (cmd.pid == -1) {
        perror("fork");
        free(cmd.command);
        return 0; // Failure
    } else if (cmd.pid == 0) {
        // Child process
        execl("/bin/sh", "sh", "-c", command, NULL);
        perror("execl"); // Should not reach here
        exit(1);
    }

    // Parent process
    return 1; // Success
}

// Callback function to handle command execution status
void on_command_status(int pid, const char *status) {
    printf("Command with PID %d has %s\n", pid, status);
    // Log the status using an external logging service here
}

int main() {
    if (!execute_command("ls -l /", on_command_status)) {
        return 0; // Critical failure
    }

    if (!execute_command("echo Hello World", on_command_status)) {
        return 0; // Critical failure
    }

    // Wait for child processes to complete
    int status;
    while (waitpid(-1, &status, WNOHANG) > 0);

    return 1; // All operations successful
}
