using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.NetworkInformation;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class SiteManager
{
    private readonly IConfigManagementApi _configApi;
    private readonly ILogger<SiteManager> _logger;
    private readonly Dictionary<string, bool> _siteStatuses = new Dictionary<string, bool>();

    public SiteManager(IConfigManagementApi configApi, ILogger<SiteManager> logger)
    {
        _configApi = configApi;
        _logger = logger;
    }

    public async Task AddAndStartSiteAsync(string siteName)
    {
        try
        {
            var siteConfig = await _configApi.GetSiteConfigAsync(siteName);
            if (!siteConfig.Exists)
            {
                _logger.LogError("Site configuration not found for {SiteName}", siteName);
                return;
            }

            if (!File.Exists(Path.Combine(siteConfig.RootPath, "web.config")) ||
                !File.Exists(Path.Combine(siteConfig.RootPath, "appsettings.json")))
            {
                _logger.LogError("Required files are missing for {SiteName}", siteName);
                return;
            }

            var portsToCheck = new List<int> { siteConfig.DefaultPort };
            for (int i = 0; i < siteConfig.AllowedPortRange; i++)
            {
                portsToCheck.Add(siteConfig.DefaultPort + i);
            }

            foreach (var port in portsToCheck)
            {
                if (!IsPortAvailable(port))
                {
                    continue;
                }

                var availablePort = await FindAvailablePortAsync(port, 5);
                if (availablePort == -1)
                {
                    _logger.LogError("No available port found for {SiteName}", siteName);
                    return;
                }

                await StartSiteAsync(siteName, availablePort);
                _siteStatuses[siteName] = true;
                _logger.LogInformation("Site {SiteName} started on port {Port}", siteName, availablePort);
                break;
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to add and start site {SiteName}", siteName);
        }
    }

    private bool IsPortAvailable(int port)
    {
        return !TcpListener.IsListening(port);
    }

    private async Task<int> FindAvailablePortAsync(int basePort, int maxRetries)
    {
        for (int i = 0; i < maxRetries; i++)
        {
            if (IsPortAvailable(basePort + i))
            {
                return basePort + i;
            }
            await Task.Delay(100); // Backoff strategy
        }
        return -1;
    }

    private async Task StartSiteAsync(string siteName, int port)
    {
        // Logic to start the site using the provided port
        _logger.LogInformation("Starting {SiteName} on port {Port}", siteName, port);
        await Task.Delay(500); // Simulate starting time
    }
}

public interface IConfigManagementApi
{
    Task<SiteConfiguration> GetSiteConfigAsync(string siteName);
}

public class SiteConfiguration
{
    public bool Exists { get; set; }
    public string RootPath { get; set; }
    public int DefaultPort { get; set; }
    public int AllowedPortRange { get; set; }
}
