import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class FileUtility {
    private static final Logger logger = Logger.getLogger(FileUtility.class.getName());
    private Path inputPath;
    private Path backupPath;
    private ExternalDataSource dataSource;

    public FileUtility(Path inputPath, Path backupPath, ExternalDataSource dataSource) {
        this.inputPath = inputPath;
        this.backupPath = backupPath;
        this.dataSource = dataSource;
    }

    public void run() {
        ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(2);
        scheduleFileMonitoring(scheduler);

        while (true) {
            try {
                Path currentPath = Paths.get("input.txt");
                File file = currentPath.toFile();
                if (!Files.exists(file)) {
                    logger.warning("Input file does not exist.");
                    continue;
                }

                BasicFileAttributes attrs = Files.readAttributes(currentPath, BasicFileAttributes.class);
                long lastModifiedTime = attrs.lastModifiedTime().toMillis();
                if (lastModifiedTime != inputLastModified) {
                    logModification(lastModifiedTime);
                    inputLastModified = lastModifiedTime;

                    if (!validateContent()) {
                        continue;
                    }

                    executeCommand();
                }
            } catch (IOException e) {
                logger.log(Level.SEVERE, "Error accessing input file", e);
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Unexpected error", e);
            }

            try {
                Thread.sleep(1000); // Check every second
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private void scheduleFileMonitoring(ScheduledExecutorService scheduler) {
        scheduler.scheduleAtFixedRate(() -> {
            try {
                BasicFileAttributes attrs = Files.readAttributes(inputPath, BasicFileAttributes.class);
                long lastModifiedTime = attrs.lastModifiedTime().toMillis();
                if (lastModifiedTime != inputLastModified) {
                    logModification(lastModifiedTime);
                    inputLastModified = lastModifiedTime;
                }
            } catch (IOException e) {
                logger.log(Level.SEVERE, "Error accessing input file", e);
            }
        }, 0, 1, TimeUnit.SECONDS);
    }

    private void logModification(long timestamp) {
        // Log modification time
    }

    private boolean validateContent() {
        int retries = 3;
        for (int i = 0; i <= retries; i++) {
            try {
                if (dataSource.validate(inputPath)) {
                    return true;
                }
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Validation failed", e);
            }

            if (i < retries) {
                try {
                    Thread.sleep(5000); // 5 seconds
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        String message = "Manual intervention required due to validation failures.";
        logger.log(Level.WARNING, message);
        return false;
    }

    private void executeCommand() {
        int maxRetries = 5;
        for (int i = 0; i <= maxRetries; i++) {
            try {
                ProcessBuilder builder = new ProcessBuilder("/path/to/command");
                Process process = builder.start();

                Future<?> future = Executors.newSingleThreadExecutor().submit(() -> {
                    BufferedReader stdout = new BufferedReader(new InputStreamReader(process.getInputStream()));
                    String line;
                    while ((line = stdout.readLine()) != null) {
                        logLine(line);
                    }
                });

                BufferedReader stderr = new BufferedReader(new InputStreamReader(process.getErrorStream()));
                String errorLine;
                while ((errorLine = stderr.readLine()) != null) {
                    logger.severe(errorLine);
                }

                process.waitFor();
                future.get();
            } catch (IOException | InterruptedException | ExecutionException e) {
                logger.log(Level.SEVERE, "Command execution failed", e);

                if (i < maxRetries) {
                    try {
                        Thread.sleep((long) Math.pow(2, i) * 1000); // Exponential backoff
                    } catch (InterruptedException e1) {
                        Thread.currentThread().interrupt();
                    }
                } else {
                    logger.severe("Max retries reached. Exiting utility.");
                    System.exit(1);
                }
            }
        }
    }

    private void logLine(String line) {
        if (line.length() > 1024) {
            line = line.substring(0, 1024);
        }
        logger.info(line);
    }

    private static boolean isDuplicateEntry(String line, long timeWindowMillis) {
        // Implement logic to check for duplicate entries
        return false;
    }

    public void stop() {
        try {
            Files.move(inputPath, backupPath);
            if (Files.exists(backupPath)) {
                Files.delete(backupPath);
                logger.info("Backup file deleted.");
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error deleting backup file", e);
        }
    }

    private long inputLastModified;
}

interface ExternalDataSource {
    boolean validate(Path path) throws Exception;
}
