using System;
using System.IO;
using System.Net.Http;
using System.Runtime.Serialization.Formatters.Binary;
using System.Security.Cryptography;
using Microsoft.Extensions.Caching.Memory;

public class DataDecryptionService
{
    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _cache;

    public DataDecryptionService(HttpClient httpClient, IMemoryCache cache)
    {
        _httpClient = httpClient;
        _cache = cache;
    }

    public object DecryptAndDeserialize(string ciphertextBase64, string keyBase64, string ivBase64, string fileUrl)
    {
        var decryptedData = Decrypt(ciphertextBase64, keyBase64, ivBase64);
        return Deserialize(decryptedData, fileUrl);
    }

    private byte[] Decrypt(string ciphertextBase64, string keyBase64, string ivBase64)
    {
        var key = Convert.FromBase64String(keyBase64);
        var iv = Convert.FromBase64String(ivBase64);
        var ciphertext = Convert.FromBase64String(ciphertextBase64);

        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            using (ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
            {
                using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        return csDecrypt.ToArray();
                    }
                }
            }
        }
    }

    private object Deserialize(byte[] data, string fileUrl)
    {
        try
        {
            using (MemoryStream ms = new MemoryStream(data))
            {
                BinaryFormatter formatter = new BinaryFormatter();
                return formatter.Deserialize(ms);
            }
        }
        catch (Exception ex)
        {
            // Log error details for debugging and auditing
            Console.WriteLine($"Deserialization error: {ex.Message}");
            throw;
        }
    }

    public string GetLatestKeyAndIv(string apiEndpoint)
    {
        var cacheKey = "EncryptionKeyAndIV";
        if (_cache.TryGetValue(cacheKey, out var cachedValue) && cachedValue is Tuple<string, string> cachedKeys)
        {
            return $"{cachedKeys.Item1}|{cachedKeys.Item2}";
        }

        try
        {
            var response = _httpClient.GetStringAsync(apiEndpoint).Result;
            var keysAndIVs = response.Split('|');
            if (keysAndIVs.Length == 2)
            {
                _cache.Set(cacheKey, new Tuple<string, string>(keysAndIVs[0], keysAndIVs[1]), TimeSpan.FromHours(1));
                return $"{keysAndIVs[0]}|{keysAndIVs[1]}";
            }
        }
        catch (Exception ex)
        {
            // Log error details for debugging and auditing
            Console.WriteLine($"API call error: {ex.Message}");
        }

        throw new Exception("Failed to retrieve encryption key and IV from the API.");
    }
}
