public class LargeDataProcessingService
{
    private readonly ILogger<LargeDataProcessingService> _logger;
    private readonly IExternalApiService _apiService;
    private readonly IDatabaseService _databaseService;

    public LargeDataProcessingService(ILogger<LargeDataProcessingService> logger, IExternalApiService apiService, IDatabaseService databaseService)
    {
        _logger = logger;
        _apiService = apiService;
        _databaseService = databaseService;
    }

    public async Task ProcessLargeFilesAsync(string filePath, int pageSize)
    {
        using (var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, 8192, true))
        {
            var formatter = new BinaryFormatter();
            while (true)
            {
                var dataBatch = await LoadNextBatchAsync(stream, formatter, pageSize);
                if (dataBatch == null) break;

                foreach (var item in dataBatch)
                {
                    try
                    {
                        // Deserialize and process each item
                        var processedData = _apiService.TransformData(item);
                        await _databaseService.SaveDataAsync(processedData);
                    }
                    catch (Exception ex)
                    {
                        _logger.LogError(ex, "Error processing data: {Item}", item);
                        // Log the error or take other appropriate actions
                    }
                }
            }
        }
    }

    private async Task<List<CustomData>> LoadNextBatchAsync(Stream stream, BinaryFormatter formatter, int pageSize)
    {
        var batch = new List<CustomData>();
        for (int i = 0; i < pageSize && stream.Position < stream.Length; i++)
        {
            try
            {
                var item = (CustomData)formatter.Deserialize(stream);
                batch.Add(item);
            }
            catch (EndOfStreamException)
            {
                break;
            }
        }
        return batch;
    }
}

