// Interface for cache manager with methods to get, put, and invalidate data
public interface CacheManager {
    <T> T get(String key);
    <T> void put(String key, T value, long ttl);
    <T> void remove(String key);
}

// Example implementation of CacheManager using an in-memory map with TTL
public class InMemoryCacheManager implements CacheManager {
    private Map<String, CacheEntry> cache = new HashMap<>();

    @Override
    public <T> T get(String key) {
        CacheEntry entry = cache.get(key);
        if (entry != null && !entry.isExpired()) {
            return (T) entry.value;
        }
        return null;
    }

    @Override
    public <T> void put(String key, T value, long ttl) {
        cache.put(key, new CacheEntry(value, System.currentTimeMillis() + ttl));
    }

    @Override
    public <T> void remove(String key) {
        cache.remove(key);
    }

    private static class CacheEntry {
        Object value;
        long expiryTime;

        CacheEntry(Object value, long expiryTime) {
            this.value = value;
            this.expiryTime = expiryTime;
        }

        boolean isExpired() {
            return System.currentTimeMillis() > expiryTime;
        }
    }
}

