type ConfigStore = RwLock<String>;

#[derive(Debug)]
struct DirectoryService {
    client: Client,
    config_store: ConfigStore,
    parent_directory: PathBuf,
    max_retries: u32,
}

impl DirectoryService {
    async fn new(parent_directory: &str, max_retries: u32) -> Self {
        let config_store = RwLock::new("".to_string());
        DirectoryService {
            client: Client::new(),
            config_store,
            parent_directory: PathBuf::from(parent_directory),
            max_retries,
        }
    }

    async fn monitor_api(&self, api_url: &str) -> Result<(), reqwest::Error> {
        let response = self.client.get(api_url).send().await?;
        if response.status().is_success() {
            let new_path = self.process_api_response(response.text().await?).await?;
            self.update_config_store(new_path).await?;
        } else {
            warn!("API request failed with status: {}", response.status());
        }
        Ok(())
    }

    async fn process_api_response(&self, api_data: String) -> Result<PathBuf, reqwest::Error> {
        // Implement logic to parse the API data and extract the new directory path
        let new_directory_name = "new_directory"; // Placeholder for actual parsing logic
        self.create_unique_directory(new_directory_name).await
    }

    async fn create_unique_directory(&self, name: &str) -> Result<PathBuf, std::io::Error> {
        let mut retries = 0;
        loop {
            let new_path = self.parent_directory.join(name);
            if !new_path.exists() {
                fs::create_dir_all(&new_path)?;
                return Ok(new_path);
            }
            retries += 1;
            if retries >= self.max_retries {
                error!("Failed to create unique directory after {} retries", retries);
                break Err(std::io::Error::new(std::io::ErrorKind::Other, "Directory already exists"));
            }
            tokio::time::sleep(tokio::time::Duration::from_secs(1)).await;
        }
    }

    async fn update_config_store(&self, new_path: PathBuf) -> Result<(), std::sync::PoisonError<()>> {
        let mut store = self.config_store.write().unwrap();
        *store = new_path.to_string_lossy().to_string();
        Ok(())
    }

    async fn run_monitoring_loop(&self, api_url: &str, interval: tokio::time::Duration) {
        loop {
            if let Err(e) = self.monitor_api(api_url).await {
                error!("Error in monitoring API: {:?}", e);
            }
            tokio::time::sleep(interval).await;
        }
    }
}

#[tokio::main]
async fn main() {
    env_logger::init();
    let service = DirectoryService::new("/parent/directory", 5).await.unwrap();
    service.run_monitoring_loop("http://api.example.com/config", tokio::time::Duration::from_secs(60)).await;
}
