# Dynamic Class Hierarchy Manager Framework

import threading
import logging
import jsonschema
from functools import wraps
from abc import ABC, abstractmethod
from requests.adapters import HTTPAdapter
from urllib3.util.retry import Retry

class DynamicClassManager:
    _instances = {}
    _lock = threading.Lock()

    @staticmethod
    def get_instance():
        with DynamicClassManager._lock:
            if not DynamicClassManager._instances:
                DynamicClassManager._instances['default'] = DynamicClassManager()
            return DynamicClassManager._instances['default']

    def __init__(self):
        self.class_registry = {}
        self.factory_registry = {}
        logging.basicConfig(level=logging.INFO)

    def register_class(self, class_id, cls):
        with DynamicClassManager._lock:
            if class_id in self.class_registry:
                logging.warning(f"Class ID {class_id} already registered. Overwriting.")
            self.class_registry[class_id] = cls

    def get_class(self, class_id):
        return self.class_registry.get(class_id)

    def register_factory(self, class_id, factory_func):
        with DynamicClassManager._lock:
            if class_id in self.factory_registry:
                logging.warning(f"Factory for ID {class_id} already registered. Overwriting.")
            self.factory_registry[class_id] = factory_func

    def create_instance(self, class_id, *args, **kwargs):
        return self.factory_registry.get(class_id)(*args, **kwargs)

class JSONProcessor:
    def parse_json(self, json_str, schema):
        try:
            jsonschema.validate(instance=json.loads(json_str), schema=schema)
            return json.loads(json_str)
        except jsonschema.exceptions.ValidationError as e:
            logging.error(f"JSON validation error: {e}")
            raise

    def serialize_instance_to_json(self, instance):
        return json.dumps(instance.__dict__)

class ExternalAPIClient:
    def __init__(self, base_url, auth_token):
        self.base_url = base_url
        self.auth_token = auth_token
        self.session = requests.Session()
        retries = Retry(total=5,
                       backoff_factor=1,
                       status_forcelist=[ 502, 503, 504 ])
        self.session.mount('http://', HTTPAdapter(max_retries=retries))
        self.session.mount('https://', HTTPAdapter(max_retries=retries))

    def get_data(self, endpoint):
        response = self.session.get(f"{self.base_url}/{endpoint}", headers={'Authorization': f'Bearer {self.auth_token}'})
        if response.status_code != 200:
            raise Exception(f"Failed to retrieve data: {response.status_code}")
        return response.json()

    def post_data(self, endpoint, data):
        response = self.session.post(f"{self.base_url}/{endpoint}", json=data, headers={'Authorization': f'Bearer {self.auth_token}'})
        if response.status_code != 201:
            raise Exception(f"Failed to post data: {response.status_code}")
        return response.json()

# Example usage
if __name__ == "__main__":
    manager = DynamicClassManager.get_instance()

    # Register a class and factory function
    class MyClass:
        def __init__(self, name):
            self.name = name

    def my_class_factory(name):
        return MyClass(name)

    manager.register_class('myclass', MyClass)
    manager.register_factory('myclass', my_class_factory)

    # Create an instance using the factory function
    instance = manager.create_instance('myclass', 'TestInstance')
    print(instance.name)  # Output: TestInstance

    # JSON processing
    json_str = '{"name": "John", "age": 30}'
    schema = {
        "type" : "object",
        "properties" : {
            "name" : {"type" : "string"},
            "age" : {"type" : "number"}
        },
        "required": ["name", "age"]
    }
    processor = JSONProcessor()
    parsed_json = processor.parse_json(json_str, schema)
    print(parsed_json)  # Output: {'name': 'John', 'age': 30}

    # External API client
    api_client = ExternalAPIClient('https://api.example.com', 'your_auth_token')
    data = api_client.get_data('users/123')
    print(data)
```']

