    DELETE_USER
} SubAction;

typedef struct {
    int id;
    User user;
    SubAction sub_action;
} UserRequest;

typedef struct State {
    User *users;
    int count;
    int capacity;
    struct State *next;
} State;

typedef struct {
    // Define FSA structure fields here
} Fsa;

typedef struct {
    char message[512];
    int error_code;
} Response;

Response* manage_user_accounts(int *state_list, int state_count, Fsa *fsa, int last_state_index, UserRequest *request) {
    Response *response = (Response *)malloc(sizeof(Response));
    if (!response) {
        response->error_code = -1;
        strcpy(response->message, "Failed to allocate memory");
        return response;
    }

    State *current_state = &state_list[last_state_index];
    User *new_user = NULL;

    switch (request->sub_action) {
        case CREATE_USER:
            if (!validate_user(&request->user)) {
                response->error_code = 1;
                strcpy(response->message, "Invalid user input");
                return response;
            }
            new_user = (User *)malloc(sizeof(User));
            if (!new_user) {
                free(response);
                response->error_code = -2;
                strcpy(response->message, "Failed to allocate memory for user");
                return response;
            }
            *new_user = request->user;
            break;

        case UPDATE_USER:
            if (request->id < 0 || request->id >= current_state->count) {
                response->error_code = 2;
                strcpy(response->message, "Invalid user ID");
                return response;
            }
            new_user = &current_state->users[request->id];
            *new_user = request->user;
            break;

        case DELETE_USER:
            if (request->id < 0 || request->id >= current_state->count) {
                response->error_code = 2;
                strcpy(response->message, "Invalid user ID");
                return response;
            }
            free(&current_state->users[request->id]);
            current_state->count--;
            break;

        default:
            response->error_code = 3;
            strcpy(response->message, "Unsupported sub_action");
            return response;
    }

    if (new_user) {
        State *new_state = (State *)malloc(sizeof(State));
        if (!new_state) {
            free(new_user);
            free(response);
            response->error_code = -3;
            strcpy(response->message, "Failed to allocate memory for state");
            return response;
        }
        new_state->users = current_state->users;
        new_state->count = current_state->count + 1;
        new_state->capacity = current_state->capacity;
        new_state->next = NULL;

        current_state->next = new_state;
    }

    strcpy(response->message, "Operation successful");
    response->error_code = 0;
    return response;
}

