int is_rate_limited(const char* ip_address) {
    time_t current_time = time(NULL);
    if (user_requests[atoi(ip_address)] > 0 && 
        current_time - last_request_time[atoi(ip_address)] < 60) {
        return 1;
    }
    user_requests[atoi(ip_address)]++;
    last_request_time[atoi(ip_address)] = current_time;
    return 0;
}

