typedef struct {
    FILE *file;
    char *buffer;
    size_t buffer_size;
} FileData;

void *process_file(void *arg) {
    FileData *data = (FileData *)arg;
    // Implement file processing logic here
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <csv_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    FileData data = { .file = file, .buffer_size = 1024 };
    data.buffer = (char *)malloc(data.buffer_size);

    pthread_t threads[MAX_THREADS];
    int thread_count = 0;

    while (!feof(file)) {
        size_t bytes_read = fread(data.buffer, 1, data.buffer_size, file);
        if (bytes_read == data.buffer_size) {
            if (thread_count >= MAX_THREADS) {
                // Handle too many threads
                fprintf(stderr, "Too many threads\n");
                goto cleanup;
            }
            pthread_create(&threads[thread_count], NULL, process_file, &data);
            thread_count++;
        } else {
            break; // End of file
        }
    }

    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

cleanup:
    free(data.buffer);
    fclose(file);
    return EXIT_SUCCESS;
}
