#include <stdio.h>
#include <stdlib.h>
#include <jpeglib.h>

// Function to open JPEG file
FILE* open_jpeg_file(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        exit(EXIT_FAILURE);
    }
    return file;
}

// Function to decode JPEG header
void decode_jpeg_header(FILE* file, struct jpeg_decompress_struct* cinfo) {
    jpeg_create_decompress(cinfo);
    jpeg_stdio_src(cinfo, file);
    if (jpeg_read_header(cinfo, TRUE) != JPEG_HEADER_OK) {
        fprintf(stderr, "Failed to read JPEG header\n");
        exit(EXIT_FAILURE);
    }
}

// Function to extract metadata from JPEG image
void extract_metadata(const char* filename, struct jpeg_decompress_struct* cinfo) {
    FILE* file = open_jpeg_file(filename);
    decode_jpeg_header(file, cinfo);

    printf("File: %s\n", filename);
    printf("Image Dimensions: %d x %d\n", cinfo->output_width, cinfo->output_height);
    printf("Compression Type: %d\n", cinfo->jpeg_color_space);
    if (cinfo->progressive_mode) {
        printf("Format: Progressive JPEG\n");
    } else {
        printf("Format: Baseline JPEG\n");
    }

    jpeg_destroy_decompress(cinfo);
    fclose(file);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <jpeg_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    struct jpeg_decompress_struct cinfo;

    extract_metadata(argv[1], &cinfo);

    return EXIT_SUCCESS;
}
```

This code snippet demonstrates how to open a JPEG file, decode its header, and extract basic metadata such as image dimensions and compression type using the libjpeg library in C. It includes error handling for file opening and JPEG header reading. This is just a starting point; the full implementation would require additional features and optimizations as specified in the task description.']

