class DataIngestor {
public:
    void start() {
        ingestThread = std::thread(&DataIngestor::run, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            running = false;
        }
        condition.notify_all();
        if (ingestThread.joinable()) {
            ingestThread.join();
        }
    }

    void enqueue(const DataRecord& record) {
        {
            std::unique_lock<std::mutex> lock(mutex);
            queue.push(record);
        }
        condition.notify_one();
    }

private:
    struct DataRecord {
        std::string sourceIP;
        std::time_t timestamp;
        std::string eventType;
        // Add more fields as needed
    };

    void run() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !queue.empty() || !running; });
            if (!running && queue.empty()) {
                break;
            }
            DataRecord record = queue.front();
            queue.pop();
            lock.unlock();

            // Process the data record
            process(record);
        }
    }

    void process(const DataRecord& record) {
        // Implement data transformation and enrichment logic here
    }

    std::thread ingestThread;
    std::queue<DataRecord> queue;
    std::mutex mutex;
    std::condition_variable condition;
    std::atomic<bool> running{true};
};

int main() {
    DataIngestor ingestor;
    ingestor.start();

    // Simulate data ingestion
    for (int i = 0; i < 100; ++i) {
        DataRecord record;
        // Populate the record with data
        ingestor.enqueue(record);
    }

    ingestor.stop();
    return 0;
}
