#include <condition_variable>

class Attack;
class Player;

class CombatSystem {
public:
    CombatSystem(int maxPlayers);
    ~CombatSystem();

    void addPlayer(Player* player);
    void removePlayer(Player* player);

    void processAttackRequest(Attack* attack);

private:
    std::vector<Player*> players_;
    std::queue<Attack*> attackQueue_;

    std::mutex queueMutex_;
    std::condition_variable queueCondVar_;
    std::atomic<bool> running_{true};
};

// Attack.h
#pragma once

class Player;

class Attack {
public:
    Attack(Player* source, Player* target);
    ~Attack();

    void execute();
    bool isCooldownExpired() const;
    void decreaseFatigue();

private:
    Player* source_;
    Player* target_;
    std::atomic<bool> onCooldown_{false};
    std::atomic<int> fatigueLevel_{0};
};

// Player.h
#pragma once

class Attack;

class Player {
public:
    Player(int id);
    ~Player();

    void receiveAttack(Attack* attack);

private:
    int id_;
    std::vector<Attack*> activeAttacks_;
};

// CombatSystem.cpp
#include "CombatSystem.h"
#include "Attack.h"
#include "Player.h"

CombatSystem::CombatSystem(int maxPlayers) {
    for (int i = 0; i < maxPlayers; ++i) {
        players_.emplace_back(new Player(i));
    }
}

CombatSystem::~CombatSystem() {
    running_ = false;
    queueCondVar_.notify_all();
    for (Player* player : players_) {
        delete player;
    }
}

void CombatSystem::addPlayer(Player* player) {
    players_.push_back(player);
}

void CombatSystem::removePlayer(Player* player) {
    players_.erase(std::remove(players_.begin(), players_.end(), player), players_.end());
    delete player;
}

void CombatSystem::processAttackRequest(Attack* attack) {
    std::unique_lock<std::mutex> lock(queueMutex_);
    attackQueue_.push(attack);
    queueCondVar_.notify_one();
}

// Attack.cpp
#include "Attack.h"
#include "Player.h"

Attack::Attack(Player* source, Player* target)
    : source_(source), target_(target) {}

Attack::~Attack() {
    // Clean up any resources
}

void Attack::execute() {
    if (!onCooldown_.load()) {
        onCooldown_.store(true);
        fatigueLevel_.fetch_add(1);
        // Perform attack logic here
        std::cout << "Player " << source_->id_ << " attacks Player " << target_->id_ << std::endl;
        // Simulate cooldown duration
        std::this_thread::sleep_for(std::chrono::seconds(2));
        onCooldown_.store(false);
    } else {
        std::cout << "Attack is on cooldown for Player " << source_->id_ << std::endl;
    }
}

bool Attack::isCooldownExpired() const {
    return !onCooldown_.load();
}

void Attack::decreaseFatigue() {
    if (fatigueLevel_.load() > 0) {
        fatigueLevel_.fetch_sub(1);
    }
}

// Player.cpp
#include "Player.h"
#include "Attack.h"

Player::Player(int id)
    : id_(id) {}

Player::~Player() {
    for (Attack* attack : activeAttacks_) {
        delete attack;
    }
}

void Player::receiveAttack(Attack* attack) {
    activeAttacks_.push_back(attack);
    std::thread([this, attack]() { attack->execute(); }).detach();
}
