#define MAX_RESOURCE_BUNDLE_SIZE 1024 * 1024 // 1 MB

typedef struct {
    char **keys;
    char **values;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} ResourceBundle;

ResourceBundle* loadResourceBundle(const char *source, size_t maxItems) {
    ResourceBundle *bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    bundle->keys = (char**)calloc(maxItems, sizeof(char*));
    bundle->values = (char**)calloc(maxItems, sizeof(char*));
    bundle->count = 0;
    bundle->capacity = maxItems;
    pthread_mutex_init(&bundle->lock, NULL);

    // Simulate loading from a file or network stream
    FILE *file = fopen(source, "r");
    if (!file) {
        perror("Failed to open resource bundle source");
        free(bundle);
        return NULL;
    }

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        if (bundle->count >= bundle->capacity) {
            // Handle truncation
            break;
        }
        size_t len = strlen(buffer);
        if (len > 0 && buffer[len - 1] == '\n') {
            buffer[--len] = '\0';
        }
        bundle->keys[bundle->count] = strdup(buffer);
        fgets(buffer, sizeof(buffer), file);
        bundle->values[bundle->count++] = strdup(buffer);
    }

    fclose(file);

    return bundle;
}

void destroyResourceBundle(ResourceBundle *bundle) {
    for (size_t i = 0; i < bundle->count; ++i) {
        free(bundle->keys[i]);
        free(bundle->values[i]);
    }
    free(bundle->keys);
    free(bundle->values);
    pthread_mutex_destroy(&bundle->lock);
    free(bundle);
}

void *getResource(ResourceBundle *bundle, const char *key) {
    pthread_mutex_lock(&bundle->lock);
    for (size_t i = 0; i < bundle->count; ++i) {
        if (strcmp(bundle->keys[i], key) == 0) {
            pthread_mutex_unlock(&bundle->lock);
            return bundle->values[i];
        }
    }
    pthread_mutex_unlock(&bundle->lock);
    return NULL;
}
