using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class EncryptionLibrary
{
    private readonly string _key;
    private readonly byte[] _salt;
    private const int Iterations = 10000;
    private const int KeySize = 256;

    public EncryptionLibrary(string password)
    {
        using (var rng = new RNGCryptoServiceProvider())
        {
            _salt = new byte[16];
            rng.GetBytes(_salt);
        }
        _key = DeriveKey(password, _salt);
    }

    private string DeriveKey(string password, byte[] salt)
    {
        var deriveBytes = new Rfc2898DeriveBytes(password, salt, Iterations);
        return Convert.ToBase64String(deriveBytes.GetBytes(KeySize / 8));
    }

    public byte[] Encrypt(byte[] data)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = Convert.FromBase64String(_key);
            aes.GenerateIV();
            var encryptor = aes.CreateEncryptor(aes.Key, aes.IV);

            using (var ms = new MemoryStream())
            {
                using (var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
                {
                    cs.Write(data, 0, data.Length);
                }
                return ms.ToArray();
            }
        }
    }

    public byte[] Decrypt(byte[] encryptedData)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = Convert.FromBase64String(_key);
            var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

            using (var ms = new MemoryStream(encryptedData))
            {
                using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    return cs.ToArray();
                }
            }
        }
    }
}

// Usage example
class Program
{
    static async Task Main(string[] args)
    {
        var library = new EncryptionLibrary("password123");
        var originalData = Encoding.UTF8.GetBytes("Hello, World!");
        var encryptedData = await Task.Run(() => library.Encrypt(originalData));
        var decryptedData = await Task.Run(() => library.Decrypt(encryptedData));

        Console.WriteLine(Encoding.UTF8.GetString(decryptedData)); // Output: Hello, World!
    }
}
