typedef struct {
    int value;
    char* metadata;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    size_t capacity;
    size_t count;
} record_collection;

record_collection* create_record_collection(size_t max_records) {
    record_collection* collection = (record_collection*)malloc(sizeof(record_collection));
    if (!collection) return NULL;

    collection->offsets = (long*)calloc(max_records, sizeof(long));
    collection->keys = (int*)calloc(max_records, sizeof(int));
    collection->records = (record*)calloc(max_records, sizeof(record));
    collection->capacity = max_records;
    collection->count = 0;

    if (!collection->offsets || !collection->keys || !collection->records) {
        free(collection->offsets);
        free(collection->keys);
        free(collection->records);
        free(collection);
        return NULL;
    }

    return collection;
}

void destroy_record_collection(record_collection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->records[i].metadata);
    }
    free(collection->offsets);
    free(collection->keys);
    free(collection->records);
    free(collection);
}

void initialize_records(record_collection* collection, int min_value, int max_value) {
    for (size_t i = 0; i < collection->capacity; ++i) {
        if (!RAND_int_range(&collection->records[i].value, min_value, max_value)) {
            // Handle error
        }
        collection->records[i].metadata = NULL;
    }
}

int insert_record(record_collection* collection, int key, const char* metadata) {
    if (collection->count >= collection->capacity) return -1; // Error: Collection is full

    size_t index = collection->count++;
    collection->keys[index] = key;

    record* new_record = &collection->records[index];
    new_record->value = collection->records[RAND_int_range(NULL, 0, collection->count)].value;
    if (metadata) {
        new_record->metadata = strdup(metadata);
    } else {
        new_record->metadata = NULL;
    }

    return 0; // Success
}
```

This code provides a basic structure for the record management library. It includes functions to create and destroy the record collection, initialize records with random values, and insert new records into the collection. The actual database integration and error handling are left as an exercise for further development.']

