// Define the caching mechanism
class Cache {
private:
    std::unordered_map<std::string, std::future<std::string>> cache;
    std::mutex mutex;
    std::condition_variable cv;

public:
    std::future<std::string> Get(const std::string& key, const std::function<std::string()>& fetchData) {
        std::lock_guard<std::mutex> lock(mutex);
        if (cache.find(key) == cache.end()) {
            cache[key] = std::async(std::launch::async, fetchData);
            cv.notify_one();
        }
        return cache[key];
    }

    void WaitUntilReady(const std::future<std::string>& future) {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this, &future] { return cache.find(future.get()) != cache.end(); });
    }
};

// Define the library
