};

// Concrete implementation for file source
class FileSource : public DataSource {
public:
    void fetchData(std::shared_ptr<std::vector<int>> data) override {
        // Simulate fetching data from a file
        *data = {1, 2, 3, 4, 5};
    }
};

// Interface for data transformations
class DataTransformation {
public:
    virtual ~DataTransformation() = default;
    virtual void transform(std::shared_ptr<std::vector<int>> data) = 0;
};

// Concrete implementation of a simple transformation
class SimpleFilter : public DataTransformation {
public:
    void transform(std::shared_ptr<std::vector<int>> data) override {
        // Filter out even numbers
        auto it = std::remove_if(data->begin(), data->end(), [](int num) { return num % 2 == 0; });
        data->erase(it, data->end());
    }
};

// Data processing engine class
class DataProcessingEngine {
private:
    std::vector<std::shared_ptr<DataSource>> sources;
    std::vector<std::shared_ptr<DataTransformation>> transformations;
    std::mutex poolMutex;
    std::condition_variable poolCondVar;
    std::vector<std::thread> workerPool;
    int numThreads;

public:
    DataProcessingEngine(int threads = 4) : numThreads(threads), workerPool(threads) {
        // Initialize worker pool
        for (int i = 0; i < threads; ++i) {
            workerPool[i] = std::thread(&DataProcessingEngine::workerThread, this);
        }
    }

    ~DataProcessingEngine() {
        {
            std::unique_lock<std::mutex> lock(poolMutex);
            running = false;
        }
        poolCondVar.notify_all();
        for (auto& thread : workerPool) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void addSource(std::shared_ptr<DataSource> source) {
        std::lock_guard<std::mutex> lock(poolMutex);
        sources.push_back(source);
    }

    void addTransformation(std::shared_ptr<DataTransformation> transformation) {
        std::lock_guard<std::mutex> lock(poolMutex);
        transformations.push_back(transformation);
    }

    void startProcessing() {
        std::vector<int> data;
        for (auto& source : sources) {
            source->fetchData(std::make_shared<std::vector<int>>(data));
        }
        // Submit data to worker pool
        submitData(data);
    }

private:
    bool running = true;

    void workerThread() {
        std::shared_ptr<std::vector<int>> data;
        while (running) {
            {
                std::unique_lock<std::mutex> lock(poolMutex);
                poolCondVar.wait(lock, [this] { return !running || !dataQueue.empty(); });
                if (!dataQueue.empty()) {
                    data = dataQueue.front();
                    dataQueue.pop();
                }
            }
            if (data) {
                for (auto& transformation : transformations) {
                    transformation->transform(data);
                }
            }
        }
    }

    void submitData(std::shared_ptr<std::vector<int>> data) {
        std::lock_guard<std::mutex> lock(poolMutex);
        dataQueue.push(data);
        poolCondVar.notify_one();
    }

    std::queue<std::shared_ptr<std::vector<int>>> dataQueue;
};

int main() {
    DataProcessingEngine engine(2);
    engine.addSource(std::make_shared<FileSource>());
    engine.addTransformation(std::make_shared<SimpleFilter>());
    engine.startProcessing();
    return 0;
}
