using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.IO;
using System.Linq;
using System.Text;

public class DatabaseConnectionPool
{
    private Dictionary<string, Queue<SqlConnection>> connectionPools = new Dictionary<string, Queue<SqlConnection>>();

    public SqlConnection GetConnection(string connectionString)
    {
        if (!connectionPools.ContainsKey(connectionString))
        {
            connectionPools[connectionString] = new Queue<SqlConnection>();
        }

        lock (connectionPools[connectionString])
        {
            if (connectionPools[connectionString].Count > 0)
            {
                return connectionPools[connectionString].Dequeue();
            }
        }

        return new SqlConnection(connectionString);
    }

    public void ReleaseConnection(string connectionString, SqlConnection connection)
    {
        lock (connectionPools[connectionString])
        {
            if (connectionPools[connectionString].Count < 10) // Example threshold
            {
                connectionPools[connectionString].Enqueue(connection);
            }
            else
            {
                connection.Dispose();
            }
        }
    }

    public void AdjustPoolSize(string connectionString, int newPoolSize)
    {
        lock (connectionPools[connectionString])
        {
            while (connectionPools[connectionString].Count > newPoolSize)
            {
                var connection = connectionPools[connectionString].Dequeue();
                connection.Dispose();
            }

            // Logic to create and enqueue new connections if necessary
        }
    }
}

public class CsvProcessor
{
    private readonly DatabaseConnectionPool _dbConnectionPool;
    private readonly ILogger _logger;

    public CsvProcessor(DatabaseConnectionPool dbConnectionPool, ILogger logger)
    {
        _dbConnectionPool = dbConnectionPool;
        _logger = logger;
    }

    public void ProcessCsv(string filePath, string connectionString)
    {
        using (var reader = new StreamReader(filePath))
        using (var connection = _dbConnectionPool.GetConnection(connectionString))
        {
            connection.Open();
            var command = new SqlCommand("INSERT INTO Results (MovingAverage) VALUES (@MovingAverage)", connection);

            while (!reader.EndOfStream)
            {
                var line = reader.ReadLine();
                var values = line.Split(',');

                if (values.Length >= 3)
                {
                    double movingAverage = Convert.ToDouble(values[0]) + Convert.ToDouble(values[1]) + Convert.ToDouble(values[2]);
                    movingAverage /= 3;

                    command.Parameters.Clear();
                    command.Parameters.AddWithValue("@MovingAverage", movingAverage);
                    command.ExecuteNonQuery();

                    _logger.Log($"Processed line: {line}, Moving Average: {movingAverage}");
                }
                else
                {
                    _logger.LogWarning($"Malformed data found: {line}");
                }
            }

            _dbConnectionPool.ReleaseConnection(connectionString, connection);
        }
    }
}

public interface ILogger
{
    void Log(string message);
    void LogWarning(string warning);
}
