using System;
using System.Net.Http;
using System.Threading.Tasks;
using System.Xml.Linq;
using Polly;
using Polly.Retry;
using Polly.CircuitBreaker;

public class XmlParsingService : IDisposable
{
    private readonly HttpClient _httpClient;
    private readonly AsyncRetryPolicy<HttpResponseMessage> _retryPolicy;
    private readonly ICircuitBreaker _circuitBreaker;

    public XmlParsingService()
    {
        _httpClient = new HttpClient();

        var exponentialBackoff = Policy.Backoff.Linear(200, 5000, 3);
        _retryPolicy = exponentialBackoff.RetryAsync(async (response, retryCount) =>
        {
            if (response.IsFailure)
            {
                throw new Exception($"Failed to fetch XML document after {retryCount} retries.");
            }
        });

        _circuitBreaker = Policy.CircuitBreakerAsync(
            async () => await _httpClient.GetAsync("https://api.example.com/xml"),
            onBreak: (ex, retryCount) =>
            {
                // Handle circuit break logic
            },
            onReset: () =>
            {
                // Handle circuit reset logic
            });
    }

    public async Task<XElement> FetchAndParseXmlAsync(string xpathExpression)
    {
        try
        {
            using (_circuitBreaker)
            {
                HttpResponseMessage response = await _retryPolicy.ExecuteAsync(() => _httpClient.GetAsync("https://api.example.com/xml"));
                response.EnsureSuccessStatusCode();
                string xmlContent = await response.Content.ReadAsStringAsync();
                return XElement.Parse(xmlContent).XPathSelectElement(xpathExpression);
            }
        }
        catch (Exception ex)
        {
            // Handle exception and provide fallback logic
            return null;
        }
    }

    public void Dispose()
    {
        _httpClient.Dispose();
    }
}
