use tokio::sync::{mpsc, Mutex};
use reqwest::Client;
use prometheus::{Registry, CounterVec, Opts};
use log4rs::config::{Config, File, Replace, Root};
use cachepot::{Cache, LruEvictionPolicy};

mod event_processor;
mod config;

#[tokio::main]
async fn main() {
    // Initialize logging
    let config = Config {
        root: Root::builder()
            .appender("stdout", Replace(Box::new(log4rs::appenders::console::ConsoleAppender::default())))
            .build(Opts::from_str("info").unwrap())
            .unwrap(),
        appenders: std::collections::HashMap::new(),
    };
    log4rs::init_config(config).unwrap();

    // Initialize metrics
    let registry = Registry::new();
    let event_count = CounterVec::new(
        Opts::new("event_count", "Number of events processed"),
        &["source"],
    )
    .unwrap();
    registry.register_boxed_metric(&event_count);

    // Initialize cache
    let cache = Cache::builder()
        .eviction_policy(LruEvictionPolicy)
        .build();

    // Initialize service components
    let (tx, mut rx) = mpsc::channel(100);
    let client = Client::new();
    let event_processor = event_processor::EventProcessor {
        tx,
        client,
        cache,
        registry: registry.clone(),
    };
    tokio::spawn(event_processor.run());

    // Simulate incoming events
    loop {
        for source in vec!["source1", "source2"] {
            tx.send((source.to_string(), format!("event_{}", source))).await.unwrap();
        }
        tokio::time::sleep(std::time::Duration::from_secs(5)).await;
    }
}

// src/event_processor.rs
pub struct EventProcessor {
    tx: mpsc::Sender<(String, String)>,
    client: Client,
    cache: Cache<String, String>,
    registry: prometheus::Registry,
}

impl EventProcessor {
    pub async fn run(mut self) {
        while let Some((source, event)) = self.rx.recv().await {
            // Process event
            log::info!("Processing event from {}: {}", source, event);
            if let Some(cached_event) = self.cache.get(&event).unwrap() {
                log::debug!("Event {} found in cache", event);
            } else {
                log::debug!("Fetching event {} from source", event);
                // Fetch event from source
                let response = self.client.get(&format!("http://source/{}/{}", source, event)).await.unwrap();
                let fetched_event = response.text().await.unwrap();
                self.cache.put(event.clone(), fetched_event.clone());
            }

            // Record metrics
            self.registry.register_boxed_metric(&event_count);
            *event_count.with_label_values(&[&source]).get() += 1;

            // Send event to next stage
            if let Err(_) = self.tx.send((source, event)).await {
                log::error!("Failed to send event to next stage");
            }
        }
    }
}

// src/config.rs
pub mod config {
    pub fn load_config() -> Result<(), Box<dyn std::error::Error>> {
        // Load configuration from environment variables, properties file, or external system
        Ok(())
    }
}
