async function executeModuleTests(moduleName, tests, blueslip, externalDataSource, performanceMetrics, config) {
  const maxRetries = config.retries || 3;
  let attempts = 0;

  while (attempts < maxRetries) {
    try {
      const module = await loadModuleWithRetry(moduleName, externalDataSource, maxRetries, attempts);
      if (!module) break; // Break if module failed to load

      sortTestsByPriority(tests);

      for (const test of tests) {
        if (!test.dependencies.every(dep => isLoaded(dep))) {
          blueslip.warn('Dependencies not met for ' + test.label);
          continue;
        }

        if (test.externalDependencies.some(dep => !isReachable(dep, externalDataSource))) {
          await waitUntilReachable(test.externalDependencies, externalDataSource);
        }

        console.log('Testing module:', moduleName, '- Test:', test.label);

        const startTime = performance.now();
        try {
          await runTestWithTimeoutAndMetrics(test.testFn, test.timeout, performanceMetrics);
          performanceMetrics.updatePerformance(moduleName, test.label, 'success', performance.now() - startTime);
        } catch (error) {
          blueslip.error('Error in ' + test.label, error);
          performanceMetrics.updatePerformance(moduleName, test.label, 'failure', performance.now() - startTime);
          if (!test.parallel && config.retries > 0) continue; // Retry only non-parallel tests
        }

        if (test.parallel) {
          scheduleParallelTest(test, moduleName, externalDataSource, performanceMetrics, config);
        }
      }

      attempts = maxRetries; // Break the loop on success
    } catch (error) {
      blueslip.error('Failed to load module or run tests', error);
      attempts++;
    }
  }
}

async function loadModuleWithRetry(moduleName, externalDataSource, maxRetries, attempts) {
  const retryDelay = config.retryDelay || 1000;
  while (attempts < maxRetries) {
    try {
      return await require(moduleName);
    } catch (error) {
      blueslip.error('Failed to load module', error);
      attempts++;
      if (attempts >= maxRetries) throw error;
      await new Promise(resolve => setTimeout(resolve, retryDelay));
    }
  }
}

function sortTestsByPriority(tests) {
  tests.sort((a, b) => a.priority - b.priority);
}

async function runTestWithTimeoutAndMetrics(testFn, timeout, performanceMetrics) {
  const startTime = performance.now();
  return new Promise((resolve, reject) => {
    if (timeout) {
      setTimeout(() => {
        blueslip.warn('Test exceeded timeout');
        reject(new Error('Test timed out'));
      }, timeout);
    }
    testFn().then(resolve).catch(reject);
  });
}

async function waitUntilReachable(dependencies, externalDataSource) {
  const checkDelay = config.checkDelay || 100;
  while (true) {
    if (dependencies.every(dep => isReachable(dep, externalDataSource))) break;
    await new Promise(resolve => setTimeout(resolve, checkDelay));
  }
}

