        : maxRetries(maxRetries), retryInterval(retryInterval) {}

    void processCSV(const std::string& filePath) {
        std::ifstream file(filePath);
        if (!file.is_open()) {
            std::cerr << "Failed to open file: " << filePath << std::endl;
            return;
        }

        std::vector<std::thread> threads;
        int threadCount = 4; // Example number of threads
        for (int i = 0; i < threadCount; ++i) {
            threads.emplace_back(&SensorDataProcessor::processFileChunk, this, &file);
        }

        for (auto& t : threads) {
            t.join();
        }
    }

private:
    void processFileChunk(std::ifstream* file) {
        std::string line;
        while (std::getline(*file, line)) {
            // Process each line using a worker function
            worker(line);
        }
    }

    void worker(const std::string& data) {
        for (int attempt = 0; attempt < maxRetries; ++attempt) {
            try {
                if (validateData(data)) {
                    archiveData(data);
                    break;
                } else {
                    // Handle errors using circuit breaker logic
                    std::this_thread::sleep_for(retryInterval);
                }
            } catch (...) {
                // Log error and retry
                std::cerr << "Error processing data: " << data << std::endl;
                std::this_thread::sleep_for(retryInterval);
            }
