fn build_and_log(project_dir: &Path, log_config_path: &Path, build_config: &BuildConfig) -> Result<(), Box<dyn std::error::Error>> {
    let system = Arc::new(Mutex::new(sysinfo::System::new_all()));
    let (tx, rx) = channel::bounded(10);

    for entry in project_dir.read_dir()? {
        let path = entry?.path();
        if path.is_dir() && path.ends_with(".rs") {
            // Start a new build task
            std::thread::spawn(move || {
                let start_time = Instant::now();
                let exit_code = execute_build_command(&build_config, &path);
                let end_time = Instant::now();
                let memory_usage = get_memory_usage(&system);
                let cpu_utilization = get_cpu_utilization(&system);

                tx.send(BuildMetrics {
                    start_time,
                    end_time,
                    exit_code,
                    memory_usage,
                    cpu_utilization,
                }).unwrap();
            });
        }
    }

    while let Some(metrics) = rx.recv() {
        log_build_metrics(&log_config_path, &metrics);
    }

    Ok(())
