import requests
from tenacity import retry, stop_after_attempt, wait_exponential
import threading
import logging
from collections import defaultdict
import time

# Mocked services for demonstration purposes
class PaymentGateway:
    def charge(self, order_id, amount):
        print(f"Processing payment for order {order_id} with amount {amount}")
        return True

class FulfillmentCenterAPI:
    def ship_order(self, order_id):
        print(f"Shipping order {order_id}")
        return True

class NotificationService:
    def notify_customer(self, order_id):
        print(f"Notifying customer about order {order_id}")

# Caching mechanism for inventory
inventory_cache = defaultdict(int)

@retry(stop=stop_after_attempt(5), wait=wait_exponential(multiplier=1, min=2, max=30))
def call_service(service_func, *args, **kwargs):
    return service_func(*args, **kwargs)

def batchProcessOrders(order_batch):
    payment_gateway = PaymentGateway()
    fulfillment_center = FulfillmentCenterAPI()
    notification_service = NotificationService()

    for order_id in order_batch:
        try:
            # Update inventory
            if inventory_cache[order_id] > 0:
                inventory_cache[order_id] -= 1
            else:
                raise Exception(f"Insufficient inventory for order {order_id}")

            # Apply discount (simple example)
            discounted_amount = calculate_discounted_amount(order_id)

            # Process payment
            if not call_service(payment_gateway.charge, order_id, discounted_amount):
                raise Exception(f"Failed to process payment for order {order_id}")

            # Ship the order
            if not call_service(fulfillment_center.ship_order, order_id):
                raise Exception(f"Failed to ship order {order_id}")

            # Notify customer
            call_service(notification_service.notify_customer, order_id)

        except Exception as e:
            logging.error(f"Error processing order {order_id}: {e}")
            continue

def calculate_discounted_amount(order_id):
    # Simple discount logic (10% off)
    return 0.9 * get_order_total(order_id)

def get_order_total(order_id):
    # Simulated function to get the total amount of an order
    return 100

# Example usage
order_batch = [1, 2, 3, 4, 5]
batchProcessOrders(order_batch)
