    Octree() : root(new Node()) {}

    ~Octree() {
        delete root;
    }

    void insert(int value) {
        std::lock_guard<std::mutex> guard(lock);
        root->insert(value);
    }

    bool query(int value) const {
        std::lock_guard<std::mutex> guard(lock);
        return root->query(value);
    }
};

