using System;
using System.Collections.Concurrent;

public class DynamicRandomValueGenerator
{
    private double minValue;
    private double maxValue;
    private Random random;
    private ConcurrentDictionary<string, object> configurationLock = new ConcurrentDictionary<string, object>();

    public DynamicRandomValueGenerator(double minValue, double maxValue)
    {
        if (minValue >= maxValue)
        {
            throw new ArgumentException("Min value must be less than max value.");
        }
        this.minValue = minValue;
        this.maxValue = maxValue;
        random = new Random();
    }

    public float GetRandomFloat()
    {
        return (float)(minValue + (maxValue - minValue) * random.NextDouble());
    }

    public float GetRandomExclusiveFloat(double exclusiveMax)
    {
        if (exclusiveMax <= minValue)
        {
            throw new ArgumentException("Exclusive max must be greater than min value.");
        }
        return (float)(minValue + (exclusiveMax - minValue) * random.NextDouble());
    }

    public int GetRandomInt()
    {
        try
        {
            return Convert.ToInt32(minValue) + random.Next(Convert.ToInt32(maxValue - minValue) + 1);
        }
        catch (OverflowException)
        {
            throw new ArgumentException("Range exceeds int capacity.");
        }
    }

    public int GetRandomExclusiveInt(int exclusiveMax)
    {
        if (exclusiveMax <= Convert.ToInt32(minValue))
        {
            throw new ArgumentException("Exclusive max must be greater than min value.");
        }
        try
        {
            return Convert.ToInt32(minValue) + random.Next(Convert.ToInt32(exclusiveMax - minValue));
        }
        catch (OverflowException)
        {
            throw new ArgumentException("Range exceeds int capacity.");
        }
    }

    public void UpdateConfiguration(double newMinValue, double newMaxValue)
    {
        if (newMinValue >= newMaxValue)
        {
            throw new ArgumentException("New min value must be less than new max value.");
        }
        minValue = newMinValue;
        maxValue = newMaxValue;
    }
}
