#include <unordered_map>
#include <atomic>

// Define the data record structure
struct DataRecord {
    std::string sourceIP;
    std::chrono::time_point<std::chrono::system_clock> timestamp;
    std::string eventType;
    std::unordered_map<std::string, std::string> contextFields;
};

// Define a class for data ingestion and processing
class DataAnalyticsLibrary {
public:
    DataAnalyticsLibrary(size_t numThreads) : stop(false), threadCount(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back(&DataAnalyticsLibrary::workerThread, this);
        }
    }

    ~DataAnalyticsLibrary() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void ingestData(const DataRecord& record) {
        {
            std::lock_guard<std::mutex> lock(mutex);
            dataQueue.push(record);
        }
        condition.notify_one();
    }

private:
    void workerThread() {
        while (true) {
            DataRecord record;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condition.wait(lock, [this] { return stop || !dataQueue.empty(); });
                if (stop && dataQueue.empty()) {
                    return;
                }
                record = dataQueue.front();
                dataQueue.pop();
            }

            // Process the data record
            processData(record);
        }
    }

    void processData(const DataRecord& record) {
        // Perform data transformation and enrichment here
        std::cout << "Processing data: Source IP - " << record.sourceIP 
                  << ", Timestamp - " << record.timestamp 
                  << ", Event Type - " << record.eventType << std::endl;
    }

    std::mutex mutex;
    std::condition_variable condition;
    std::queue<DataRecord> dataQueue;
    std::vector<std::thread> workers;
    std::atomic<bool> stop;
    size_t threadCount;
};

int main() {
    DataAnalyticsLibrary library(4);

    // Example usage
    DataRecord record = {"192.168.1.1", std::chrono::system_clock::now(), "ERROR", {{"message", "Disk full"}}};
    library.ingestData(record);

    return 0;
}
