void load_config() {
    // Implementation to load config from environment variables or file
    memset(&config, 0, sizeof(config));
    config.use_timestamp = atoi(getenv("USE_TIMESTAMP") ?: "0");
    strcpy(config.template, getenv("FILENAME_TEMPLATE") ?: "%Y%m%d_%s.txt");
}

// Generate a filename based on the configured template
FilenameData generate_filename() {
    pthread_mutex_lock(&lock);
    FilenameData data;
    time_t now = time(NULL);
    struct tm* tm_info = localtime(&now);

    if (config.use_timestamp) {
        strftime(data.filename, MAX_FILENAME_LEN, config.template, tm_info);
    } else {
        snprintf(data.filename, MAX_FILENAME_LEN, config.template, getpid());
    }

    pthread_mutex_unlock(&lock);
    return data;
}

