            while (running) {
                std::unique_lock<std::mutex> lock(queueMutex);
                cv.wait(lock, [this] { return !queue.empty() || !running; });
                if (!running && queue.empty()) break;
                DataRecord record = queue.front();
                queue.pop();
                lock.unlock();

                ProcessData(record);
            }
        }).detach();
    }

