            modelCache[modelId] = std::make_shared<void>(nullptr); // Replace with actual model loading logic
        }
    }

    void workerThread() {
        while (running.load()) {
            std::string modelId;
            {
                std::unique_lock<std::mutex> lock(cacheMutex);
                cacheCondition.wait(lock, [this] { return !modelCache.empty(); });
                modelId = *modelCache.begin()->first;
