import java.util.concurrent.*;
import java.util.logging.*;

public class JobScheduler {
    private static final Logger LOGGER = Logger.getLogger(JobScheduler.class.getName());
    private final ExecutorService executor;
    private final BlockingQueue<Runnable> jobQueue;
    private final int maxConcurrency;
    private final int maxRetries;

    public JobScheduler(int maxConcurrency, int maxRetries) {
        this.maxConcurrency = maxConcurrency;
        this.maxRetries = maxRetries;
        this.jobQueue = new LinkedBlockingQueue<>();
        this.executor = Executors.newFixedThreadPool(maxConcurrency);
        Runtime.getRuntime().addShutdownHook(new Thread(this::shutdown));
    }

    public void submitJob(Runnable task) {
        try {
            jobQueue.put(task);
        } catch (InterruptedException e) {
            LOGGER.log(Level.SEVERE, "Failed to submit job", e);
        }
    }

    private void processJobs() {
        while (true) {
            Runnable task = null;
            try {
                task = jobQueue.take();
                executor.submit(() -> executeTaskWithRetry(task));
            } catch (InterruptedException e) {
                LOGGER.log(Level.SEVERE, "Job processing interrupted", e);
                Thread.currentThread().interrupt();
            }
        }
    }

    private void executeTaskWithRetry(Runnable task) {
        for (int attempt = 0; attempt <= maxRetries; attempt++) {
            try {
                long startTime = System.currentTimeMillis();
                task.run();
                long executionTime = System.currentTimeMillis() - startTime;
                LOGGER.log(Level.INFO, "Job executed successfully in {0} ms", executionTime);
                return;
            } catch (Exception e) {
                if (attempt == maxRetries) {
                    LOGGER.log(Level.SEVERE, "Job failed after {1} retries due to {2}", new Object[]{maxRetries, task.getClass().getSimpleName(), e.getMessage()});
                } else {
                    LOGGER.log(Level.WARNING, "Job attempt {0} failed: {1}", new Object[]{attempt + 1, e.getMessage()});
                }
            }
        }
    }

    private void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    public static void main(String[] args) {
        JobScheduler scheduler = new JobScheduler(10, 3);
        for (int i = 0; i < 20; i++) {
            scheduler.submitJob(new FileDeletionTask("file" + i));
        }
        new Thread(scheduler::processJobs).start();
    }

    static class FileDeletionTask implements Runnable {
        private final String fileName;

        public FileDeletionTask(String fileName) {
            this.fileName = fileName;
        }

        @Override
        public void run() {
            // Simulate file deletion
            LOGGER.log(Level.INFO, "Deleting file: {0}", fileName);
            try {
                Thread.sleep(1000); // Simulate time taken for deletion
            } catch (InterruptedException e) {
                LOGGER.log(Level.WARNING, "File deletion interrupted", e);
            }
        }

        @Override
        public String toString() {
            return getClass().getSimpleName() + "[" + fileName + "]";
        }
    }
}
```

This code provides a basic structure for the JobScheduler class. It uses an `ExecutorService` to manage concurrent tasks and a `BlockingQueue` to store job requests. The scheduler processes jobs by continuously taking tasks from the queue and submitting them to the executor. Each task is retried up to a configurable maximum number of times if it fails due to transient issues.

The FileDeletionTask class demonstrates how a job can be implemented, simulating file deletion with a sleep. The main method initializes the scheduler with a maximum concurrency level and number of retries, submits several tasks, and starts the job processing loop in a separate thread.']

