using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class TripleDESDecryptor
{
    private static readonly ConcurrentDictionary<string, ICryptoTransform> _decryptors = new ConcurrentDictionary<string, ICryptoTransform>();
    private static readonly HttpClient _httpClient = new HttpClient();
    private static readonly ILogger _logger = LoggerFactory.Create();

    public string Decrypt(string base64Message)
    {
        try
        {
            var key = GetKeyFromService();
            var iv = GetIVFromService();
            var decryptor = _decryptors.GetOrAdd($"{key}_{iv}", k => CreateDecryptor(key, iv));

            using (var ms = new MemoryStream(Convert.FromBase64String(base64Message)))
            using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
            using (var sr = new StreamReader(cs))
            {
                return sr.ReadToEnd();
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to decrypt message");
            throw;
        }
    }

    private byte[] GetKeyFromService()
    {
        // Simulate fetching key from cloud service
        var response = _httpClient.GetAsync("https://configservice/key").Result;
        return Encoding.UTF8.GetBytes(response.Content.ReadAsStringAsync().Result);
    }

    private byte[] GetIVFromService()
    {
        // Simulate fetching IV from cloud service
        var response = _httpClient.GetAsync("https://configservice/iv").Result;
        return Encoding.UTF8.GetBytes(response.Content.ReadAsStringAsync().Result);
    }

    private ICryptoTransform CreateDecryptor(byte[] key, byte[] iv)
    {
        using (var tdes = TripleDES.Create())
        {
            tdes.Key = key;
            tdes.IV = iv;
            return tdes.CreateDecryptor();
        }
    }
}

public class IntegerProcessor
{
    private readonly TripleDESDecryptor _decryptor;

    public IntegerProcessor(TripleDESDecryptor decryptor)
    {
        _decryptor = decryptor;
    }

    public int Process(int input)
    {
        // Simulate integer processing logic
        return input * 2; // Example operation
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        var decryptor = new TripleDESDecryptor();
        var processor = new IntegerProcessor(decryptor);

        while (true)
        {
            Console.WriteLine("Enter Base64-encoded message to decrypt:");
            string base64Message = Console.ReadLine();

            try
            {
                string decryptedMessage = decryptor.Decrypt(base64Message);
                int processedInteger = processor.Process(Convert.ToInt32(decryptedMessage));

                Console.WriteLine($"Decrypted and processed integer: {processedInteger}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing input: {ex.Message}");
            }

            Console.WriteLine("Press any key to continue or 'q' to quit...");
            if (Console.ReadKey(true).KeyChar == 'q')
            {
                break;
            }
        }
    }
