import json

class JSONManager:
    _registry = {}

    @staticmethod
    def register(id, factory_function):
        JSONManager._registry[id] = factory_function

    @staticmethod
    def from_json(json_data):
        data = json.loads(json_data)
        id = data['id']
        if id in JSONManager._registry:
            return JSONManager._registry[id](data)
        raise ValueError(f"No factory function registered for ID: {id}")

    @staticmethod
    def to_json(obj):
        return json.dumps(obj.__dict__)

class ExampleSubclass(JSONManager):
    def __init__(self, data):
        self.value = data['value']

# Register the subclass with an ID
JSONManager.register('example', lambda data: ExampleSubclass(data))

# Example usage
json_data = '{"id": "example", "value": 42}'
obj = JSONManager.from_json(json_data)
print(f"Value from JSON: {obj.value}")
