import threading
import time
from flask import Flask, request, jsonify
from kafka import KafkaProducer
from redis import Redis
from pympler import muppy, summary
import psutil

app = Flask(__name__)
producer = KafkaProducer(bootstrap_servers='localhost:9092')
redis_client = Redis(host='localhost', port=6379, db=0)
cache_timeout = 300  # Cache timeout in seconds

def process_transaction(transaction):
    try:
        # Simulate transaction processing
        time.sleep(1)
        return "Transaction processed successfully"
    except Exception as e:
        handle_error(e)

def handle_error(error):
    # Log error and perform fallback strategy if necessary
    app.logger.error(f"Error processing transaction: {error}")
    return jsonify({"error": str(error)}), 500

@app.route('/process', methods=['POST'])
def process():
    transaction_data = request.json
    if 'amount' not in transaction_data or 'currency' not in transaction_data:
        return jsonify({"error": "Missing required fields"}), 400

    result = redis_client.get(transaction_data['amount'] + transaction_data['currency'])
    if result is None:
        result = process_transaction(transaction_data)
        redis_client.setex(transaction_data['amount'] + transaction_data['currency'], cache_timeout, result)

    return jsonify({"result": result})

@app.route('/memory_usage', methods=['GET'])
def memory_usage():
    all_objects = muppy.get_objects()
    sum1 = summary.summarize(all_objects)
    sorted_stats = summary.sort_stats('lineno')
    sorted_stats.print_stats(10)  # Print top 10 memory-consuming lines
    return jsonify({"memory_usage": psutil.virtual_memory().percent})

@app.route('/cpu_usage', methods=['GET'])
def cpu_usage():
    return jsonify({"cpu_usage": psutil.cpu_percent()})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=True)
