using Polly.Retry;

namespace StateMachineLibrary
{
    public class FsaManager : IFsaManager
    {
        private readonly HttpClient _httpClient;
        private readonly IMemoryCache _cache;
        private readonly IRetryPolicy _retryPolicy;
        private readonly byte[] _encryptionKey;
        private readonly byte[] _iv;

        public FsaManager(HttpClient httpClient, IMemoryCache cache)
        {
            _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
            _cache = cache ?? throw new ArgumentNullException(nameof(cache));

            // Initialize AES-CBC key and IV
            _encryptionKey = Encoding.UTF8.GetBytes("YourEncryptionKeyHere");
            _iv = Encoding.UTF8.GetBytes("YourInitializationVectorHere");

            _retryPolicy = Policy.Handle<HttpRequestException>()
                .WaitAndRetryAsync(5, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));
        }

        public async Task<State> ProcessStateTransition(string currentState, string input)
        {
            var nextState = await GetNextState(currentState, input);
            return nextState;
        }

        private async Task<State> GetNextState(string currentState, string input)
        {
            // Simulate state transition logic
            if (currentState == "A" && input == "x")
                return new State { Id = "B", Data = await GetDataFromExternalSource() };

            throw new InvalidOperationException("Invalid state transition");
        }

        private async Task<string> GetDataFromExternalSource()
        {
            var url = "https://api.example.com/data";

            var response = await _retryPolicy.ExecuteAsync(async () =>
            {
                return await _httpClient.GetStringAsync(url);
            });

            // Decrypt and deserialize data
            var decryptedData = await DecryptAndDeserialize(response);

            return decryptedData;
        }

        private async Task<string> DecryptAndDeserialize(string ciphertext)
        {
            using (var aes = Aes.Create())
            {
                aes.Key = _encryptionKey;
                aes.IV = _iv;

                ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

                using (var msDecrypt = new System.IO.MemoryStream(Encoding.UTF8.GetBytes(ciphertext)))
                {
                    using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        using (var reader = new System.IO.StreamReader(csDecrypt))
                        {
                            return await reader.ReadToEndAsync();
                        }
                    }
                }
            }
        }

        public void CacheState(string stateId, State state)
        {
            _cache.Set(stateId, state);
        }

        public State GetCachedState(string stateId)
        {
            if (_cache.TryGetValue(stateId, out var state))
                return state;

            return null;
        }
    }

    public interface IFsaManager
    {
        Task<State> ProcessStateTransition(string currentState, string input);
        void CacheState(string stateId, State state);
        State GetCachedState(string stateId);
    }

    public class State
    {
        public string Id { get; set; }
        public string Data { get; set; }
    }
}
