using System;
using System.Threading.Tasks;

public class DynamicRandomValueGenerator
{
    private double minValue;
    private double maxValue;
    private int minIntValue;
    private int maxIntValue;
    private Random random;

    public DynamicRandomValueGenerator(double minValue, double maxValue, int minIntValue, int maxIntValue)
    {
        if (minValue >= maxValue || minIntValue >= maxIntValue)
            throw new ArgumentException("Invalid range values.");

        this.minValue = minValue;
        this.maxValue = maxValue;
        this.minIntValue = minIntValue;
        this.maxIntValue = maxIntValue;
        this.random = new Random();
    }

    public float GetRandomFloat()
    {
        return (float)(minValue + random.NextDouble() * (maxValue - minValue));
    }

    public float GetRandomExclusiveFloat(double exclusiveMax)
    {
        return (float)(minValue + random.NextDouble() * (exclusiveMax - minValue));
    }

    public int GetRandomInt()
    {
        return minIntValue + random.Next(maxIntValue - minIntValue + 1);
    }

    public int GetRandomExclusiveInt(int exclusiveMax)
    {
        return minIntValue + random.Next(exclusiveMax - minIntValue);
    }
}
