// Define data record structure
struct DataRecord {
    std::string sourceIP;
    int timestamp;
    std::string eventType;
    std::map<std::string, std::string> contextFields;
};

// Thread-safe queue for data records
class SafeQueue {
private:
    std::queue<DataRecord> queue_;
    mutable std::mutex mutex_;
    std::condition_variable cond_;

public:
    void push(const DataRecord& record) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(record);
        cond_.notify_one();
    }

    bool pop(DataRecord& record) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (cond_.wait_for(lock, std::chrono::seconds(1), [this] { return !queue_.empty(); })) {
            record = queue_.front();
            queue_.pop();
            return true;
        }
        return false;
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_.empty();
    }
};

// Data processing function
void processData(const DataRecord& record) {
    // Perform data transformation and enrichment here
    std::cout << "Processing data: " << record.eventType << "\n";
}

// Worker thread function
void workerThread(SafeQueue& queue) {
    while (true) {
        DataRecord record;
        if (queue.pop(record)) {
            processData(record);
        }
    }
}

int main() {
    const int numThreads = 4;
    SafeQueue dataQueue;

    // Start worker threads
    std::vector<std::thread> workers;
    for (int i = 0; i < numThreads; ++i) {
        workers.emplace_back(workerThread, std::ref(dataQueue));
    }

    // Simulate data ingestion from multiple sources
    for (int i = 0; i < 100; ++i) {
        DataRecord record;
        record.sourceIP = "192.168.1." + std::to_string(i);
        record.timestamp = i * 1000;
        record.eventType = "Event" + std::to_string(i % 5);
        dataQueue.push(record);
    }

    // Join worker threads
    for (auto& thread : workers) {
        thread.join();
    }

    return 0;
}
