using System;
using System.Threading;

public class DynamicRandomValueGenerator
{
    private float minValue;
    private float maxValue;
    private int minIntValue;
    private int maxIntValue;
    private Random[] threadLocalRandoms;

    public DynamicRandomValueGenerator(float minValue, float maxValue, int minIntValue, int maxIntValue)
    {
        if (minValue >= maxValue || minIntValue >= maxIntValue)
            throw new ArgumentException("Invalid range values.");

        this.minValue = minValue;
        this.maxValue = maxValue;
        this.minIntValue = minIntValue;
        this.maxIntValue = maxIntValue;

        int threadCount = Environment.ProcessorCount;
        threadLocalRandoms = new Random[threadCount];
        for (int i = 0; i < threadCount; i++)
        {
            threadLocalRandoms[i] = new Random();
        }
    }

    public float GetRandomFloat()
    {
        int threadIndex = Thread.CurrentThread.ManagedThreadId % threadLocalRandoms.Length;
        return threadLocalRandoms[threadIndex].NextSingle(minValue, maxValue);
    }

    public float GetRandomExclusiveFloat(double exclusiveMax)
    {
        if (exclusiveMax <= minValue || exclusiveMax > maxValue)
            throw new ArgumentException("Invalid exclusive max value.");

        int threadIndex = Thread.CurrentThread.ManagedThreadId % threadLocalRandoms.Length;
        return threadLocalRandoms[threadIndex].NextSingle(minValue, (float)exclusiveMax);
    }

    public int GetRandomInt()
    {
        int threadIndex = Thread.CurrentThread.ManagedThreadId % threadLocalRandoms.Length;
        return threadLocalRandoms[threadIndex].Next(minIntValue, maxIntValue + 1);
    }

    public int GetRandomExclusiveInt(int exclusiveMax)
    {
        if (exclusiveMax <= minIntValue || exclusiveMax > maxIntValue)
            throw new ArgumentException("Invalid exclusive max value.");

        int threadIndex = Thread.CurrentThread.ManagedThreadId % threadLocalRandoms.Length;
        return threadLocalRandoms[threadIndex].Next(minIntValue, exclusiveMax);
    }
}
