using System;
using System.Text;
using System.Security.Cryptography;

public class MD5HashGenerator
{
    public static string GetMD5Hash(string input)
    {
        // Create a new instance of the MD5CryptoServiceProvider, which provides the MD5 hashing algorithm.
        using (MD5 md5 = MD5.Create())
        {
            // Convert the input string to a byte array and compute the hash.
            byte[] inputBytes = Encoding.ASCII.GetBytes(input);
            byte[] hashBytes = md5.ComputeHash(inputBytes);

            // Create a new StringBuilder to collect the bytes and create a string.
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < hashBytes.Length; i++)
            {
                sb.Append(hashBytes[i].ToString("x2"));
            }
            return sb.ToString();
        }
    }

    public static void Main()
    {
        // Example usage:
        string input = "Hello, World!";
        string hash = GetMD5Hash(input);
        Console.WriteLine($"MD5 hash of '{input}': {hash}");
    }
}
```

### Explanation:

1. **MD5CryptoServiceProvider**: This class is used to provide the MD5 hashing algorithm.
2. **Encoding.ASCII.GetBytes(input)**: Converts the input string into a byte array.
3. **md5.ComputeHash(inputBytes)**: Computes the hash of the input byte array.
4. **StringBuilder**: Used to convert the hash byte array into a hexadecimal string.

