class IoTMonitoringLibrary {
public:
    IoTMonitoringLibrary(size_t maxQueueSize) : running(true), maxQueueSize(maxQueueSize) {}

    void start() {
        workerThread = std::thread(&IoTMonitoringLibrary::processData, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            running = false;
        }
        condition.notify_all();
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }

    bool enqueue(const std::string& deviceID, const std::string& timestamp, 
                 const std::string& metricName, double value, const std::string& unit,
                 const std::string& locationFields) {
        std::unique_lock<std::mutex> lock(mutex);
        if (queue.size() >= maxQueueSize) {
            return false; // Queue is full
        }
        queue.push({deviceID, timestamp, metricName, value, unit, locationFields});
        condition.notify_one();
        return true;
    }

private:
    struct DataRecord {
        std::string deviceID;
        std::string timestamp;
        std::string metricName;
        double value;
        std::string unit;
        std::string locationFields;
    };

    void processData() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !queue.empty() || !running; });
            if (!running && queue.empty()) {
                break;
            }
            DataRecord record = queue.front();
            queue.pop();
            lock.unlock();

            // Process the data
            process(record);
        }
    }

    void process(const DataRecord& record) {
        // Implement data processing logic here
        std::cout << "Processing: " << record.deviceID << ", " << record.timestamp 
                  << ", " << record.metricName << ", " << record.value << ", " 
                  << record.unit << ", " << record.locationFields << std::endl;
    }

    std::thread workerThread;
    std::queue<DataRecord> queue;
    std::mutex mutex;
    std::condition_variable condition;
    bool running;
    size_t maxQueueSize;
};

int main() {
    IoTMonitoringLibrary library(100);
    library.start();

    // Simulate data ingestion
    for (size_t i = 0; i < 200; ++i) {
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
        library.enqueue("device" + std::to_string(i % 10), 
                        std::to_string(std::time(nullptr)), "metric", i, "unit", "location");
    }

    library.stop();
    return 0;
}
```

