#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_FILENAME_LENGTH 256

typedef struct {
    char template_path[MAX_FILENAME_LENGTH];
    int rotation_size;
    int max_versions;
    pthread_mutex_t lock;
} FilenameGenerator;

FilenameGenerator generator = {0};

void* generate_filename(void* arg) {
    pthread_mutex_lock(&generator.lock);
    time_t now = time(NULL);
    char timestamp[9];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d", localtime(&now));

    char filename[MAX_FILENAME_LENGTH];
    snprintf(filename, sizeof(filename), "%s/%s.log", generator.template_path, timestamp);

    pthread_mutex_unlock(&generator.lock);
    return filename;
}

void init_generator(const char* template_path, int rotation_size, int max_versions) {
    strncpy(generator.template_path, template_path, MAX_FILENAME_LENGTH - 1);
    generator.rotation_size = rotation_size;
    generator.max_versions = max_versions;
    pthread_mutex_init(&generator.lock, NULL);
}

int main() {
    init_generator("/var/log", 1024 * 1024, 5);

    for (int i = 0; i < 10; ++i) {
        char* filename = generate_filename(NULL);
        printf("Generated Filename: %s\n", filename);
        free(filename); // Assuming the function returns a dynamically allocated string
    }

    pthread_mutex_destroy(&generator.lock);
    return 0;
}
```

