        } catch (IOException e) {
            throw new RuntimeException("Failed to save event to database", e);
        }
    }

    private void handleException(Exception e, ConsumerRecord<String, String> record) {
        if (e instanceof TransientFailureException) {
            // Retry mechanism with exponential backoff
            retryProcessing(record);
        } else {
            // Log error and alert system
        }
    }

    private void retryProcessing(ConsumerRecord<String, String> record) {
        try {
            TimeUnit.SECONDS.sleep((long) Math.pow(2, record.headers().lastHeader("Retry-Count").value()));
            consumer.seekToEnd(java.util.Collections.singletonList(record.topic()), record.partition());
            processEvent(record);
        } catch (InterruptedException ie) {
            Thread.currentThread().interrupt();
        }
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }
