#define MAX_FILENAME_LENGTH 256

void modify_filename(char *original_filename, int digits, const char *file_type) {
    if (original_filename == NULL || file_type == NULL) {
        return;
    }

    size_t len = strlen(original_filename);
    if (len + digits + strlen(file_type) + 1 > MAX_FILENAME_LENGTH) {
        return;
    }

    char new_filename[MAX_FILENAME_LENGTH];
    sprintf(new_filename, "%s%d%s", original_filename, digits, file_type);

    printf("Original Filename: %s\n", original_filename);
    printf("New Filename: %s\n", new_filename);
}

int main() {
    const char *original_filename = "example";
    int digits = 4;
    const char *file_type = ".log";

    modify_filename(original_filename, digits, file_type);

    return 0;
}
