#define SESSION_DB_HOST "localhost"
#define SESSION_DB_PORT 6379

typedef struct {
    char session_id[256];
    char user_data[1024];
} Session;

RedisContext *session_db_context = NULL;
pthread_mutex_t session_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_session_system() {
    // Initialize Redis connection
    session_db_context = redisConnect(SESSION_DB_HOST, SESSION_DB_PORT);
    if (session_db_context == NULL || session_db_context->err) {
        fprintf(stderr, "Failed to connect to Redis: %s\n", session_db_context ? session_db_context->errstr : "Unknown error");
        exit(EXIT_FAILURE);
    }
}

Session* create_session(char* user_data) {
    Session *new_session = (Session*)malloc(sizeof(Session));
    sprintf(new_session->session_id, "%p", new_session); // Use pointer address as unique identifier
    strncpy(new_session->user_data, user_data, sizeof(new_session->user_data) - 1);
    return new_session;
}

void add_session(Session* session) {
    pthread_mutex_lock(&session_mutex);
    redisReply *reply = (redisReply*)redisCommand(session_db_context, "SET %s %s", session->session_id, session->user_data);
    if (reply == NULL || reply->type == REDIS_REPLY_ERROR) {
        printf("Failed to add session: %s\n", reply ? reply->str : "Unknown error");
    } else {
        freeReplyObject(reply);
    }
    pthread_mutex_unlock(&session_mutex);
}

void remove_session(char* session_id) {
    pthread_mutex_lock(&session_mutex);
    redisReply *reply = (redisReply*)redisCommand(session_db_context, "DEL %s", session_id);
    if (reply == NULL || reply->type == REDIS_REPLY_ERROR) {
        printf("Failed to remove session: %s\n", reply ? reply->str : "Unknown error");
    } else {
        freeReplyObject(reply);
    }
    pthread_mutex_unlock(&session_mutex);
}

Session* get_session(char* session_id) {
    pthread_mutex_lock(&session_mutex);
    redisReply *reply = (redisReply*)redisCommand(session_db_context, "GET %s", session_id);
    Session *session = NULL;
    if (reply != NULL && reply->type == REDIS_REPLY_STRING) {
        session = create_session(reply->str);
    } else if (reply != NULL) {
        printf("Failed to get session: %s\n", reply->str);
    }
    freeReplyObject(reply);
    pthread_mutex_unlock(&session_mutex);
    return session;
}

void handle_webhook_update(char* session_id, char* user_data) {
    add_session(create_session(user_data));
}

int main() {
    init_session_system();

    // Example usage
    Session *new_session = create_session("user123");
    add_session(new_session);

    Session *retrieved_session = get_session(new_session->session_id);
    if (retrieved_session != NULL) {
        printf("Retrieved session data: %s\n", retrieved_session->user_data);
        free(retrieved_session);
    }

    remove_session(new_session->session_id);
    free(new_session);

    redisFree(session_db_context);
    return 0;
}
