// resourceLoader.cpp

#include "resourceLoader.hpp"

namespace resourceLoader {

ResourceLoader::ResourceLoader(std::string apiUrl, std::string eventBrokerUrl, size_t maxConnections)
    : apiUrl_(apiUrl), eventBrokerUrl_(eventBrokerUrl), maxConnections_(maxConnections),
      circuitBreaker_(std::make_unique<CircuitBreaker>(CircuitBreaker::RetryPolicy{...})),
      messageBroker_(std::make_unique<MessageBroker>(eventBrokerUrl_)),
      eventHandler_(std::make_unique<EventHandler>()),
      cacheManager_(std::make_unique<CacheManager>()),
      dataParser_(std::make_unique<DataParser>()),
      networkManager_(std::make_unique<NetworkManager>(maxConnections)) {}

ResourceLoader::~ResourceLoader() = default;

std::future<std::shared_ptr<ResourceBundle>> ResourceLoader::fetchResource(const std::string& version) {
    return circuitBreaker_->execute([this, version]() -> std::shared_ptr<ResourceBundle> {
        if (cacheManager_->hasResource(version)) {
            return cacheManager_->getResource(version);
        }
        handleResourceRequest(version);
        return cacheManager_->getResource(version);
    });
}

void ResourceLoader::setRetryPolicy(const CircuitBreaker::RetryPolicy& policy) {
    circuitBreaker_->setRetryPolicy(policy);
}

void ResourceLoader::handleResourceRequest(const std::string& version) {
    try {
        std::shared_ptr<ResourceBundle> resource = networkManager_->fetchResource(apiUrl_, version);
        std::shared_ptr<ResourceBundle> parsedResource = dataParser_->parse(resource);
        cacheManager_->cacheResource(version, parsedResource);
        publishEvent("resource_fetched", version);
    } catch (const NetworkError& e) {
        publishEvent("network_error", e.what());
    } catch (const ParseError& e) {
        publishEvent("parse_error", e.what());
    } catch (const std::bad_alloc& e) {
        publishEvent("memory_error", e.what());
    }
}

void ResourceLoader::publishEvent(const std::string& eventType, const std::string& eventData) {
    eventHandler_->handleEvent(eventType, eventData);
}

} // namespace resourceLoader
```

