// Import necessary libraries and dependencies
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;

public class LogProcessingEngine {

    private ExecutorService processingPool;
    private LinkedBlockingQueue<LogEvent> logQueue;

    public LogProcessingEngine(int numThreads) {
        this.processingPool = Executors.newFixedThreadPool(numThreads);
        this.logQueue = new LinkedBlockingQueue<>();

        // Start worker threads to process logs
        for (int i = 0; i < numThreads; i++) {
            processingPool.submit(new LogProcessor(logQueue));
        }
    }

    public void submitLog(LogEvent logEvent) throws InterruptedException {
        logQueue.put(logEvent); // Blocking operation if queue is full
    }

    private static class LogProcessor implements Runnable {
        private final LinkedBlockingQueue<LogEvent> logQueue;

        public LogProcessor(LinkedBlockingQueue<LogEvent> logQueue) {
            this.logQueue = logQueue;
        }

        @Override
        public void run() {
            while (true) {
                try {
                    LogEvent logEvent = logQueue.take(); // Blocking operation until an event is available
                    processLog(logEvent);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        }

        private void processLog(LogEvent logEvent) {
            // Placeholder for actual log processing logic
            System.out.println("Processing log: " + logEvent.getContent());
        }
    }

    public void shutdown() throws InterruptedException {
        processingPool.shutdown();
        if (!processingPool.awaitTermination(60, TimeUnit.SECONDS)) {
            processingPool.shutdownNow();
        }
    }

    // Define a simple LogEvent class
    static class LogEvent {
        private String content;
        private String source;

        public LogEvent(String content, String source) {
            this.content = content;
            this.source = source;
        }

        public String getContent() {
            return content;
        }

        public String getSource() {
            return source;
        }
    }

    // Main method to demonstrate usage
    public static void main(String[] args) throws InterruptedException {
        LogProcessingEngine engine = new LogProcessingEngine(10);

        for (int i = 0; i < 100; i++) {
            engine.submitLog(new LogEvent("Log message " + i, "Source-" + (i % 5)));
        }

        engine.shutdown();
    }
}
