using System;
using System.Threading;

public class DynamicRandomValueGenerator
{
    private readonly float minValue;
    private readonly float maxValue;
    private readonly int minIntValue;
    private readonly int maxIntValue;
    private readonly ThreadLocal<Random> random = new ThreadLocal<Random>(() => new Random());

    public DynamicRandomValueGenerator(float minValue, float maxValue, int minIntValue, int maxIntValue)
    {
        if (minValue >= maxValue || minIntValue >= maxIntValue)
            throw new ArgumentException("Invalid range values");

        this.minValue = minValue;
        this.maxValue = maxValue;
        this.minIntValue = minIntValue;
        this.maxIntValue = maxIntValue;
    }

    public float GetRandomFloat()
    {
        return (float)random.Value.NextDouble() * (maxValue - minValue) + minValue;
    }

    public float GetRandomExclusiveFloat(float exclusiveMax)
    {
        if (exclusiveMax <= minValue || exclusiveMax >= maxValue)
            throw new ArgumentException("Invalid exclusive max value");

        return (float)random.Value.NextDouble() * (exclusiveMax - minValue) + minValue;
    }

    public int GetRandomInt()
    {
        return random.Value.Next(minIntValue, maxIntValue + 1);
    }

    public int GetRandomExclusiveInt(int exclusiveMax)
    {
        if (exclusiveMax <= minIntValue || exclusiveMax >= maxIntValue)
            throw new ArgumentException("Invalid exclusive max value");

        return random.Value.Next(minIntValue, exclusiveMax);
    }
}
