#include <atomic>
#include <chrono>
#include <random>
#include <mutex>
#include <condition_variable>

class CombatSystem {
private:
    std::atomic<int> fatigueLevel;
    std::mutex cooldownMutex;
    std::condition_variable cooldownCV;
    std::vector<std::pair<int, int>> attacks; // attack ID and cooldown
    std::mt19937 randomGenerator;

public:
    CombatSystem() : fatigueLevel(50), randomGenerator(std::random_device{}()) {
        // Initialize attack database and other resources
    }

    bool canAttack(int attackID) {
        std::lock_guard<std::mutex> lock(cooldownMutex);
        auto it = std::find_if(attacks.begin(), attacks.end(), [attackID](const auto& p){ return p.first == attackID; });
        if (it != attacks.end()) {
            int currentTime = std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch()).count();
            if (currentTime - it->second > 5) { // Minimum cooldown of 5 seconds
                it->second = currentTime;
                return true;
            }
        }
        return false;
    }

    void attack(int attackID) {
        std::lock_guard<std::mutex> lock(cooldownMutex);
        auto it = std::find_if(attacks.begin(), attacks.end(), [attackID](const auto& p){ return p.first == attackID; });
        if (it != attacks.end()) {
            int currentTime = std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch()).count();
            it->second = currentTime;
            fatigueLevel += randomGenerator() % 5 + 1;
            if (fatigueLevel > 100) fatigueLevel = 100;
        }
    }

    void updateFatigue(int amount) {
        std::lock_guard<std::mutex> lock(cooldownMutex);
        fatigueLevel -= amount;
        if (fatigueLevel < 5) fatigueLevel = 5;
        cooldownCV.notify_all();
    }

    void run() {
        while (true) {
            std::unique_lock<std::mutex> lock(cooldownMutex);
            cooldownCV.wait_for(lock, std::chrono::seconds(1), [this]{ return canAttack(std::rand()); });
            int attackID = std::rand() % attacks.size();
            if (canAttack(attackID)) {
                attack(attackID);
                // Log attack details
            }
        }
    }
};

int main() {
    CombatSystem combatSystem;
    combatSystem.run();
    return 0;
}
