class DynamicInventoryManager {
public:
    void acquireItem(int itemId) {
        std::lock_guard<std::mutex> lock(mutex_);
        inventory_[itemId]++;
        logAction("Acquired", itemId);
    }

    void useItem(int itemId) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (inventory_[itemId] > 0) {
            inventory_[itemId]--;
            logAction("Used", itemId);
        } else {
            std::cerr << "Item not found or out of stock: " << itemId << std::endl;
        }
    }

    void startSynchronization() {
        synchronizationThread_ = std::thread(&DynamicInventoryManager::synchronize, this);
    }

private:
    std::mutex mutex_;
    std::unordered_map<int, int> inventory_;
    std::queue<std::pair<int, std::string>> logQueue_;
    std::condition_variable notEmpty_;
    std::thread synchronizationThread_;

    void synchronize() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            notEmpty_.wait(lock, [this] { return !logQueue_.empty(); });
            auto action = logQueue_.front();
            logQueue_.pop();
            lock.unlock();

            // Simulate network delay
            std::this_thread::sleep_for(std::chrono::milliseconds(100));

            // Log the action to a distributed logging service
            logAction(action.second, action.first);
        }
    }

    void logAction(const std::string& action, int itemId) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::cout << "InventoryManager: " << action << " item " << itemId << std::endl;
        logQueue_.push({itemId, action});
        notEmpty_.notify_one();
    }
};
```

