#include <iostream>
#include <thread>
#include <vector>
#include <atomic>
#include <mutex>
#include <condition_variable>
#include <unordered_map>
#include <queue>
#include <memory>

// Define the DataRecord structure to hold data record metadata and context-specific fields.
struct DataRecord {
    std::string sourceIP;
    long timestamp;
    std::string eventType;
    // Additional context-specific fields can be added here.
};

// Define a highly available, scalable event-driven architecture using a message queue system.
class EventDrivenArchitecture {
public:
    void subscribe(std::function<void(const DataRecord&)> callback) {
        callbacks_.push_back(callback);
    }

    void publish(const DataRecord& dataRecord) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(dataRecord);
        condition_variable_.notify_one();
    }

private:
    std::vector<std::function<void(const DataRecord&)>> callbacks_;
    std::queue<DataRecord> queue_;
    std::mutex mutex_;
    std::condition_variable condition_variable_;

    // Worker thread function to handle data records.
    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_variable_.wait(lock, [this] { return !queue_.empty(); });
            DataRecord dataRecord = queue_.front();
            queue_.pop();
            lock.unlock();

            // Notify all subscribers.
            for (auto& callback : callbacks_) {
                callback(dataRecord);
            }
        }
    }

    std::vector<std::thread> workers_;
};

// Define a class to handle data ingestion and processing.
class DataIngestion {
public:
    DataIngestion(int numThreads) {
        for (int i = 0; i < numThreads; ++i) {
            workers_.emplace_back(&DataIngestion::worker, this);
        }
    }

    ~DataIngestion() {
