#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <future>
#include <json/json.h>

class Task {
public:
    virtual void execute() = 0;
    virtual ~Task() {}
};

class BatchProcessor {
private:
    std::queue<std::shared_ptr<Task>> taskQueue;
    std::vector<std::thread> workerThreads;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool stop;

public:
    BatchProcessor(size_t numThreads) : stop(false) {
        for (size_t i = 0; i < numThreads; ++i) {
            workerThreads.emplace_back([this] {
                while (true) {
                    std::shared_ptr<Task> task;
                    {
                        std::unique_lock<std::mutex> lock(queueMutex);
                        condition.wait(lock, [this] { return stop || !taskQueue.empty(); });
                        if (stop && taskQueue.empty()) {
                            break;
                        }
                        task = std::move(taskQueue.front());
                        taskQueue.pop();
                    }
                    task->execute();
                }
            });
        }
    }

    ~BatchProcessor() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
        for (auto& thread : workerThreads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    void addTask(std::shared_ptr<Task> task) {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            taskQueue.push(task);
        }
        condition.notify_one();
    }
};

class TransformTask : public Task {
private:
    Json::Value record;
    std::function<void(Json::Value&)> transformation;

public:
    TransformTask(Json::Value record, std::function<void(Json::Value&)>& transformation)
        : record(record), transformation(transformation) {}

    void execute() override {
        transformation(record);
        // Further processing or storage
    }
};

int main() {
    BatchProcessor processor(4);

    Json::Value record1;
    record1["field"] = "value1";

    Json::Value record2;
    record2["field"] = "value2";

    auto transform = [](Json::Value& record) {
        record["processed"] = true;
    };

    processor.addTask(std::make_shared<TransformTask>(record1, transform));
    processor.addTask(std::make_shared<TransformTask>(record2, transform));

    return 0;
}
```']

