        try (FileInputStream fileIn = new FileInputStream(filePath);
             ObjectInputStream in = new ObjectInputStream(fileIn)) {
            Object obj = in.readObject();
            if (obj instanceof T) {
                return (T) obj;
            } else {
                throw new IllegalArgumentException("Deserialized object is not an instance of the expected type.");
