#include <openssl/rand.h>
#include <openssl/evp.h>
#include <openssl/kdf.h>
#include <openssl/hmac.h>
#include <openssl/pem.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define SALT_SIZE 16
#define KEY_LENGTH 32
#define IV_LENGTH 12
#define GCM_TAG_LENGTH 16

typedef struct {
    unsigned char salt[SALT_SIZE];
    unsigned char key[KEY_LENGTH];
} EncryptionContext;

void generate_salt(unsigned char *salt) {
    if (!RAND_bytes(salt, SALT_SIZE)) {
        fprintf(stderr, "Error generating salt\n");
        exit(EXIT_FAILURE);
    }
}

void derive_key(const char *password, unsigned char *salt, unsigned char *key) {
    const EVP_KDF *kdf = EVP_KDF_fetch(NULL, "PBKDF2", NULL);
    EVP_KDF_CTX *ctx = EVP_KDF_new_ctx(kdf);

    if (!EVP_KDF_set_params(ctx, EVP_KDF_PARAM_SALT, SALT_SIZE, salt,
                             EVP_KDF_PARAM_ITER, 100000,
                             EVP_KDF_PARAM_DIGEST, EVP_sha256(),
                             EVP_KDF_PARAM_MODE, EVP_KDF_MODE_RAW)) {
        fprintf(stderr, "Error setting KDF parameters\n");
        exit(EXIT_FAILURE);
    }

    if (!EVP_KDF_derive(ctx, KEY_LENGTH, key) || !EVP_KDF_free(ctx)) {
        fprintf(stderr, "Error deriving key\n");
        exit(EXIT_FAILURE);
    }
}

void generate_iv(unsigned char *iv) {
    if (!RAND_bytes(iv, IV_LENGTH)) {
        fprintf(stderr, "Error generating IV\n");
        exit(EXIT_FAILURE);
    }
}

int encrypt(const unsigned char *plaintext, size_t plaintext_len,
            const unsigned char *salt, const unsigned char *key,
            unsigned char *iv, unsigned char *ciphertext, unsigned char *tag) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error creating cipher context\n");
        return 0;
    }

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) {
        fprintf(stderr, "Error initializing encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &ciphertext_len,
                                plaintext, plaintext_len)) {
        fprintf(stderr, "Error updating encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    size_t tag_len = GCM_TAG_LENGTH;
    if (1 != EVP_EncryptFinal_ex(ctx, NULL, &tag_len)) {
        fprintf(stderr, "Error finalizing encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    if (tag_len != GCM_TAG_LENGTH) {
        fprintf(stderr, "Invalid tag length\n");
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    memcpy(tag, EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, GCM_TAG_LENGTH, NULL), GCM_TAG_LENGTH);

    EVP_CIPHER_CTX_free(ctx);
    return 1;
}

int decrypt(const unsigned char *ciphertext, size_t ciphertext_len,
            const unsigned char *tag, const unsigned char *salt, const unsigned char *key,
            unsigned char *iv, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error creating cipher context\n");
        return 0;
    }

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) {
        fprintf(stderr, "Error initializing decryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    if (1 != EVP_GCM_add_auth_tag(ctx, tag, GCM_TAG_LENGTH)) {
        fprintf(stderr, "Error adding authentication tag\n");
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    size_t plaintext_len;
    if (1 != EVP_DecryptUpdate(ctx, plaintext, &plaintext_len,
                                ciphertext, ciphertext_len)) {
        fprintf(stderr, "Error updating decryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, GCM_TAG_LENGTH, NULL)) {
        fprintf(stderr, "Error setting authentication tag\n");
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    size_t final_len;
    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + plaintext_len, &final_len)) {
        fprintf(stderr, "Error finalizing decryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return 0;
    }

    plaintext_len += final_len;

    EVP_CIPHER_CTX_free(ctx);
    return 1;
}

int main() {
    EncryptionContext ctx;
    generate_salt(ctx.salt);
    derive_key("password", ctx.salt, ctx.key);

    unsigned char iv[IV_LENGTH];
    generate_iv(iv);

    const char *plaintext = "Hello, World!";
    size_t plaintext_len = strlen(plaintext);

    unsigned char ciphertext[plaintext_len + GCM_TAG_LENGTH];
    unsigned char tag[GCM_TAG_LENGTH];

    if (!encrypt((unsigned char *)plaintext, plaintext_len,
                ctx.salt, ctx.key, iv, ciphertext, tag)) {
        fprintf(stderr, "Encryption failed\n");
        return EXIT_FAILURE;
    }

    unsigned char decrypted_text[plaintext_len + 1];
    if (!decrypt(ciphertext, plaintext_len + GCM_TAG_LENGTH,
                  tag, ctx.salt, ctx.key, iv, decrypted_text)) {
        fprintf(stderr, "Decryption failed\n");
        return EXIT_FAILURE;
    }

    decrypted_text[plaintext_len] = '\0';
    printf("Decrypted text: %s\n", decrypted_text);

    return EXIT_SUCCESS;
}
