import java.util.concurrent.ConcurrentHashMap;
import java.util.zip.GZIPOutputStream;

public class DistributedLoggingFramework {

    private ConcurrentHashMap<String, LogQueue> logQueues = new ConcurrentHashMap<>();
    private ElasticsearchIndexer indexer = new ElasticsearchIndexer();

    public void init() {
        // Initialize service discovery and failover mechanisms
        ServiceDiscovery.init();
        FailoverMechanism.init();
    }

    public void log(String microserviceId, String logMessage) {
        LogQueue queue = logQueues.computeIfAbsent(microserviceId, k -> new LogQueue());
        queue.add(logMessage);

        if (queue.size() >= 1000) { // Batch size
            indexLogs(queue);
            queue.clear();
        }
    }

    private void indexLogs(LogQueue queue) {
        try {
            GZIPOutputStream gzipOutputStream = new GZIPOutputStream(new java.io.ByteArrayOutputStream());
            for (String log : queue) {
                byte[] logBytes = log.getBytes("UTF-8");
                gzipOutputStream.write(logBytes);
            }
            gzipOutputStream.close();
            indexer.index(gzipOutputStream.toByteArray());
        } catch (Exception e) {
            handleLogIndexingError(e);
        }
    }

    private void handleLogIndexingError(Exception e) {
        // Log error details and take appropriate action
    }

    public void shutdown() {
        for (LogQueue queue : logQueues.values()) {
            indexLogs(queue);
        }
        indexer.shutdown();
