['```go
package main

import (
	"encoding/json"
	"fmt"
	"net/http"
)

type OAuth2Token struct {
	TokenType    string `json:"token_type"`
	ExpiresIn    int    `json:"expires_in"`
}

func validateOAuth2Token(w http.ResponseWriter, r *http.Request) {
	tokenHeader := r.Header.Get("Authorization")
	if tokenHeader == "" {
		http.Error(w, "Missing Authorization header", http.StatusUnauthorized)
		return
	}

	parts := strings.Split(tokenHeader, " ")
	if len(parts) != 2 || parts[0] != "Bearer" {
		http.Error(w, "Invalid authorization format", http.StatusBadRequest)
		return
	}

	tokenString := parts[1]
	var token OAuth2Token

	err := json.Unmarshal([]byte(tokenString), &token)
	if err != nil {
		http.Error(w, "Invalid token format", http.StatusBadRequest)
		return
	}

	if token.TokenType != "Bearer" || token.ExpiresIn <= 0 {
		http.Error(w, "Invalid token type or expires_in value", http.StatusUnauthorized)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Token is valid")
}
