class ContainerOrchestrator {
public:
    void addContainer(const std::string& containerId, bool isStateful) {
        std::lock_guard<std::mutex> lock(mutex_);
        containers_[containerId] = {isStateful, 0};
    }

    void removeContainer(const std::string& containerId) {
        std::lock_guard<std::mutex> lock(mutex_);
        containers_.erase(containerId);
    }

    void updateResourceUsage() {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& [id, info] : containers_) {
            info.resourceUsage++;
        }
    }

    void balanceLoad() {
        std::vector<std::string> highUsageContainers;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            for (const auto& [id, info] : containers_) {
                if (info.resourceUsage > 50) {
                    highUsageContainers.push_back(id);
                }
            }
