// Define data record structure
struct DataRecord {
    std::string sourceIP;
    double timestamp;
    std::string eventType;
    std::unordered_map<std::string, std::string> contextFields;
};

// Define a simple in-memory cache for data records
class Cache {
private:
    std::unordered_map<std::string, DataRecord> cache;
    std::mutex mutex;

public:
    void add(const std::string& key, const DataRecord& record) {
        std::lock_guard<std::mutex> lock(mutex);
        cache[key] = record;
    }

    bool get(const std::string& key, DataRecord& record) {
        std::lock_guard<std::mutex> lock(mutex);
        if (cache.find(key) != cache.end()) {
            record = cache[key];
            return true;
        }
        return false;
    }
};

// Define a class for data ingestion
class DataIngestor {
private:
    Cache& cache;
    std::queue<DataRecord> queue;
    std::mutex mutex;
    std::condition_variable condition;

public:
    DataIngestor(Cache& cache) : cache(cache) {}

    void push(const DataRecord& record) {
        std::lock_guard<std::mutex> lock(mutex);
        queue.push(record);
        condition.notify_one();
    }

    bool pop(DataRecord& record) {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [this] { return !queue.empty(); });
        record = queue.front();
        queue.pop();
        return true;
    }
};

// Define a class for data transformation and enrichment
class DataProcessor {
private:
    Cache& cache;

public:
    DataProcessor(Cache& cache) : cache(cache) {}

