// Define the MAC entity structure
typedef struct {
    char mac_id[18];
    int supported_protocols;
    int vlan_tags;
} MacEntity;

// Define a thread-safe linked list for pooling MacEntity objects
typedef struct MacEntityNode {
    MacEntity entity;
    struct MacEntityNode* next;
} MacEntityNode;

MacEntityNode* pool_head = NULL;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add an entity to the pool
void add_to_pool(MacEntity entity) {
    pthread_mutex_lock(&pool_lock);
    MacEntityNode* new_node = (MacEntityNode*)malloc(sizeof(MacEntityNode));
    if (new_node != NULL) {
        new_node->entity = entity;
        new_node->next = pool_head;
        pool_head = new_node;
    } else {
        // Handle memory allocation failure
        printf("Memory allocation failed for MacEntity pool\n");
    }
    pthread_mutex_unlock(&pool_lock);
}

// Function to get an entity from the pool
MacEntity* get_from_pool() {
    MacEntity* result = NULL;
    pthread_mutex_lock(&pool_lock);
    if (pool_head != NULL) {
        MacEntityNode* temp = pool_head;
        result = &temp->entity;
        pool_head = temp->next;
        free(temp);
    }
    pthread_mutex_unlock(&pool_lock);
    return result;
}

// Function to simulate database operations
void simulate_db_operation(MacEntity entity) {
    // Simulate adding, updating, or retrieving a record from the database
    printf("Database operation performed for MAC entity ID: %s\n", entity.mac_id);
}

// Thread function to handle RESTful API requests
void* api_thread_func(void* arg) {
    MacEntity* entity = (MacEntity*)arg;
    simulate_db_operation(*entity);
    free(entity); // Free allocated memory after database operation
    return NULL;
}

int main() {
    // Example usage of the library
    MacEntity new_entity = {"00:1A:2B:3C:4D:5E", 3, 10};
    add_to_pool(new_entity);

    pthread_t thread_id;
    MacEntity* entity_copy = get_from_pool();
    if (entity_copy != NULL) {
        if (pthread_create(&thread_id, NULL, api_thread_func, entity_copy) == 0) {
            pthread_join(thread_id, NULL);
        } else {
            // Handle thread creation failure
            printf("Failed to create API thread\n");
        }
    }

    return 0;
}
