class MACConfigManager {
public:
    struct Config {
        std::string mac;
        std::string ipAddress;
        // Other configuration fields
    };

    using ConfigMap = std::unordered_map<std::string, Config>;

    void addOrUpdateConfig(const std::string& mac, const Config& config) {
        std::unique_lock<std::mutex> lock(mutex_);
        configs_[mac] = config;
        notifySubscribers(mac);
    }

    Config getConfig(const std::string& mac) {
        std::unique_lock<std::mutex> lock(mutex_);
        return configs_[mac];
    }

    void subscribeToUpdates(const std::string& mac, std::function<void()> callback) {
        std::lock_guard<std::mutex> lock(subscriptionMutex_);
        subscriptions_[mac].push_back(callback);
    }

private:
    ConfigMap configs_;
    std::unordered_map<std::string, std::vector<std::function<void()>>> subscriptions_;
    std::mutex mutex_, subscriptionMutex_;

    void notifySubscribers(const std::string& mac) {
        std::lock_guard<std::mutex> lock(subscriptionMutex_);
        for (auto& callback : subscriptions_[mac]) {
            callback();
        }
    }
};

int main() {
    MACConfigManager manager;
    Config config1 = {"00:1A:2B:3C:4D:5E", "192.168.1.1"};
    Config config2 = {"00:1A:2B:3C:4D:5F", "192.168.1.2"};

    manager.addOrUpdateConfig("00:1A:2B:3C:4D:5E", config1);
    manager.addOrUpdateConfig("00:1A:2B:3C:4D:5F", config2);

    auto retrievedConfig = manager.getConfig("00:1A:2B:3C:4D:5E");
    std::cout << "Retrieved MAC: " << retrievedConfig.mac << ", IP: " << retrievedConfig.ipAddress << std::endl;

