// Define a simple data record structure
struct DataRecord {
    std::string sourceIP;
    std::chrono::system_clock::time_point timestamp;
    std::string eventType;
    // Add context-specific fields here
};

// Define a data processing function
void process_data(const DataRecord& record) {
    // Placeholder for data processing logic
    std::cout << "Processing data: " << record.eventType << std::endl;
}

// Define a class to manage the ingestion and processing of data
class DataIngestor {
private:
    std::queue<DataRecord> dataQueue;
    std::mutex queueMutex;
    std::condition_variable dataReady;
    bool running;

public:
    DataIngestor() : running(false) {}

    void start() {
        running = true;
        std::thread([this]() {
            while (running) {
                std::unique_lock<std::mutex> lock(queueMutex);
                dataReady.wait(lock, [this] { return !dataQueue.empty() || !running; });
                if (!running && dataQueue.empty()) break;

                DataRecord record = dataQueue.front();
                dataQueue.pop();

                lock.unlock();
                process_data(record);
            }
        }).detach();
    }

    void stop() {
        running = false;
        dataReady.notify_one();
    }

    void ingest(const DataRecord& record) {
        std::lock_guard<std::mutex> lock(queueMutex);
        dataQueue.push(record);
        dataReady.notify_one();
    }
};

int main() {
    DataIngestor ingestor;
    ingestor.start();

    // Simulate ingesting data
    for (int i = 0; i < 10; ++i) {
        DataRecord record;
        record.sourceIP = "192.168.1." + std::to_string(i);
        record.timestamp = std::chrono::system_clock::now();
        record.eventType = "Event" + std::to_string(i);

        ingestor.ingest(record);
    }

    // Stop the ingestor after some time
    std::this_thread::sleep_for(std::chrono::seconds(5));
    ingestor.stop();

    return 0;
}
