class CacheEntry {
public:
    CacheEntry(std::string data, int ttl)
        : data(data), lastAccessed(time(nullptr)), ttl(ttl) {}

    std::string getData() const { return data; }
    time_t getLastAccessed() const { return lastAccessed; }
    int getTTL() const { return ttl; }

private:
    std::string data;
    time_t lastAccessed;
    int ttl;
};

class Cache {
public:
    void add(const std::string& key, std::string value, int ttl) {
        std::lock_guard<std::mutex> lock(mutex);
        cache[key] = CacheEntry(value, ttl);
    }

    std::optional<std::string> get(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = cache.find(key);
        if (it != cache.end() && time(nullptr) - it->second.getLastAccessed() < it->second.getTTL()) {
            it->second.lastAccessed = time(nullptr); // Update last accessed time
            return it->second.getData();
        }
        return std::nullopt;
    }

private:
    std::mutex mutex;
    std::unordered_map<std::string, CacheEntry> cache;
};

class DataFetcher {
public:
    DataFetcher(std::vector<APIWrapper*> apis, Cache& cache)
        : apis(apis), cache(cache) {}

    void fetchData(const std::string& endpoint) {
        for (auto api : apis) {
            auto result = cache.get(endpoint);
            if (!result.has_value()) {
                std::string data = api->fetchData(endpoint);
                cache.add(endpoint, data, 60); // Cache for 1 minute
            }
            std::cout << "Fetched: " << *result << std::endl;
        }
    }

private:
    std::vector<APIWrapper*> apis;
    Cache& cache;
};

int main() {
    APIWrapper* weather = new WeatherAPI();
    APIWrapper* traffic = new TrafficAPI();
    APIWrapper* environmental = new EnvironmentalAPI();

    std::vector<APIWrapper*> apis = {weather, traffic, environmental};
    Cache cache;

    DataFetcher fetcher(apis, cache);
    fetcher.fetchData("/api/weather");
    fetcher.fetchData("/api/traffic");
    fetcher.fetchData("/api/environmental");

    delete weather;
    delete traffic;
    delete environmental;

    return 0;
}
