import os
import json
from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from flask_socketio import SocketIO, emit
from threading import Lock
from concurrent.futures import ThreadPoolExecutor
import requests

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///config.db'
db = SQLAlchemy(app)
socketio = SocketIO(app)
executor = ThreadPoolExecutor(max_workers=5)
config_lock = Lock()

# Define configuration model
class Config(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), unique=True, nullable=False)
    value = db.Column(db.String(255), nullable=False)

# Function to load configurations from JSON file
def load_config(file_path):
    with open(file_path, 'r') as file:
        config_data = json.load(file)
    return config_data

# Endpoint to update configuration
@app.route('/update_config', methods=['POST'])
def update_config():
    data = request.json
    for item in data['config']:
        with config_lock:
            config = Config.query.filter_by(name=item['name']).first()
            if config:
                config.value = item['value']
            else:
                config = Config(name=item['name'], value=item['value'])
            db.session.add(config)
        executor.submit(save_config)
    return jsonify({"message": "Configuration updated successfully"}), 200

# Function to save configuration changes
def save_config():
    try:
        db.session.commit()
    except Exception as e:
        print(f"Error saving config: {e}")
        db.session.rollback()

# SocketIO event for real-time updates
@socketio.on('config_update')
def handle_config_update(data):
    emit('update', data, broadcast=True)

if __name__ == '__main__':
    socketio.run(app)
