#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_MSG_SIZE 1024
#define CHECKSUM_SIZE 8

// Function to calculate checksum for a message
unsigned long calculate_checksum(char *message, int size) {
    unsigned long checksum = 0;
    for (int i = 0; i < size; i++) {
        checksum += (unsigned char)message[i];
    }
    return checksum;
}

// Function to process incoming messages and append checksum
int process_message(char *input, char **output) {
    int input_size = strlen(input);

    if (input_size > MAX_MSG_SIZE) {
        printf("Message size exceeds limit: %d\n", input_size);
        return -1; // Return error code for oversized message
    }

    *output = malloc(input_size + CHECKSUM_SIZE);
    if (*output == NULL) {
        printf("Memory allocation failed\n");
        return -2; // Return memory allocation error code
    }

    // Copy original message and append checksum
    memcpy(*output, input, input_size);
    unsigned long checksum = calculate_checksum(input, input_size);
    memcpy((*output) + input_size, &checksum, CHECKSUM_SIZE);

    return 0; // Return success
}

// Example usage of the process_message function
int main() {
    char input[] = "Sample message";
    char *processed_message;

    int result = process_message(input, &processed_message);
    if (result == 0) {
        printf("Processed Message: %s\n", processed_message);
    } else {
        printf("Error processing message: %d\n", result);
    }

    free(processed_message); // Free allocated memory
    return 0;
}
