from kafka import KafkaConsumer, KafkaProducer
from rabbitmq import RabbitMQConsumer, RabbitMQProducer
from redis import Redis
from idempotent_processing import IdempotentProcessor
from circuit_breaker import CircuitBreaker
import logging

# Define the event processing pipeline
class EventProcessingPipeline:
    def __init__(self):
        self.kafka_producer = KafkaProducer()
        self.rabbitmq_producer = RabbitMQProducer()
        self.redis_client = Redis()
        self.idempotent_processor = IdempotentProcessor(self.redis_client)
        self.circuit_breaker = CircuitBreaker()

    def process_event(self, event):
        try:
            if not self.circuit_breaker.is_open():
                self.circuit_breaker.reset()
                with self.circuit_breaker:
                    self.idempotent_processor.process(event)
                    if event['type'] == 'kafka':
                        self.kafka_producer.send(event['data'])
                    elif event['type'] == 'rabbitmq':
                        self.rabbitmq_producer.send(event['data'])
        except Exception as e:
            logging.error(f"Error processing event: {e}")
            self.circuit_breaker.open()

# Implementing the circuit breaker pattern
class CircuitBreaker:
    def __init__(self):
        self.is_open = False

    def open(self):
        self.is_open = True

    def reset(self):
        self.is_open = False

    def __enter__(self):
        if self.is_open:
            raise Exception("Circuit breaker is open")

    def __exit__(self, exc_type, exc_val, exc_tb):
        pass

# Example usage
pipeline = EventProcessingPipeline()
event = {'type': 'kafka', 'data': 'example_data'}
pipeline.process_event(event)
