    int* updatedStates = (int*)manageUserAccount(&fsa.currentStates, 1, &fsa, &request);

    if (updatedStates) {
        printf("User account managed successfully.\n");
        // Free allocated memory
        free(updatedStates);
    } else {
        printf("Failed to manage user account.\n");
    }

    return 0;
}
```

