void ConfigManager::pushConfig(const std::string& service, const Json::Value& config) {
    std::unique_lock<std::mutex> lock(cacheMutex);
    localCache[service] = config;
    lock.unlock();
    dataReady.notify_all();
}

Json::Value ConfigManager::pullConfig(const std::string& service) {
    std::unique_lock<std::mutex> lock(cacheMutex);
    dataReady.wait(lock, [this, &service]() { return cmsAvailable || localCache.count(service); });
    if (cmsAvailable) {
        fetchFromCMS();
    }
    return localCache[service];
}

