    std::string metricType;
    std::map<std::string, std::string> tags;

    Metric(std::string service, std::string endpoint, std::time_t ts, std::string type, std::map<std::string, std::string> tags)
        : serviceName(service), endpoint(endpoint), timestamp(ts), metricType(type), tags(tags) {}
};

class MetricsCollector {
public:
    void collect(const Metric& metric);
    void start();
    void stop();

private:
    std::queue<Metric> queue;
    std::mutex mutex;
    std::condition_variable condition;
    bool running = false;
    int workerCount = 10;
    std::vector<std::thread> workers;

    void workerThread();
};

void MetricsCollector::collect(const Metric& metric) {
    std::lock_guard<std::mutex> lock(mutex);
    queue.push(metric);
    condition.notify_one();
}

void MetricsCollector::start() {
    running = true;
    for (int i = 0; i < workerCount; ++i) {
        workers.emplace_back(&MetricsCollector::workerThread, this);
    }
}

void MetricsCollector::stop() {
    running = false;
    condition.notify_all();
    for (auto& worker : workers) {
        worker.join();
    }
}

void MetricsCollector::workerThread() {
    while (true) {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [this] { return !running || !queue.empty(); });
