// Asynchronous communication channel using a thread pool
class AsyncChannel {
private:
    std::vector<std::thread> workers_;
    std::queue<std::function<void()>> tasks_;
    std::mutex queueMutex_;
    std::condition_variable condition_;
    bool stop_;

public:
    AsyncChannel(size_t numThreads) : stop_(false) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers_.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(queueMutex_);
                        condition_.wait(lock, [this] { return stop_ || !tasks_.empty(); });
                        if (stop_ && tasks_.empty()) {
                            return;
                        }
                        task = std::move(tasks_.front());
                        tasks_.pop();
                    }
                    task();
                }
            });
        }
    }

    ~AsyncChannel() {
        {
            std::unique_lock<std::mutex> lock(queueMutex_);
            stop_ = true;
        }
        condition_.notify_all();
        for (auto& worker : workers_) {
            worker.join();
        }
    }

    template<typename F, typename... Args>
    void enqueue(F&& f, Args&&... args) {
        {
            std::unique_lock<std::mutex> lock(queueMutex_);
            tasks_.emplace([f, args...] { f(args...); });
        }
        condition_.notify_one();
    }
};

// Main library class
class LogLibrary {
private:
    ICompression* compression_;
    ILoggingService* loggingService_;
    AsyncChannel channel_;

public:
    LogLibrary(ICompression* comp, ILoggingService* logServ, size_t numThreads)
        : compression_(comp), loggingService_(logServ), channel_(numThreads) {}

    ~LogLibrary() {
        delete compression_;
        delete loggingService_;
    }

    void logEntry(const std::string& entry) {
        channel_.enqueue([this, entry] {
            std::string compressed = compression_->compress(entry);
            loggingService_->log(compressed);
        });
    }

    std::string getLogEntry(size_t index) const {
        return compression_->decompress(loggingService_->getLogEntry(index));
    }
};

int main() {
    auto comp = new ZlibCompression();
    auto logServ = new ExternalLoggingService();
    LogLibrary library(comp, logServ, 4);

    // Simulate logging entries
    for (size_t i = 0; i < 100; ++i) {
        library.logEntry("Log entry " + std::to_string(i));
    }

    // Retrieve and decompress a log entry
    try {
        std::string decompressedEntry = library.getLogEntry(50);
        std::cout << "Decompressed entry: " << decompressedEntry << std::endl;
    } catch (const std::out_of_range& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
