const express = require('express');
const bodyParser = require('body-parser');
const axios = require('axios');
const CircuitBreaker = require('opossum');

const app = express();
app.use(bodyParser.json());

// Payment gateways integrations
const paymentGateways = {
  'stripe': createPaymentGateway('https://api.stripe.com/v1/charges'),
  'paypal': createPaymentGateway('https://api.paypal.com/v1/payments/payment')
};

function createPaymentGateway(url) {
  const breaker = new CircuitBreaker(() => axios.post(url), {
    timeout: 5000,
    errorThresholdPercentage: 20,
    resetTimeout: 30000
  });

  return async (data, options = {}) => {
    try {
      return await breaker.fire(data, options);
    } catch (error) {
      throw new Error('Payment gateway failed');
    }
  };
}

// CRM system integration
async function updateOrderStatus(orderId, status) {
  const url = 'https://api.crm.com/orders';
  try {
    await axios.put(url, { orderId, status });
  } catch (error) {
    console.error('Failed to update order status in CRM');
  }
}

// Route for processing transactions
app.post('/process-transaction', async (req, res) => {
  const { paymentMethod, amount, currency, orderId } = req.body;

  try {
    // Process payment through selected gateway
    const paymentResponse = await paymentGateways[paymentMethod]({
      amount,
      currency,
      source: 'token' // Example token for demonstration
    });

    if (paymentResponse.status === 200) {
      // Update order status in CRM
      await updateOrderStatus(orderId, 'paid');
      res.status(200).json({ message: 'Transaction processed successfully' });
    } else {
      res.status(paymentResponse.status).json({ error: paymentResponse.data.error.message });
    }
  } catch (error) {
    res.status(500).json({ error: 'Failed to process transaction' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
```

