import io.grpc.Server;
import io.grpc.ServerBuilder;
import com.google.common.util.concurrent.ListeningScheduledExecutorService;
import com.google.common.util.concurrent.MoreExecutors;

public class DynamicProcessManager {

    private Server server;
    private ListeningScheduledExecutorService scheduler;

    public void start() throws Exception {
        int port = 50051;
        server = ServerBuilder.forPort(port)
                .addService(new ProcessManagementServiceImpl())
                .build()
                .start();

        System.err.println("Server started, listening on " + port);

        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            System.err.println("*** shutting down gRPC server since JVM is shutting down");
            DynamicProcessManager.this.stop();
            System.err.println("*** server shut down");
        }));
    }

    private void stop() {
        if (server != null) {
            server.shutdown();
        }
        scheduler.shutdownGracefully();
    }

    public static void main(String[] args) throws Exception {
        final DynamicProcessManager manager = new DynamicProcessManager();
        manager.start();
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            try {
                manager.stop();
            } catch (InterruptedException e) {
                e.printStackTrace(System.err);
            }
        }));
    }

