CREATE PROCEDURE GetEmployeeInfoBySupervisorID (@SupervisorID INT)
AS
BEGIN
    BEGIN TRY
        DECLARE @JSON NVARCHAR(MAX);
        SET @JSON = N'';

        -- Simulate fetching data from external systems
        DECLARE @HRISData NVARCHAR(MAX) = dbo.FetchFromExternalSystem('HRIS');
        DECLARE @CRMData NVARCHAR(MAX) = dbo.FetchFromExternalSystem('CRM');

        IF @SupervisorID IS NULL OR @SupervisorID <= 0
        BEGIN
            THROW 50001, 'Invalid supervisor ID', 1;
        END

        -- Parse and create JSON objects using the custom class
        DECLARE @HRISObject dbo.JSONParser = dbo.JSONParser.CreateFromJSON(@HRISData);
        DECLARE @CRMObject dbo.JSONParser = dbo.JSONParser.CreateFromJSON(@CRMData);

        -- Retrieve employee information based on supervisor ID
        SELECT 
            e.EmployeeID,
            e.Name,
            e.City,
            e.Address,
            d.DepartmentName
        FROM 
            Employees e
        JOIN 
            Departments d ON e.DepartmentID = d.DepartmentID
        WHERE 
            e.SupervisorID = @SupervisorID;

        -- Log successful retrieval
        INSERT INTO AuditLog (Action, Message)
        VALUES ('RetrieveEmployeeInfoBySupervisorID', 'Successful retrieval for SupervisorID: ' + CAST(@SupervisorID AS NVARCHAR(10)));
    END TRY
    BEGIN CATCH
        -- Handle exceptions and log errors
        DECLARE @ErrorMessage NVARCHAR(MAX);
        SET @ErrorMessage = ERROR_MESSAGE();
        INSERT INTO ErrorLog (ErrorNumber, ErrorMessage)
        VALUES (ERROR_NUMBER(), @ErrorMessage);

        THROW;
    END CATCH
END
