import json

class JSONParser:
    _factory_functions = {}

    @staticmethod
    def add_factory_function(id, factory_function):
        JSONParser._factory_functions[id] = factory_function

    @staticmethod
    def create_from_json(json_string):
        data = json.loads(json_string)
        if 'type' not in data:
            raise ValueError('JSON object missing "type" field')
        factory_function = JSONParser._factory_functions.get(data['type'])
        if factory_function is None:
            raise ValueError(f"No factory function registered for type: {data['type']}")
        return factory_function(data)

    def __init__(self, data):
        self.data = data

    def to_json(self):
        return json.dumps(self.data)
```

