CREATE FUNCTION dbo.FetchFromExternalSystem(@System NVARCHAR(50))
RETURNS NVARCHAR(MAX)
AS
BEGIN
    DECLARE @Result NVARCHAR(MAX);
    -- Simulate fetching data from an external system with varying latency
    IF @System = 'HRIS'
    BEGIN
        WAITFOR DELAY '00:00:01'; -- Simulate 1 second delay
        SET @Result = N'{ "type": "HRIS", "data": { "employees": [ {"employeeID": 1, "name": "John Doe", "supervisorID": 2}, ... ] } }';
    END
    ELSE IF @System = 'CRM'
    BEGIN
        WAITFOR DELAY '00:00:02'; -- Simulate 2 second delay
        SET @Result = N'{ "type": "CRM", "data": { "employees": [ {"employeeID": 2, "name": "Jane Smith", "supervisorID": 2}, ... ] } }';
    END
    RETURN @Result;
END
