    void convertToPDF(const ImageFile& img, const std::string& outputPath) {
        // Use third-party library to convert image to PDF
    }
};

class TaskQueue {
private:
    std::queue<ImageFile> tasks;
    std::mutex queueMutex;
    std::condition_variable notEmpty;
    bool stopped;

public:
    void enqueue(const ImageFile& task) {
        std::unique_lock<std::mutex> lock(queueMutex);
        if (stopped) throw std::runtime_error("Queue is stopped");
        tasks.push(task);
        notEmpty.notify_one();
    }

    ImageFile dequeue() {
        std::unique_lock<std::mutex> lock(queueMutex);
        while (tasks.empty()) {
            notEmpty.wait(lock);
        }
        ImageFile task = tasks.front();
        tasks.pop();
        return task;
    }

    void stop() {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            stopped = true;
        }
        notEmpty.notify_all();
    }

    bool isStopped() const {
        std::lock_guard<std::mutex> lock(queueMutex);
        return stopped;
    }
};

class WorkerThread {
private:
    TaskQueue& taskQueue;
    PDFConverter converter;
    std::atomic<bool> running;

public:
    WorkerThread(TaskQueue& queue) : taskQueue(queue), running(true) {
        std::thread([this]() {
            while (running.load()) {
                ImageFile img = taskQueue.dequeue();
                try {
                    converter.convertToPDF(img, "output/" + img.path);
