#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pthread.h>

typedef void (*callback_t)(int pid, int status);

typedef struct {
    char *command;
    callback_t callback;
    pthread_t thread_id;
} command_task;

command_task tasks[100];
int task_count = 0;
pthread_mutex_t lock;

void execute_command(command_task *task) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("Fork failed");
        exit(EXIT_FAILURE);
    } else if (pid == 0) {
        execl("/bin/sh", "sh", "-c", task->command, NULL);
        perror("Exec failed");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_lock(&lock);
    tasks[task_count].thread_id = pthread_self();
    tasks[task_count].pid = pid;
    task_count++;
    pthread_mutex_unlock(&lock);

    int status;
    waitpid(pid, &status, 0);
    if (WIFEXITED(status)) {
        task->callback(pid, WEXITSTATUS(status));
    } else if (WIFSIGNALED(status)) {
        task->callback(pid, WTERMSIG(status));
    }
}

void *worker_thread(void *arg) {
    while (1) {
        pthread_mutex_lock(&lock);
        if (task_count == 0) {
            pthread_mutex_unlock(&lock);
            break;
        }

        command_task task = tasks[0];
        for (int i = 1; i < task_count; i++) {
            tasks[i - 1] = tasks[i];
        }
        task_count--;
        pthread_mutex_unlock(&lock);

        execute_command(&task);
    }
    return NULL;
}

void initialize_library(int num_threads) {
    pthread_mutex_init(&lock, NULL);
    for (int i = 0; i < num_threads; i++) {
        pthread_t thread_id;
        pthread_create(&thread_id, NULL, worker_thread, NULL);
    }
}

void submit_command(char *command, callback_t callback) {
    command_task task = {command, callback, 0};
    execute_command(&task);
}

int main() {
    initialize_library(5);

    void status_callback(int pid, int status) {
        printf("Command with PID %d completed with status %d\n", pid, status);
    }

    submit_command("sleep 10", status_callback);
    submit_command("echo Hello World", status_callback);

    pthread_exit(NULL);
}
