import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.Collectors;

public class EventLogProcessor {

    private static final DateTimeFormatter FORMATTER = DateTimeFormatter.ISO_LOCAL_DATE_TIME;
    private static final Set<String> VALID_EVENT_TYPES = Set.of("ERROR", "WARNING", "INFO");
    private static final ExecutorService executorService = Executors.newFixedThreadPool(10);

    public static void main(String[] args) {
        try {
            List<String> logLines = Files.readAllLines(Paths.get("logs.txt"));
            logLines.forEach(logLine -> executorService.submit(() -> processLog(logLine)));
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void processLog(String logLine) {
        try {
            Map<String, Object> log = parseLog(logLine);
            if (isValidLog(log)) {
                // Process and store valid log
                System.out.println("Processed Log: " + log);
            } else {
                // Store or retry processing invalid log
                System.err.println("Invalid Log: " + logLine);
            }
        } catch (Exception e) {
            // Handle parsing exceptions and errors
            System.err.println("Error processing log: " + logLine);
        }
    }

    private static Map<String, Object> parseLog(String logLine) throws IOException {
        // Implement JSON parsing logic here
        return new ObjectMapper().readValue(logLine, Map.class);
    }

    private static boolean isValidLog(Map<String, Object> log) {
        String timestamp = (String) log.get("timestamp");
        String eventType = (String) log.get("event_type");
        Integer severity = (Integer) log.get("severity");

        return isValidTimestamp(timestamp)
                && VALID_EVENT_TYPES.contains(eventType)
                && severity != null && severity >= 1 && severity <= 5;
    }

    private static boolean isValidTimestamp(String timestamp) {
        try {
            LocalDateTime.parse(timestamp, FORMATTER);
            return true;
        } catch (Exception e) {
            return false;
        }
    }
}
