using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class TripleDESDecryptor
{
    private readonly ConcurrentDictionary<string, (byte[], byte[])> _keyCache = new();
    private readonly HttpClient _httpClient;
    private readonly string _configServiceUrl;

    public TripleDESDecryptor(string configServiceUrl)
    {
        _configServiceUrl = configServiceUrl;
        _httpClient = new HttpClient();
    }

    public async Task<string> DecryptAsync(string base64EncodedMessage, string keyId)
    {
        if (!_keyCache.TryGetValue(keyId, out var (key, iv)))
        {
            key = await FetchKeyFromConfigServiceAsync(keyId);
            iv = await FetchIVFromConfigServiceAsync(keyId);
            _keyCache.TryAdd(keyId, (key, iv));
        }

        using (var decryptor = new TripleDESCryptoServiceProvider())
        {
            decryptor.Key = key;
            decryptor.IV = iv;

            var encryptedBytes = Convert.FromBase64String(base64EncodedMessage);
            var decryptedBytes = decryptor.CreateDecryptor().TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);

            return System.Text.Encoding.UTF8.GetString(decryptedBytes);
        }
    }

    private async Task<byte[]> FetchKeyFromConfigServiceAsync(string keyId)
    {
        // Simulate fetching key from a cloud service
        var response = await _httpClient.GetAsync($"{_configServiceUrl}/keys/{keyId}");
        if (response.IsSuccessStatusCode)
        {
            return Convert.FromBase64String(await response.Content.ReadAsStringAsync());
        }
        throw new Exception("Failed to fetch decryption key");
    }

    private async Task<byte[]> FetchIVFromConfigServiceAsync(string keyId)
    {
        // Simulate fetching IV from a cloud service
        var response = await _httpClient.GetAsync($"{_configServiceUrl}/ivs/{keyId}");
        if (response.IsSuccessStatusCode)
        {
            return Convert.FromBase64String(await response.Content.ReadAsStringAsync());
        }
        throw new Exception("Failed to fetch initialization vector");
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        var decryptor = new TripleDESDecryptor("https://configservice.example.com");

        string encryptedMessage = "your_encrypted_base64_message_here";
        string keyId = "your_key_id_here";

        try
        {
            string decryptedMessage = await decryptor.DecryptAsync(encryptedMessage, keyId);
            Console.WriteLine($"Decrypted Message: {decryptedMessage}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
