public class StateTransitionManager : IDisposable
{
    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _cache;
    private readonly byte[] _encryptionKey;
    private readonly byte[] _iv;
    private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1, 1);

    public StateTransitionManager(HttpClient httpClient, IMemoryCache cache, byte[] encryptionKey, byte[] iv)
    {
        _httpClient = httpClient;
        _cache = cache;
        _encryptionKey = encryptionKey;
        _iv = iv;
    }

    public async Task<string> TransitionStateAsync(string ciphertext, string url)
    {
        await _semaphore.WaitAsync();
        try
        {
            if (!_cache.TryGetValue(url, out var state))
            {
                state = await FetchStateFromUrlAsync(url);
                _cache.Set(url, state, TimeSpan.FromMinutes(5));
            }

            var decryptedData = DecryptAndDeserialize(ciphertext);
            return ProcessState(state, decryptedData);
        }
        catch (Exception ex)
        {
            // Log error and retry logic here
            throw;
        }
        finally
        {
            _semaphore.Release();
        }
    }

    private async Task<string> FetchStateFromUrlAsync(string url)
    {
        var response = await _httpClient.GetAsync(url, HttpCompletionOption.ResponseHeadersRead);
        response.EnsureSuccessStatusCode();

        using (var contentStream = await response.Content.ReadAsStreamAsync())
        {
            return await JsonSerializer.DeserializeAsync<string>(contentStream);
        }
    }

    private string DecryptAndDeserialize(string ciphertext)
    {
        // Implement AES-CBC decryption and JSON deserialization logic here
        return JsonConvert.DeserializeObject<string>(ciphertext);
    }

    private string ProcessState(string state, string decryptedData)
    {
        // Implement state processing logic here
        return state + decryptedData;
    }

    public void Dispose()
    {
        _semaphore.Dispose();
    }
}
