        try {
            Schema schema = metadataResolver.resolveSchema(eventType);
            Event event = eventProcessor.process(schema, data);
            eventCache.store(event);
        } catch (Exception e) {
            handleDeserializationFailure(data, e);
        }
    }

    @Override
    public Event retrieveEvent(String eventId) {
        return eventCache.retrieve(eventId);
    }

    private void handleDeserializationFailure(String data, Exception e) {
        logger.error("Failed to deserialize event: " + data, e);
