# Python code for file hash computation with cloud storage integration

import hashlib
import requests
from oauthlib.oauth2 import BackendApplicationClient
from requests_oauthlib import OAuth2Session

def compute_md5_hash(file_uri):
    response = requests.get(file_uri, stream=True)
    md5_hash = hashlib.md5()
    for chunk in response.iter_content(chunk_size=8192):
        md5_hash.update(chunk)
    return md5_hash.hexdigest()

def compute_sha256_hash(file_uri):
    response = requests.get(file_uri, stream=True)
    sha256_hash = hashlib.sha256()
    for chunk in response.iter_content(chunk_size=8192):
        sha256_hash.update(chunk)
    return sha256_hash.hexdigest()

def authenticate_with_oauth2(client_id, client_secret):
    client = BackendApplicationClient(client_id=client_id)
    oauth = OAuth2Session(client=client)
    token = oauth.fetch_token(token_url='https://provider.com/oauth/token', client_id=client_id, client_secret=client_secret)
    return oauth

# C function for validating OAuth2 access token
#include <stdbool.h>
#include <stdio.h>
#include <string.h>

bool validate_oauth2_access_token(const char* authorization_header) {
    if (authorization_header == NULL) {
        return false;
    }
    const char* prefix = "Bearer ";
    size_t prefix_length = strlen(prefix);
    if (strncmp(authorization_header, prefix, prefix_length) != 0) {
        return false;
    }
    const char* token_type_start = authorization_header + prefix_length;
    const char* space_pos = strchr(token_type_start, ' ');
    if (space_pos == NULL) {
        return false;
    }
    size_t token_type_length = space_pos - token_type_start;
    if (strncmp(token_type_start, "Bearer", token_type_length) != 0) {
        return false;
    }
    const char* expires_in_start = space_pos + 1;
    long expires_in_value = strtol(expires_in_start, NULL, 10);
    if (expires_in_value <= 0) {
        return false;
    }
    return true;
}

