import boto3
from google.cloud import storage as gcs
from azure.storage.blob import BlobServiceClient
from oauthlib.oauth2 import BackendApplicationClient
from requests_oauthlib import OAuth2Session
from hashlib import md5, sha256
import os

class CloudStorageHasher:
    def __init__(self):
        self.s3_client = boto3.client('s3')
        self.gcs_client = gcs.Client()
        self.blob_service_client = BlobServiceClient.from_connection_string("your_connection_string")

    def get_hash(self, uri, provider):
        if provider == 's3':
            return self._get_s3_hash(uri)
        elif provider == 'gcs':
            return self._get_gcs_hash(uri)
        elif provider == 'azure':
            return self._get_azure_hash(uri)

    def _get_s3_hash(self, uri):
        bucket_name, file_key = uri.split('//')[1].split('/')
        response = self.s3_client.get_object(Bucket=bucket_name, Key=file_key)
        content = response['Body'].read()
        return {'md5': md5(content).hexdigest(), 'sha256': sha256(content).hexdigest()}

    def _get_gcs_hash(self, uri):
        bucket_name, file_path = uri.split('//')[1].split('/')
        blob = self.gcs_client.bucket(bucket_name).blob(file_path)
        content = blob.download_as_text()
        return {'md5': md5(content.encode()).hexdigest(), 'sha256': sha256(content.encode()).hexdigest()}

    def _get_azure_hash(self, uri):
        container_name, file_path = uri.split('//')[1].split('/')
        blob_client = self.blob_service_client.get_blob_client(container=container_name, blob=file_path)
        content = blob_client.download_blob().readall()
        return {'md5': md5(content).hexdigest(), 'sha256': sha256(content).hexdigest()}

# Usage
hasher = CloudStorageHasher()
print(hasher.get_hash('s3://your-bucket/your-file', 's3'))
```

