        self.executor = ThreadPoolExecutor(max_workers=self.max_connections)

    def monitor_app(self, app_id, metrics_url, alert_thresholds):
        future = self.executor.submit(self._collect_metrics, app_id, metrics_url)
        result = future.result()
        if not self._check_alert_conditions(result, alert_thresholds):
            self._trigger_alert(app_id, result)

