#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <unordered_map>

class DataRecord {
public:
    std::string sourceIP;
    std::chrono::system_clock::time_point timestamp;
    std::string eventType;
    std::unordered_map<std::string, std::string> contextFields;

    DataRecord(std::string ip, std::chrono::system_clock::time_point ts, std::string et, std::unordered_map<std::string, std::string>&& ctx)
        : sourceIP(ip), timestamp(ts), eventType(et), contextFields(std::move(ctx)) {}
};

class IngestionService {
private:
    std::queue<DataRecord> dataQueue;
    std::mutex queueMutex;
    std::condition_variable notEmpty;
    std::atomic<bool> running{true};
    std::unordered_map<std::string, std::string> localCatalog;

public:
    void start() {
        std::thread worker(&IngestionService::processData, this);
        worker.detach();
    }

    void stop() {
        running.store(false);
        notEmpty.notify_all();
    }

    void enqueue(const DataRecord& record) {
        std::lock_guard<std::mutex> lock(queueMutex);
        dataQueue.push(record);
        notEmpty.notify_one();
    }

private:
    void processData() {
        while (running.load()) {
            std::unique_lock<std::mutex> lock(queueMutex);
            notEmpty.wait(lock, [this] { return !dataQueue.empty() || !running.load(); });

            if (!running.load())
                break;

            DataRecord record = dataQueue.front();
            dataQueue.pop();
            lock.unlock();

            // Process and enrich data
            processAndEnrich(record);
        }
    }

    void processAndEnrich(DataRecord& record) {
        std::lock_guard<std::mutex> lock(queueMutex);
        if (localCatalog.find(record.sourceIP) == localCatalog.end()) {
            // Fetch from external catalog and update cache
            fetchAndUpdateCatalog(record.sourceIP);
        }

        // Apply transformations and enrichments based on catalog
        // ...
    }

    void fetchAndUpdateCatalog(const std::string& sourceIP) {
        // Simulate fetching data from external catalog
        std::this_thread::sleep_for(std::chrono::seconds(1));
        localCatalog[sourceIP] = "mapped_value";
    }
};

int main() {
    IngestionService service;
    service.start();

    // Example usage: Enqueue data records
    for (int i = 0; i < 10; ++i) {
        DataRecord record("192.168.1." + std::to_string(i), std::chrono::system_clock::now(), "event" + std::to_string(i), {});
        service.enqueue(record);
    }

    // Stop the service after processing
    service.stop();

    return 0;
}
