public class StreamingDataProcessor {
    private final ExecutorService executorService;
    private final LinkedBlockingQueue<String> queue;
    private final ObjectMapper objectMapper;

    public StreamingDataProcessor(int numThreads) {
        this.executorService = Executors.newFixedThreadPool(numThreads);
        this.queue = new LinkedBlockingQueue<>();
        this.objectMapper = new ObjectMapper();

        for (int i = 0; i < numThreads; i++) {
            executorService.submit(new DataProcessor());
        }
    }

    public void submitData(String json) {
        queue.offer(json);
    }

    private class DataProcessor implements Runnable {
        @Override
        public void run() {
            while (true) {
                try {
                    String json = queue.take();
                    JsonNode node = objectMapper.readTree(json);
                    processMetrics(node);
                } catch (Exception e) {
                    // Handle exception, e.g., log error and retry
                }
            }
        }

        private void processMetrics(JsonNode node) {
            // Implement logic to aggregate metrics from the JSON data
        }
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }
}
