#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <unistd.h>
#include <sys/wait.h>

#define AES_KEY_SIZE 32
#define IV_SIZE 16
#define SALT_SIZE 16
#define MAX_COMMAND_LENGTH 512
#define LOG_FILE "process_log.txt"

void log_message(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log != NULL) {
        fprintf(log, "%s\n", message);
        fclose(log);
    }
}

int derive_key(const char *password, unsigned char *salt, unsigned char *key) {
    return EVP_PBKDF2_HMAC(password, strlen(password), salt, SALT_SIZE, 10000, EVP_sha256(), AES_KEY_SIZE, key) > 0;
}

void encrypt_data(const unsigned char *data, size_t data_len, const unsigned char *key, const unsigned char *iv, unsigned char *encrypted_data) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        log_message("Failed to create cipher context");
        return;
    }

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        log_message("Failed to initialize encryption");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    int len;
    if (1 != EVP_EncryptUpdate(ctx, encrypted_data, &len, data, data_len)) {
        log_message("Encryption update failed");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    int ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, encrypted_data + len, &len)) {
        log_message("Encryption final failed");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    ciphertext_len += len;

    encrypted_data[ciphertext_len] = '\0';
    EVP_CIPHER_CTX_free(ctx);
}

void execute_command(const char *command, const char *environment[]) {
    FILE *output_log = fopen(LOG_FILE, "a");
    if (output_log == NULL) {
        log_message("Failed to open log file for command output");
        return;
    }

    int pipefd[2];
    if (pipe(pipefd) == -1) {
        log_message("Failed to create pipe");
        fclose(output_log);
        return;
    }

    pid_t pid = fork();
    if (pid == -1) {
        log_message("Fork failed");
        close(pipefd[0]);
        close(pipefd[1]);
        fclose(output_log);
        return;
    } else if (pid == 0) {
        // Child process
        dup2(pipefd[1], STDOUT_FILENO);
        dup2(pipefd[1], STDERR_FILENO);
        close(pipefd[0]);
        close(pipefd[1]);

        execle("/bin/sh", "sh", "-c", command, NULL, environment);
        log_message("Execution failed");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        close(pipefd[1]);
        char buffer[128];
        while (read(pipefd[0], buffer, sizeof(buffer) - 1) > 0) {
            fwrite(buffer, 1, strlen(buffer), output_log);
        }
        close(pipefd[0]);

        int status;
        waitpid(pid, &status, 0);
        if (!WIFEXITED(status)) {
            log_message("Command terminated abnormally");
        } else {
            log_message("Command executed successfully");
        }
    }

    fclose(output_log);
}

void secure_process_manager(const char *password, const char *command) {
    unsigned char salt[SALT_SIZE];
    if (RAND_bytes(salt, SALT_SIZE) != 1) {
        log_message("Failed to generate random salt");
        return;
    }

    unsigned char key[AES_KEY_SIZE];
    if (!derive_key(password, salt, key)) {
        log_message("Key derivation failed");
        return;
    }

    unsigned char iv[IV_SIZE];
    if (RAND_bytes(iv, IV_SIZE) != 1) {
        log_message("Failed to generate random IV");
        return;
    }

    // Example data encryption
    const char *data = "Sensitive data";
    unsigned char encrypted_data[strlen(data) + AES_BLOCK_SIZE];
    encrypt_data((const unsigned char *)data, strlen(data), key, iv, encrypted_data);
    printf("Encrypted data: %s\n", encrypted_data);

    // Example command execution with predefined environment
    const char *environment[] = { "VAR1=value1", NULL };
    execute_command(command, environment);
}

int main() {
    secure_process_manager("userpassword", "ls -la /home/user");
    return 0;
}
