#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

// Function to derive a 32-byte AES key using PBKDF2 and SHA-256
void derive_key(const char *password, const unsigned char *salt, size_t salt_len, unsigned char *key) {
    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), NULL, (unsigned char *)password, strlen(password), 10000, key, NULL);
}

// Function to encrypt data using AES-256-CBC
void encrypt_data(const unsigned char *key, const unsigned char *iv, const unsigned char *data, size_t data_len, unsigned char **encrypted_data, size_t *encrypted_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    int len;
    EVP_EncryptUpdate(ctx, encrypted_data, &len, data, data_len);
    *encrypted_len += len;
    EVP_EncryptFinal_ex(ctx, encrypted_data, &len);
    *encrypted_len += len;
    EVP_CIPHER_CTX_free(ctx);
}

// Function to decrypt data using AES-256-CBC
void decrypt_data(const unsigned char *key, const unsigned char *iv, const unsigned char *data, size_t data_len, unsigned char **decrypted_data, size_t *decrypted_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    int len;
    EVP_DecryptUpdate(ctx, decrypted_data, &len, data, data_len);
    *decrypted_len += len;
    EVP_DecryptFinal_ex(ctx, decrypted_data, &len);
    *decrypted_len += len;
    EVP_CIPHER_CTX_free(ctx);
}

// Function to execute a shell command in the background
void execute_command(const char *command) {
    pid_t pid = fork();
    if (pid == 0) {
        execl("/bin/sh", "sh", "-c", command, NULL);
        exit(127); // Only reached if execl fails
    }
}

// Function to log command output and errors
void log_command_output(const char *command, FILE *output_file, FILE *error_file) {
    execute_command(command);
    // Redirect stdout and stderr to files for auditing
    fclose(stdout);
    fclose(stderr);
    freopen("stdout.log", "a", stdout);
    freopen("stderr.log", "a", stderr);
}

// Main function for demonstration purposes
int main() {
    const char *password = "user_password";
    unsigned char key[32];
    unsigned char iv[16];
    unsigned char data[] = "sensitive_data";
    size_t data_len = strlen((char *)data);

    // Derive the AES key from the password and salt
    derive_key(password, NULL, 0, key);
    RAND_bytes(iv, sizeof(iv));

    // Encrypt the data
    unsigned char *encrypted_data;
    size_t encrypted_len = data_len + EVP_CIPHER_block_size(EVP_aes_256_cbc());
    encrypted_data = (unsigned char *)malloc(encrypted_len);
    encrypt_data(key, iv, data, data_len, &encrypted_data, &encrypted_len);

    // Decrypt the data
    unsigned char *decrypted_data;
    size_t decrypted_len = data_len;
    decrypted_data = (unsigned char *)malloc(decrypted_len);
    decrypt_data(key, iv, encrypted_data, encrypted_len, &decrypted_data, &decrypted_len);

    // Free allocated memory
    free(encrypted_data);
    free(decrypted_data);

    return 0;
}
