#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/rand.h>
#include <openssl/evp.h>
#include <openssl/aes.h>
#include <unistd.h>
#include <sys/wait.h>

#define KEY_SIZE 32
#define IV_SIZE 16

void derive_key(const char *password, const unsigned char *salt, size_t salt_len, unsigned char *key) {
    EVP_PKEY_CTX *ctx = EVP_PKEY_CTX_new_id(EVP_PBE_HMAC_SHA256(), NULL);
    EVP_PKEY_derive_init(ctx);
    EVP_PKEY_set1_passphrase(ctx, (const unsigned char *)password, strlen(password));
    EVP_PKEY_derive_keypair(ctx, key);
    EVP_PKEY_free(ctx);
}

void encrypt_data(const unsigned char *key, const unsigned char *iv, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    EVP_EncryptUpdate(ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx, ciphertext + ciphertext_len, &ciphertext_len);
    EVP_CIPHER_CTX_free(ctx);
}

void decrypt_data(const unsigned char *key, const unsigned char *iv, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    EVP_DecryptUpdate(ctx, plaintext, &ciphertext_len, ciphertext, ciphertext_len);
    EVP_DecryptFinal_ex(ctx, plaintext + ciphertext_len, &ciphertext_len);
    EVP_CIPHER_CTX_free(ctx);
}

void execute_command(const char *command) {
    pid_t pid = fork();
    if (pid == 0) {
        execlp("/bin/sh", "sh", "-c", command, NULL);
        exit(127); /* only reached if execlp fails */
    } else if (pid < 0) {
        perror("fork");
        return;
    }
    int status;
    waitpid(pid, &status, 0);
    if (WIFEXITED(status)) {
        printf("Command exited with status %d\n", WEXITSTATUS(status));
    } else if (WIFSIGNALED(status)) {
        printf("Command terminated by signal %d\n", WTERMSIG(status));
    }
}

int main() {
    const char *password = "my_password";
    unsigned char salt[16];
    OpenSSL_add_all_algorithms();
    RAND_bytes(salt, sizeof(salt));

    unsigned char key[KEY_SIZE];
    derive_key(password, salt, sizeof(salt), key);

    unsigned char iv[IV_SIZE];
    RAND_bytes(iv, sizeof(iv));

    const char *plaintext = "Sensitive data";
    size_t plaintext_len = strlen(plaintext);
    unsigned char ciphertext[plaintext_len + EVP_CIPHER_block_size(EVP_aes_256_cbc())];

    encrypt_data(key, iv, (unsigned char *)plaintext, plaintext_len, ciphertext);

    unsigned char decrypted_text[plaintext_len];
    decrypt_data(key, iv, ciphertext, sizeof(ciphertext), decrypted_text);
    decrypted_text[plaintext_len] = '\0';

    printf("Decrypted text: %s\n", decrypted_text);

    execute_command("ls -la");

    return 0;
}
