#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <functional>
#include <memory>
#include <chrono>

class DynamicImageProcessor {
public:
    DynamicImageProcessor(size_t maxThreads, size_t cacheSize)
        : maxThreads(maxThreads), taskQueue(), workers(), stop(false) {
        for (size_t i = 0; i < maxThreads; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(this->queueMutex);
                        this->condition.wait(lock, [this] { return this->stop || !this->taskQueue.empty(); });
                        if (this->stop && this->taskQueue.empty()) {
                            return;
                        }
                        task = std::move(this->taskQueue.front());
                        this->taskQueue.pop();
                    }
                    task();
                }
            });
        }
    }

    ~DynamicImageProcessor() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    template<typename Func, typename... Args>
    void enqueue(Func&& func, Args&&... args) {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            if (stop) {
                throw std::runtime_error("enqueue on stopped DynamicImageProcessor");
            }
            taskQueue.emplace(std::bind(std::forward<Func>(func), std::forward<Args>(args)...));
        }
        condition.notify_one();
    }

private:
    size_t maxThreads;
    std::queue<std::function<void()>> taskQueue;
    std::vector<std::thread> workers;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool stop;
};
