# Python - File Hash Computation Service
import hashlib
import requests
from flask import Flask, request, jsonify

app = Flask(__name__)

def compute_md5(file_path):
    md5_hash = hashlib.md5()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            md5_hash.update(chunk)
    return md5_hash.hexdigest()

def compute_sha256(file_path):
    sha256_hash = hashlib.sha256()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            sha256_hash.update(chunk)
    return sha256_hash.hexdigest()

@app.route('/compute_hash', methods=['POST'])
def compute_hash():
    data = request.json
    file_path = data.get('file_path')
    hash_type = data.get('hash_type')

    if not (file_path and hash_type):
        return jsonify({"error": "Missing parameters"}), 400

    try:
        if hash_type == 'md5':
            result = compute_md5(file_path)
        elif hash_type == 'sha256':
            result = compute_sha256(file_path)
        else:
            return jsonify({"error": "Unsupported hash type"}), 400

        return jsonify({"hash_value": result})
    except Exception as e:
        return jsonify({"error": str(e)}), 500
