package secure_encryption

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"fmt"
	"golang.org/x/crypto/pbkdf2"
	"sync"
)

const (
	defaultKeySize = 32 // AES-256
	maxIterations  = 100000
	minIterations  = 1000
	keyDerivationFunctionSalt = "secure_encryption_kdf_salt"
)

type EncryptionService struct {
	config Config
	keys   map[string][]byte
	lock   sync.RWMutex
}

type Config struct {
	KeySize        int
	IterationCount int
}

func NewEncryptionService(config Config) *EncryptionService {
	return &EncryptionService{
		config: config,
		keys:   make(map[string][]byte),
	}
}

func (s *EncryptionService) Initialize() error {
	if s.config.KeySize != 16 && s.config.KeySize != 24 && s.config.KeySize != 32 {
		s.config.KeySize = defaultKeySize
	}

	if s.config.IterationCount < minIterations || s.config.IterationCount > maxIterations {
		s.config.IterationCount = 10000
	}

	return nil
}

func (s *EncryptionService) Encrypt(data []byte, userID string) ([]byte, error) {
	key := s.getKey(userID)
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, fmt.Errorf("failed to create cipher: %w", err)
	}

	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, fmt.Errorf("failed to create GCM mode: %w", err)
	}

	nonce := make([]byte, gcm.NonceSize())
	if _, err := rand.Read(nonce); err != nil {
		return nil, fmt.Errorf("failed to generate nonce: %w", err)
	}

	ciphertext := gcm.Seal(nil, nonce, data, nil)
	return append(nonce, ciphertext...), nil
}

func (s *EncryptionService) Decrypt(data []byte, userID string) ([]byte, error) {
	key := s.getKey(userID)
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, fmt.Errorf("failed to create cipher: %w", err)
	}

	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, fmt.Errorf("failed to create GCM mode: %w", err)
	}

	if len(data) < gcm.NonceSize() {
		return nil, fmt.Errorf("ciphertext too short")
	}

	nonce := data[:gcm.NonceSize()]
	ciphertext := data[gcm.NonceSize():]

	plaintext, err := gcm.Open(nil, nonce, ciphertext, nil)
	if err != nil {
		return nil, fmt.Errorf("failed to decrypt: %w", err)
	}

	return plaintext, nil
}

func (s *EncryptionService) getKey(userID string) []byte {
	s.lock.RLock()
	key, ok := s.keys[userID]
	s.lock.RUnlock()

	if ok {
		return key
	}

	password := "user_password" // Replace with actual password retrieval logic
	salt := keyDerivationFunctionSalt

	key = pbkdf2.Key(password, salt, s.config.IterationCount, int(s.config.KeySize), sha256.New)
	s.lock.Lock()
	s.keys[userID] = key
	s.lock.Unlock()

	return key
}
