// CloudImageProcessorImpl.h
#pragma once

#include "CloudImageProcessor.h"
#include <memory>
#include <unordered_map>

class ImageStoreClient {
public:
    virtual ~ImageStoreClient() = default;

    // Fetch an image from the store asynchronously
    virtual std::future<Image*> fetchAsync(const std::string& url) = 0;
};

class CloudImageProcessorImpl : public CloudImageProcessor {
public:
    explicit CloudImageProcessorImpl(std::shared_ptr<ImageStoreClient> client);

    ~CloudImageProcessorImpl() override;

    std::future<Image*> transformAsync(const Image* original, const TransformRequest& request) override;

    std::string getApiVersion() const override;

    bool isInRegion(const std::string& region) const override;

private:
    void initializeTransformServices();
    void handleApiDeprecation();

    std::shared_ptr<ImageStoreClient> client_;
    std::unordered_map<std::string, TransformService*> transformServices_;
};

class TransformService {
public:
    virtual ~TransformService() = default;

    // Apply a transformation to an image
    virtual Image* apply(const Image* original, const TransformRequest& request) = 0;

protected:
    CloudImageProcessorImpl& processor_;
};
