#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_LOG_LEVEL 4
#define FATAL 0
#define ERROR 1
#define WARNING 2
#define INFO 3

typedef struct {
    int log_level;
    char *service_url;
} LoggerConfig;

typedef struct {
    LoggerConfig config;
    CURL *handle;
    pthread_mutex_t lock;
} LoggerInstance;

void logger_init(LoggerInstance *logger, LoggerConfig config) {
    logger->config = config;
    curl_global_init(CURL_GLOBAL_DEFAULT);
    logger->handle = curl_easy_init();
    pthread_mutex_init(&logger->lock, NULL);
}

void logger_destroy(LoggerInstance *logger) {
    if (logger->handle)
        curl_easy_cleanup(logger->handle);
    curl_global_cleanup();
    pthread_mutex_destroy(&logger->lock);
}

size_t logger_write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    // Implement callback to handle log data
    return size * nmemb;
}

void logger_log(LoggerInstance *logger, int level, const char *message) {
    if (level >= logger->config.log_level)
        return;

    pthread_mutex_lock(&logger->lock);
    curl_easy_setopt(logger->handle, CURLOPT_URL, logger->config.service_url);
    curl_easy_setopt(logger->handle, CURLOPT_POSTFIELDS, message);
    curl_easy_setopt(logger->handle, CURLOPT_WRITEFUNCTION, logger_write_callback);
    CURLcode res = curl_easy_perform(logger->handle);
    if (res != CURLE_OK) {
        // Handle error
    }
    pthread_mutex_unlock(&logger->lock);
}

int main() {
    LoggerConfig config = {INFO, "http://example.com/log"};
    LoggerInstance logger;
    logger_init(&logger, config);

    logger_log(&logger, INFO, "System is starting up.");
    logger_log(&logger, ERROR, "Failed to connect to database.");

    logger_destroy(&logger);
    return 0;
}
```

