import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.util.concurrent.ConcurrentHashMap;

public class Deserializer {

    private static final ConcurrentHashMap<String, Class<?>> classCache = new ConcurrentHashMap<>();

    public static <T> T deserialize(byte[] bytes, Class<T> clazz) throws IOException, ClassNotFoundException {
        ByteArrayInputStream bis = new ByteArrayInputStream(bytes);
        ObjectInputStream ois = new ObjectInputStream(bis);

        try {
            return clazz.cast(ois.readObject());
        } catch (ClassCastException e) {
            throw new IllegalArgumentException("The deserialized object is not an instance of the specified class.");
        } finally {
            ois.close();
            bis.close();
        }
    }

    private static Class<?> getClassForName(String className) throws ClassNotFoundException {
        Class<?> clazz = classCache.get(className);
        if (clazz == null) {
            try {
                clazz = Class.forName(className);
                classCache.put(className, clazz);
            } catch (ClassNotFoundException e) {
                throw new ClassNotFoundException("Class not found: " + className);
            }
        }
        return clazz;
    }

    public static void main(String[] args) {
        byte[] serializedData = ...; // Assume this is the byte array to deserialize
        try {
            MyClass obj = deserialize(serializedData, MyClass.class);
            System.out.println("Deserialized object: " + obj);
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
    }

    private static class MyClass implements Serializable {
        private String field1;
        private int field2;

        // Getters and setters
    }
}
