// Import necessary libraries
import org.apache.kafka.clients.consumer.ConsumerConfig;
import org.apache.kafka.clients.producer.ProducerConfig;
import org.apache.kafka.common.serialization.StringDeserializer;
import org.apache.kafka.common.serialization.StringSerializer;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.converter.json.MappingJackson2HttpMessageConverter;
import org.springframework.web.client.RestTemplate;

// Kafka Configuration
@Configuration
public class KafkaConfig {

    @Bean
    public ProducerFactory<String, String> producerFactory() {
        return new DefaultKafkaProducerFactory<>(producerConfigs());
    }

    @Bean
    public Map<String, Object> producerConfigs() {
        Map<String, Object> props = new HashMap<>();
        props.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
        props.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class);
        props.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class);
        return props;
    }

    @Bean
    public KafkaTemplate<String, String> kafkaTemplate() {
        return new KafkaTemplate<>(producerFactory());
    }
}

// REST API Configuration
@Configuration
public class RestApiConfig {

    @Bean
    public RestTemplate restTemplate() {
        RestTemplate restTemplate = new RestTemplate();
        restTemplate.getMessageConverters().add(new MappingJackson2HttpMessageConverter());
        return restTemplate;
    }
}

// Database Configuration
@Configuration
public class DatabaseConfig {

    @Bean
    public DataSource dataSource() {
        // Configure PostgreSQL data source properties
        DriverManagerDataSource dataSource = new DriverManagerDataSource();
        dataSource.setDriverClassName("org.postgresql.Driver");
        dataSource.setUrl("jdbc:postgresql://localhost:5432/mydb");
        dataSource.setUsername("myuser");
        dataSource.setPassword("mypassword");
        return dataSource;
    }
}

// Cache Configuration
@Configuration
public class CacheConfig {

    @Bean
    public CacheManager cacheManager() {
        // Configure adaptive caching layer
        CaffeineCacheManager cacheManager = new CaffeineCacheManager("data");
        cacheManager.setCaffeine(caffeineCacheBuilder());
        return cacheManager;
    }

    @Bean
    public Caffeine<Object, Object> caffeineCacheBuilder() {
        return Caffeine.newBuilder()
                .expireAfterWrite(Duration.ofMinutes(10))
                .maximumSize(500);
    }
}

// Error Handling and Retry Configuration
@Configuration
public class ErrorHandlingConfig {

    @Bean
    public RetryTemplate retryTemplate(RetryPolicy retryPolicy, BackoffPolicy backoffPolicy) {
        RetryTemplate template = new RetryTemplate();
        template.setRetryPolicy(retryPolicy);
        template.setBackoffPolicy(backoffPolicy);
        return template;
    }

    @Bean
    public RetryPolicy retryPolicy() {
        return SimpleRetryPolicy.builder()
                .maxAttempts(3)
                .build();
    }

    @Bean
    public BackoffPolicy backoffPolicy() {
        return ExponentialBackOffPolicy.builder()
                .initialInterval(Duration.ofSeconds(1))
                .maxInterval(Duration.ofSeconds(5))
                .multiplier(2.0)
                .build();
    }
}

// Security Configuration
@Configuration
public class SecurityConfig {

    @Bean
    public TokenStore tokenStore() {
        return new InMemoryTokenStore();
    }

    @Bean
    public TokenEnhancer jwtAccessTokenConverter() {
        JwtAccessTokenConverter converter = new JwtAccessTokenConverter();
        converter.setSigningKey("123");
        return converter;
    }
}

// Monitoring and Metrics Configuration
@Configuration
public class MonitoringConfig {

    @Bean
    public MeterRegistryCustomizer<MeterRegistry> metricsCommonTags() {
        return registry -> registry.config().commonTags("service", "my-service");
    }

    @Bean
    public PrometheusMeterRegistry prometheusMeterRegistry(MeterRegistryCustomizers<MeterRegistry> customizers) {
        PrometheusMeterRegistry prometheus = new PrometheusMeterRegistry(PrometheusConfig.DEFAULT);
        customizers.customize(prometheus);
        return prometheus;
    }
}
