#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <memory>

class DynamicImageProcessor {
public:
    DynamicImageProcessor(size_t numThreads) : stop(false), threadPool(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            threadPool.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(this->queueMutex);
                        this->condition.wait(lock, [this] { return this->stop || !this->tasks.empty(); });
                        if (this->stop && this->tasks.empty()) {
                            return;
                        }
                        task = std::move(this->tasks.front());
                        this->tasks.pop();
                    }
                    task();
                }
            });
        }
    }

    ~DynamicImageProcessor() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : threadPool) {
            worker.join();
        }
    }

    void enqueueTask(std::function<void()> task) {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            if (stop) {
                throw std::runtime_error("enqueueing on stopped ThreadPool");
            }
            tasks.emplace(task);
        }
        condition.notify_one();
    }

private:
    bool stop;
    std::vector<std::thread> threadPool;
    std::queue<std::function<void()>> tasks;
    std::mutex queueMutex;
    std::condition_variable condition;
};
