        std::string key = "external_data";
        if (cache.get(key).empty()) {
            std::string data = api.fetchData();
            cache.update(key, data);
        }
    });
    tasks.push(api_task.share());

    // Join worker threads
    for (auto& worker : workers) {
        worker.join();
    }

    // Format results for display or storage
