using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.Threading;

public class RandomValueGenerator
{
    private readonly Random _random = new Random();
    private readonly ConcurrentDictionary<string, object> _cache = new ConcurrentDictionary<string, object>();
    private readonly IExternalLoggingSystem _loggingSystem;
    private readonly ConcurrentQueue<string> _logQueue = new ConcurrentQueue<string>();

    public RandomValueGenerator(IExternalLoggingSystem loggingSystem)
    {
        _loggingSystem = loggingSystem ?? throw new ArgumentNullException(nameof(loggingSystem));
    }

    public float GenerateRandomFloat(double minValue, double maxValue)
    {
        ValidateInputs(minValue, maxValue);
        LogEvent("GenerateRandomFloat", $"Min: {minValue}, Max: {maxValue}");
        return (float)_random.NextDouble() * (float)(maxValue - minValue) + (float)minValue;
    }

    public int GenerateRandomInt(int minValue, int maxValue)
    {
        ValidateInputs(minValue, maxValue);
        LogEvent("GenerateRandomInt", $"Min: {minValue}, Max: {maxValue}");
        return _random.Next(minValue, maxValue + 1);
    }

    public bool GenerateRandomBoolean()
    {
        LogEvent("GenerateRandomBoolean");
        return _random.Next(2) == 0;
    }

    public Vector3 GenerateRandomVector3(Vector3 minVector, Vector3 maxVector)
    {
        ValidateInputs(minVector, maxVector);
        LogEvent("GenerateRandomVector3", $"Min: {minVector}, Max: {maxVector}");
        return new Vector3(
            _random.NextFloat(minVector.X, maxVector.X),
            _random.NextFloat(minVector.Y, maxVector.Y),
            _random.NextFloat(minVector.Z, maxVector.Z)
        );
    }

    private void ValidateInputs(double minValue, double maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("Min value cannot be greater than max value.");
        }
    }

    private void ValidateInputs(Vector3 minVector, Vector3 maxVector)
    {
        if (minVector.X > maxVector.X || minVector.Y > maxVector.Y || minVector.Z > maxVector.Z)
        {
            throw new ArgumentException("Min vector values cannot be greater than max vector values.");
        }
    }

    private void LogEvent(string methodName, string parameters = null)
    {
        var logMessage = $"{DateTime.Now}: {methodName}({parameters})";
        _logQueue.Enqueue(logMessage);
        ThreadPool.QueueUserWorkItem(LogBatchMessages);
    }

    private void LogBatchMessages(object state)
    {
        while (_logQueue.TryDequeue(out var logMessage))
        {
            _loggingSystem.Log(logMessage);
        }
    }
}

public interface IExternalLoggingSystem
{
    void Log(string message);
}
