using System;
using System.Numerics;
using System.Security.Cryptography;

public class SecureRandomValueGenerator
{
    private RNGCryptoServiceProvider _rng = new RNGCryptoServiceProvider();

    public int GenerateSecureRandomInt(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("MinValue cannot be greater than MaxValue");

        byte[] randomBytes = new byte[sizeof(int)];
        _rng.GetBytes(randomBytes);
        int result = BitConverter.ToInt32(randomBytes, 0);

        return (int)(result * (maxValue - minValue + 1.0f) / int.MaxValue) + minValue;
    }

    public float GenerateSecureRandomFloat(double minValue, double maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("MinValue cannot be greater than MaxValue");

        byte[] randomBytes = new byte[sizeof(float)];
        _rng.GetBytes(randomBytes);
        return BitConverter.ToSingle(randomBytes, 0) * (float)(maxValue - minValue) + (float)minValue;
    }

    public bool GenerateSecureRandomBoolean()
    {
        byte[] randomByte = new byte[1];
        _rng.GetBytes(randomByte);
        return randomByte[0] % 2 == 0;
    }

    public Vector3 GenerateSecureRandomVector3(Vector3 minVector, Vector3 maxVector)
    {
        return new Vector3(
            GenerateSecureRandomFloat(minVector.X, maxVector.X),
            GenerateSecureRandomFloat(minVector.Y, maxVector.Y),
            GenerateSecureRandomFloat(minVector.Z, maxVector.Z));
    }
}
