using System;
using System.Diagnostics;
using System.Linq;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class DynamicValueGenerator
{
    private float minValue;
    private float maxValue;
    private long seed;
    private ExternalConfigService externalConfig;
    private readonly object configurationLock = new object();

    public DynamicValueGenerator(float minValue, float maxValue, ExternalConfigService externalConfig)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
        this.externalConfig = externalConfig;
        this.seed = Environment.TickCount64;
    }

    public float GetRandomFloat()
    {
        return (float)GetRandomDouble(minValue, maxValue);
    }

    public float GetRandomFloatExclusive()
    {
        return (float)GetRandomDouble(minValue, maxValue - epsilon);
    }

    public int GetRandomInt()
    {
        return Convert.ToInt32(GetRandomDouble(minValue, maxValue));
    }

    public int GetRandomIntExclusive()
    {
        return Convert.ToInt32(GetRandomDouble(minValue, maxValue - 1));
    }

    public async Task UpdateConfiguration()
    {
        await TryUpdateConfiguration(0);
    }

    public void SetSeed(long seed)
    {
        lock (configurationLock)
        {
            this.seed = seed;
        }
    }

    public string GetCurrentRange()
    {
        return $"Current range: {minValue} to {maxValue}";
    }

    private double GetRandomDouble(double min, double max)
    {
        using (var rng = RandomNumberGenerator.Create())
        {
            byte[] entropy = new byte[1024];
            rng.GetBytes(entropy);
            var randomSource = new Random(BitConverter.ToInt64(entropy, 0));
            lock (configurationLock)
            {
                return min + randomSource.NextDouble() * (max - min);
            }
        }
    }

    private async Task TryUpdateConfiguration(int retryCount)
    {
        try
        {
            var config = await externalConfig.GetConfig();
            lock (configurationLock)
            {
                minValue = config.MinValue;
                maxValue = config.MaxValue;
            }
        }
        catch (HttpRequestException ex) when (retryCount < 3)
        {
            LogError($"Failed to update configuration: {ex.Message}");
            await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, retryCount)));
            await TryUpdateConfiguration(retryCount + 1);
        }
    }

    private void LogError(string message)
    {
        Debug.WriteLine(message);
