public class DataProcessorManager
{
    private readonly IEventStore _eventStore;
    private readonly IDataPipeline _pipeline;
    private readonly ILogger _logger;
    private readonly IConfigService _configService;
    private Dictionary<string, IDataSource> _dataSources = new Dictionary<string, IDataSource>();

    public DataProcessorManager(IEventStore eventStore, IDataPipeline pipeline, ILogger logger, IConfigService configService)
    {
        if (eventStore == null) throw new ArgumentNullException(nameof(eventStore));
        if (pipeline == null) throw new ArgumentNullException(nameof(pipeline));
        if (logger == null) throw new ArgumentNullException(nameof(logger));
        if (configService == null) throw new ArgumentNullException(nameof(configService));

        _eventStore = eventStore;
        _pipeline = pipeline;
        _logger = logger;
        _configService = configService;
    }

    public void AddDataSource(string dataSourceId, IDataSource dataSource)
    {
        if (_dataSources.ContainsKey(dataSourceId))
        {
            _logger.LogError($"Data source with ID {dataSourceId} already exists.");
            return;
        }
        try
        {
            _dataSources[dataSourceId] = dataSource;
            _logger.LogInformation($"Data source added: {dataSourceId}");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Failed to add data source: {dataSourceId}");
        }
    }

    public async Task RemoveDataSourceAsync(string dataSourceId)
    {
        if (!_dataSources.ContainsKey(dataSourceId))
        {
            _logger.LogWarning($"Data source with ID {dataSourceId} not found.");
            return;
        }
        try
        {
            _dataSources[dataSourceId].ProcessDataAsync(this).Wait(); // For simplicity, using .Wait() here
            _dataSources.Remove(dataSourceId);
            _logger.LogInformation($"Data source removed: {dataSourceId}");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Failed to remove data source: {dataSourceId}");
        }
    }

    public async Task ProcessDataAsync()
    {
        foreach (var dataSource in _dataSources.Values)
        {
            try
            {
                await dataSource.ProcessDataAsync(this);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to process data from a data source.");
            }
        }
    }

    public DataStats GetProcessedDataStats()
    {
        // Implement stats calculation logic here
        return new DataStats();
    }
}

