int* manage_states(int *initial_states, int num_states) {
    StateManager manager;
    manager.states = initial_states;
    manager.num_states = num_states;
    pthread_mutex_init(&manager.lock, NULL);

    pthread_t threads[MAX_CONCURRENT_THREADS];
