// Function to process NFAPI PDU archive
void processNfapiPduArchive(const char* archivePath) {
    int result;

    // Detect compression format and load the appropriate decompression library
    if (endsWith(archivePath, ".gz")) {
        // Load gzip decompression library
        unzFile file = unzOpen64(archivePath);
        if (!file) {
            perror("Failed to open gzip archive");
            return;
        }
        // Decompress and parse PDUs from the archive
        processPdusFromUnzFile(file, "gz");
        unzClose(file);
    } else if (endsWith(archivePath, ".zip")) {
        // Load zip decompression library
        UnzFile file = unzipOpen64(archivePath);
        if (!file) {
            perror("Failed to open zip archive");
            return;
        }
        // Decompress and parse PDUs from the archive
        processPdusFromUnzFile(file, "zip");
        unzipClose(file);
    } else if (endsWith(archivePath, ".tar.gz")) {
        // Load tar.gz decompression library
        TarFile file = tarOpen64(archivePath);
        if (!file) {
            perror("Failed to open tar.gz archive");
            return;
        }
        // Decompress and parse PDUs from the archive
        processPdusFromTarFile(file, "tar.gz");
        tarClose(file);
    } else {
        fprintf(stderr, "Unsupported compression format\n");
        return;
    }

    // Handle potential network failures gracefully
    if (result != 0) {
        perror("Network failure during processing");
        return;
    }
}

// Helper function to check file extension
int endsWith(const char* str, const char* suffix) {
    size_t lenStr = strlen(str);
    size_t lenSuffix = strlen(suffix);
    if (lenStr < lenSuffix) return 0;
    return strncmp(str + lenStr - lenSuffix, suffix, lenSuffix) == 0;
}

