        keyGen.init(AES_KEY_SIZE);
        secretKey = keyGen.generateKey();
        cipher = Cipher.getInstance(DEFAULT_ENCRYPTION_MODE);
    }

    public byte[] encrypt(byte[] data, int mode) throws Exception {
        switch (mode) {
            case 1: // GCM
                return gcmEncrypt(data);
            case 2: // CFB
                return cfbEncrypt(data);
            case 3: // OFB
                return ofbEncrypt(data);
            case 4: // CBC
                return cbcEncrypt(data);
            default:
                throw new IllegalArgumentException("Invalid encryption mode");
        }
    }

    private byte[] gcmEncrypt(byte[] data) throws Exception {
        SecureRandom random = new SecureRandom();
        byte[] iv = new byte[12];
        random.nextBytes(iv);

        GCMParameterSpec spec = new GCMParameterSpec(128, iv);
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, spec);

        return cipher.doFinal(data);
    }

