public class DataProcessor
{
    private string connectionString;

    public DataProcessor(string connectionString)
    {
        this.connectionString = connectionString;
    }

    public DataTableReader SendDataToDatabase(byte[] data)
    {
        using (MySqlConnection connection = new MySqlConnection(connectionString))
        {
            try
            {
                connection.Open();
                byte[] buffer = new byte[data.Length];
                Array.Copy(data, buffer, data.Length);

                string query = "INSERT INTO SensorData (SensorId, Data) VALUES (@SensorId, @Data)";
                using (MySqlCommand command = new MySqlCommand(query, connection))
                {
                    MySqlParameter sensorIdParam = new MySqlParameter("@SensorId", MySqlDbType.Int32);
                    MySqlParameter dataParam = new MySqlParameter("@Data", MySqlDbType.Blob);

                    sensorIdParam.Value = 1; // Example sensor ID
                    dataParam.Value = buffer;

                    command.Parameters.Add(sensorIdParam);
                    command.Parameters.Add(dataParam);

                    int rowsAffected = command.ExecuteNonQuery();
                    Console.WriteLine($"{rowsAffected} rows inserted.");

                    query = "SELECT * FROM SensorData WHERE SensorId = @SensorId";
                    using (MySqlCommand selectCommand = new MySqlCommand(query, connection))
                    {
                        MySqlParameter selectSensorIdParam = new MySqlParameter("@SensorId", MySqlDbType.Int32);
                        selectSensorIdParam.Value = 1; // Example sensor ID
                        selectCommand.Parameters.Add(selectSensorIdParam);

                        using (MySqlDataReader reader = selectCommand.ExecuteReader())
                        {
                            DataTable table = new DataTable();
                            table.Load(reader);
                            return new DataTableReader(table);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error: {ex.Message}");
                throw;
            }
        }
    }
}

