#include <queue>
#include <atomic>

class ConfigUpdater {
public:
    void updateConfig(const std::string& target, const std::string& replacement, std::forward_list<std::string>& config) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = std::find(config.begin(), config.end(), target);
        if (it != config.end()) {
            *it = replacement;
        }
    }

private:
    std::mutex mutex_;
};

class LoggingService {
public:
    void logAsync(const std::string& message) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(message);
        condition_.notify_one();
    }

    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this] { return !queue_.empty(); });
            auto message = queue_.front();
            queue_.pop();
            lock.unlock();

            // Simulate network latency
            std::this_thread::sleep_for(std::chrono::milliseconds(100));

            // Log message to external service
            logToExternalService(message);
        }
    }

private:
    std::mutex mutex_;
    std::condition_variable condition_;
    std::queue<std::string> queue_;

    void logToExternalService(const std::string& message) {
        // Simulate logging to external service
        std::cout << "Logged: " << message << std::endl;
    }
};

void configUpdater(const std::string& target, const std::string& replacement, std::forward_list<std::string>& config, LoggingService& logger) {
    ConfigUpdater updater;
    updater.updateConfig(target, replacement, config);

    // Log the update
    std::string logMessage = "Configuration updated: " + target + " -> " + replacement;
    logger.logAsync(logMessage);
}

int main() {
    std::forward_list<std::string> config = {"param1", "target", "param3"};
    LoggingService logger;

    // Create a thread pool for logging
    std::vector<std::thread> workers;
    for (size_t i = 0; i < 5; ++i) {
        workers.emplace_back(&LoggingService::worker, &logger);
    }

    configUpdater("target", "replacement", config, logger);

    // Join the worker threads
    for (auto& thread : workers) {
        thread.join();
    }

    return 0;
}
