using System;
using System.Data;
using System.Data.SqlClient;
using System.Data.PostgreSQL;
using MySql.Data.MySqlClient;
using System.Threading.Tasks;

public class DatabaseService : IDatabaseService
{
    private readonly ILogger _logger;
    private readonly IMonitoringTool _monitoringTool;

    public DatabaseService(ILogger logger, IMonitoringTool monitoringTool)
    {
        _logger = logger;
        _monitoringTool = monitoringTool;
    }

    public async Task<IDataReader> ExecuteQueryAsync(string connectionString, string query, List<SqlParameter> parameters = null, DbType databaseType = DbType.SqlServer)
    {
        using (var connection = CreateConnection(connectionString, databaseType))
        {
            await connection.OpenAsync();
            var command = CreateCommand(connection, query, parameters);
            return await command.ExecuteReaderAsync(CommandBehavior.CloseConnection);
        }
    }

    private IDbConnection CreateConnection(string connectionString, DbType databaseType)
    {
        switch (databaseType)
        {
            case DbType.SqlServer:
                return new SqlConnection(connectionString);
            case DbType.PostgreSQL:
                return new NpgsqlConnection(connectionString);
            case DbType.MySql:
                return new MySqlConnection(connectionString);
            default:
                throw new ArgumentException("Unsupported database type");
        }
    }

    private IDbCommand CreateCommand(IDbConnection connection, string query, List<SqlParameter> parameters = null)
    {
        var command = connection.CreateCommand();
        command.CommandText = query;

        if (parameters != null)
        {
            foreach (var param in parameters)
            {
                command.Parameters.Add(param);
            }
        }

        return command;
    }
}

public interface IDatabaseService
{
    Task<IDataReader> ExecuteQueryAsync(string connectionString, string query, List<SqlParameter> parameters = null, DbType databaseType = DbType.SqlServer);
}

public enum DbType
{
    SqlServer,
    PostgreSQL,
    MySql
}
