using Polly;
using Polly.CircuitBreaker;

public class DatabaseManager
{
    private readonly Dictionary<string, DbProviderFactory> _factories = new Dictionary<string, DbProviderFactory>();
    private readonly CircuitBreakerPolicy _breakerPolicy;

    public DatabaseManager()
    {
        // Initialize factories for different databases
        _factories["SQLServer"] = SqlClient.SqlClientFactory.Instance;
        _factories["MySQL"] = MySql.Data.MySqlClient.MySqlClientFactory.Instance;
        _breakerPolicy = Policy.CircuitBreaker(3, TimeSpan.FromSeconds(30), onReset: OnCircuitReset);
    }

    public void Execute(string connectionString, string providerName, Action<DbConnection> action)
    {
        using (var connection = _factories[providerName].CreateConnection())
        {
            connection.ConnectionString = connectionString;
            _breakerPolicy.Execute(() =>
            {
                if (connection.State == System.Data.ConnectionState.Closed)
                    connection.Open();
                action(connection);
            });
        }
    }

    private void OnCircuitReset()
    {
        Console.WriteLine("Circuit breaker has been reset.");
    }
}

