// Define a class for managing dynamic configurations
class ConfigManager {
private:
    std::unordered_map<std::string, std::string> configCache;
    mutable std::mutex cacheMutex;
    std::condition_variable cv;

public:
    void updateConfig(const std::string& key, const std::string& value) {
        std::unique_lock<std::mutex> lock(cacheMutex);
        configCache[key] = value;
        cv.notify_all();
    }

    std::string getConfig(const std::string& key) {
        std::unique_lock<std::mutex> lock(cacheMutex);
        cv.wait(lock, [this, &key] { return configCache.find(key) != configCache.end(); });
        return configCache[key];
    }
};

// Define a class for managing asynchronous operations
class AsyncManager {
private:
    std::queue<std::function<void()>> taskQueue;
    mutable std::mutex queueMutex;
    std::condition_variable cv;
    bool stop = false;

public:
    void addTask(std::function<void()> task) {
        std::unique_lock<std::mutex> lock(queueMutex);
        taskQueue.push(task);
        cv.notify_one();
    }

    void worker() {
        while (true) {
            std::function<void()> task;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                cv.wait(lock, [this] { return !taskQueue.empty() || stop; });
                if (stop && taskQueue.empty()) break;
                task = taskQueue.front();
                taskQueue.pop();
            }
            task();
        }
    }

    void start(size_t numWorkers) {
        for (size_t i = 0; i < numWorkers; ++i) {
            std::thread(&AsyncManager::worker, this).detach();
        }
    }

    void stopAll() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        cv.notify_all();
    }
};

