import java.util.concurrent.*;
import io.github.resilience4j.circuitbreaker.CircuitBreaker;
import io.github.resilience4j.circuitbreaker.CircuitBreakerConfig;

public class UserActivityAggregator {
    private static final CircuitBreaker circuitBreaker = CircuitBreaker.of("analyticsPlatform", CircuitBreakerConfig.custom()
            .failureRateThreshold(50)
            .waitDurationInOpenState(Duration.ofSeconds(10))
            .build());

    public static void main(String[] args) {
        ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(3);

        // WebSocket data ingestion
        scheduler.scheduleAtFixedRate(() -> processWebSocketData(), 0, 1, TimeUnit.SECONDS);

        // HTTP data ingestion
        scheduler.scheduleAtFixedRate(() -> processHttpData(), 0, 2, TimeUnit.SECONDS);

        // MQTT data ingestion
        scheduler.scheduleAtFixedRate(() -> processMqttData(), 0, 3, TimeUnit.SECONDS);
    }

    private static void processWebSocketData() {
        try {
            circuitBreaker.executeSupplier(() -> {
                // Process WebSocket data and enrich with external insights from analytics platform
                return true;
            });
        } catch (Exception e) {
            System.err.println("Failed to process WebSocket data: " + e.getMessage());
        }
    }

    private static void processHttpData() {
        try {
            circuitBreaker.executeSupplier(() -> {
                // Process HTTP data and enrich with external insights from analytics platform
                return true;
