from flask import Flask, request, jsonify
from flask_caching import Cache
from apscheduler.schedulers.background import BackgroundScheduler
import requests
import threading
import time

app = Flask(__name__)
cache = Cache(app, config={'CACHE_TYPE': 'simple'})
scheduler = BackgroundScheduler()

config_data = {}
module_cache = {}

def load_config():
    global config_data
    # Simulate fetching configuration from a distributed storage service
    config_data = {"api_key": "fake_api_key", "endpoint": "https://api.example.com"}
    return config_data

def fetch_updates():
    global module_cache, config_data
    for module in module_cache:
        try:
            response = requests.get(config_data['endpoint'], headers={"Authorization": f"Bearer {config_data['api_key']}"})
            response.raise_for_status()
            new_module_data = response.json()
            if new_module_data != module_cache[module]:
                module_cache[module] = new_module_data
        except (requests.RequestException, KeyError) as e:
            # Handle API failures and missing keys gracefully
            pass

def refresh_config():
    while True:
        time.sleep(600)  # Run every 10 minutes
        load_config()
        fetch_updates()

scheduler.add_job(refresh_config, 'interval', minutes=10)

@app.route('/api/data')
@cache.cached(timeout=50)  # Cache this endpoint for 50 seconds
def get_data():
    global module_cache
    data = {}
    for module in module_cache:
        data[module] = module_cache[module]
    return jsonify(data), 200

@app.route('/api/module', methods=['POST'])
def add_module():
    data = request.get_json()
    if 'module_name' in data and 'module_data' in data:
        module_cache[data['module_name']] = data['module_data']
        return jsonify({"message": "Module added successfully"}), 201
    else:
        return jsonify({"error": "Invalid module data"}), 400

def start_scheduler():
    scheduler.start()

if __name__ == '__main__':
    thread = threading.Thread(target=start_scheduler)
    thread.daemon = True
    thread.start()
    app.run(debug=True, host='0.0.0.0')
```

