        this.channel = channel;
        blockingStub = MetricsServiceGrpc.newBlockingStub(channel);
    }

    public void getMetrics(String serviceId, StreamObserver<MetricsResponse> responseObserver) {
        MetricsRequest request = MetricsRequest.newBuilder()
                .setServiceId(serviceId)
                .build();
        blockingStub.getMetrics(request, responseObserver);
    }

    public void shutdown() throws InterruptedException {
        channel.shutdown().awaitTermination(5, TimeUnit.SECONDS);
    }
}
