import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

public class CollaborativeDocumentService {

    private final VersionControlSystem versionControlSystem;
    private final AuthenticationProvider authenticationProvider;
    private final DocumentStorageSolution documentStorageSolution;
    private final ConflictResolver conflictResolver;

    public CollaborativeDocumentService(VersionControlSystem versionControlSystem,
                                        AuthenticationProvider authenticationProvider,
                                        DocumentStorageSolution documentStorageSolution,
                                        ConflictResolver conflictResolver) {
        this.versionControlSystem = versionControlSystem;
        this.authenticationProvider = authenticationProvider;
        this.documentStorageSolution = documentStorageSolution;
        this.conflictResolver = conflictResolver;
    }

    public Flux<Document> getDocumentUpdates(String documentId, String userId) {
        return documentStorageSolution.getDocument(documentId)
                .flatMapMany(document -> 
                    versionControlSystem.getChangesSince(document.getLastCommit())
                        .flatMap(change -> 
                            authenticationProvider.authenticate(userId, change.getUser())
                                .then(versionControlSystem.applyChange(change))
                                .onErrorResume(e -> conflictResolver.resolveConflict(change, document))
                        )
                );
    }

    public Mono<Void> saveDocument(String documentId, Document document) {
        return versionControlSystem.commitChanges(document)
                .flatMap(documentStorageSolution::saveDocument);
    }

