import asyncio
from kafka import KafkaProducer, KafkaConsumer
from kafka.admin import AdminClient, NewTopic

class MessagingBroker:
    def __init__(self, bootstrap_servers):
        self.producer = KafkaProducer(bootstrap_servers=bootstrap_servers)
        self.consumer = KafkaConsumer(bootstrap_servers=bootstrap_servers)

    async def publish(self, topic, message):
        await asyncio.to_thread(self.producer.send, topic, value=message.encode('utf-8'))

    async def subscribe(self, topic):
        self.consumer.subscribe([topic])
        try:
            for message in self.consumer:
                yield message.value.decode('utf-8')
        finally:
            self.consumer.unsubscribe()

class ExternalMessageBroker:
    def __init__(self, external_broker_url):
        self.external_producer = KafkaProducer(bootstrap_servers=external_broker_url)
        self.external_consumer = KafkaConsumer(bootstrap_servers=external_broker_url)

    async def publish_external(self, topic, message):
        await asyncio.to_thread(self.external_producer.send, topic, value=message.encode('utf-8'))

    async def subscribe_external(self, topic):
        self.external_consumer.subscribe([topic])
        try:
            for message in self.external_consumer:
                yield message.value.decode('utf-8')
        finally:
            self.external_consumer.unsubscribe()

class ClusterManager:
    def __init__(self, kafka_broker_urls):
        self.admin_client = AdminClient(bootstrap_servers=kafka_broker_urls)

    async def add_cluster(self, cluster_name, num_partitions):
        topic_list = [NewTopic(name=cluster_name, num_partitions=num_partitions, replication_factor=3)]
        futures = self.admin_client.create_topics(new_topics=topic_list)
        for _, future in futures.items():
            try:
                future.result()
            except Exception as e:
                print(f"Failed to create topic: {e}")

