#include <iostream>
#include <memory>
#include <string>
#include <vector>
#include <future>
#include <mutex>

class ConfigManager {
public:
    using ConfigData = std::variant<std::string, int, double>;
    using ConfigKey = std::string;

    struct ConfigVersion {
        int version;
        std::chrono::time_point<std::chrono::system_clock> timestamp;
    };

    class ConfigSource {
    public:
        virtual ~ConfigSource() = default;
        virtual ConfigData get(const ConfigKey& key) const = 0;
        virtual void update(const ConfigKey& key, const ConfigData& data) = 0;
        virtual ConfigVersion getVersion() const = 0;
    };

    class ConfigCache {
    public:
        using CacheEntry = std::pair<ConfigData, ConfigVersion>;

        void put(const ConfigKey& key, const CacheEntry& entry) {
            cache_[key] = entry;
        }

        bool get(const ConfigKey& key, CacheEntry& entry) const {
            auto it = cache_.find(key);
            if (it != cache_.end()) {
                entry = it->second;
                return true;
            }
            return false;
        }

    private:
        std::unordered_map<ConfigKey, CacheEntry> cache_;
    };

    ConfigManager(std::vector<std::unique_ptr<ConfigSource>> sources)
        : sources_(std::move(sources)), cache_(std::make_unique<ConfigCache>()) {}

    void update(const ConfigKey& key, const ConfigData& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& source : sources_) {
            source->update(key, data);
        }
        cache_->put(key, {data, getCurrentVersion()});
    }

    ConfigData get(const ConfigKey& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        ConfigEntry entry;
        if (cache_->get(key, entry)) {
            return entry.first;
        }
        for (auto& source : sources_) {
            ConfigData data = source->get(key);
            cache_->put(key, {data, getCurrentVersion()});
            return data;
        }
        throw std::runtime_error("Configuration key not found");
    }

private:
    std::vector<std::unique_ptr<ConfigSource>> sources_;
    std::unique_ptr<ConfigCache> cache_;
    mutable std::mutex mutex_;

    ConfigVersion getCurrentVersion() const {
        ConfigVersion version;
        version.version = 0; // Simulated versioning logic
        version.timestamp = std::chrono::system_clock::now();
        return version;
    }
};
```']

