# This is a high-level Python script outline for a logging framework
# Due to its complexity, actual implementation would be much more detailed

import yaml
from abc import ABC, abstractmethod
import queue
import threading
import time
import random

class Logger(ABC):
    @abstractmethod
    def log(self, message: str):
        pass

class ConsoleLogger(Logger):
    def log(self, message: str):
        print(message)

class FileLogger(Logger):
    def __init__(self, filename: str):
        self.filename = filename

    def log(self, message: str):
        with open(self.filename, 'a') as f:
            f.write(message + '\n')

