[Route("api/[controller]")]
public class NotificationHubController : ControllerBase
{
    private readonly IAmazonSimpleNotificationService _snsClient;

    public NotificationHubController(IAmazonSimpleNotificationService snsClient)
    {
        _snsClient = snsClient;
    }

    [HttpPost("send")]
    public async Task<IActionResult> SendNotification([FromBody] NotificationRequest request)
    {
        var message = new Message { Subject = request.Subject, Body = request.Body };

        var response = await _snsClient.PublishAsync(new PublishRequest
        {
            TopicArn = "arn:aws:sns:us-east-1:123456789012:NotificationTopic",
            Message = Newtonsoft.Json.JsonConvert.SerializeObject(message),
            MessageStructure = "json"
        });

        return Ok(new { MessageId = response.MessageId });
    }
}

public class NotificationRequest
{
    public string Subject { get; set; }
    public string Body { get; set; }
}

public class Message
{
    public string Subject { get; set; }
    public string Body { get; set; }
}
