// JavaScript function to refresh multiple dialog fields using a resource ID and URL
function refreshDialogFields(resourceId, url) {
    const fieldsToRefresh = ['field1', 'field2', 'field3']; // Example field names to refresh

    // Iterate through all dialog fields
    document.querySelectorAll('.dialog-field').forEach(field => {
        // Check if the field name matches any of the names in the array of field names to refresh
        if (fieldsToRefresh.includes(field.name)) {
            fetch(url + resourceId)
                .then(response => response.json())
                .then(data => {
                    // Update the field value with data from API
                    field.value = data[field.name];
                })
                .catch(error => {
                    console.error('Error refreshing dialog field:', error);
                });
        }
    });
}
