// Global variables for thread safety and memory management
pthread_mutex_t allocation_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *memory_pool = NULL;
size_t pool_size = 0;

// Function to initialize the memory pool
void init_memory_pool(size_t N) {
    pthread_mutex_lock(&allocation_lock);
    if (memory_pool == NULL) {
        memory_pool = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (memory_pool == NULL) {
            perror("Failed to allocate memory for memory pool");
            exit(EXIT_FAILURE);
        }
        pool_size = N;
    }
    pthread_mutex_unlock(&allocation_lock);
}

// Function to safely generate unique RX_UE_INFORMATION_TAG
int generate_unique_rx_ue_information_tag() {
    static int current_tag = 0;
    pthread_mutex_lock(&allocation_lock);
    int tag = current_tag++;
    pthread_mutex_unlock(&allocation_lock);
    return tag;
}

// Main function to allocate and populate structures
NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_structs(int N) {
    if (N <= 0 || memory_pool == NULL) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *result = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (result == NULL) {
        perror("Failed to allocate memory for result array");
        return NULL;
    }

    pthread_mutex_lock(&allocation_lock);
    for (int i = 0; i < N; i++) {
        result[i].RX_UE_INFORMATION_TAG = generate_unique_rx_ue_information_tag();
        result[i].RNTI = rand() % 65536; // Random RNTI value
        result[i].CRC_INDICATION_REL8_TAG = rand() % 256; // Random CRC_INDICATION_REL8_TAG value
        result[i].CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
    }
    pthread_mutex_unlock(&allocation_lock);

    return result;
}

// Function to free allocated memory
void free_structs(NFAPI_CRC_INDICATION_PDU_T *structs, size_t N) {
    if (structs != NULL) {
        free(structs);
    }
}

int main() {
