    init_memory_pool(1000); // Initialize memory pool with 1000 structs

    int N = 5; // Number of structures to allocate and populate
    NFAPI_CRC_INDICATION_PDU_T *structs = allocate_and_populate_structs(N);
    if (structs != NULL) {
        // Use the allocated structures
