#define MAX_TAGS 100000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* array = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
uint32_t next_tag = 1;

void initialize_array(int N) {
    array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Failed to allocate memory for the array");
        exit(EXIT_FAILURE);
    }
}

uint32_t generate_unique_tag() {
    uint32_t tag;
    pthread_mutex_lock(&lock);
    do {
        tag = next_tag++;
        if (next_tag >= MAX_TAGS) {
            next_tag = 1; // Wrap around
        }
    } while (find_by_tag(tag));
    pthread_mutex_unlock(&lock);
    return tag;
}

bool find_by_tag(uint32_t tag) {
    for (int i = 0; i < N; i++) {
        if (array[i].RX_UE_INFORMATION_TAG == tag) {
            return true;
        }
    }
    return false;
}

void initialize_structures(int N) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = generate_unique_tag();
        array[i].RNTI = rand() % 1024;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        array[i].CRCFLAG = (rand() % 2) ? true : false;
    }
    pthread_mutex_unlock(&lock);
}

void* thread_function(void* arg) {
    int N = *(int*)arg;
    initialize_structures(N);
    return NULL;
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <N>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int N = atoi(argv[1]);
    if (N <= 0) {
        fprintf(stderr, "Invalid input: N must be a positive integer\n");
        return EXIT_FAILURE;
    }

    initialize_array(N);

    pthread_t threads[N];
    for (int i = 0; i < N; i++) {
        pthread_create(&threads[i], NULL, thread_function, &N);
    }

    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }

    free(array);
    return EXIT_SUCCESS;
}
