    std::vector<NFAPI_CRC_INDICATION_PDU_T> dataPool;
    std::mutex poolMutex;
    std::condition_variable notFull;
    std::queue<NFAPI_CRC_INDICATION_PDU_T*> taskQueue;
    std::mutex queueMutex;
    std::condition_variable notEmpty;
