    CURL* curlHandle = curl_easy_init();

    std::vector<std::thread> workers(4); // Example number of threads
    for (auto& worker : workers) {
        worker = std::thread(worker, std::ref(service), curlHandle);
    }

    // Simulate producing data
    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* item = &service.dataPool[i];
        service.produce(item);
    }

    // Wait for all workers to finish
    for (auto& worker : workers) {
        worker.join();
    }

    curl_easy_cleanup(curlHandle);
    return 0;
