#include <algorithm>

// Function to copy a specified number of bytes from a list of buffered data chunks
std::vector<std::byte> copyBufferedData(const std::vector<std::vector<std::byte>>& buffers, size_t numBytes) {
    std::vector<std::byte> result;
    result.reserve(numBytes);

    for (const auto& buffer : buffers) {
        if (result.size() + buffer.size() > numBytes) {
            std::copy_n(buffer.begin(), numBytes - result.size(), std::back_inserter(result));
            break;
        }
        std::copy(buffer.begin(), buffer.end(), std::back_inserter(result));
    }

    return result;
}

int main() {
    // Example usage
    std::vector<std::byte> buffer1 = {0x01, 0x23, 0x45};
    std::vector<std::byte> buffer2 = {0x67, 0x89, 0xAB, 0xCD};
    std::vector<std::byte> buffer3 = {0xEF, 0x01};

    std::vector<std::vector<std::byte>> buffers = {buffer1, buffer2, buffer3};
    size_t numBytesToCopy = 5;

    std::vector<std::byte> copiedData = copyBufferedData(buffers, numBytesToCopy);

    // Output the copied data
    for (auto byte : copiedData) {
        std::cout << std::hex << static_cast<int>(byte) << " ";
    }
    std::cout << std::endl;

    return 0;
}
