using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class DecryptionService
{
    private readonly ConcurrentDictionary<string, (byte[], byte[])> _cache = new();
    private readonly HttpClient _httpClient;
    private readonly string _configurationServiceUrl;

    public DecryptionService(string configurationServiceUrl)
    {
        _configurationServiceUrl = configurationServiceUrl;
        _httpClient = new HttpClient();
    }

    public async Task<byte[]> DecryptAsync(string base64EncodedMessage, string keyId)
    {
        var (key, iv) = await GetDecryptionParametersAsync(keyId);

        using (var decryptor = Aes.Create())
        {
            decryptor.Key = key;
            decryptor.IV = iv;

            var encryptedData = Convert.FromBase64String(base64EncodedMessage);
            var decryptedData = decryptor.CreateDecryptor().TransformFinalBlock(encryptedData, 0, encryptedData.Length);

            return decryptedData;
        }
    }

    private async Task<(byte[], byte[])> GetDecryptionParametersAsync(string keyId)
    {
        if (_cache.TryGetValue(keyId, out var parameters))
        {
            return parameters;
        }

        var response = await _httpClient.GetAsync($"{_configurationServiceUrl}/{keyId}");
        response.EnsureSuccessStatusCode();

        var decryptionParameters = await response.Content.ReadAsAsync<DecryptionParameters>();
        _cache.TryAdd(keyId, (decryptionParameters.Key, decryptionParameters.IV));

        return decryptionParameters;
    }
}

public class DecryptionParameters
{
    public byte[] Key { get; set; }
    public byte[] IV { get; set; }
}
