            _cachingService = cachingService;
            _rateLimiterService = rateLimiterService;
            _logger = logger;
        }

        [HttpPost("decrypt")]
        public async Task<IActionResult> DecryptData([FromBody] DecryptionRequest request)
        {
            try
            {
                if (!_rateLimiterService.AllowRequest(request.ClientId))
                    return StatusCode(429, "Too Many Requests");

                byte[] encryptionKey = await GetEncryptionKeyFromApi(request.ApiEndpoint);
                byte[] authenticationTag = Convert.FromBase64String(request.AuthenticationTag);
                byte[] initializationVector = Convert.FromBase64String(request.InitializationVector);
                byte[] ciphertext = Convert.FromBase64String(request.Ciphertext);

                using (AesGcm aesGcm = new AesGcm(encryptionKey))
                {
                    byte[] decryptedData;
                    aesGcm.Decrypt(authenticationTag, initializationVector, ciphertext, Array.Empty<byte>(), out decryptedData);
                    string dataString = Encoding.UTF8.GetString(decryptedData);
                    var dataObject = JsonConvert.DeserializeObject<CustomDataStructure>(dataString);

                    using (FileStream fs = new FileStream("path_to_binary_file", FileMode.Open))
                    {
                        BinaryFormatter formatter = new BinaryFormatter();
                        CustomDataStructure loadedData = (CustomDataStructure)formatter.Deserialize(fs);
                    }

                    return Ok(new { Data = dataObject });
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error during decryption process.");
                return StatusCode(500, "Internal Server Error");
            }
        }

        private async Task<byte[]> GetEncryptionKeyFromApi(string apiEndpoint)
        {
            try
            {
                if (_cachingService.TryGet("encryptionKey", out byte[] cachedKey))
                    return cachedKey;

                var response = await _httpClient.GetAsync(apiEndpoint);
                response.EnsureSuccessStatusCode();
                string keyString = await response.Content.ReadAsStringAsync();
                byte[] encryptionKey = Convert.FromBase64String(keyString);

                _cachingService.Set("encryptionKey", encryptionKey, TimeSpan.FromMinutes(10));
                return encryptionKey;
            }
            catch (Exception ex)
