// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int some_field;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a simple pool structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t size;
    size_t count;
    pthread_mutex_t mutex;
} NFAPool;

// Initialize the pool
void nfapool_init(NFAPool *pool, size_t size) {
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->size = size;
    pool->count = 0;
    pthread_mutex_init(&pool->mutex, NULL);
}

// Get an item from the pool
NFAPI_CRC_INDICATION_PDU_T* nfapool_get(NFAPool *pool) {
    NFAPI_CRC_INDICATION_PDU_T *item;
    pthread_mutex_lock(&pool->mutex);
    if (pool->count > 0) {
        item = &pool->pool[--pool->count];
    } else {
        item = NULL; // Handle pool exhaustion
    }
    pthread_mutex_unlock(&pool->mutex);
    return item;
}

// Free an item back to the pool
void nfapool_put(NFAPool *pool, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->count < pool->size) {
        pool->pool[pool->count++] = *item;
    } else {
        // Handle pool overflow
    }
    pthread_mutex_unlock(&pool->mutex);
}

// MD5 hashing function
void md5(const char *data, size_t len, unsigned char out[16]) {
