#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    ALLOC_SUCCESS,
    ALLOC_FAILURE_DB_CONN,
    ALLOC_FAILURE_MEM_ALLOC,
    ALLOC_FAILURE_CONCURRENCY
} AllocationResult;

typedef struct {
    pthread_mutex_t mutex;
    size_t total_allocated;
    size_t successful_allocations;
    size_t failed_allocations;
} MemoryManager;

MemoryManager memory_manager = {PTHREAD_MUTEX_INITIALIZER, 0, 0, 0};

int fetch_unique_rx_tag() {
    // Simulate fetching a unique RX_UE_INFORMATION_TAG from an external database
    static int tag = 0;
    return tag++;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_memory(size_t N) {
    pthread_mutex_lock(&memory_manager.mutex);

    for (size_t i = 0; i < N; ++i) {
        AllocationResult result = ALLOC_FAILURE_DB_CONN;

        // Simulate database fetch
        int tag = fetch_unique_rx_tag();
        if (tag == -1) {
            fprintf(stderr, "Failed to fetch unique RX_UE_INFORMATION_TAG\n");
            result = ALLOC_FAILURE_DB_CONN;
            goto cleanup;
        }

        NFAPI_CRC_INDICATION_PDU_T* new_struct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_struct) {
            fprintf(stderr, "Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T\n");
            result = ALLOC_FAILURE_MEM_ALLOC;
            goto cleanup;
        }

        new_struct->RX_UE_INFORMATION_TAG = tag;

        // Simulate concurrent access
        pthread_mutex_t temp_lock;
        if (pthread_mutex_init(&temp_lock, NULL) != 0) {
            fprintf(stderr, "Failed to initialize temporary mutex\n");
            result = ALLOC_FAILURE_CONCURRENCY;
            free(new_struct);
            goto cleanup;
        }

        pthread_mutex_destroy(&temp_lock);

        memory_manager.total_allocated++;
        memory_manager.successful_allocations++;

        // Log successful allocation
        printf("Successfully allocated %zu/%zu structures\n", i + 1, N);
    }

cleanup:
    if (result != ALLOC_SUCCESS) {
        memory_manager.failed_allocations++;
        // Log failed allocation with reason
        printf("Failed to allocate %s\n", result == ALLOC_FAILURE_DB_CONN ? "due to database connection issues" : 
                                          result == ALLOC_FAILURE_MEM_ALLOC ? "due to memory allocation failure" :
                                          result == ALLOC_FAILURE_CONCURRENCY ? "due to concurrency problems" : "");
    }

    pthread_mutex_unlock(&memory_manager.mutex);
    return (result == ALLOC_SUCCESS) ? malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T)) : NULL;
}

void* monitor_memory_state(void* arg) {
    while (1) {
        pthread_mutex_lock(&memory_manager.mutex);
        printf("Total allocated: %zu, Successful allocations: %zu, Failed allocations: %zu\n",
               memory_manager.total_allocated,
               memory_manager.successful_allocations,
               memory_manager.failed_allocations);
        pthread_mutex_unlock(&memory_manager.mutex);

        // Simulate real-time updates
        sleep(5);
    }

    return NULL;
}

int main() {
    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, monitor_memory_state, NULL);

    NFAPI_CRC_INDICATION_PDU_T* array = allocate_memory(100);
    if (!array) {
        fprintf(stderr, "Failed to allocate memory for the array\n");
        return EXIT_FAILURE;
    }

    free(array);
    pthread_join(monitor_thread, NULL);

    return EXIT_SUCCESS;
}
