void mq_push(MESSAGE_QUEUE_T* mq, NFAPI_CRC_INDICATION_PDU_T* pdu);
NFAPI_CRC_INDICATION_PDU_T* mq_pop(MESSAGE_QUEUE_T* mq);

void log_event(const char* type, const char* message);

// Global variables for the library
DB_CONNECTION_T db_conn;
MESSAGE_QUEUE_T msg_queue;

// Mutex and condition variable for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
bool shutdown_flag = false;

// Function to initialize the library
void init_library() {
    // Initialize database connection
    db_conn = db_connect("MySQL", "host=localhost;user=root;password=pass;dbname=test");
    if (!db_conn) {
        log_event("ERROR", "Failed to connect to database");
        exit(EXIT_FAILURE);
    }

    // Initialize message queue
    mq_init(&msg_queue);

    // Start background thread for processing messages
    pthread_t tid;
    pthread_create(&tid, NULL, process_messages, NULL);
}

// Function to clean up the library on exit
void cleanup_library() {
    // Stop background thread
    shutdown_flag = true;
    pthread_cond_signal(&cond);

    // Wait for the thread to finish
    pthread_join(tid, NULL);

    // Disconnect from database
    db_disconnect(&db_conn);
}

// Background thread function for processing messages
void* process_messages(void* arg) {
    while (!shutdown_flag) {
        NFAPI_CRC_INDICATION_PDU_T* pdu;
        pthread_mutex_lock(&lock);
        while ((pdu = mq_pop(&msg_queue)) == NULL && !shutdown_flag) {
            pthread_cond_wait(&cond, &lock);
        }
        pthread_mutex_unlock(&lock);

        if (pdu) {
            // Process the message
            db_insert(&db_conn, pdu);
            free(pdu);  // Free the memory allocated for the message
        }
    }

    return NULL;
}

// Function to insert a new PDU into the database and enqueue it for processing
int insert_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    int result = db_insert(&db_conn, pdu);
    if (result == 0) {
        mq_push(&msg_queue, pdu);
        pthread_cond_signal(&cond);
    } else {
        log_event("ERROR", "Failed to insert PDU into database");
        free(pdu);  // Free the memory allocated for the PDU on failure
    }

    return result;
}

// Function to query a PDU from the database by ID
NFAPI_CRC_INDICATION_PDU_T* query_pdu(int id) {
    return db_query(&db_conn, id);
}

// Function to delete a PDU from the database by ID
int delete_pdu(int id) {
    int result = db_delete(&db_conn, id);
    if (result != 0) {
        log_event("ERROR", "Failed to delete PDU from database");
    }

    return result;
}
