    // Define your structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T *data;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->capacity = initial_capacity;
    array->size = 0;
    array->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, NFAPI_CRC_INDICATION_PDU_T_SIZE);
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    free(array->data);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_to_dynamic_array(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->data, new_capacity * NFAPI_CRC_INDICATION_PDU_T_SIZE);
        if (!new_data) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    memcpy(&array->data[array->size], &element, NFAPI_CRC_INDICATION_PDU_T_SIZE);
    array->size++;
    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

