// This code snippet represents a simplified example of a component within the middleware application.
// It demonstrates how to create a custom message broker using Java with Apache Kafka as an underlying messaging system.

import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerRecord;

import java.util.Properties;

public class CustomMessageBroker {

    private final KafkaProducer<String, String> producer;

    public CustomMessageBroker(String bootstrapServers) {
        Properties props = new Properties();
        props.put("bootstrap.servers", bootstrapServers);
        props.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        props.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");

        this.producer = new KafkaProducer<>(props);
    }

    public void sendMessage(String topic, String key, String value) {
        ProducerRecord<String, String> record = new ProducerRecord<>(topic, key, value);
        producer.send(record, (metadata, exception) -> {
            if (exception != null) {
                exception.printStackTrace();
            } else {
                System.out.printf("Message sent to topic %s with offset %d%n", metadata.topic(), metadata.offset());
            }
        });
    }

    public void close() {
        producer.close();
    }

    // Unit and integration tests can be implemented here using frameworks like JUnit and Mockito
}

