use tokio::net::TcpListener;
use hyper::{Body, Request, Response, Server};
use tower_http::retry::RetryLayer;
use tower_http::services::ServeDir;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Create a new HTTP server that listens on a TCP socket
    let addr = "127.0.0.1:3000".parse()?;
    let listener = TcpListener::bind(&addr).await?;

    // Define a service to handle requests
    let make_svc = || async {
        Ok::<_, std::io::Error>(ServiceBuilder::new()
            .layer(RetryLayer::new())
            .service(ServeDir::new("public")))
    };

    // Create the server and start listening for incoming connections
    let server = Server::builder(make_svc)
        .serve(listener);

    println!("Listening on {}", addr);
    if let Err(e) = server.await {
        eprintln!("Server error: {}", e);
    }

    Ok(())
}
