# Python Library: Real-Time Data Processing

import threading
from queue import Queue, Full, Empty
import time
import logging

class DataProcessor:
    def __init__(self, max_threads=10):
        self.max_threads = max_threads
        self.queue = Queue(maxsize=50)
        self.threads = []
        for _ in range(self.max_threads):
            t = threading.Thread(target=self.process_data)
            t.start()
            self.threads.append(t)

    def add_to_queue(self, data):
        try:
            self.queue.put(data)
        except Full:
            logging.warning("Queue is full")

    def process_data(self):
        while True:
            try:
                data = self.queue.get(timeout=1)
                # Perform data processing here
                print(f"Processing {data}")
                self.queue.task_done()
            except Empty:
                pass

# C Program: Concurrent Data Processing (simplified)

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define QUEUE_SIZE 50
#define MAX_THREADS 100

typedef struct {
    int data;
    pthread_mutex_t lock;
} Data;

Data queue[QUEUE_SIZE];
int front = -1, rear = -1;
sem_t mutex, full, empty;

void* process_data(void* arg) {
    while (1) {
        sem_wait(&full);
        sem_wait(&mutex);

        if (front == -1 && rear == -1) {
            printf("Queue is empty\n");
        } else {
            front = (front + 1) % QUEUE_SIZE;
            int data = queue[front].data;
            printf("Processing %d\n", data);
        }

        sem_post(&mutex);
        sem_post(&empty);
    }
}

int main() {
    pthread_t threads[MAX_THREADS];
    sem_init(&mutex, 0, 1);
    sem_init(&full, 0, QUEUE_SIZE);
    sem_init(&empty, 0, 0);

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, process_data, NULL);
    }

    int data_to_process[] = {1, 2, 3, 4, 5};
    int num_data = sizeof(data_to_process) / sizeof(data_to_process[0]);

    for (int i = 0; i < num_data; i++) {
        sem_wait(&empty);
        sem_wait(&mutex);

        if (front == -1 && rear == -1) {
            front = rear = 0;
        } else {
            rear = (rear + 1) % QUEUE_SIZE;
        }
        queue[rear].data = data_to_process[i];
        printf("Added to queue: %d\n", data_to_process[i]);

        sem_post(&mutex);
        sem_post(&full);
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&mutex);
    sem_destroy(&full);
    sem_destroy(&empty);

    return 0;
}
```

