using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace SecureStateManagementLibrary
{
    public class StateManager
    {
        private readonly byte[] _key;
        private readonly byte[] _iv;
        private readonly ICryptoTransform _encryptor;
        private readonly ICryptoTransform _decryptor;

        public StateManager(byte[] key, byte[] iv)
        {
            _key = key;
            _iv = iv;
            _encryptor = AES.Create().CreateEncryptor(_key, _iv);
            _decryptor = AES.Create().CreateDecryptor(_key, _iv);
        }

        public async Task<string> EncryptAsync(string plaintext)
        {
            using (var memoryStream = new MemoryStream())
            {
                using (var cryptoStream = new CryptoStream(memoryStream, _encryptor, CryptoStreamMode.Write))
                {
                    await cryptoStream.WriteAsync(Encoding.UTF8.GetBytes(plaintext), 0, plaintext.Length);
                }
                return Convert.ToBase64String(memoryStream.ToArray());
            }
        }

        public async Task<string> DecryptAsync(string ciphertext)
        {
            using (var memoryStream = new MemoryStream(Convert.FromBase64String(ciphertext)))
            {
                using (var cryptoStream = new CryptoStream(memoryStream, _decryptor, CryptoStreamMode.Read))
                {
                    using (var reader = new StreamReader(cryptoStream))
                    {
                        return await reader.ReadToEndAsync();
                    }
                }
            }
        }
    }

    public class StateTransitionHandler
    {
        private readonly StateManager _stateManager;

        public StateTransitionHandler(byte[] key, byte[] iv)
        {
            _stateManager = new StateManager(key, iv);
        }

        public async Task<string> TransitionStateAsync(string ciphertext)
        {
            var plaintext = await _stateManager.DecryptAsync(ciphertext);
