#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_THREADS 10
#define CACHE_SIZE 1024

typedef struct {
    char *key;
    char *value;
} CacheItem;

typedef struct {
    CacheItem items[CACHE_SIZE];
    int size;
} Cache;

Cache cache;

void init_cache() {
    memset(&cache, 0, sizeof(cache));
}

int cache_get(char *key, char **value) {
    for (int i = 0; i < cache.size; i++) {
        if (strcmp(cache.items[i].key, key) == 0) {
            *value = strdup(cache.items[i].value);
            return 1;
        }
    }
    return 0;
}

void cache_set(char *key, char *value) {
    if (cache.size < CACHE_SIZE) {
        CacheItem item = {strdup(key), strdup(value)};
        cache.items[cache.size++] = item;
    } else {
        // Evict least recently used item
        for (int i = 0; i < CACHE_SIZE - 1; i++) {
            cache.items[i] = cache.items[i + 1];
        }
        CacheItem item = {strdup(key), strdup(value)};
        cache.items[CACHE_SIZE - 1] = item;
    }
}

void *load_resource(void *arg) {
    char *url = (char *)arg;
    CURL *curl;
    CURLcode res;
    char buffer[1024];

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, (void (*)(char *, size_t, size_t, void *))fwrite);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, buffer);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    // Parse the JSON and cache the result
    char *value;
    if (cache_get(url, &value)) {
        printf("Cached resource for URL: %s\n", url);
        free(value);
    } else {
        printf("Loading resource from URL: %s\n", url);
        cache_set(url, buffer);
    }

    return NULL;
}

int main() {
    init_cache();

    pthread_t threads[MAX_THREADS];
    char *urls[] = {"https://example.com/resource1", "https://example.com/resource2"};
    int num_urls = sizeof(urls) / sizeof(urls[0]);

    for (int i = 0; i < num_urls; i++) {
        if (pthread_create(&threads[i], NULL, load_resource, urls[i]) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_urls; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("All resources loaded\n");

    return EXIT_SUCCESS;
}
