FSA_State* pool;
int pool_size;
int current_index;
sem_t semaphore;
pthread_mutex_t mutex;

void initialize_pool(int size) {
    pool_size = size;
    pool = (FSA_State*)malloc(pool_size * sizeof(FSA_State));
    sem_init(&semaphore, 0, pool_size);
    pthread_mutex_init(&mutex, NULL);
}

void* acquire_state(void* arg) {
    FSA_State* state;
    sem_wait(&semaphore);
    pthread_mutex_lock(&mutex);
    if (current_index < pool_size) {
        state = &pool[current_index++];
    } else {
        // Handle partial deallocation using LRU or FIFO policy
    }
    pthread_mutex_unlock(&mutex);
    return state;
}

void release_state(FSA_State* state) {
    pthread_mutex_lock(&mutex);
    if (current_index > 0) {
        current_index--;
    } else {
        // Handle partial deallocation using LRU or FIFO policy
    }
    pthread_mutex_unlock(&mutex);
    sem_post(&semaphore);
}

void cleanup_pool() {
    free(pool);
    sem_destroy(&semaphore);
    pthread_mutex_destroy(&mutex);
}
