NFAPI_CRC_INDICATION_PDU_T* allocateAndPopulateNFApiPduArray(int N) {
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        logError("Failed to allocate memory for NFAPI structures");
        return NULL;
    }

