    for (int i = 0; i < N; ++i) {
        array[i].rxTag = currentRxTag++;
        array[i].rnti = generateRandomRNTI();
        array[i].crcTag = generateUniqueCrcTag(array, N);
        array[i].crcFlag = rand() % 256; // Randomly set CRC flag
    }
    pthread_mutex_unlock(&tagMutex);

    return array;
}

void freeNFApiPduArray(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    if (array) {
        free(array);
    }
