class StreamDataCollector {
    constructor() {
        this.buffer = [];
        this.paused = false;
        this.retries = 0;
        this.maxRetries = 5;
        this.backoffTime = 100; // Initial backoff time in ms
    }

    collect(data) {
        if (!this.paused) {
            this.buffer.push(data);
        }
    }

    pause() {
        this.paused = true;
    }

    resume() {
        this.paused = false;
        this.processBuffer();
    }

    async processBuffer() {
        while (this.buffer.length > 0 && !this.paused) {
            try {
                const data = this.buffer.shift();
                await this.exportData(data);
                this.retries = 0; // Reset retries on successful export
            } catch (error) {
                if (this.retries < this.maxRetries) {
                    this.retries++;
                    setTimeout(() => this.processBuffer(), this.backoffTime * Math.pow(2, this.retries));
                } else {
                    logError("Failed to export data after multiple retries");
                }
            }
        }
    }

    async exportData(data, destination) {
        // Placeholder for exporting data
        console.log(`Exporting data to ${destination}:`, data);
    }

    static async collectFromStream(stream, collector) {
        stream.on('data', (chunk) => collector.collect(chunk));
        stream.on('end', () => collector.processBuffer());
        stream.on('error', (err) => logError("Stream error:", err.message));
    }
}

// Usage
const collector = new StreamDataCollector();
StreamDataCollector.collectFromStream(inputStream, collector);
