#define RX_UE_INFORMATION_TAG 0x1A2B3C4D
#define RNTI 0xFEDCBA98
#define CRC_INDICATION_REL8_TAG 0x56789ABC

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int tag;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* pool = NULL;
int pool_size = 0;
int next_index = 0;

void initialize_pool(int N) {
    pthread_mutex_lock(&pool_lock);
    if (pool != NULL) free(pool);
    pool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < N; i++) {
        pool[i].tag = RX_UE_INFORMATION_TAG;
        pool[i].RNTI = RNTI;
        pool[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }
    pool_size = N;
    next_index = 0;
    pthread_mutex_unlock(&pool_lock);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_resource() {
    pthread_mutex_lock(&pool_lock);
    if (next_index < pool_size) {
        return &pool[next_index++];
    } else {
        pthread_mutex_unlock(&pool_lock);
        return NULL; // Pool is full
    }
}

void deallocate_resource(NFAPI_CRC_INDICATION_PDU_T* resource) {
    pthread_mutex_lock(&pool_lock);
    int index = (resource - pool) % pool_size;
    if (index >= 0 && index < pool_size && &pool[index] == resource) {
        next_index--;
        if (next_index < index) {
            memmove(pool + next_index, pool + index + 1, (index - next_index) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
    }
    pthread_mutex_unlock(&pool_lock);
}

