    NFAPI_CRC_INDICATION_PDU_T* resource = allocate_resource();
    if (resource != NULL) {
        *resource = *(NFAPI_CRC_INDICATION_PDU_T*)data;
    }
    free(data); // Free the temporary data
    return resource;
}

void destroy_structure(NFAPI_CRC_INDICATION_PDU_T* resource) {
