/**
 * Recursively traverses a DOM tree and returns a list of elements matching a given selector.
 * @param {HTMLElement} element - The root element to start traversal from.
 * @param {string} selector - The CSS selector to match elements against.
 * @param {Function} testFn - A function that tests if an element should be included based on its class or ID.
 * @returns {Array<HTMLElement>} An array of matching elements.
 */
function traverseDOM(element, selector, testFn) {
    const matches = [];
    if (element.matches(selector)) {
        if (testFn(element)) {
            matches.push(element);
        }
    }
    element.children.forEach(child => {
        matches.push(...traverseDOM(child, selector, testFn));
    });
    return matches;
}
