#include <pthread.h>
#include <stdlib.h>

#define MAX_PDU_POOL_SIZE 10000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pthread_mutex_t lock;
} PDUPoolElement;

PDUPoolElement pdu_pool[MAX_PDU_POOL_SIZE];
int pool_size = 0;

pthread_mutex_t pool_lock;
pthread_cond_t pool_condition;

void init_pdu_pool() {
    pthread_mutex_init(&pool_lock, NULL);
    pthread_cond_init(&pool_condition, NULL);

    for (int i = 0; i < MAX_PDU_POOL_SIZE; i++) {
        pdu_pool[i].lock = PTHREAD_MUTEX_INITIALIZER;
        // Initialize each PDU element as needed
    }
}

PDUPoolElement* acquire_pdu() {
    pthread_mutex_lock(&pool_lock);
    while (pool_size == 0) {
        pthread_cond_wait(&pool_condition, &pool_lock);
    }

    PDUPoolElement* pdu = pdu_pool[--pool_size];
    pthread_mutex_unlock(&pdu_lock);
    return pdu;
}

void release_pdu(PDUPoolElement* pdu) {
    pthread_mutex_lock(&pdu_lock);
    pdu_pool[pool_size++] = *pdu;
    pthread_cond_signal(&pool_condition);
    pthread_mutex_unlock(&pdu_lock);
}
