class RequestPoolManager {
public:
    using HTTP_REQUEST_PDU_T = struct {
        int REQUEST_ID;
        std::string USER_AGENT;
        std::string URI;
        int STATUS_CODE;
    };

private:
    const int N;
    std::vector<std::unique_ptr<HTTP_REQUEST_PDU_T>> pool;
    std::atomic<int> available;
    std::mutex mutex;
    std::condition_variable cv;

public:
    RequestPoolManager(int N) : N(N), available(N), pool(N) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(200, 599);

        for (int i = 0; i < N; ++i) {
            pool[i] = std::make_unique<HTTP_REQUEST_PDU_T>();
            pool[i]->REQUEST_ID = i;
            pool[i]->USER_AGENT = "UserAgent" + std::to_string(i);
            pool[i]->URI = "/path" + std::to_string(i);
            pool[i]->STATUS_CODE = dis(gen);
        }
    }

    HTTP_REQUEST_PDU_T* allocate() {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this] { return available > 0; });
        --available;
        return pool[N - available].get();
    }

    void deallocate(HTTP_REQUEST_PDU_T* request) {
        std::unique_lock<std::mutex> lock(mutex);
        // Perform any necessary pre-deallocation checks or updates
        ++available;
        cv.notify_one();
    }
};
