class MD5Hasher {
public:
    std::string computeMD5(const std::string& input) {
        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)input.c_str(), input.length(), (unsigned char*)&digest);    
        char mdString[33];
        for(int i = 0; i < 16; ++i)
            sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);
        return std::string(mdString);
    }
};

class JSONStreamHandler {
public:
    void streamJSON(const std::string& filePath, const MD5Hasher& hasher) {
        std::ifstream file(filePath, std::ios::binary | std::ios::ate);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open file");
        }

        std::streamsize size = file.tellg();
        file.seekg(0, std::ios::beg);

        char* buffer = new char[size];
        if (!file.read(buffer, size)) {
            delete[] buffer;
            throw std::runtime_error("Failed to read file");
        }
        file.close();

        std::string md5Hash = hasher.computeMD5(std::string(buffer, size));
        std::cout << "File MD5: " << md5Hash << std::endl;

        Json::Value root;
        Json::CharReaderBuilder builder;
        std::unique_ptr<Json::CharReader> reader(builder.newCharReader());
        std::string errs;
        if (!reader->parse(buffer, buffer + size, &root, &errs)) {
            delete[] buffer;
            throw std::runtime_error("Failed to parse JSON: " + errs);
        }

        // Deserialize logic here
        // Example: CustomDataModel data = deserializeJSON(root);

        delete[] buffer;
    }
};

