struct CUSTOMER_ORDER_RECORD {
    int ORDER_ID;
    int CUSTOMER_ID;
    // Other fields...
};

class OrderManager {
public:
    using RecordPtr = std::shared_ptr<CUSTOMER_ORDER_RECORD>;

    OrderManager(size_t initial_capacity)
        : order_pool_(initial_capacity, [](CUSTOMER_ORDER_RECORD* rec) { delete[] rec; }),
          next_order_id_(1),
          transaction_count_(0) {}

    ~OrderManager() {
        // RAII will handle releasing resources
    }

    RecordPtr addOrder(const CUSTOMER_ORDER_RECORD& record) {
        std::lock_guard<std::mutex> lock(mutex_);
        RecordPtr new_record(order_pool_.allocate());
        new (new_record.get()) CUSTOMER_ORDER_RECORD(record); // Placement new to call constructor on pre-allocated memory
        order_set_.insert(new_record);
        return new_record;
    }

    void removeOrder(const RecordPtr& record) {
        std::lock_guard<std::mutex> lock(mutex_);
        order_set_.erase(record);
        record->~CUSTOMER_ORDER_RECORD(); // Explicitly call destructor
        order_pool_.deallocate(record.get(), 1);
    }

private:
    struct OrderPool : public std::pmr::memory_resource {
        explicit OrderPool(size_t initial_capacity, std::function<void(CUSTOMER_ORDER_RECORD*)> deleter)
            : capacity_(initial_capacity), pool_(new CUSTOMER_ORDER_RECORD[capacity_]), deleter_(deleter) {}

        ~OrderPool() override {
            deleter_(pool_);
            delete[] pool_;
        }

        void* do_allocate(std::size_t bytes, std::size_t alignment) override {
            if (next_free_ + bytes > capacity_) {
                throw std::bad_alloc();
            }
            void* ptr = reinterpret_cast<void*>(reinterpret_cast<char*>(pool_) + next_free_);
            next_free_ += bytes;
            return ptr;
        }

        void do_deallocate(void* p, std::size_t bytes, std::size_t alignment) override {}

    private:
        size_t capacity_;
        CUSTOMER_ORDER_RECORD* pool_;
        std::function<void(CUSTOMER_ORDER_RECORD*)> deleter_;
        size_t next_free_ = 0;
    };

    OrderPool order_pool_;
    std::mutex mutex_;
    std::unordered_set<RecordPtr, std::owner_less<RecordPtr>> order_set_;
    std::atomic<int> transaction_count_;
};
