#include <atomic>
#include <mutex>
#include <unordered_map>
#include <vector>
#include <memory>
#include <thread>
#include <chrono>

// Define CUSTOMER_ORDER_RECORD structure
struct CUSTOMER_ORDER_RECORD {
    std::string ORDER_ID;
    std::string CUSTOMER_ID;
    double AMOUNT;
    // Other fields...
};

// Define PaymentGateway interface
class PaymentGateway {
public:
    virtual bool processPayment(const CUSTOMER_ORDER_RECORD& record) = 0;
    virtual ~PaymentGateway() {}
};

// Define CustomerDataAPI interface
class CustomerDataAPI {
public:
    virtual std::string getCustomerDetails(const std::string& customerId) = 0;
    virtual ~CustomerDataAPI() {}
};

// DistributedOrderManager class
class DistributedOrderManager {
private:
    std::atomic<int> nextOrderId;
    std::mutex orderIdMutex;
    std::unordered_map<std::string, CUSTOMER_ORDER_RECORD> orderMap;
    PaymentGateway* paymentGateway;
    CustomerDataAPI* customerDataAPI;

public:
    DistributedOrderManager(PaymentGateway* pg, CustomerDataAPI* cda) 
        : nextOrderId(0), paymentGateway(pg), customerDataAPI(cda) {}

    bool addOrder(const CUSTOMER_ORDER_RECORD& record) {
        std::lock_guard<std::mutex> lock(orderIdMutex);
        if (orderMap.find(record.ORDER_ID + record.CUSTOMER_ID) != orderMap.end()) {
            return false; // Order already exists
        }
        record.ORDER_ID = generateUniqueOrderId();
        orderMap[record.ORDER_ID + record.CUSTOMER_ID] = record;
        return true;
    }

    bool processOrder(const std::string& orderId, const std::string& customerId) {
        std::lock_guard<std::mutex> lock(orderIdMutex);
        auto it = orderMap.find(orderId + customerId);
        if (it == orderMap.end()) {
            return false; // Order not found
        }
        CUSTOMER_ORDER_RECORD record = it->second;
        if (!paymentGateway->processPayment(record)) {
            return false; // Payment failed
        }
        // Log successful payment
        return true;
    }

private:
    std::string generateUniqueOrderId() {
        int id = nextOrderId.fetch_add(1, std::memory_order_relaxed);
        return "ORD" + std::to_string(id);
    }
};

// Example usage
int main() {
    auto pg = std::make_unique<PaymentGateway>();
    auto cda = std::make_unique<CustomerDataAPI>();
    DistributedOrderManager dom(pg.get(), cda.get());

    CUSTOMER_ORDER_RECORD record;
    record.ORDER_ID = "";
    record.CUSTOMER_ID = "CUST123";
    record.AMOUNT = 100.0;

    if (dom.addOrder(record)) {
        std::cout << "Order added successfully." << std::endl;
        dom.processOrder(record.ORDER_ID, record.CUSTOMER_ID);
    } else {
        std::cout << "Failed to add order." << std::endl;
    }

    return 0;
}
```']

