#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_FILENAME_LENGTH 256

typedef struct {
    char template[MAX_FILENAME_LENGTH];
    int sequence_number;
    pthread_mutex_t lock;
} FilenameGenerator;

FilenameGenerator generator = { .sequence_number = 0 };

void init_generator() {
    pthread_mutex_init(&generator.lock, NULL);
}

char* generate_filename(const char* custom_template) {
    char filename[MAX_FILENAME_LENGTH];
    time_t now = time(NULL);
    struct tm* local_time = localtime(&now);

    snprintf(filename, sizeof(filename), custom_template, 
             local_time->tm_year + 1900, local_time->tm_mon + 1, local_time->tm_mday,
             local_time->tm_hour, local_time->tm_min, local_time->tm_sec);

    pthread_mutex_lock(&generator.lock);
    snprintf(filename, sizeof(filename), "%s_%d", filename, generator.sequence_number++);
    pthread_mutex_unlock(&generator.lock);

    return strdup(filename);
}

void* update_template(void* arg) {
    const char* new_template = (const char*)arg;
    strcpy(generator.template, new_template);
    return NULL;
}

int main() {
    init_generator();

    // Example usage
    char* filename = generate_filename("%Y-%m-%d_%H-%M-%S");
    printf("Generated filename: %s\n", filename);
    free(filename);

    // Update template asynchronously
    pthread_t thread;
    const char* new_template = "%d-%b-%Y_%I:%M%p";
    if (pthread_create(&thread, NULL, update_template, (void*)new_template) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    // Wait for template update
    pthread_join(thread, NULL);

    filename = generate_filename(NULL); // Use updated template
    printf("Generated filename with new template: %s\n", filename);
    free(filename);

    return 0;
}
```

