namespace fs = std::filesystem;

class FileRenamer {
public:
    FileRenamer(const std::string& directory, const std::string& metadataServiceUrl)
        : directory_(directory), metadataServiceUrl_(metadataServiceUrl) {}

    void start(int batchSize, int concurrencyLevel, int updateFrequency) {
        for (int i = 0; i < concurrencyLevel; ++i) {
            workers_.emplace_back([this]() { worker(); });
        }

        std::thread producer([this, batchSize]() {
            fs::directory_iterator it(directory_);
            while (it != fs::directory_iterator{}) {
                queue_.push(it->path());
                it++;
                if (queue_.size() >= static_cast<size_t>(batchSize)) {
                    cv_.notify_one();
                }
            }
        }).detach();

        for (auto& worker : workers_) {
            worker.join();
        }
    }

private:
    void worker() {
        while (true) {
            std::vector<std::future<void>> futures;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                cv_.wait(lock, [this] { return !queue_.empty(); });
                int batchSize = std::min(static_cast<int>(queue_.size()), maxBatchSize_);
                for (int i = 0; i < batchSize; ++i) {
                    futures.push_back(std::async(std::launch::async, &FileRenamer::renameFile, this, queue_.front()));
                    queue_.pop();
                }
            }

            for (auto& future : futures) {
                try {
                    future.get();
                } catch (...) {
                    std::cerr << "Error occurred during file renaming." << std::endl;
                }
            }

            std::this_thread::sleep_for(std::chrono::seconds(updateFrequency));
        }
    }

    void renameFile(const fs::path& path) {
        std::string content = readFile(path);
        std::string hash = computeHash(content);
        std::string timestamp = getTimestamp();
        fs::path newFilePath = path.parent_path() / (path.stem().string() + "_" + hash + "_" + timestamp + path.extension().string());
