import java.util.concurrent.*;
import java.util.stream.IntStream;

public class MessageProcessor {
    private final String message;
    private boolean isPaused = false;

    public MessageProcessor(String message) {
        this.message = message;
    }

    public void process() {
        if (!isPaused) {
            // Process the message
            System.out.println("Processing message: " + message);
        }
    }

    public void pause() {
        isPaused = true;
    }

    public void resume() {
        isPaused = false;
    }
}

public class MessageBroker {
    private final ExecutorService executorService;
    private final BlockingQueue<MessageProcessor> pool;
    private final ConcurrentHashMap<String, MessageProcessor> processorMap;

    public MessageBroker(int maxPoolSize) {
        this.pool = new ArrayBlockingQueue<>(maxPoolSize);
        this.processorMap = new ConcurrentHashMap<>();
        this.executorService = Executors.newFixedThreadPool(maxPoolSize);

        // Initialize the pool with MessageProcessor instances
        IntStream.range(0, maxPoolSize).forEach(i -> {
            MessageProcessor processor = new MessageProcessor("Message-" + i);
            pool.offer(processor);
            processorMap.put("Processor-" + i, processor);
        });
    }

    public void receiveMessage(String message) {
        try {
            MessageProcessor processor = pool.take();
            processor.process();
            pool.offer(processor); // Return the processor to the pool
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.err.println("Failed to process message: " + message);
        }
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }
}

public class Main {
    public static void main(String[] args) {
        MessageBroker messageBroker = new MessageBroker(100_000);

        // Simulate receiving messages
        for (int i = 0; i < 200_000; i++) {
            String message = "Message-" + i;
            messageBroker.receiveMessage(message);
        }

        messageBroker.shutdown();
    }
}
```

