#include <mutex>
#include <queue>
#include <condition_variable>
#include <future>
#include <functional>

class ImageProcessor {
public:
    void processImage(const std::string& imageId) {
        // Simulate image processing task
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }
};

class CloudImageProcessor {
private:
    ImageProcessor processor;
    std::queue<std::future<void>> tasks;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool stop = false;

public:
    void enqueueTask(const std::string& imageId) {
        std::lock_guard<std::mutex> lock(queueMutex);
        tasks.push(processor.processImage(imageId));
        condition.notify_one();
    }

    void worker() {
        while (true) {
            std::future<void> task;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                condition.wait(lock, [this] { return !tasks.empty() || stop; });
                if (stop && tasks.empty()) break;
                task = std::move(tasks.front());
                tasks.pop();
            }
            task.get(); // Execute the task
        }
    }

    void startProcessing(size_t numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            std::thread(&CloudImageProcessor::worker, this).detach();
        }
    }

    void stopProcessing() {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
    }
};

int main() {
    CloudImageProcessor processor;
    processor.startProcessing(4);

    // Enqueue tasks
    for (size_t i = 0; i < 100; ++i) {
        processor.enqueueTask("image" + std::to_string(i));
    }

    processor.stopProcessing();

    return 0;
}
