import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class MessageBroker {
    private final ConcurrentHashMap<String, MessageProcessor> processors = new ConcurrentHashMap<>();
    private final AtomicInteger processorCount = new AtomicInteger(0);

    public void receiveMessage(String message) {
        // Implement message validation and handling logic here
        String key = generateKey(message);
        MessageProcessor processor = processors.computeIfAbsent(key, k -> createNewProcessor());
        processor.process(message);
    }

    private String generateKey(String message) {
        // Generate a unique key based on the message content or other criteria
        return message.hashCode() + "";
    }

    private MessageProcessor createNewProcessor() {
        if (processorCount.incrementAndGet() > 10_000_000) {
            processorCount.decrementAndGet();
            throw new RuntimeException("Cannot exceed maximum number of processors");
        }
        return new MessageProcessor(this);
    }

    public void pauseProcessing(String key) {
        MessageProcessor processor = processors.get(key);
        if (processor != null) {
            processor.pause();
        }
    }

    public void resumeProcessing(String key) {
        MessageProcessor processor = processors.get(key);
        if (processor != null) {
            processor.resume();
        }
    }

    private static class MessageProcessor {
        private final MessageBroker broker;
        private boolean paused;

        public MessageProcessor(MessageBroker broker) {
            this.broker = broker;
            // Initialize any necessary resources
        }

        public void process(String message) {
            if (!paused) {
                try {
                    // Process the message here
