        if not payment_request.amount or payment_request.amount <= 0:
            raise HTTPException(status_code=422, detail="Invalid amount")

        # Detect fraud
        if not detect_fraud(payment_request):
            raise HTTPException(status_code=422, detail="Fraudulent transaction detected")

