    std::string format;
    std::string content;
    size_t timestamp;
};

// Define the main logging library class
class LoggingLibrary {
public:
    LoggingLibrary(ILogger* logger, ICompressionAlgorithm* compression)
        : logger_(logger), compression_(compression) {}

    void log(const std::string& message) {
        LogEntry entry = { "text/plain", message, time(nullptr) };
        logEntries_.push_back(entry);
        if (logEntries_.size() >= batchSize_) {
            flush();
        }
    }

private:
    ILogger* logger_;
    ICompressionAlgorithm* compression_;
    std::vector<LogEntry> logEntries_;
    size_t batchSize_ = 100;
    std::mutex mtx_;
    std::condition_variable cv_;

    void flush() {
        std::lock_guard<std::mutex> lock(mtx_);
        // Perform batch processing
        logger_->log("Batch of logs processed");
        logEntries_.clear();
    }
};

int main() {
    ConsoleLogger consoleLogger;
    SimpleCompressionAlgorithm compressionAlgorithm;
    LoggingLibrary loggingLibrary(&consoleLogger, &compressionAlgorithm);

    loggingLibrary.log("This is a test message.");
    loggingLibrary.log("Another test message.");

    return 0;
}
