import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class MessageProcessorPool {

    private static final int MAX_PROCESSORS = 10_000_000;
    private ConcurrentHashMap<String, MessageProcessor> processorMap;
    private ScheduledExecutorService evictionScheduler;

    public MessageProcessorPool() {
        processorMap = new ConcurrentHashMap<>();
        evictionScheduler = Executors.newScheduledThreadPool(1);
        startEvictionTask();
    }

    private void startEvictionTask() {
        evictionScheduler.scheduleAtFixedRate(this::evictExpiredProcessors, 1, 1, TimeUnit.MINUTES);
    }

    public MessageProcessor getProcessor(String id) throws InterruptedException {
        return processorMap.computeIfAbsent(id, k -> createNewProcessor());
    }

    private MessageProcessor createNewProcessor() {
        if (processorMap.size() >= MAX_PROCESSORS) {
            throw new IllegalStateException("Max processors reached");
        }
        return new MessageProcessor();
    }

    private void evictExpiredProcessors() {
        processorMap.values().removeIf(processor -> processor.isExpired());
    }

    public void shutdown() {
        evictionScheduler.shutdownNow();
        processorMap.clear();
    }
}
