using System;
using System.Threading;

public interface IThemeSettings
{
    double MinValue { get; set; }
    double MaxValue { get; set; }
}

public class DynamicRandomValueGenerator
{
    private readonly double minValue;
    private readonly double maxValue;
    private readonly IThemeSettings themeSettings;
    private Random random;

    public DynamicRandomValueGenerator(double minValue, double maxValue, IThemeSettings themeSettings)
    {
        if (minValue >= maxValue)
            throw new ArgumentException("minValue must be less than maxValue");

        this.minValue = minValue;
        this.maxValue = maxValue;
        this.themeSettings = themeSettings;
        this.random = new Random();

        // Subscribe to theme changes
        themeSettings.PropertyChanged += OnThemeSettingsChanged;
    }

    private void OnThemeSettingsChanged(object sender, EventArgs e)
    {
        lock (this)
        {
            minValue = themeSettings.MinValue;
            maxValue = themeSettings.MaxValue;
            random = new Random();
        }
    }

    public float GetRandomFloat()
    {
        return (float)random.NextDouble() * (maxValue - minValue) + minValue;
    }

    public float GetRandomExclusiveFloat(double exclusiveMax)
    {
        if (exclusiveMax <= maxValue)
            throw new ArgumentException("exclusiveMax must be greater than maxValue");

        return (float)random.NextDouble() * (exclusiveMax - minValue) + minValue;
    }

    public int GetRandomInt()
    {
        try
        {
            return Convert.ToInt32(random.Next((int)(minValue), (int)(maxValue) + 1));
        }
        catch (OverflowException ex)
        {
            LogError(ex);
            throw;
        }
    }

    public int GetRandomExclusiveInt(int exclusiveMax)
    {
        try
        {
            return random.Next((int)(Convert.ToInt32(minValue)), exclusiveMax);
        }
        catch (OverflowException ex)
        {
            LogError(ex);
            throw;
        }
    }

    private void UpdateThemeRange(double newMin, double newMax)
    {
        if (newMin >= newMax)
            throw new ArgumentException("minValue must be less than maxValue");

        lock (this)
        {
            minValue = newMin;
            maxValue = newMax;
            random = new Random();
        }
    }

    private void LogError(Exception ex)
    {
        // Centralized logging implementation
        Console.WriteLine($"Error: {ex.Message}");
    }
}
