#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define NFAPI_CRC_INDICATION_PDU_T struct { int RX_UE_INFORMATION_TAG; int RNTI; int CRC_INDICATION_REL8_TAG; int CRCFLAG; }
#define MAX_ENTRIES 1024

NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu_array = NULL;
int array_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_error(const char* message, const char* error_code) {
    time_t now = time(NULL);
    fprintf(stderr, "Error at %s: %s (%s)\n", ctime(&now), message, error_code);
}

NFAPI_CRC_INDICATION_PDU_T* resize_array(int new_size) {
    NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(crc_indication_pdu_array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        log_error("Failed to resize array", "RE.alloc_fail");
        return crc_indication_pdu_array;
    }
    memset(new_array + array_size, 0, (new_size - array_size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array_size = new_size;
    return new_array;
}

void populate_crc_indication_pdu_array(int N) {
    pthread_mutex_lock(&mutex);
    if (array_size < N) {
        crc_indication_pdu_array = resize_array(N);
        if (!crc_indication_pdu_array) {
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    for (int i = 0; i < N; i++) {
        crc_indication_pdu_array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        crc_indication_pdu_array[i].RNTI = rand() % 4096;
        crc_indication_pdu_array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        crc_indication_pdu_array[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG to either 0 or 1
    }
    pthread_mutex_unlock(&mutex);
}
