# Python Service Implementation

from flask import Flask, request, jsonify
from werkzeug.security import check_password_hash
from hashlib import md5, sha256
import requests
from cacheout import Cache
import threading

app = Flask(__name__)
auth_cache = Cache(maxsize=100, ttl=3600)
file_cache = Cache(maxsize=500, ttl=86400)

def fetch_metadata(url):
    try:
        response = requests.get(url)
        if response.status_code == 200:
            return response.json()
    except requests.exceptions.RequestException as e:
        print(f"Metadata fetch failed: {e}")
    return None

def validate_oauth_token(token_response):
    token_data = token_response.json()
    if 'token_type' in token_data and token_data['token_type'] == 'Bearer':
        try:
            expires_in = int(token_data.get('expires_in'))
            if expires_in > 0:
                return True
        except ValueError:
            pass
    return False

def compute_hash(file_path, hash_function):
    with open(file_path, 'rb') as f:
        while chunk := f.read(8192):  # Read in chunks to handle large files
            hash_function.update(chunk)
    return hash_function.hexdigest()

@app.route('/hash', methods=['POST'])
def compute_hash_route():
    data = request.json
    if not validate_oauth_token(data['token']):
        return jsonify({'error': 'Invalid token'}), 401

    file_info = fetch_metadata(data['file_url'])
    if not file_info:
        return jsonify({'error': 'File metadata fetch failed'}), 503

    hash_function = md5() if data['hash_type'] == 'md5' else sha256()
    hash_value = compute_hash(file_info['path'], hash_function)

    return jsonify({'hash_value': hash_value, 'verification_status': True})

if __name__ == '__main__':
    app.run(debug=True)
