#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char token_type[10];
    int expires_in;
} OAuthTokenResponse;

int validate_oauth_token(const char *token_response_json) {
    OAuthTokenResponse token_data;
    if (sscanf(token_response_json, "{\"token_type\":\"%9s\",\"expires_in\":%d}", token_data.token_type, &token_data.expires_in) != 2) {
        printf("Malformed JSON\n");
        return 0;
    }
    if (strcmp(token_data.token_type, "Bearer") == 0 && token_data.expires_in > 0) {
        return 1;
    }
    return 0;
}

int main() {
    const char *token_response = "{\"token_type\":\"Bearer\",\"expires_in\":3600}";
    if (validate_oauth_token(token_response)) {
        printf("Token is valid\n");
