#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define NFAPI_CRC_INDICATION_PDU_T struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} ConcurrentArray;

ConcurrentArray* create_concurrent_array() {
    ConcurrentArray* array = (ConcurrentArray*)malloc(sizeof(ConcurrentArray));
    if (!array) return NULL;

    array->size = 0;
    array->capacity = 16; // Initial capacity
    array->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL;
    }

    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_concurrent_array(ConcurrentArray* array) {
    if (array->array) free(array->array);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int resize_concurrent_array(ConcurrentArray* array) {
    size_t new_capacity = array->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return -1;

    array->array = new_array;
    array->capacity = new_capacity;
    return 0;
}

int concurrent_array_append(ConcurrentArray* array, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity && resize_concurrent_array(array) != 0) {
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }

    array->array[array->size++] = item;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void generate_and_append_random_crc_indication(ConcurrentArray* array, unsigned int RX_UE_INFORMATION_TAG, unsigned short RNTI) {
    NFAPI_CRC_INDICATION_PDU_T item;
    item.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    item.RNTI = RNTI;
    item.CRCFLAG = (rand() % 2 == 0) ? 1 : 0; // Randomly set CRCFLAG

    concurrent_array_append(array, item);
}
