package main

import (
	"context"
	"errors"
	"net/http"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/go-chi/chi/v5"
	"github.com/go-chi/cors"
	"github.com/go-chi/middleware"
	"go.uber.org/zap"
)

func main() {
	l, err := zap.NewProduction()
	if err != nil {
		panic(err)
	}
	defer l.Sync()

	logger := l.Sugar()
	router := chi.NewRouter()
	router.Use(middleware.RequestID)
	router.Use(middleware.RealIP)
	router.Use(cors.Handler(cors.Options{
		AllowedOrigins:   []string{"*"},
		AllowedMethods:   []string{"GET", "POST", "PUT", "DELETE", "OPTIONS"},
		AllowedHeaders:   []string{"Accept", "Authorization", "Content-Type"},
		AllowCredentials: true,
	}))

	router.Use(middleware.Compress(5))

	router.Use(func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			start := time.Now()
			next.ServeHTTP(w, r)
			logger.Infow("request", "method", r.Method, "url", r.URL.Path, "status", w.Header().Get("X-Status-Code"), "duration", time.Since(start))
		})
	})

	router.Use(func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			rateLimiter := middleware.NewRateLimitByIP(1000, time.Second)
			if rateLimiter(r.Context(), w, r) != nil {
				http.Error(w, "Too Many Requests", http.StatusTooManyRequests)
				return
			}
			next.ServeHTTP(w, r)
		})
	})

	router.Use(func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			ctx := context.WithValue(r.Context(), "logger", logger)
			next.ServeHTTP(w, r.WithContext(ctx))
		})
	})

	router.Route("/v1/payment", func(r chi.Router) {
		r.Post("/", paymentHandler)
		r.Get("/{id}", getPaymentHandler)
	})

	router.Route("/v1/weather", func(r chi.Router) {
		r.Get("/", weatherHandler)
	})

	http.ListenAndServe(":8080", router)
}

func paymentHandler(w http.ResponseWriter, r *http.Request) {
	logger := r.Context().Value("logger").(*zap.SugaredLogger)
	// Handle payment processing
	logger.Infow("payment processed")
}

func getPaymentHandler(w http.ResponseWriter, r *http.Request) {
	id := chi.URLParam(r, "id")
	logger := r.Context().Value("logger").(*zap.SugaredLogger)
	// Retrieve payment details by ID
	logger.Infow("payment retrieved", "id", id)
}

func weatherHandler(w http.ResponseWriter, r *http.Request) {
	logger := r.Context().Value("logger").(*zap.SugaredLogger)
	// Fetch weather data
	logger.Infow("weather data fetched")
}
