        uint32_t operator()(const GeoData& data) const {
            return std::hash<uint64_t>()((static_cast<uint64_t>(data.latitude) << 32) | static_cast<uint64_t>(data.longitude));
        }
    };

    std::unordered_map<ShardingKey, std::vector<GeoData>, ShardingKey> distributedCache;
    std::shared_mutex cacheMutex;
    std::atomic<int> nodeIndex;

public:
    DynamicGeoDataProcessor() : nodeIndex(0) {}

    void process(const std::vector<GeoData>& dataBatch) {
        for (const auto& data : dataBatch) {
            if (isValid(data)) {
                storeInCache(data);
            }
        }
    }

private:
