namespace AdvancedNetworkResourceMonitor
{
    public class NetworkInterface : IDisposable
    {
        private readonly HttpClient _httpClient;
        private Timer _monitoringTimer;

        public string InterfaceName { get; }
        public Gauge MetricGauge { get; }

        public NetworkInterface(string interfaceName)
        {
            InterfaceName = interfaceName;
            MetricGauge = Metrics.CreateGauge($"network_interface_{interfaceName}_usage", "Network usage percentage");

            _httpClient = new HttpClient();
            SetupMonitoring();
        }

        private void SetupMonitoring()
        {
            _monitoringTimer = new Timer(async state =>
            {
                try
                {
                    var resourceUsage = await FetchResourceUsageAsync();
                    MetricGauge.Set(resourceUsage);
                }
                catch (Exception ex)
                {
                    // Log and handle exceptions
                }
            }, null, TimeSpan.Zero, TimeSpan.FromMilliseconds(50));
        }

        private async Task<double> FetchResourceUsageAsync()
        {
            // Simulate fetching resource usage from the interface
            return await Task.Delay(10).ContinueWith(_ => Math.Round(new Random().NextDouble() * 100, 2));
        }

        public void Dispose()
        {
            _monitoringTimer?.Change(Timeout.Infinite, 0);
            _httpClient.Dispose();
        }
    }

    public class AdvancedNetworkResourceMonitor
    {
        private readonly ConcurrentDictionary<string, NetworkInterface> _networkInterfaces = new ConcurrentDictionary<string, NetworkInterface>();
        private readonly CircuitBreakerPolicy _circuitBreaker;

        public AdvancedNetworkResourceMonitor()
        {
            _circuitBreaker = Policy.CircuitBreakerAsync(3, TimeSpan.FromSeconds(10));
        }

        public void AddNetworkInterface(string interfaceName)
        {
            if (!_networkInterfaces.TryAdd(interfaceName, new NetworkInterface(interfaceName)))
                throw new InvalidOperationException("Interface already exists.");
        }

        public void RemoveNetworkInterface(string interfaceName)
        {
            _networkInterfaces.TryRemove(interfaceName, out _);
        }

        public async Task MonitorAsync()
        {
            await foreach (var task in _networkInterfaces.Values.Select(ni => ni.MonitoringTimer.PollAsync()))
                await task;
        }

        public void Dispose()
        {
            foreach (var ni in _networkInterfaces.Values)
                ni.Dispose();
        }
    }
}
