        {
            foreach (var interfacePair in _interfaces)
            {
                var response = await _prometheusService.GetResourceUsage(interfacePair.Value.MetricsEndpoint);
                // Process and update the resource usage data
                _grafanaService.SendDataToGrafana(interfaceName, response);
            }
        }

