        {
            if (_leaderElectionService.IsLeader)
            {
                var leaderTasks = _interfaces.Values.Select(async interfaceDetails =>
                {
                    // Perform resource allocation based on current load and business priorities
                    await AllocateResourcesForInterface(interfaceDetails);
                });

                await Task.WhenAll(leaderTasks);
            }
