// CRCIndicationHandler.h

#ifndef CRC_INDICATION_HANDLER_H
#define CRC_INDICATION_HANDLER_H

#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CRCIndicationHandlerContext {
    NFAPI_CRC_INDICATION_PDU_T* pduArray;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} CRCIndicationHandlerContext;

CRCIndicationHandlerContext* crc_indication_handler_init(size_t initial_capacity);
void crc_indication_handler_free(CRCIndicationHandlerContext* context);
int crc_indication_handler_populate(CRCIndicationHandlerContext* context, int RX_UE_INFORMATION_TAG, int RNTI);
void crc_indication_handler_log_interactions(const CRCIndicationHandlerContext* context);

#endif // CRC_INDICATION_HANDLER_H
```

```c
// CRCIndicationHandler.c

#include "CRCIndicationHandler.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static NFAPI_CRC_INDICATION_PDU_T* resize_pdu_array(NFAPI_CRC_INDICATION_PDU_T* oldArray, size_t oldCapacity, size_t newCapacity) {
    NFAPI_CRC_INDICATION_PDU_T* newArray = (NFAPI_CRC_INDICATION_PDU_T*)realloc(oldArray, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newArray) {
        free(oldArray);
        return NULL;
    }
    return newArray;
}

CRCIndicationHandlerContext* crc_indication_handler_init(size_t initial_capacity) {
    CRCIndicationHandlerContext* context = (CRCIndicationHandlerContext*)malloc(sizeof(CRCIndicationHandlerContext));
    if (!context) return NULL;

    context->pduArray = resize_pdu_array(NULL, 0, initial_capacity);
    if (!context->pduArray) {
        free(context);
        return NULL;
    }

    context->capacity = initial_capacity;
    context->size = 0;
    pthread_mutex_init(&context->mutex, NULL);

    return context;
}

void crc_indication_handler_free(CRCIndicationHandlerContext* context) {
    if (context) {
        free(context->pduArray);
        pthread_mutex_destroy(&context->mutex);
        free(context);
    }
}

int crc_indication_handler_populate(CRCIndicationHandlerContext* context, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&context->mutex);

    if (context->size >= context->capacity) {
        size_t newCapacity = context->capacity == 0 ? 1 : context->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* newArray = resize_pdu_array(context->pduArray, context->capacity, newCapacity);
        if (!newArray) {
            pthread_mutex_unlock(&context->mutex);
            return -1; // Memory allocation failed
        }
        context->pduArray = newArray;
        context->capacity = newCapacity;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &context->pduArray[context->size];
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG = context->size; // Assuming this is unique for simplicity
    pdu->CRCFLAG = rand() % 2 == 0 ? 1 : 0; // Random CRCFLAG

    context->size++;
    pthread_mutex_unlock(&context->mutex);

    return 0;
}

void crc_indication_handler_log_interactions(const CRCIndicationHandlerContext* context) {
    pthread_mutex_lock(&context->mutex);
    for (size_t i = 0; i < context->size; ++i) {
        printf("PDU %zu: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n",
               i, context->pduArray[i].RX_UE_INFORMATION_TAG, context->pduArray[i].RNTI,
               context->pduArray[i].CRC_INDICATION_REL8_TAG, context->pduArray[i].CRCFLAG);
    }
    pthread_mutex_unlock(&context->mutex);
}
```

