// main.c

#include "CRCIndicationHandler.h"
#include <pthread.h>
#include <time.h>

void* producer_thread(void* arg) {
    CRCIndicationHandlerContext* context = (CRCIndicationHandlerContext*)arg;
    for (int i = 0; i < 100; ++i) {
        crc_indication_handler_populate(context, rand() % 1000, rand() % 1000);
        usleep(rand() % 1000); // Simulate network delay
    }
    return NULL;
}

int main() {
    srand(time(NULL));

    CRCIndicationHandlerContext* context = crc_indication_handler_init(100);
    if (!context) {
        fprintf(stderr, "Failed to initialize CRC Indication Handler\n");
        return 1;
    }

    pthread_t threads[500];
    for (int i = 0; i < 500; ++i) {
        if (pthread_create(&threads[i], NULL, producer_thread, context)) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            return 1;
        }
    }

    for (int i = 0; i < 500; ++i) {
        pthread_join(threads[i], NULL);
    }

    crc_indication_handler_log_interactions(context);

    crc_indication_handler_free(context);
    return 0;
}
```

