std::string compute_hash(const std::string& file_path, const std::string& algorithm) {
    FILE* file = fopen(file_path.c_str(), "rb");
    if (!file) return "";

    unsigned char buffer[4096];
    MD5_CTX md5;
    SHA256_CTX sha256;

    if (algorithm == "md5") {
        MD5_Init(&md5);
        while (size_t bytesRead = fread(buffer, 1, sizeof(buffer), file)) {
            MD5_Update(&md5, buffer, bytesRead);
        }
        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5_Final(digest, &md5);

        // Convert hash to hexadecimal string
        std::stringstream ss;
        for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            ss << std::hex << std::setw(2) << std::setfill('0') << (int)digest[i];
        }
        return ss.str();
    } else if (algorithm == "sha-256") {
        SHA256_Init(&sha256);
        while (size_t bytesRead = fread(buffer, 1, sizeof(buffer), file)) {
            SHA256_Update(&sha256, buffer, bytesRead);
        }
        unsigned char digest[SHA256_DIGEST_LENGTH];
        SHA256_Final(digest, &sha256);

        // Convert hash to hexadecimal string
        std::stringstream ss;
        for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
            ss << std::hex << std::setw(2) << std::setfill('0') << (int)digest[i];
        }
        return ss.str();
    }

    fclose(file);
    return "";
}

size_t write_callback(void* contents, size_t size, size_t nmemb, void* userp) {
    ((std::string*)userp)->append((char*)contents, size * nmemb);
    return size * nmemb;
}

std::string fetch_metadata(const std::string& url) {
    CURL* curl = curl_easy_init();
    if (!curl) return "";

    std::string readBuffer;
    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        curl_easy_cleanup(curl);
        return "";
    }

    curl_easy_cleanup(curl);
    return readBuffer;
}

void hash_file(const std::string& file_path, const std::string& algorithm, const std::string& username) {
    // Implement asynchronous thread to compute hash and store result in Redis
    std::thread([file_path, algorithm, username]() {
        std::string hash = compute_hash(file_path, algorithm);
        // Store hash in Redis for the user
    }).detach();
}

void handle_request(const std::string& username, const std::string& password, const nlohmann::json& data) {
    if (!authenticate(username, password)) {
        std::cout << "Unauthorized" << std::endl;
        return;
