        std::cout << "Hash computation started for file: " << data["file_path"] << std::endl;
    } else if (data.contains("url")) {
        std::string metadata = fetch_metadata(data["url"]);
        if (!metadata.empty()) {
            // Process metadata and perform necessary actions
            std::cout << "Processing metadata" << std::endl;
        }
    }
}

int main() {
    nlohmann::json request_data = {
        {"username", "user1"},
        {"password", "pass123"},
        {"file_path", "/path/to/file.txt"}
    };

    handle_request(request_data["username"], request_data["password"], request_data);
    return 0;
}
