# Python implementation of MD5 and SHA-256 hash computation for files and URLs

import hashlib
import requests

def compute_md5(file_path):
    """Compute MD5 hash for a local file."""
    with open(file_path, 'rb') as f:
        md5_hash = hashlib.md5()
        while chunk := f.read(8192):  # Read in chunks to handle large files efficiently
            md5_hash.update(chunk)
    return md5_hash.hexdigest()

def compute_sha256(file_path):
    """Compute SHA-256 hash for a local file."""
    with open(file_path, 'rb') as f:
        sha256_hash = hashlib.sha256()
        while chunk := f.read(8192):  # Read in chunks to handle large files efficiently
            sha256_hash.update(chunk)
    return sha256_hash.hexdigest()

def compute_md5_url(url):
    """Compute MD5 hash for a remote resource."""
    response = requests.get(url, stream=True)
    md5_hash = hashlib.md5()
    for chunk in response.iter_content(chunk_size=8192):
        md5_hash.update(chunk)
    return md5_hash.hexdigest()

def compute_sha256_url(url):
    """Compute SHA-256 hash for a remote resource."""
    response = requests.get(url, stream=True)
    sha256_hash = hashlib.sha256()
    for chunk in response.iter_content(chunk_size=8192):
        sha256_hash.update(chunk)
    return sha256_hash.hexdigest()

# Example usage
file_path = 'example.txt'
print("MD5:", compute_md5(file_path))
print("SHA-256:", compute_sha256(file_path))

url = 'https://example.com/file.txt'
print("MD5 URL:", compute_md5_url(url))
print("SHA-256 URL:", compute_sha256_url(url))
