# Python Code Block

from flask import Flask, request, jsonify
import hashlib
import requests
from io import BytesIO
from concurrent.futures import ThreadPoolExecutor

app = Flask(__name__)
executor = ThreadPoolExecutor(max_workers=10)

def compute_hash(url_or_path, hash_type='md5'):
    if url_or_path.startswith('http'):
        response = requests.get(url_or_path, stream=True)
        return hash_url_content(response.iter_content(chunk_size=8192), hash_type)
    else:
        with open(url_or_path, 'rb') as f:
            return hash_file(f, hash_type)

def hash_url_content(content_iter, hash_type):
    hasher = hashlib.new(hash_type)
    for chunk in content_iter:
        hasher.update(chunk)
    return hasher.hexdigest()

def hash_file(file_obj, hash_type):
    hasher = hashlib.new(hash_type)
    while chunk := file_obj.read(8192):
        hasher.update(chunk)
    return hasher.hexdigest()

@app.route('/hash', methods=['POST'])
def hash_request():
    data = request.json
    url_or_path = data['url_or_path']
    hash_type = data.get('hash_type', 'md5')

    future = executor.submit(compute_hash, url_or_path, hash_type)
    return jsonify({'task_id': future.result()})

if __name__ == '__main__':
    app.run(debug=True)

