// NetworkFlowMonitor.h
#pragma once

#include <mutex>
#include <unordered_map>
#include <thread>
#include <atomic>
#include <queue>

enum INTERFACE_ID { /* Define unique IDs for each interface */ };

struct STATS_RECORD {
    uint64_t BYTES_IN;
    uint64_t BYTES_OUT;
    uint64_t PACKETS_IN;
    uint64_t PACKETS_OUT;
    uint64_t DROPPED_PKTS;
    uint32_t ERRORS;
};

class NetworkFlowMonitor {
public:
    NetworkFlowMonitor();
    ~NetworkFlowMonitor();

    void addInterface(INTERFACE_ID id);
    void removeInterface(INTERFACE_ID id);
    void updateStats(INTERFACE_ID id, const STATS_RECORD& stats);

    void startMonitoring();
    void stopMonitoring();

private:
    std::unordered_map<INTERFACE_ID, STATS_RECORD> interfaceStats;
    std::mutex statsMutex;
    std::atomic<bool> running;
    std::thread monitoringThread;

    void monitorLoop();
};

// NetworkFlowMonitor.cpp
#include "NetworkFlowMonitor.h"
#include <iostream>
#include <chrono>

NetworkFlowMonitor::NetworkFlowMonitor() : running(false) {}

NetworkFlowMonitor::~NetworkFlowMonitor() {
    stopMonitoring();
}

void NetworkFlowMonitor::addInterface(INTERFACE_ID id) {
    std::lock_guard<std::mutex> lock(statsMutex);
    interfaceStats[id] = {0};
}

void NetworkFlowMonitor::removeInterface(INTERFACE_ID id) {
    std::lock_guard<std::mutex> lock(statsMutex);
    interfaceStats.erase(id);
}

void NetworkFlowMonitor::updateStats(INTERFACE_ID id, const STATS_RECORD& stats) {
    std::lock_guard<std::mutex> lock(statsMutex);
    if (interfaceStats.find(id) != interfaceStats.end()) {
        interfaceStats[id] = stats;
    }
}

void NetworkFlowMonitor::startMonitoring() {
    running.store(true);
    monitoringThread = std::thread(&NetworkFlowMonitor::monitorLoop, this);
}

void NetworkFlowMonitor::stopMonitoring() {
    running.store(false);
    if (monitoringThread.joinable()) {
        monitoringThread.join();
    }
}

void NetworkFlowMonitor::monitorLoop() {
    while (running.load()) {
        // Perform statistical analysis and aggregation here
        std::this_thread::sleep_for(std::chrono::seconds(1)); // Adaptive sampling strategy
    }
}
