def hash_file():
    data = request.json
    file_uri = data['file_uri']
    provider = data.get('provider', 'provider1')  # Default to provider1

    if not validate_oauth_token(request.headers.get('Authorization')):
        return jsonify({'error': 'Unauthorized'}), 401

    try:
        session = get_oauth_session(provider)
        response = session.get(file_uri)
        if response.status_code != 200:
            raise Exception(f"Failed to download file: {response.status_code}")

        # Calculate MD5 and SHA-256 hashes
        md5_hash = hashlib.md5(response.content).hexdigest()
