#include <string>
#include <atomic>

struct NetworkEvent {
    std::chrono::system_clock::time_point timestamp;
    std::string eventType;
    std::string networkIdentifier;
    int statusCode;
};

class NetworkEventHandler {
public:
    NetworkEventHandler(size_t initialCapacity = 1024)
        : events(initialCapacity), stop(false) {}

    void start() {
        workerThread = std::thread(&NetworkEventHandler::processEvents, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }

    void addEvent(const NetworkEvent& event) {
        std::lock_guard<std::mutex> lock(mutex);
        events.push_back(event);
        condition.notify_one();
    }

private:
    void processEvents() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return stop || !events.empty(); });

            if (stop && events.empty()) {
                break;
            }

            NetworkEvent event = events.front();
            events.pop_front();

            lock.unlock();
            processEvent(event);
        }
    }

    void processEvent(const NetworkEvent& event) {
        try {
            // Simulate network API call
            std::this_thread::sleep_for(std::chrono::milliseconds(100));

            if (event.statusCode != 200) {
                logError("Network error", event);
            } else {
                logInfo("Event processed successfully", event);
            }
        } catch (const std::exception& e) {
            logError("Exception during event processing", event, e.what());
        }
    }

    void logInfo(const std::string& message, const NetworkEvent& event) {
        log(message, event, "INFO");
    }

    void logError(const std::string& message, const NetworkEvent& event, const char* error = nullptr) {
        std::ofstream logFile("error_log.txt", std::ios::app);
        if (logFile.is_open()) {
            auto now = std::chrono::system_clock::now();
            time_t timeNow = std::chrono::system_clock::to_time_t(now);
            logFile << std::ctime(&timeNow) << " [" << message << "] Event: " << event.eventType
                    << ", Network ID: " << event.networkIdentifier << ", Status Code: " << event.statusCode;
            if (error) {
                logFile << ", Error: " << error;
            }
            logFile << std::endl;
            logFile.close();
        } else {
            std::cerr << "Failed to open log file" << std::endl;
        }
    }

    std::vector<NetworkEvent> events;
    std::mutex mutex;
    std::condition_variable condition;
    bool stop;
    std::thread workerThread;
};

int main() {
    NetworkEventHandler handler;

    // Simulate adding network events
    for (int i = 0; i < 10; ++i) {
        NetworkEvent event{
            std::chrono::system_clock::now(),
            "DATA_RECEIVED",
            "Network" + std::to_string(i),
            (i % 2 == 0 ? 200 : 500)
        };
        handler.addEvent(event);
    }

    handler.start();
    std::this_thread::sleep_for(std::chrono::seconds(5));
    handler.stop();

    return 0;
}
