#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_LOG_SIZE 1024
#define RETRY_DELAY 5000

typedef struct {
    char *buffer;
    size_t length;
    size_t max_length;
    sem_t buffer_lock;
} Logger;

Logger logger = {NULL, 0, MAX_LOG_SIZE};

void initialize_logger() {
    logger.buffer = (char *)malloc(MAX_LOG_SIZE);
    if (!logger.buffer) {
        fprintf(stderr, "Failed to allocate memory for logger buffer\n");
        exit(1);
    }
    sem_init(&logger.buffer_lock, 0, 1);
}

void append_log(const char *message) {
    sem_wait(&logger.buffer_lock);
    size_t remaining = logger.max_length - logger.length;
    if (strlen(message) < remaining) {
        strcat(logger.buffer, message);
        logger.length += strlen(message);
    } else {
        fprintf(stderr, "Log buffer overflow\n");
    }
    sem_post(&logger.buffer_lock);
}

void *log_thread(void *arg) {
    // Simulate log transmission to external service
    sleep(1);  // Simulate network latency
    printf("Logged: %s\n", logger.buffer);
    return NULL;
}

int main() {
    initialize_logger();
    pthread_t thread;

    // Example usage of the logger
    append_log("Starting application...\n");
    pthread_create(&thread, NULL, log_thread, NULL);
    pthread_join(thread, NULL);

    sem_destroy(&logger.buffer_lock);
    free(logger.buffer);
    return 0;
}
```

