    {
        private readonly byte[] _encryptionKey;
        private readonly byte[] _initializationVector;
        private readonly ICacheProvider _cacheProvider;
        private readonly IRetryPolicy _retryPolicy;
        private readonly ILogger _logger;

        public DynamicStateManager(byte[] encryptionKey, byte[] initializationVector, ICacheProvider cacheProvider, IRetryPolicy retryPolicy, ILogger logger)
        {
            _encryptionKey = encryptionKey;
            _initializationVector = initializationVector;
            _cacheProvider = cacheProvider;
            _retryPolicy = retryPolicy;
            _logger = logger;
        }

        public async Task<T> GetStateAsync<T>(string stateId, Func<Task<T>> fetchDataFromSource)
        {
            try
            {
                var cachedData = await _cacheProvider.GetAsync<T>(stateId);
                if (cachedData != null)
                {
                    return cachedData;
                }

                var data = await _retryPolicy.ExecuteAsync(fetchDataFromSource);
                var decryptedData = Decrypt(data);
                var state = Deserialize(decryptedData);

                await _cacheProvider.SetAsync(stateId, state);
                return state;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to get state.");
                throw;
            }
        }

        private byte[] Decrypt(byte[] ciphertext)
        {
            using (var aes = Aes.Create())
            {
                aes.Key = _encryptionKey;
                aes.IV = _initializationVector;

                var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
                using (var msDecrypt = new System.IO.MemoryStream(ciphertext))
                using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                using (var srDecrypt = new System.IO.StreamReader(csDecrypt))
                {
                    return Encoding.UTF8.GetBytes(srDecrypt.ReadToEnd());
                }
