{
    Task<T> ExecuteAsync(Func<Task<T>> action);
}

public class RetryPolicy : IRetryPolicy
{
    private readonly int _maxRetries;
    private readonly TimeSpan _initialDelay;

    public RetryPolicy(int maxRetries, TimeSpan initialDelay)
    {
        _maxRetries = maxRetries;
        _initialDelay = initialDelay;
    }

    public async Task<T> ExecuteAsync(Func<Task<T>> action)
    {
        var delay = _initialDelay;
        for (int i = 0; i <= _maxRetries; i++)
        {
            try
            {
                return await action();
            }
            catch when (i < _maxRetries)
            {
                await Task.Delay(delay);
                delay *= 2;
            }
        }

        throw new Exception("Operation failed after maximum retries.");
    }
}

