#include <iostream>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <vector>

// Define the MessagePacket structure
struct MessagePacket {
    std::string metadata;
    std::string payload;
    bool delivered = false;

    MessagePacket(std::string meta, std::string pay) : metadata(meta), payload(pay) {}
};

// Define the AsyncQueue class
class AsyncQueue {
private:
    std::queue<MessagePacket> queue;
    std::mutex mtx;
    std::condition_variable cv;
    std::atomic<bool> running{true};

public:
    void push(const MessagePacket& packet) {
        std::lock_guard<std::mutex> lock(mtx);
        queue.push(packet);
        cv.notify_one();
    }

    bool try_pop(MessagePacket& packet) {
        std::unique_lock<std::mutex> lock(mtx);
        if (queue.empty()) {
            return false;
        }
        packet = std::move(queue.front());
        queue.pop();
        return true;
    }

    void stop() {
        running = false;
        cv.notify_all();
    }
};

// Define the Consumer class
class Consumer {
private:
    AsyncQueue& queue;

public:
    Consumer(AsyncQueue& q) : queue(q) {}

    void start() {
        while (true) {
            MessagePacket packet;
            if (!queue.try_pop(packet)) {
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
                continue;
            }
            process_packet(packet);
        }
    }

private:
    void process_packet(const MessagePacket& packet) {
        // Process the message
        std::cout << "Processing: " << packet.metadata << ", " << packet.payload << std::endl;
        // Mark as delivered
        packet.delivered = true;
    }
};

// Define the Producer class
class Producer {
private:
    AsyncQueue& queue;

public:
    Producer(AsyncQueue& q) : queue(q) {}

    void start() {
        while (true) {
            MessagePacket packet("meta", "payload");
            queue.push(packet);
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }
};

int main() {
    AsyncQueue queue;
    Producer producer(queue);
    Consumer consumer(queue);

    std::thread producerThread(&Producer::start, &producer);
    std::thread consumerThread(&Consumer::start, &consumer);

    producerThread.join();
    consumerThread.join();

    return 0;
}
