private:
    std::unordered_map<std::string, std::string> cache;
public:
    void store(const std::string& key, const std::string& data) override {
        cache[key] = data;
    }
    std::optional<std::string> retrieve(const std::string& key) override {
        auto it = cache.find(key);
        if (it != cache.end()) {
            return it->second;
        }
        return std::nullopt;
    }
};

// Concrete implementation of memory pool allocator
