    void initLogging(const std::string& configPath);
    void logMessage(const std::string& message, int level);
    void shutdownLogging();

private:
    struct LogEntry {
        std::string message;
        int level;
    };

    std::queue<LogEntry> logQueue;
    std::vector<std::thread> workerThreads;
    std::mutex queueMutex;
    std::condition_variable queueCondVar;
    std::atomic<bool> running;
    int maxLevel;
};

void NetworkEventProcessor::initLogging(const std::string& configPath) {
    // Load configuration and initialize logging parameters
}

void NetworkEventProcessor::logMessage(const std::string& message, int level) {
    std::unique_lock<std::mutex> lock(queueMutex);
    logQueue.push({message, level});
    queueCondVar.notify_one();
}

void NetworkEventProcessor::shutdownLogging() {
    running.store(false);
    for (auto& thread : workerThreads) {
        if (thread.joinable()) {
            thread.join();
        }
    }
}

