typedef struct {
    int id;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RETRIES 5
#define INITIAL_DELAY_MS 100

NFAPI_CRC_INDICATION_PDU_T** array = NULL;
size_t array_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* populate_array(void* arg) {
    int retries = 0;
    clock_t start_time, end_time;
    double elapsed_time;

    while (retries < MAX_RETRIES) {
        start_time = clock();

        // Simulate data retrieval from external API
        NFAPI_CRC_INDICATION_PDU_T* new_data = fetch_external_data();
        if (!new_data) {
            retries++;
            continue;
        }

        pthread_mutex_lock(&mutex);

        // Resize array if needed
        if (array_size == 0 || array_size < new_data->id + 1) {
            size_t new_size = (new_data->id + 1) * 2;
            NFAPI_CRC_INDICATION_PDU_T** newArray = realloc(array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
            if (!newArray) {
                perror("Failed to reallocate array");
                pthread_mutex_unlock(&mutex);
                return NULL;
            }
            array = newArray;
            memset(&array[array_size], 0, (new_size - array_size) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
            array_size = new_size;
        }

        // Populate array
        if (!array[new_data->id]) {
            array[new_data->id] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!array[new_data->id]) {
                perror("Failed to allocate memory for new data");
                pthread_mutex_unlock(&mutex);
                return NULL;
            }
        }
        memcpy(array[new_data->id], new_data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        pthread_mutex_unlock(&mutex);

        end_time = clock();
        elapsed_time = (double)(end_time - start_time) / CLOCKS_PER_SEC;

        printf("Data populated successfully in %.3f seconds\n", elapsed_time);
        return NULL;
    }

    perror("Failed to fetch data after multiple retries");
    return NULL;
}

NFAPI_CRC_INDICATION_PDU_T* fetch_external_data() {
    // Simulate external data retrieval with transient failures
    if (rand() % 10 == 0) {
        printf("Transient failure in fetching data\n");
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    data->id = rand() % 100; // Example field
    return data;
}

int main() {
    srand(time(NULL));

    pthread_t thread;
    if (pthread_create(&thread, NULL, populate_array, NULL) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("Failed to join thread");
        return 1;
    }

    // Clean up
    for (size_t i = 0; i < array_size; i++) {
        free(array[i]);
    }
    free(array);

    pthread_mutex_destroy(&mutex);
    return 0;
}
