#include <iostream>
#include <thread>
#include <atomic>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <websocketpp/config/asio_no_tls_client.hpp>
#include <websocketpp/client.hpp>

typedef websocketpp::client<websocketpp::config::asio> client;

class SensorDataModule {
public:
    void start() {
        m_stop = false;
        m_worker.reset(new client::connection_hdl());
        m_thread = std::thread(&SensorDataModule::run, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(m_mutex);
            m_stop = true;
            m_cv.notify_all();
        }
        if (m_thread.joinable()) {
            m_thread.join();
        }
    }

private:
    void run() {
        client c;

        try {
            c.init_asio();

            // Set up connection
            client::connection_hdl hdl = c.get_connection("ws://example.com/sensor_data");
            c.connect(hdl);

            // Start async read operations
            c.start_reading();

            while (!m_stop) {
                std::this_thread::sleep_for(std::chrono::seconds(1));
            }
        } catch (const std::exception &e) {
            std::cerr << "Exception: " << e.what() << std::endl;
        }

        // Cleanup
        c.stop_reading();
        c.close_connection(m_worker->get_handle());
    }

    std::atomic<bool> m_stop;
    client::connection_hdl m_worker;
    std::thread m_thread;
    std::mutex m_mutex;
    std::condition_variable m_cv;
};

int main() {
    SensorDataModule module;
    module.start();
    // Simulate running for a while
    std::this_thread::sleep_for(std::chrono::seconds(10));
    module.stop();
    return 0;
}
```

