#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <chrono>
#include <memory>
#include <cstdlib>
#include <cstring>
#include <unistd.h>

// Define the data point structure
struct DataPoint {
    std::string device_id;
    double value;
    std::chrono::system_clock::time_point timestamp;
};

// Forward declare the SensorDataProcessor class
class SensorDataProcessor;

// Interface for IoT platforms and sensors
class IoTDevice {
public:
    virtual void sendData(const DataPoint& data, SensorDataProcessor* processor) = 0;
    virtual ~IoTDevice() {}
};

// Adapter to convert raw sensor data to DataPoint format
class DataPointAdapter : public IoTDevice {
private:
    std::string device_id;
public:
    DataPointAdapter(std::string id) : device_id(id) {}

    void sendData(const DataPoint& data, SensorDataProcessor* processor) override {
        // Convert raw data to DataPoint and send it to the processor
        processor->processData(data);
    }
};

// State machine for managing device connectivity
enum class ConnectionState { DISCONNECTED, CONNECTING, CONNECTED };

class ConnectionStateMachine {
private:
    std::atomic<ConnectionState> state;
public:
    ConnectionStateMachine() : state(ConnectionState::DISCONNECTED) {}

    void connect() {
        if (state.load() == ConnectionState::DISCONNECTED) {
            state.store(ConnectionState::CONNECTING);
            // Perform connection logic here
            state.store(ConnectionState::CONNECTED);
        }
    }

    void disconnect() {
        if (state.load() == ConnectionState::CONNECTED) {
            state.store(ConnectionState::DISCONNECTING);
            // Perform disconnection logic here
            state.store(ConnectionState::DISCONNECTED);
        }
    }
};

// Class to handle sensor data processing
class SensorDataProcessor {
private:
    std::vector<IoTDevice*> devices;
    ConnectionStateMachine connection_state;
    std::mutex queue_mutex;
    std::condition_variable data_available;
    std::queue<DataPoint> data_queue;
    std::atomic<bool> running;

    void processThread() {
        while (running) {
            std::unique_lock<std::mutex> lock(queue_mutex);
            data_available.wait(lock, [this] { return !data_queue.empty() || !running; });

            if (!data_queue.empty()) {
                DataPoint data = data_queue.front();
                data_queue.pop();

                for (IoTDevice* device : devices) {
                    device->sendData(data, this);
                }
            }

            lock.unlock();
        }
    }

public:
    SensorDataProcessor() : running(true) {
        std::thread([this] { processThread(); }).detach();
    }

    ~SensorDataProcessor() {
        running.store(false);
        data_available.notify_all();
    }

    void addDevice(IoTDevice* device) {
        devices.push_back(device);
    }

    void processData(const DataPoint& data) {
        std::lock_guard<std::mutex> lock(queue_mutex);
        data_queue.push(data);
        data_available.notify_one();
    }

    ConnectionStateMachine& getConnectionState() {
        return connection_state;
    }
};

int main() {
    // Example usage
    SensorDataProcessor processor;

    DataPointAdapter device1("device1");
    DataPointAdapter device2("device2");

    processor.addDevice(&device1);
    processor.addDevice(&device2);

    DataPoint data = {"device1", 3.14, std::chrono::system_clock::now()};
    processor.processData(data);

    return 0;
}
```']

