#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <random>
#include <stdexcept>

class SecureRandomService {
public:
    SecureRandomService() : should_stop(false), next_seed(0) {}

    ~SecureRandomService() {
        stop();
    }

    void start() {
        worker_thread = std::thread(&SecureRandomService::work, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            should_stop = true;
        }
        condition.notify_all();
        if (worker_thread.joinable()) {
            worker_thread.join();
        }
    }

    int generateRandomInt(int min, int max) {
        std::lock_guard<std::mutex> lock(mutex);
        std::uniform_int_distribution<int> distribution(min, max);
        return distribution(generator);
    }

    double generateRandomDouble(double min, double max) {
        std::lock_guard<std::mutex> lock(mutex);
        std::uniform_real_distribution<double> distribution(min, max);
        return distribution(generator);
    }

    double generateGaussianRandom(double mean = 0.0, double stddev = 1.0) {
        std::lock_guard<std::mutex> lock(mutex);
        static std::normal_distribution<double> normal_distribution;
        return normal_distribution(generator) * stddev + mean;
    }

private:
    void work() {
        while (true) {
            int seed;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condition.wait(lock, [this] { return should_stop || !requests.empty(); });
                if (should_stop && requests.empty()) {
                    break;
                }
                seed = next_seed++;
            }

            auto request = requests.front();
            requests.pop();

            try {
                switch (request.type) {
                    case RequestType::RandomInt:
                        request.callback(request.min, request.max);
                        break;
                    case RequestType::RandomDouble:
                        request.callback(request.min, request.max);
                        break;
                    case RequestType::GaussianRandom:
                        request.callback(request.mean, request.stddev);
                        break;
                }
            } catch (const std::exception& e) {
                std::cerr << "Error processing request: " << e.what() << std::endl;
            }
        }
    }

    enum class RequestType { RandomInt, RandomDouble, GaussianRandom };

    struct Request {
        RequestType type;
        int min = 0, max = 0;
        double mean = 0.0, stddev = 1.0;
        std::function<void(int)> callback_int;
        std::function<void(double)> callback_double;

        Request(RequestType t, int mmin, int mmax, std::function<void(int)> cb)
            : type(t), min(mmin), max(mmax), callback_int(cb) {}
        Request(RequestType t, double mmean, double mstddev, std::function<void(double)> cb)
            : type(t), mean(mmean), stddev(mstddev), callback_double(cb) {}
    };

    std::thread worker_thread;
    std::mutex mutex;
    std::condition_variable condition;
    bool should_stop;
    int next_seed;
    std::queue<Request> requests;

    std::mt19937 generator = std::mt19937(std::random_device()());
};

int main() {
    SecureRandomService service;
    service.start();

    auto callback_int = [](int value) { std::cout << "Generated random int: " << value << std::endl; };
    auto callback_double = [](double value) { std::cout << "Generated random double: " << value << std::endl; };

    service.requests.push(SecureRandomService::Request(SecureRandomService::RequestType::RandomInt, 0, 100, callback_int));
    service.requests.push(SecureRandomService::Request(SecureRandomService::RequestType::RandomDouble, 0.0, 1.0, callback_double));

    std::this_thread::sleep_for(std::chrono::seconds(2));

    service.stop();
    return 0;
}
