using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;
using StackExchange.Redis;

public class DatabaseLibrary
{
    private readonly string _connectionString;
    private readonly IDatabase _redisCache;
    private readonly ILogger _logger;
    private readonly IAuthenticationService _authenticationService;

    public DatabaseLibrary(string connectionString, IDatabase redisCache, ILogger logger, IAuthenticationService authenticationService)
    {
        _connectionString = connectionString;
        _redisCache = redisCache;
        _logger = logger;
        _authenticationService = authenticationService;
    }

    public async Task<T> ExecuteQueryAsync<T>(string sql, Dictionary<string, object> parameters)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            var command = new SqlCommand(sql, connection);
            foreach (var param in parameters)
            {
                command.Parameters.AddWithValue(param.Key, param.Value);
            }
            using (var reader = await command.ExecuteReaderAsync())
            {
                if (reader.Read())
                {
                    return (T)reader.GetValue(0); // Assuming a single result
                }
            }
        }
        return default;
    }

    public async Task<int> ExecuteNonQueryAsync(string sql, Dictionary<string, object> parameters)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            var command = new SqlCommand(sql, connection);
            foreach (var param in parameters)
            {
                command.Parameters.AddWithValue(param.Key, param.Value);
            }
            return await command.ExecuteNonQueryAsync();
        }
    }

    public async Task<T> GetFromCacheOrExecuteAsync<T>(string cacheKey, Func<Task<T>> executeQueryAsync)
    {
        if (_redisCache.KeyExists(cacheKey))
        {
            var cachedValue = await _redisCache.StringGetAsync(cacheKey);
            return JsonConvert.DeserializeObject<T>(cachedValue);
        }
        else
        {
            var result = await executeQueryAsync();
            await _redisCache.StringSetAsync(cacheKey, JsonConvert.SerializeObject(result), TimeSpan.FromMinutes(10));
            return result;
        }
    }

    public async Task<List<T>> ExecutePagedQueryAsync<T>(string sql, Dictionary<string, object> parameters, int pageNumber, int pageSize)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            var command = new SqlCommand(sql + " OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY", connection);
            parameters["@Offset"] = (pageNumber - 1) * pageSize;
            parameters["@PageSize"] = pageSize;
            foreach (var param in parameters)
            {
                command.Parameters.AddWithValue(param.Key, param.Value);
            }
            using (var reader = await command.ExecuteReaderAsync())
            {
                var results = new List<T>();
                while (await reader.ReadAsync())
                {
                    results.Add((T)reader.GetValue(0)); // Assuming a single result per row
                }
                return results;
            }
        }
    }

    public async Task<List<T>> ExecuteStreamedQueryAsync<T>(string sql, Dictionary<string, object> parameters)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            var command = new SqlCommand(sql, connection);
            foreach (var param in parameters)
            {
                command.Parameters.AddWithValue(param.Key, param.Value);
            }
            using (var reader = await command.ExecuteReaderAsync(CommandBehavior.SequentialAccess))
            {
                while (await reader.ReadAsync())
                {
                    yield return (T)reader.GetValue(0); // Assuming a single result per row
                }
            }
        }
    }

    public async Task<T> RetryWithExponentialBackoffAsync<T>(Func<Task<T>> operation, int maxRetries = 3)
    {
        for (int attempt = 1; attempt <= maxRetries; attempt++)
        {
            try
            {
                return await operation();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Attempt {attempt} failed. Retrying...");
                await Task.Delay((int)Math.Pow(2, attempt) * 100); // Exponential backoff
            }
        }
        throw new Exception("Operation failed after maximum retries.");
    }

    public async Task<T> ExecuteWithTransactionAsync<T>(Func<SqlTransaction, Task<T>> transactionBody)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            using (var transaction = connection.BeginTransaction())
            {
                try
                {
                    var result = await transactionBody(transaction);
                    transaction.Commit();
                    return result;
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Transaction failed. Rolling back.");
                    transaction.Rollback();
                    throw;
                }
            }
        }
    }

    public async Task<List<T>> GetSchemaChangesAsync()
    {
        // Logic to detect and retrieve schema changes
        return new List<T>();
    }

    public async Task ApplySchemaChangesAsync(List<T> schemaChanges)
    {
        foreach (var change in schemaChanges)
        {
            // Logic to apply each schema change
        }
    }
}
