public class DistributedQueryService : IDistributedQueryService
{
    private readonly List<DbConnection> _connections = new List<DbConnection>();
    private readonly ILogger _logger;

    public DistributedQueryService(IEnumerable<string> connectionStrings, ILogger logger)
    {
        foreach (var connectionString in connectionStrings)
        {
            var factory = DbProviderFactories.GetFactory(connectionString);
            var connection = factory.CreateConnection();
            connection.ConnectionString = connectionString;
            _connections.Add(connection);
        }

        _logger = logger;
    }

    public async Task<IEnumerable<T>> ExecuteQueryAsync<T>(string sql, Dictionary<string, object> parameters)
    {
        using (var connection = await GetNextConnectionAsync())
        {
            var command = connection.CreateCommand();
            command.CommandText = sql;

            foreach (var param in parameters)
            {
                var parameter = command.CreateParameter();
                parameter.ParameterName = param.Key;
                parameter.Value = param.Value;
                command.Parameters.Add(parameter);
            }

            try
            {
                await connection.OpenAsync();
                using (var reader = await command.ExecuteReaderAsync())
                {
                    return await MapResultsAsync<T>(reader);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "An error occurred while executing the query.");
                throw;
            }
        }
    }

