    }

    private async Task<IEnumerable<T>> MapResultsAsync<T>(DbDataReader reader)
    {
        var results = new List<T>();

        while (await reader.ReadAsync())
        {
            var instance = (T)Activator.CreateInstance(typeof(T));
            // Implement mapping logic here
            // Use reflection or other techniques to map database columns to object properties
            results.Add(instance);
        }

        return results;
    }
}

