    std::queue<std::string> dataQueue;
    std::mutex queueMutex;
    std::condition_variable dataCondition;
    MarketDataProcessor processor;
    bool running;

public:
    StreamingAnalyticsEngine() : running(true) {
        for (int i = 0; i < 500; ++i) {
            workerThreads.emplace_back(&StreamingAnalyticsEngine::workerThread, this);
        }
    }

