import time

class PaymentGatewayService:
    def __init__(self):
        self.gateways = {
            'gateway1': Gateway1(),
            'gateway2': Gateway2()
        }

    def process_transaction(self, data):
        gateway_name = data.get('gateway')
        if gateway_name not in self.gateways:
            return {'error': 'Gateway not supported'}, 400

        gateway = self.gateways[gateway_name]
        try:
            result = gateway.process(data)
            return result
        except Exception as e:
            self.handle_error(e)
            return {'error': 'Transaction failed'}, 500

    def get_transaction(self, transaction_id):
        for gateway in self.gateways.values():
            transaction = gateway.get_transaction(transaction_id)
            if transaction:
                return transaction
        return {'error': 'Transaction not found'}, 404

    def handle_error(self, error):
        # Implement retry mechanism and error logging here
        print(f"Error occurred: {error}")

class Gateway1:
