#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_CONCURRENT_FILES 20
#define NUM_APIS 5
#define FALLBACK_API_INDEX 4

typedef struct {
    char *file_path;
    int is_validated;
} FileData;

FileData file_queue[MAX_CONCURRENT_FILES];
int queue_head = 0, queue_tail = 0, queue_size = 0;

pthread_mutex_t file_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t file_not_empty = PTHREAD_COND_INITIALIZER;
pthread_cond_t file_not_full = PTHREAD_COND_INITIALIZER;

void *file_processor(void *arg) {
    while (1) {
        pthread_mutex_lock(&file_lock);
        while (queue_size == 0) {
            pthread_cond_wait(&file_not_empty, &file_lock);
        }
        int index = queue_head;
        queue_head = (queue_head + 1) % MAX_CONCURRENT_FILES;
        queue_size--;

        // Process file
        FileData *data = &file_queue[index];
        process_file(data->file_path);

        pthread_mutex_unlock(&file_lock);
        pthread_cond_signal(&file_not_full);
    }
}

void add_to_queue(char *file_path) {
    pthread_mutex_lock(&file_lock);
    while (queue_size == MAX_CONCURRENT_FILES) {
        pthread_cond_wait(&file_not_full, &file_lock);
    }
    int index = queue_tail;
    queue_tail = (queue_tail + 1) % MAX_CONCURRENT_FILES;
    queue_size++;
    file_queue[index].file_path = strdup(file_path);
    file_queue[index].is_validated = 0;

    pthread_mutex_unlock(&file_lock);
    pthread_cond_signal(&file_not_empty);
}

void *api_thread(void *arg) {
    int api_index = *(int *)arg;
    while (1) {
        // Call API and handle response
        if (!call_api(api_index)) {
            // Fallback to alternative API
            if (api_index != FALLBACK_API_INDEX) {
                call_api(FALLBACK_API_INDEX);
            }
        }

        // Sleep or retry logic
        sleep(1); // Placeholder for rate limiting and retry logic
    }
}

int main() {
    pthread_t processors[MAX_CONCURRENT_FILES];
    pthread_t apis[NUM_APIS];

    // Create file processors
    for (int i = 0; i < MAX_CONCURRENT_FILES; i++) {
        pthread_create(&processors[i], NULL, file_processor, NULL);
    }

    // Create API threads
    int api_indices[NUM_APIS] = {0, 1, 2, 3, 4};
    for (int i = 0; i < NUM_APIS; i++) {
        pthread_create(&apis[i], NULL, api_thread, &api_indices[i]);
    }

    // Simulate file arrivals
    char *file_paths[] = {"file1.json", "file2.json", "file3.json"};
    for (int i = 0; i < sizeof(file_paths) / sizeof(file_paths[0]); i++) {
        add_to_queue(file_paths[i]);
    }

    // Wait for threads to finish
    for (int i = 0; i < MAX_CONCURRENT_FILES; i++) {
        pthread_join(processors[i], NULL);
    }
    for (int i = 0; i < NUM_APIS; i++) {
        pthread_join(apis[i], NULL);
    }

    return 0;
}

