// Node.js Service Entry Point

const express = require('express');
const bodyParser = require('body-parser');
const cluster = require('cluster');
const numCPUs = require('os').cpus().length;

if (cluster.isMaster) {
  console.log(`Master ${process.pid} is running`);

  // Fork workers.
  for (let i = 0; i < numCPUs; i++) {
    cluster.fork();
  }

  cluster.on('exit', (worker, code, signal) => {
    console.log(`worker ${worker.process.pid} died`);
  });
} else {
  const app = express();
  app.use(bodyParser.json());

  // Python and C++ integration using child_process
  const { spawn } = require('child_process');

  app.post('/process', (req, res) => {
    let data = req.body;

    if (data.format === 'json' || data.format === 'csv') {
      const pythonProcess = spawn('python3', ['scripts/process_data.py'], {
        stdio: ['pipe', 'pipe', process.stderr]
      });

      pythonProcess.stdin.write(JSON.stringify(data));
      pythonProcess.stdin.end();

      pythonProcess.stdout.on('data', (chunk) => {
        res.send(chunk.toString());
      });
    } else if (data.format === 'text') {
      const cppProcess = spawn('./cpp_processor', ['scripts/process_text.cpp'], {
        stdio: ['pipe', 'pipe', process.stderr]
      });

      cppProcess.stdin.write(data.text);
      cppProcess.stdin.end();

      cppProcess.stdout.on('data', (chunk) => {
        res.send(chunk.toString());
      });
    }
  });

  app.listen(3000, () => {
    console.log(`Worker ${process.pid} started`);
  });
}
