from flask import Flask, request, jsonify
from sqlalchemy import create_engine, Column, Integer, String, Float
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker
import requests
import time
import asyncio

app = Flask(__name__)

# Database setup
Base = declarative_base()
engine = create_engine('sqlite:///data.db', echo=True)
Session = sessionmaker(bind=engine)
session = Session()

# Cache setup
cache = {}

class DataPoint(Base):
    __tablename__ = 'datapoints'
    id = Column(Integer, primary_key=True)
    value = Column(Float)

Base.metadata.create_all(engine)

def fetch_data_from_api(api_url):
    try:
        response = requests.get(api_url)
        response.raise_for_status()
        return response.json()
    except requests.RequestException as e:
        print(f"Failed to fetch data from API: {e}")
        return None

@app.route('/data', methods=['GET'])
def get_data():
    api_url = 'https://api.example.com/data'
    if api_url in cache and time.time() - cache[api_url]['timestamp'] < 60:
        return jsonify(cache[api_url]['data'])

    data = fetch_data_from_api(api_url)
    if data:
        cache[api_url] = {'data': data, 'timestamp': time.time()}
        session.add_all([DataPoint(value=value) for value in data])
        session.commit()
    return jsonify(data)

@app.route('/reduce', methods=['POST'])
def reduce_numbers():
    numbers = request.json.get('numbers')
    initial_value = request.json.get('initial_value')
    callback = request.json.get('callback')

    async def process_reduce(numbers, initial_value, callback):
        result = await asyncio.gather(*[callback(num) for num in numbers])
        return sum(result)

    loop = asyncio.new_event_loop()
    asyncio.set_event_loop(loop)
    result = loop.run_until_complete(process_reduce(numbers, initial_value, lambda x: asyncio.sleep(0.1) or x))
    loop.close()

    return jsonify({'result': result})

if __name__ == '__main__':
    app.run(debug=True)
```

