// AngularJS Service: FormFieldRefreshService

angular.module('app.services')
.service('FormFieldRefreshService', ['$timeout', '$http', '$q', 'CacheFactory', function($timeout, $http, $q, CacheFactory) {
    var cache = CacheFactory.get('fieldData') || CacheFactory.createCache('fieldData');

    this.refreshFields = function() {
        return $timeout(this.performRefresh, 5000);
    };

    this.performRefresh = function() {
        var fieldNames = Object.keys(cache.data);

        if (fieldNames.length === 0) {
            return $q.resolve();
        }

        var requests = fieldNames.map(fieldName => {
            if (!cache.get(fieldName)) {
                return $http.get('https://api.example.com/fields/' + fieldName)
                    .then(response => {
                        cache.put(fieldName, response.data);
                        return response.data;
                    })
                    .catch(error => {
                        console.error('Error fetching data for field:', fieldName, error);
                        return $q.reject(error);
                    });
            }

            return $q.resolve(cache.get(fieldName));
        });

        return $q.all(requests);
    };

    this.forceRefresh = function() {
        cache.removeAll();
        return this.performRefresh();
    };

    this.handleError = function(error) {
        if (error.status === 404) {
            console.error('Resource not found');
        } else if (error.status === 500) {
            console.error('Server error');
        } else if (error.status === 0) {
            console.error('Network error or offline mode');
        }
    };

    this.handleOfflineMode = function() {
        // Implement offline functionality here
        console.warn('Offline mode - limited functionality available');
    };
}]);
