class NetworkLogEventProcessor(EventProcessor):
    def process_event(self, event):
        # Process network log event data
        print(f"Processing network log event: {event}")

class EventDispatcher:
    def __init__(self):
        self.processors = []

    def register_processor(self, processor):
        self.processors.append(processor)

    def dispatch_event(self, event_type, event_data):
        for processor in self.processors:
            if isinstance(event_data, processor.__name__):
                processor.process_event(event_data)

class EventStorage:
    def store_event(self, event):
        # Store event data in the appropriate storage layer
        print(f"Storing event: {event}")

