use std::fs;
use std::path::Path;
use std::process::{Command, Stdio};
use std::time::{Instant, SystemTime};
use sysinfo::{ProcessExt, System, SystemExt};
use crossbeam::channel::{bounded, Receiver, Sender};
use git2::Repository;

fn build_and_monitor(
    project_dir: &Path,
    log_config_path: &Path,
    build_strategy: &str,
    concurrency_limit: usize,
) {
    let mut system = System::new_all();
    let repo = Repository::open(project_dir).expect("Failed to open repository");
    let changes = track_changes(&repo);

    let (sender, receiver): (Sender<_>, Receiver<_>) = bounded(10);
    crossbeam::scope(|scope| {
        for _ in 0..concurrency_limit {
            scope.spawn(move |_| {
                loop {
                    if let Some(change) = receiver.recv().unwrap() {
                        handle_build(change, &project_dir, sender.clone());
                    }
                }
            });
        }
    });

    let mut changes_channel = bounded(1);
    let _ = std::thread::spawn(move || loop {
        if let Some(changes) = track_changes(&repo) {
            changes_channel.0.send(changes).unwrap();
        }
        std::thread::sleep(std::time::Duration::from_secs(1));
    });

    for change in receiver.iter() {
        handle_build(change, project_dir, sender.clone());
    }
}

fn track_changes(repo: &Repository) -> Option<String> {
    let mut index = repo.index().unwrap();
    if index.has_conflicts() || !index.is_clean(true).unwrap() {
        Some(String::from("Changes detected"))
    } else {
        None
    }
}

fn handle_build(change: String, project_dir: &Path, sender: Sender<String>) {
    let mut system = System::new_all();
    let start_time = Instant::now();
    let process = Command::new("cargo")
        .arg("build")
        .current_dir(project_dir)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("Failed to run cargo build");

    let mut process_output = process.output().unwrap();
    let end_time = Instant::now();

    if process_output.status.success() {
        sender.send(change).unwrap();
    } else {
        // Handle failure, retry, and escalate
    }

    let memory_usage = system.process(process.id as u32).unwrap().memory();
    let cpu_utilization = system.process(process.id as u32).unwrap().cpu_usage();

    log_metrics(
        start_time,
        end_time,
        memory_usage,
        cpu_utilization,
        &process_output.stdout,
        &process_output.stderr,
    );
}

fn log_metrics(
    start_time: Instant,
    end_time: Instant,
    memory_usage: u64,
    cpu_utilization: f32,
    stdout: &[u8],
    stderr: &[u8],
) {
    // Log metrics to the third-party logging service
}
