class ClinicOperations {
    private $database;
    private $semaphore;
    private $retryParams;

    public function __construct($dbConfig, $semaphoreConfig, $retryParams) {
        $this->database = new Database($dbConfig);
        $this->semaphore = new Semaphore($semaphoreConfig);
        $this->retryParams = $retryParams;
    }

    public function updateClinicStatus($clinicId, $newStatus, $ipAddress) {
        if (!$this->semaphore->acquireLock('clinic_update_lock_' . $clinicId)) {
            return false; // Lock acquisition failed
        }

        try {
            $clinicDetails = $this->fetchClinicDetailsFromExternalAPI($clinicId);
            if ($clinicDetails === false) {
                throw new Exception("Failed to fetch clinic details");
            }

            $retryCount = 0;
            while ($retryCount < $this->retryParams['max_retries']) {
                try {
                    $this->database->beginTransaction();

                    // Update the clinic status
                    $updateResult = $this->database->execute(
                        "UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_time = ? WHERE id = ?",
                        [$newStatus, $ipAddress, date('Y-m-d H:i:s'), $clinicId]
                    );

                    if ($updateResult === false) {
                        throw new Exception("Failed to update clinic record");
                    }

                    // Log the change
                    $this->logChange($clinicId, $newStatus, $ipAddress);

                    $this->database->commit();
                    break;
                } catch (Exception $e) {
                    if ($retryCount + 1 >= $this->retryParams['max_retries']) {
                        throw $e; // Re-throw exception after max retries
                    }

                    // Exponential backoff before retrying
                    usleep($this->retryParams['backoff_factor'] * pow(2, $retryCount) * 1000);
                    $retryCount++;
                }
            }
        } finally {
            $this->semaphore->releaseLock('clinic_update_lock_' . $clinicId);
        }

        return true;
