function asyncReduce(array, initialValue, callback) {
    return new Promise((resolve, reject) => {
        let accumulator = initialValue;
        let index = 0;

        function next() {
            if (index < array.length) {
                const current = array[index++];
                try {
                    const result = callback(accumulator, current);
                    if (result instanceof Promise) {
                        result.then(next).catch(reject);
                    } else {
                        accumulator = result;
                        next();
                    }
                } catch (error) {
                    reject(error);
                }
            } else {
                resolve(accumulator);
            }
        }

        next();
    });
}

// Example usage
const numbers = [1, 2, 3, 4, 5];
const initialValue = 0;
const callback = (acc, num) => acc + num;

asyncReduce(numbers, initialValue, callback)
    .then(result => console.log(result)) // Output: 15
    .catch(error => console.error(error));
```']

