class DistributedHashTable {
private:
    struct Node {
        std::string key;
        std::string value;
        bool occupied;

        Node() : key(""), value(""), occupied(false) {}
    };

    std::vector<Node> buckets;
    size_t capacity;
    float loadFactor;
    size_t resizeThreshold;
    std::atomic<bool> resizing;
    std::mutex bucketLocks[1024];
    std::mutex monitorMutex;

    void expand();
    size_t hash(const std::string& key) const;
    bool probing(const std::string& key, Node* &bucket);
    void retryExternalServiceCall() const;
    void logError(const std::string& error) const;

public:
    DistributedHashTable(size_t initialCapacity = 16, float loadFactor = 0.75f)
        : capacity(initialCapacity), loadFactor(loadFactor),
          resizeThreshold(std::ceil(capacity * loadFactor)), resizing(false) {
        buckets.resize(capacity);
    }

    void set(const std::string& key, const std::string& value);
    std::optional<std::string> get(const std::string& key);
    void remove(const std::string& key);

    void tuneParameters(size_t newCapacity, float newLoadFactor) {
        capacity = newCapacity;
        loadFactor = newLoadFactor;
        resizeThreshold = std::ceil(capacity * loadFactor);
        buckets.resize(capacity);
    }

    size_t getCapacity() const { return capacity; }
    float getLoadFactor() const { return loadFactor; }
    size_t getSize() const {
        std::lock_guard<std::mutex> lock(monitorMutex);
        size_t count = 0;
        for (const auto& bucket : buckets) {
            if (bucket.occupied) ++count;
        }
        return count;
    }
};

