            Model* model = static_cast<Model*>(models[model_name].get()); // Replace with actual model type
            std::vector<float> prediction = model->predict(input_data); // Replace with actual prediction logic
            models_mutex.unlock();

            json::value response;
            response["prediction"] = json::value::array(prediction);
            msg.reply(status_codes::OK, response);
        } else {
            models_mutex.unlock();
            msg.reply(status_codes::NotFound, "Model not found");
        }
    }
};

