import java.net.InetAddress;
import java.net.UnknownHostException;
import java.util.HashMap;
import java.util.Map;

public class DNSResolver {
    private Map<String, String> dnsCache = new HashMap<>();
    private String primaryDNSServer = "primary.dns.server";
    private String fallbackDNSServer = "fallback.dns.server";

    public String resolve(String hostname) throws UnknownHostException {
        // Check cache
        if (dnsCache.containsKey(hostname)) {
            return dnsCache.get(hostname);
        }

        try {
            // Attempt to resolve using primary DNS server
            InetAddress address = InetAddress.getByName(primaryDNSServer + "/" + hostname);
            dnsCache.put(hostname, address.getHostAddress());
            return address.getHostAddress();
        } catch (UnknownHostException e) {
            // Fallback to secondary DNS server if primary fails
            try {
                InetAddress address = InetAddress.getByName(fallbackDNSServer + "/" + hostname);
                dnsCache.put(hostname, address.getHostAddress());
                return address.getHostAddress();
            } catch (UnknownHostException e2) {
                throw new UnknownHostException("Failed to resolve " + hostname);
            }
        }
    }

    public void setPrimaryDNSServer(String primaryDNSServer) {
        this.primaryDNSServer = primaryDNSServer;
    }

    public void setFallbackDNSServer(String fallbackDNSServer) {
        this.fallbackDNSServer = fallbackDNSServer;
    }
}
