using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Distributed;
using Microsoft.Extensions.Configuration;
using StackExchange.Redis;

public class DecryptionService
{
    private readonly IDistributedCache _cache;
    private readonly IConnectionMultiplexer _redis;
    private readonly ILogger<DecryptionService> _logger;
    private readonly MachineLearningModel _mlModel;

    public DecryptionService(IDistributedCache cache, IConnectionMultiplexer redis, ILogger<DecryptionService> logger, MachineLearningModel mlModel)
    {
        _cache = cache;
        _redis = redis;
        _logger = logger;
        _mlModel = mlModel;
    }

    public async Task<string> DecryptAsync(string base64Message)
    {
        var decryptionParams = await GetDecryptionParametersAsync();
        using (var provider = new TripleDESCryptoServiceProvider())
        {
            provider.Key = decryptionParams.Key;
            provider.IV = decryptionParams.IV;

            using (var decryptor = provider.CreateDecryptor(provider.Key, provider.IV))
            using (var ms = new System.IO.MemoryStream(Convert.FromBase64String(base64Message)))
            using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
            using (var sr = new System.IO.StreamReader(cs))
            {
                return await sr.ReadToEndAsync();
            }
        }
    }

    private async Task<DecryptionParameters> GetDecryptionParametersAsync()
    {
        var cachedParams = await _cache.GetStringAsync("DecryptionParams");
        if (cachedParams != null)
        {
            return JsonConvert.DeserializeObject<DecryptionParameters>(cachedParams);
        }

        var paramsFromRedis = await _redis.GetDatabase().StringGetAsync("DecryptionParams");
        if (!string.IsNullOrEmpty(paramsFromRedis))
        {
            cachedParams = Encoding.UTF8.GetString(paramsFromRedis);
            _cache.SetString("DecryptionParams", cachedParams, new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromHours(1) });
            return JsonConvert.DeserializeObject<DecryptionParameters>(cachedParams);
        }

        var newParams = GenerateNewDecryptionParameters();
        var paramsJson = JsonConvert.SerializeObject(newParams);

        await _cache.SetStringAsync("DecryptionParams", paramsJson, new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromHours(1) });
        await _redis.GetDatabase().StringSetAsync("DecryptionParams", Encoding.UTF8.GetBytes(paramsJson), null, When.NotExists);
        return newParams;
    }

    private async Task<DecryptionParameters> GenerateNewDecryptionParameters()
    {
        var key = Convert.ToBase64String(RandomNumberGenerator.GetBytes(24));
        var iv = Convert.ToBase64String(RandomNumberGenerator.GetBytes(8));
        await _mlModel.PredictDemandAndUpdateCaching(key, iv);
        return new DecryptionParameters { Key = key, IV = iv };
    }
}

