public class GraphService
{
    private IDriver _driver;

    public GraphService(string uri, string user, string password)
    {
        _driver = GraphDatabase.Driver(uri, AuthTokens.Basic(user, password));
    }

    public void AddRandomVerticesAndEdges(int numVertices, int numEdges)
    {
        using (var session = _driver.Session())
        {
            for (int i = 0; i < numVertices; i++)
            {
                var vertexId = Guid.NewGuid().ToString();
                var randomProperties = GetRandomProperties();
                var query = $"CREATE (v:Vertex {{id: '{vertexId}', properties: {JsonConvert.SerializeObject(randomProperties)}}}";
                session.Run(query);
            }

            for (int i = 0; i < numEdges; i++)
            {
                var sourceId = Guid.NewGuid().ToString();
                var targetId = Guid.NewGuid().ToString();
                var randomProperties = GetRandomProperties();
                var query = $"MATCH (s:Vertex {{id: '{sourceId}'}}), (t:Vertex {{id: '{targetId}'}}) CREATE (s)-[:RELATIONSHIP {{id: '{Guid.NewGuid().ToString()}', properties: {JsonConvert.SerializeObject(randomProperties)}}]->(t)";
                session.Run(query);
            }
        }
    }

    private Dictionary<string, object> GetRandomProperties()
    {
        var properties = new Dictionary<string, object>();
        for (int i = 0; i < Random.Shared.Next(1, 5); i++)
        {
            properties[$"property{i}"] = Random.Shared.Next();
        }
        return properties;
    }
}
