use tokio::sync::{mpsc, Mutex};
use std::collections::HashMap;
use reqwest::Client;
use serde_json::Value;

struct DataAggregator {
    clients: HashMap<String, Client>,
    backup_clients: HashMap<String, Client>,
    message_tx: mpsc::Sender<(String, Value)>,
}

impl DataAggregator {
    async fn new() -> Self {
        let (message_tx, _) = mpsc::channel(100);
        DataAggregator {
            clients: HashMap::new(),
            backup_clients: HashMap::new(),
            message_tx,
        }
    }

    async fn add_client(&mut self, name: String, client: Client) {
        self.clients.insert(name.clone(), client);
        if let Some(backup_client) = ClientBuilder::new().build() {
            self.backup_clients.insert(name, backup_client);
        }
    }

    async fn fetch_data(&self, source_name: &str) -> Result<Value, reqwest::Error> {
        if let Some(client) = self.clients.get(source_name) {
            client.get(format!("https://api.example.com/{}", source_name)).send().await?.json::<Value>().await
        } else if let Some(backup_client) = self.backup_clients.get(source_name) {
            backup_client.get(format!("https://api.backup.com/{}", source_name)).send().await?.json::<Value>().await
        } else {
            Err(reqwest::Error::new(reqwest::error::Kind::Other, "Client not found"))
        }
    }

    async fn start_aggregation(&self) {
        let mut interval = tokio::time::interval(tokio::time::Duration::from_secs(10));
        while let _ = interval.tick().await {
            for (source_name, _) in &self.clients {
                if let Ok(data) = self.fetch_data(source_name).await {
                    self.message_tx.send((source_name.clone(), data)).await.unwrap();
                }
            }
        }
    }
}

#[tokio::main]
async fn main() {
    let mut aggregator = DataAggregator::new().await;
    aggregator.add_client("weather".to_string(), ClientBuilder::new().build()).await;
    aggregator.add_client("finance".to_string(), ClientBuilder::new().build()).await;
    aggregator.start_aggregation().await;
}
