import hashlib
import os
from concurrent.futures import ThreadPoolExecutor, as_completed
from queue import Queue, Empty

def compute_sha256(file_path):
    with open(file_path, 'rb') as f:
        return hashlib.sha256(f.read()).hexdigest()

def process_files(file_paths, max_workers=10):
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = {executor.submit(compute_sha256, file_path): file_path for file_path in file_paths}
        results = {}
        for future in as_completed(futures):
            file_path = futures[future]
            try:
                hash_value = future.result()
                results[file_path] = hash_value
            except Exception as e:
                results[file_path] = str(e)
    return results

def main():
    # Example usage
    file_paths = ['path/to/large/file1', 'path/to/large/file2']
    hash_values = process_files(file_paths, max_workers=5)
    for file_path, hash_value in hash_values.items():
        print(f'{file_path}: {hash_value}')

if __name__ == '__main__':
    main()
```

