    po::store(po::parse_command_line(argc, argv, desc), vm);
    po::notify(vm);

    if (vm.count("help")) {
        std::cout << desc << "\n";
        return 1;
    }

    // Initialize logging
    Logger logger;

    try {
        // Initialize cloud storage client
        CloudStorageClient storage_client("your-cloud-storage-config");

        // Process each input file
        for (const auto& file : vm["input-files"].as<std::vector<std::string>>()) {
            std::unique_ptr<DataHandler> data_handler = DataHandler::create(file);

            if (!data_handler) {
                logger.error("Failed to create data handler for file: " + file);
                continue;
            }

            // Process the data
            auto processed_data = data_handler->process();

            // Store or retrieve data from cloud storage
            std::string storage_key = "processed_" + data_handler->getFileName();
            if (vm.count("report")) {
                storage_client.store(storage_key, processed_data);
            } else {
                std::cout << "Data stored in cloud: " << storage_key << "\n";
            }
        }

    } catch (const std::exception& e) {
        logger.error("An error occurred: " + std::string(e.what()));
