    LOG_LEVEL_INFO,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_ERROR,
    LOG_LEVEL_CRITICAL
} LogLevel;

// Function to generate a random boolean value
int generateRandomBoolean() {
    return rand() % 2;
}

// Function to log messages with detailed information
void logMessage(LogLevel level, const char* message) {
    time_t now = time(NULL);
    printf("[%s] [%d] %s\n", ctime(&now), level, message);
}

// Function to dynamically resize the array and manage memory leaks
NFAPI_CRC_INDICATION_PDU_T** resizeArray(NFAPI_CRC_INDICATION_PDU_T** array, size_t* currentSize, size_t newSize) {
    NFAPI_CRC_INDICATION_PDU_T** newArray = realloc(array, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (newArray == NULL) {
        logMessage(LOG_LEVEL_ERROR, "Memory allocation failed while resizing array.");
        return NULL;
    }
    *currentSize = newSize;
    for (size_t i = 0; i < *currentSize; ++i) {
        newArray[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newArray[i] == NULL) {
            logMessage(LOG_LEVEL_ERROR, "Memory allocation failed while resizing array.");
            return NULL;
        }
    }
    return newArray;
}

// Function to populate the array with NFAPI_CRC_INDICATION_PDU_T structures
void populateCRCIndicationPDUs(NFAPI_CRC_INDICATION_PDU_T** array, size_t* currentSize, size_t maxSize) {
    srand(time(NULL)); // Seed for random number generation

    while (*currentSize < maxSize) {
        if (*currentSize == 0 || *currentSize % 1024 == 0) { // Resize every 1024 elements
            array = resizeArray(array, currentSize, *currentSize + 1024);
            if (array == NULL) {
                logMessage(LOG_LEVEL_CRITICAL, "Failed to resize array. Exiting...");
                exit(EXIT_FAILURE);
            }
        }

        NFAPI_CRC_INDICATION_PDU_T* pdu = array[*currentSize];
        pdu->RX_UE_INFORMATION_TAG = rand() % 100;
        pdu->RNTI = rand() % 4096;
        pdu->CRC_INDICATION_REL8_TAG = generateRandomBoolean();

        (*currentSize)++;
    }
}

// Function to simulate external REST API service
void callExternalAPI(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Simulate API call with potential errors
    if (rand() % 10 == 0) {
        logMessage(LOG_LEVEL_WARNING, "External API call failed due to network issues.");
        return;
    }
    // Process the PDU here
    printf("Processing PDU: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n",
           pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG);
}

// Function to asynchronously process data using a message queue
void* processMessageQueue(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)arg;
    size_t currentSize = 0, maxSize = 1024;

    while (currentSize < maxSize) {
        populateCRCIndicationPDUs(array, &currentSize, maxSize);
        for (size_t i = 0; i < currentSize; ++i) {
            callExternalAPI(array[i]);
        }
        currentSize = 0;
    }

    return NULL;
}

// Main function
int main() {
    size_t arraySize = 1024;
    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(arraySize * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (array == NULL) {
        logMessage(LOG_LEVEL_CRITICAL, "Failed to initialize memory for the array. Exiting...");
        return EXIT_FAILURE;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, processMessageQueue, (void*)array) != 0) {
        logMessage(LOG_LEVEL_CRITICAL, "Failed to create thread for processing message queue. Exiting...");
        free(array);
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    // Clean up
    for (size_t i = 0; i < arraySize; ++i) {
        free(array[i]);
    }
    free(array);

    return EXIT_SUCCESS;
}
