#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *buffer;
    size_t size;
    pthread_mutex_t mutex;
} StringReplicationLibrary;

StringReplicationLibrary* create_library(size_t size) {
    StringReplicationLibrary *lib = (StringReplicationLibrary*)malloc(sizeof(StringReplicationLibrary));
    lib->buffer = (char*)malloc(size);
    lib->size = size;
    pthread_mutex_init(&lib->mutex, NULL);
    return lib;
}

void replicate_string(StringReplicationLibrary *lib, const char *input) {
    pthread_mutex_lock(&lib->mutex);
    if (strlen(input) < lib->size) {
        strcpy(lib->buffer, input);
    } else {
        printf("Input string too large\n");
    }
    pthread_mutex_unlock(&lib->mutex);
}

void destroy_library(StringReplicationLibrary *lib) {
    free(lib->buffer);
    pthread_mutex_destroy(&lib->mutex);
    free(lib);
}
