    IoTDataProcessor(const std::string& apiEndpoint, const std::string& clientId, const std::string& clientSecret)
        : apiEndpoint(apiEndpoint), clientId(clientId), clientSecret(clientSecret) {}

    void start() {
        // Start worker threads
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(queueMutex);
                        condition.wait(lock, [this]{ return !tasks.empty() || stop; });
                        if (stop && tasks.empty()) {
                            return;
                        }
                        task = std::move(tasks.front());
                        tasks.pop();
                    }
                    task();
                }
            });
        }

        // Start data ingestion and processing loop
        while (!stop) {
            processBatchedData();
            processLiveSensorFeeds();
            std::this_thread::sleep_for(std::chrono::seconds(10));
        }

        // Join worker threads
        for (auto& worker : workers) {
            worker.join();
        }
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
    }

