public class DocumentUpdateService
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<DocumentUpdateService> _logger;
    private readonly AsyncRetryPolicy _retryPolicy;

    public DocumentUpdateService(HttpClient httpClient, ILogger<DocumentUpdateService> logger)
    {
        _httpClient = httpClient;
        _logger = logger;
        _retryPolicy = Policy
            .Handle<HttpRequestException>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));
    }

    public async Task UpdateDocument(DocumentUpdateRequest request)
    {
        try
        {
            var response = await _retryPolicy.ExecuteAsync(async () =>
                await _httpClient.PutAsJsonAsync($"https://contentmanagementapi/documents/{request.DocumentId}", request));

            if (!response.IsSuccessStatusCode)
            {
                throw new InvalidOperationException($"Failed to update document: {await response.Content.ReadAsStringAsync()}");
            }

            var updatedDocument = await response.Content.ReadFromJsonAsync<DocumentUpdateResponse>();
            _logger.LogInformation("Document updated successfully. Version: {Version}, Timestamp: {Timestamp}", updatedDocument.Version, updatedDocument.Timestamp);

            // Notify subscribers
            await NotifySubscribers(updatedDocument);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating document");
        }
    }

    private async Task NotifySubscribers(DocumentUpdateResponse updatedDocument)
    {
        // Logic to notify subscribers about the update
    }
}

public class DocumentUpdateRequest
{
    public string DocumentId { get; set; }
    public string SectionName { get; set; }
    public string Content { get; set; }
}

