# Define the executeAttackSequence function in C++
#include <iostream>
#include <thread>
#include <chrono>

void executeAttackSequence() {
    // Initialize variables for attack selection and energy management
    int currentEnergy = 100;
    const int cooldownA = 5; // seconds
    const int cooldownB = 7; // seconds
    const int cooldownC = 3; // seconds
    bool canAttackA = true, canAttackB = true, canAttackC = true;

    while (true) {
        // Simulate energy regeneration
        std::this_thread::sleep_for(std::chrono::seconds(1));
        currentEnergy += 2;
        if (currentEnergy > 100) currentEnergy = 100;

        // Select attacks dynamically based on energy and cooldown status
        if (canAttackA && currentEnergy >= 10) {
            std::cout << "Executing Attack A\n";
            canAttackA = false;
            currentEnergy -= 10;
            std::this_thread::sleep_for(std::chrono::seconds(cooldownA));
        } else if (canAttackB && currentEnergy >= 20) {
            std::cout << "Executing Attack B\n";
            canAttackB = false;
            currentEnergy -= 20;
            std::this_thread::sleep_for(std::chrono::seconds(cooldownB));
        } else if (canAttackC && currentEnergy >= 5) {
            std::cout << "Executing Attack C\n";
            canAttackC = false;
            currentEnergy -= 5;
            std::this_thread::sleep_for(std::chrono::seconds(cooldownC));
        }

        // Reset attack cooldowns after attacks
        if (!canAttackA && currentEnergy < 10) {
            canAttackA = true;
        }
        if (!canAttackB && currentEnergy < 20) {
            canAttackB = true;
        }
        if (!canAttackC && currentEnergy < 5) {
            canAttackC = true;
        }

        // Check for insufficient energy or cooldown overlaps
        if (currentEnergy < 10 || canAttackA || canAttackB || canAttackC) {
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    }
}

int main() {
    executeAttackSequence();
    return 0;
}
