    int sourcePort;
    int destPort;
    std::string transmissionType;
};

class NetworkManager {
public:
    void populatePacketQueue(const std::function<void(std::vector<PacketHeader>&)>& packetGenerator) {
        std::lock_guard<std::mutex> lock(mutex_);
        packetGenerator(packetQueue_);
        cv_.notify_all();
    }

    PacketHeader getNextPacket() {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this] { return !packetQueue_.empty(); });
        PacketHeader packet = packetQueue_.front();
        packetQueue_.pop();
        return packet;
    }

private:
    std::queue<PacketHeader> packetQueue_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

void simulateNetworkLoad(NetworkManager& manager) {
    for (int i = 0; i < 100; ++i) {
        std::vector<PacketHeader> packets;
        // Simulate packet generation
        for (int j = 0; j < 5; ++j) {
            PacketHeader packet;
            packet.PacketID = i * 5 + j;
            packet.sourceIP = "192.168.1." + std::to_string(i);
            packet.destIP = "10.0.0." + std::to_string(j);
            packet.sourcePort = 8080 + i % 100;
            packet.destPort = 5000 + j % 100;
            packet.transmissionType = "TCP";
            packets.push_back(packet);
        }
        manager.populatePacketQueue([&packets](std::vector<PacketHeader>& queue) {
            for (const auto& packet : packets) {
                queue.push(packet);
            }
        });
    }
}

void processPackets(NetworkManager& manager) {
    while (true) {
        PacketHeader packet = manager.getNextPacket();
        // Process packet
        std::cout << "Processing packet ID: " << packet.PacketID << std::endl;
        std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Simulate processing time
    }
}

