// Thread-safe queue implementation
template<typename T>
class SafeQueue {
private:
    std::queue<T> q;
    mutable std::mutex m;
    std::condition_variable c;

public:
    void push(T value) {
        std::lock_guard<std::mutex> lock(m);
        q.push(value);
        c.notify_one();
    }

    T pop() {
        std::unique_lock<std::mutex> lock(m);
        c.wait(lock, [this] { return !q.empty(); });
        T val = q.front();
        q.pop();
        return val;
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(m);
        return q.empty();
    }
};

