class PacketThreadWorker {
public:
    PacketThreadWorker(std::vector<PacketHeader>& packetHeaders)
        : packetHeaders_(packetHeaders), currentPos_(0) {}

    void operator()() {
        while (true) {
            PacketHeader packet;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                cv_.wait(lock, [this] { return currentPos_ < packetHeaders_.size(); });
                if (currentPos_ >= packetHeaders_.size()) break;
                packet = packetHeaders_[currentPos_++];
            }
            PacketProcessor().processPacket(packet);
        }
    }

private:
    std::vector<PacketHeader>& packetHeaders_;
    size_t currentPos_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

