NetworkPacketManager::~NetworkPacketManager() {
    stop();
}

void NetworkPacketManager::start() {
    for (int i = 0; i < workers.size(); ++i) {
        workers.emplace_back(&NetworkPacketManager::workerThread, this);
    }
}

void NetworkPacketManager::stop() {
    running.store(false);
    queueCondVar.notify_all();
    for (auto& worker : workers) {
        if (worker.joinable()) {
