public class DynamicNetworkResourceManager
{
    private readonly ConcurrentDictionary<string, NetworkInterface> _interfaces = new();
    private readonly HttpClient _httpClient = new HttpClient();

    public async Task UpdateResourceUsageAsync(string interfaceId, double usage)
    {
        if (!_interfaces.TryGetValue(interfaceId, out var networkInterface))
        {
            networkInterface = new NetworkInterface { Id = interfaceId };
            _interfaces[interfaceId] = networkInterface;
        }

        networkInterface.CurrentUsage = usage;

        // Integrate with Prometheus and Grafana
        await PushMetricsToPrometheusAsync(networkInterface);
        await SendAlertsToGrafanaAsync(networkInterface);
    }

    private async Task PushMetricsToPrometheusAsync(NetworkInterface networkInterface)
    {
        var metricsUrl = "http://prometheus-server/metrics";
        var data = $"network_usage{{interface_id=\"{networkInterface.Id}\"}} {networkInterface.CurrentUsage}";

        await _httpClient.PostAsync(metricsUrl, new StringContent(data));
    }

    private async Task SendAlertsToGrafanaAsync(NetworkInterface networkInterface)
    {
        if (networkInterface.CurrentUsage > 90) // Example threshold
        {
            var alertUrl = "http://grafana-server/alert";
            var data = $"{{\"interface_id\": \"{networkInterface.Id}\", \"usage\": {networkInterface.CurrentUsage}}}";

            await _httpClient.PostAsync(alertUrl, new StringContent(data));
        }
    }

    public class NetworkInterface
    {
        public string Id { get; set; }
        public double CurrentUsage { get; set; }
    }
}
