#include <pthread.h>
#include <semaphore.h>

#define MAX_STRUCTURES 1024

typedef struct {
    // Define the structure fields here
    int field1;
    int field2;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pool[MAX_STRUCTURES];
    sem_t available_sems[MAX_STRUCTURES];
    pthread_mutex_t mutex;
} CRC_POOL_T;

CRC_POOL_T crc_pool;

void init_crc_pool() {
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        sem_init(&crc_pool.available_sems[i], 0, 1);
    }
    pthread_mutex_init(&crc_pool.mutex, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_struct() {
    NFAPI_CRC_INDICATION_PDU_T* new_struct = NULL;

    if (sem_wait(&crc_pool.available_sems[0]) == -1) {
        perror("Failed to wait on semaphore");
        return NULL;
    }

    pthread_mutex_lock(&crc_pool.mutex);
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (sem_getvalue(&crc_pool.available_sems[i], &i) == 1) {
            new_struct = &crc_pool.pool[i];
            sem_post(&crc_pool.available_sems[i]);
            break;
        }
    }
    pthread_mutex_unlock(&crc_pool.mutex);

    return new_struct;
}

void free_struct(NFAPI_CRC_INDICATION_PDU_T* struct_to_free) {
    if (struct_to_free == NULL) {
        return;
    }

    pthread_mutex_lock(&crc_pool.mutex);
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (&crc_pool.pool[i] == struct_to_free) {
            sem_wait(&crc_pool.available_sems[i]);
            break;
        }
    }
    pthread_mutex_unlock(&crc_pool.mutex);
}

