#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <functional>
#include <future>

class TCPConnectionPool {
public:
    using Connection = int; // Simplified representation of a connection

    explicit TCPConnectionPool(size_t initialSize, size_t maxSize)
        : pool(initialSize), maxConnections(maxSize) {}

    ~TCPConnectionPool() {
        for (auto& conn : pool) {
            close(conn);
        }
    }

    Connection getConnection() {
        std::unique_lock<std::mutex> lock(mutex);
        while (pool.empty()) {
            if (connectionsWaiting.fetch_add(1, std::memory_order_relaxed) >= maxConnections - 1) {
                connectionsWaiting.fetch_sub(1, std::memory_order_relaxed);
                throw std::runtime_error("No available connections");
            }
            cv.wait(lock, [this] { return !pool.empty(); });
        }

        Connection conn = pool.front();
        pool.pop();
        connectionsWaiting.fetch_sub(1, std::memory_order_relaxed);
        cv.notify_one();
        return conn;
    }

    void releaseConnection(Connection conn) {
        std::unique_lock<std::mutex> lock(mutex);
        if (pool.size() < maxConnections) {
            pool.push(conn);
            cv.notify_one();
        } else {
            close(conn); // Close connection if pool is full
        }
    }

private:
    std::vector<Connection> pool;
    size_t maxConnections;
    std::mutex mutex;
    std::condition_variable cv;
    std::atomic<int> connectionsWaiting{0};

    void close(Connection conn) {
        // Simulate closing a connection
        std::cout << "Closing connection: " << conn << std::endl;
    }
};

// Unit tests
#include <gtest/gtest.h>

TEST(TCPConnectionPoolTest, BasicOperations) {
    TCPConnectionPool pool(2, 4);

    auto conn1 = pool.getConnection();
    EXPECT_NE(conn1, -1);
    EXPECT_EQ(pool.pool.size(), 1);

    auto conn2 = pool.getConnection();
    EXPECT_NE(conn2, -1);
    EXPECT_EQ(pool.pool.size(), 0);

    pool.releaseConnection(conn1);
    EXPECT_EQ(pool.pool.size(), 1);

    pool.releaseConnection(conn2);
    EXPECT_EQ(pool.pool.size(), 2);
}

TEST(TCPConnectionPoolTest, MaxConnections) {
    TCPConnectionPool pool(2, 3);

    auto conn1 = pool.getConnection();
    EXPECT_NE(conn1, -1);
    EXPECT_EQ(pool.pool.size(), 1);

    auto conn2 = pool.getConnection();
    EXPECT_NE(conn2, -1);
    EXPECT_EQ(pool.pool.size(), 0);

    try {
        auto conn3 = pool.getConnection();
        FAIL() << "Expected exception";
    } catch (const std::runtime_error& e) {
        // Expected
    }
}

int main(int argc, char** argv) {
    ::testing::InitGoogleTest(&argc, argv);
    return RUN_ALL_TESTS();
}
```

