#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <queue>
#include <memory>

class Connection {
public:
    virtual ~Connection() = default;
    virtual void connect() = 0;
    virtual void disconnect() = 0;
};

class TCPConnection : public Connection {
public:
    void connect() override { std::cout << "TCP Connection Established" << std::endl; }
    void disconnect() override { std::cout << "TCP Connection Disconnected" << std::endl; }
};

class ConnectionPool {
public:
    ConnectionPool(size_t size) : max_size_(size), connections_(), available_connections_(size), mutex_(), cv_() {}

    ~ConnectionPool() {
        for (auto& conn : connections_) {
            conn->disconnect();
        }
    }

    std::shared_ptr<Connection> getConnection() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (available_connections_.empty()) {
            cv_.wait(lock, [this] { return !available_connections_.empty(); });
        }
        auto conn = available_connections_.front();
        available_connections_.pop();
        return conn;
    }

    void releaseConnection(std::shared_ptr<Connection> conn) {
        std::unique_lock<std::mutex> lock(mutex_);
        available_connections_.push(conn);
        cv_.notify_one();
    }

private:
    size_t max_size_;
    std::vector<std::shared_ptr<Connection>> connections_;
    std::queue<std::shared_ptr<Connection>> available_connections_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

class ConnectionManager {
public:
    void addConnection(std::shared_ptr<Connection> conn) {
        pool_->releaseConnection(conn);
    }

    std::shared_ptr<Connection> getConnection() {
        return pool_->getConnection();
    }

private:
    std::unique_ptr<ConnectionPool> pool_;
};

int main() {
    auto manager = std::make_unique<ConnectionManager>();
    manager->addConnection(std::make_shared<TCPConnection>());
    manager->addConnection(std::make_shared<TCPConnection>());

    auto conn = manager->getConnection();
    conn->connect();

    return 0;
}
