class RandomValueGenerator {
public:
    static std::shared_ptr<RandomValueGenerator> getInstance() {
        static std::once_flag flag;
        std::call_once(flag, [](){
            instance.reset(new RandomValueGenerator());
        });
        return instance;
    }

    float generateFloat(float min, float max) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (cache_.find(min) != cache_.end() && cache_[min].second == max) {
            return cache_[min].first;
        }
        float value = dist_(gen_);
        cache_[min] = {value, max};
        log("Float generated: " + std::to_string(value));
        return value;
    }

    int generateInt(int min, int max) {
        // Similar to float generation
    }

    bool generateBoolean() {
        // Similar to float generation
    }

    Vector3 generateVector3(float minX, float maxX, float minY, float maxY, float minZ, float maxZ) {
        // Similar to float generation
    }

private:
    RandomValueGenerator() : gen_(std::random_device{}()), dist_(0.0f, 1.0f), cache_(), logLevel_("INFO") {}

    void log(const std::string& message) {
        if (logLevel_ == "DEBUG") {
            std::cout << message << std::endl;
        }
    }

    static std::shared_ptr<RandomValueGenerator> instance;
    std::mutex mutex_;
    std::mt19937 gen_;
    std::uniform_real_distribution<> dist_;
    std::unordered_map<std::pair<float, float>, std::pair<float, float>, CacheKeyHasher> cache_;
    std::string logLevel_;
};

class CacheKeyHasher {
public:
    size_t operator()(const std::pair<float, float>& key) const {
        return std::hash<float>()(key.first) ^ std::hash<float>()(key.second);
    }
};
