import threading
from kafka import KafkaConsumer, KafkaProducer
from confluent_kafka import Producer as ConfluentProducer, Consumer as ConfluentConsumer
import json
import queue
from datetime import datetime
import logging

class LogAggregator:
    def __init__(self):
        self.log_queue = queue.Queue()
        self.kafka_producer = KafkaProducer(bootstrap_servers='localhost:9092')
        self.confluent_producer = ConfluentProducer({'bootstrap.servers': 'localhost:9093'})
        self.kafka_consumers = [KafkaConsumer(f'log-topic-{i}', group_id='log-group') for i in range(10)]
        self.confluent_consumers = [ConfluentConsumer([('log-topic', {'auto.offset.reset': 'earliest'})]) for _ in range(5)]

    def start_consuming(self):
        for consumer in self.kafka_consumers:
            thread = threading.Thread(target=self.consume_logs, args=(consumer,))
            thread.start()

        for consumer in self.confluent_consumers:
            consumer.subscribe(['log-topic'])
            thread = threading.Thread(target=self.consume_logs_confluent, args=(consumer,))
            thread.start()

    def consume_logs(self, consumer):
        for message in consumer:
            self.log_queue.put(message.value.decode('utf-8'))

    def consume_logs_confluent(self, consumer):
        while True:
            msg = consumer.poll(timeout=1.0)
            if msg is None:
                continue
            if msg.error():
                if msg.error().code() == KafkaError._PARTITION_EOF:
                    logging.info(f'Reached end of partition {msg.topic()} [{msg.partition()}] at offset {msg.offset()}')
                else:
                    raise KafkaException(msg.error())
            else:
                self.log_queue.put(msg.value.decode('utf-8'))

    def process_logs(self):
        while True:
            log_entry = self.log_queue.get()
            # Process log entry here
            print(log_entry)

