#include <iostream>
#include <vector>
#include <mutex>
#include <thread>
#include <condition_variable>
#include <atomic>

class ConnectionPool {
public:
    ConnectionPool(size_t initialSize, size_t maxSize)
        : pool(initialSize), maxConnections(maxSize) {}

    void addConnection(std::shared_ptr<TCPConnection> conn) {
        std::lock_guard<std::mutex> lock(mutex);
        if (pool.size() < maxConnections) {
            pool.push_back(conn);
            cv.notify_one();
        }
    }

    std::shared_ptr<TCPConnection> getConnection() {
        std::unique_lock<std::mutex> lock(mutex);
        cv.wait(lock, [this] { return !pool.empty(); });
        auto conn = pool.back();
        pool.pop_back();
        return conn;
    }

    void releaseConnection(std::shared_ptr<TCPConnection> conn) {
        std::lock_guard<std::mutex> lock(mutex);
        if (pool.size() < maxConnections) {
            pool.push_back(conn);
            cv.notify_one();
        }
    }

private:
    std::vector<std::shared_ptr<TCPConnection>> pool;
    size_t maxConnections;
    std::mutex mutex;
    std::condition_variable cv;
};

class TCPConnection {
public:
    void connect() { /* Implementation */ }
    void disconnect() { /* Implementation */ }
    // Other methods
};

int main() {
    ConnectionPool pool(10, 50);

    // Example usage
    auto conn = pool.getConnection();
    conn->connect();

    // ...

    pool.releaseConnection(conn);

    return 0;
}
```

