#include <pthread.h>
#include <cstdlib>
#include <ctime>

struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    bool CRCFLAG;
};

void* populateArray(void* arg) {
    int N = *(int*)arg; // Number of structures to populate
    NFAPI_CRC_INDICATION_PDU_T* array = new NFAPI_CRC_INDICATION_PDU_T[N];

    srand(time(0));
    for(int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand() % 65536;
        array[i].CRCFLAG = (rand() % 2 == 0);
    }

    // Simulate processing
    sleep(1); // Delay to mimic processing time

    delete[] array; // Clean up memory
    pthread_exit(NULL);
}

int main() {
    int N = 1000000;
    pthread_t thread;
    int rc;

    rc = pthread_create(&thread, NULL, populateArray, (void*)&N);
    if (rc) {
        std::cerr << "Error: unable to create thread," << rc << std::endl;
        return -1;
    }

    pthread_join(thread, NULL);
    return 0;
}
