class ConfigManager:
    def __init__(self, key):
        self.cipher_suite = Fernet(key)

    def encrypt(self, config):
        return self.cipher_suite.encrypt(json.dumps(config).encode())

    def decrypt(self, encrypted_config):
        decrypted_data = self.cipher_suite.decrypt(encrypted_config).decode()
        return json.loads(decrypted_data)

