        pthread_mutex_lock(&mutex);
        if (pdu_count >= MAX_PDU) {
            pthread_mutex_unlock(&mutex);
            break;
        }
        pdus[pdu_count] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdus[pdu_count]->RNTI = rand() % 1024;
        pdus[pdu_count]->CRCFLAG = rand() & 1;
        pdu_count++;
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t threads[4];
    int i;

    for (i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, generate_pdu, NULL);
    }

    for (i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

