#include <stdlib.h>
#include <pthread.h>
#include <sqlite3.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_flag;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T* head;
    sqlite3* db;
} LinkedListDBManager;

LinkedListDBManager* create_manager() {
    LinkedListDBManager* manager = (LinkedListDBManager*)malloc(sizeof(LinkedListDBManager));
    if (manager) {
        pthread_mutex_init(&manager->mutex, NULL);
        manager->head = NULL;
        sqlite3_open("crc_indication.db", &manager->db);
        // Create table or perform other setup
    }
    return manager;
}

void insert_node(LinkedListDBManager* manager, NFAPI_CRC_INDICATION_PDU_T* new_node) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->head == NULL) {
        manager->head = new_node;
    } else {
        new_node->next = manager->head;
        manager->head = new_node;
    }
    sqlite3_stmt* stmt;
    const char* sql = "INSERT INTO crc_indication_table VALUES (?, ?, ?)";
    if (sqlite3_prepare_v2(manager->db, sql, -1, &stmt, NULL) == SQLITE_OK) {
        // Bind values and execute statement
        sqlite3_step(stmt);
        sqlite3_finalize(stmt);
    }
    pthread_mutex_unlock(&manager->mutex);
}

void free_nodes(NFAPI_CRC_INDICATION_PDU_T* node) {
    while (node != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* temp = node;
        node = node->next;
        free(temp);
    }
}

void destroy_manager(LinkedListDBManager* manager) {
    pthread_mutex_lock(&manager->mutex);
    free_nodes(manager->head);
    sqlite3_close(manager->db);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}
