struct UDP_PACKET_RECORD {
    std::string SOURCE_IP;
    std::string DESTINATION_IP;
    std::chrono::system_clock::time_point TIMESTAMP;
    size_t PAYLOAD_SIZE;
};

class UDPPacketManager {
public:
    void AddPacket(const UDP_PACKET_RECORD& packet) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (queue_.size() >= capacity_) {
            // Handle queue full scenario
            handleQueueFull();
        }
        queue_.push(packet);
        condition_variable_.notify_one();
    }

    void StartProcessing() {
        processing_thread_ = std::thread(&UDPPacketManager::processQueue, this);
    }

    ~UDPPacketManager() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stop_processing_ = true;
        }
        condition_variable_.notify_one();
        if (processing_thread_.joinable()) {
            processing_thread_.join();
        }
    }

private:
    void processQueue() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_variable_.wait(lock, [this] { return !queue_.empty() || stop_processing_; });
            if (stop_processing_ && queue_.empty()) {
                break;
            }
            UDP_PACKET_RECORD packet = queue_.front();
            queue_.pop();
            lock.unlock();

            // Process the packet
            processPacket(packet);
        }
    }

    void handleQueueFull() {
        // Implement logic for handling full queue scenario
        // This could involve throttling new packets, retrying after a delay, etc.
    }

    void processPacket(const UDP_PACKET_RECORD& packet) {
        // Implement packet processing logic
        std::cout << "Processing packet: " << packet.SOURCE_IP << " -> " << packet.DESTINATION_IP << std::endl;
    }

    std::mutex mutex_;
    std::condition_variable condition_variable_;
    std::queue<UDP_PACKET_RECORD> queue_;
    size_t capacity_ = 1000; // Example capacity
    bool stop_processing_ = false;
    std::thread processing_thread_;
};

int main() {
    UDPPacketManager manager;
    manager.StartProcessing();

    // Simulate adding packets
    for (int i = 0; i < 1500; ++i) {
        UDP_PACKET_RECORD packet = {"192.168.1." + std::to_string(i % 256), "10.0.0." + std::to_string(i % 256),
                                    std::chrono::system_clock::now(), 1400};
        manager.AddPacket(packet);
    }

    // Let the processing thread run for a bit
    std::this_thread::sleep_for(std::chrono::seconds(5));

    return 0;
}
