import hashlib
import os
import time
from threading import Lock
from queue import Queue, Empty

class FileHasher:
    def __init__(self, data_store):
        self.data_store = data_store
        self.lock = Lock()
        self.chunk_size = 1024 * 1024  # 1MB initial chunk size
        self.retries = 3
        self.backoff_factor = 2

    def calculate_md5(self, file_path):
        md5_hash = hashlib.md5()
        with open(file_path, 'rb') as file:
            while True:
                data = file.read(self.chunk_size)
                if not data:
                    break
                md5_hash.update(data)
        return md5_hash.hexdigest()

    def upload_to_data_store(self, hash_value):
        try:
            self.data_store.upload(hash_value)
        except Exception as e:
            for _ in range(self.retries):
                time.sleep(self.backoff_factor ** _)
                try:
                    self.data_store.upload(hash_value)
                    return
                except Exception as e:
                    pass
            raise

    def process_file_concurrently(self, file_paths, num_workers):
        queue = Queue()
        results = []
        threads = []

        for file_path in file_paths:
            queue.put(file_path)

        for _ in range(num_workers):
            thread = threading.Thread(target=self.worker, args=(queue, results))
            thread.start()
            threads.append(thread)

        for thread in threads:
            thread.join()

        return results

    def worker(self, queue, results):
        while True:
            try:
                file_path = queue.get(timeout=1)
                hash_value = self.calculate_md5(file_path)
                with self.lock:
                    results.append((file_path, hash_value))
                self.upload_to_data_store(hash_value)
                queue.task_done()
            except Empty:
                break
