#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <curl/curl.h>

// Function to compute MD5 hash of an image file
void compute_md5(const char *file_path, unsigned char *md5_hash) {
    FILE *file = fopen(file_path, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", file_path);
        return;
    }

    unsigned char buffer[4096];
    size_t bytes_read;
    MD5_CTX md5_context;

    MD5_Init(&md5_context);
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), file)) != 0) {
        MD5_Update(&md5_context, buffer, bytes_read);
    }
    fclose(file);

    MD5_Final(md5_hash, &md5_context);
}

// Function to compute SHA-256 hash of an image file
void compute_sha256(const char *file_path, unsigned char *sha256_hash) {
    FILE *file = fopen(file_path, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", file_path);
        return;
    }

    unsigned char buffer[4096];
    size_t bytes_read;
    SHA256_CTX sha256_context;

    SHA256_Init(&sha256_context);
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), file)) != 0) {
        SHA256_Update(&sha256_context, buffer, bytes_read);
    }
    fclose(file);

    SHA256_Final(sha256_hash, &sha256_context);
}

// Function to validate OAuth2 access token response
int validate_oauth2_token(const char *json_response) {
    CURL *curl;
    CURLcode res;

    curl = curl_easy_init();
    if(curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");
        headers = curl_slist_append(headers, "Authorization: Bearer YOUR_ACCESS_TOKEN");

        curl_easy_setopt(curl, CURLOPT_URL, "https://oauth2.example.com/validate_token");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_response);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    }

    return (res == CURLE_OK) ? 1 : 0;
}

// Main function to demonstrate usage
int main() {
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    unsigned char sha256_hash[SHA256_DIGEST_LENGTH];

    compute_md5("path/to/image.jpg", md5_hash);
    compute_sha256("path/to/image.jpg", sha256_hash);

    printf("MD5: ");
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        printf("%02x", md5_hash[i]);
    }
    printf("\n");

    printf("SHA-256: ");
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        printf("%02x", sha256_hash[i]);
    }
    printf("\n");

    const char *json_response = "{\"access_token\":\"your_token\",\"token_type\":\"Bearer\",\"expires_in\":3600}";
    if (validate_oauth2_token(json_response)) {
        printf("Token is valid.\n");
    } else {
        printf("Token is invalid.\n");
    }

    return 0;
}
