class DataProcessingFramework {
public:
    // Constructor
    DataProcessingFramework() {}

    // Destructor
    ~DataProcessingFramework() {
        stop();
    }

    // Add a data source
    void addDataSource(std::string name, std::function<void()> dataSource) {
        dataSources[name] = dataSource;
    }

    // Add a processing module
    void addModule(std::string name, std::function<void(const std::string&)> module) {
        modules[name] = module;
    }

    // Start the framework
    void start() {
        running = true;
        for (const auto& ds : dataSources) {
            threads.emplace_back([this, &ds]() {
                while (running) {
                    ds.second();
                }
            });
        }
    }

    // Stop the framework
    void stop() {
        running = false;
        for (auto& thread : threads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

private:
    bool running = false;
    std::map<std::string, std::function<void()>> dataSources;
    std::map<std::string, std::function<void(const std::string&)>> modules;
    std::vector<std::thread> threads;
};

