std::mutex ingestionMutex;
std::condition_variable ingestionCond;

// Worker thread function for processing logs
void workerThread(int id) {
    while (true) {
        std::unique_lock<std::mutex> lock(ingestionMutex);
        ingestionCond.wait(lock, []{ return !ingestionQueue.empty(); });

        LogEntry log = ingestionQueue.front();
        ingestionQueue.pop();
        lock.unlock();

        // Process log
        processLog(log);

        if (id == 0) {
            // Periodically check for log spikes and adjust ingestion rate
            checkForSpikes();
        }
    }
}

