#include <iostream>
#include <unordered_map>
#include <string>
#include <mutex>
#include <condition_variable>
#include <memory>

class CacheManager {
public:
    void set(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        cache_[key] = value;
        cv_.notify_all();
    }

    std::string get(const std::string& key) {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this, &key]{ return cache_.find(key) != cache_.end(); });
        return cache_[key];
    }

private:
    std::unordered_map<std::string, std::string> cache_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

class CacheService {
public:
    void configure(const std::string& config) {
        // Parse and apply configuration
        std::cout << "Configuring cache with: " << config << std::endl;
    }

    void addNode(const std::string& node) {
        std::lock_guard<std::mutex> lock(mutex_);
        nodes_.insert(node);
        cv_.notify_all();
    }

    void removeNode(const std::string& node) {
        std::unique_lock<std::mutex> lock(mutex_);
        nodes_.erase(node);
        cv_.notify_all();
    }

private:
    std::unordered_set<std::string> nodes_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

class DistributedDataCacheManager {
public:
    void setConfig(const std::string& config) {
        cache_service_.configure(config);
    }

    void addNode(const std::string& node) {
        cache_service_.addNode(node);
    }

    void removeNode(const std::string& node) {
        cache_service_.removeNode(node);
    }

    void set(const std::string& key, const std::string& value) {
        cache_manager_.set(key, value);
    }

    std::string get(const std::string& key) {
        return cache_manager_.get(key);
    }

private:
