#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <fstream>
#include <string>

struct SensorDataPacket {
    std::string SENSOR_ID;
    std::string TIME_STAMP;
    double DATA_VALUE;
};

class DataProcessor {
public:
    void ingestData(const SensorDataPacket& packet) {
        dataQueue.push(packet);
        dataCond.notify_one();
    }

    void processBatch() {
        while (true) {
            std::unique_lock<std::mutex> lock(dataMutex);
            dataCond.wait(lock, [this] { return !dataQueue.empty(); });
            SensorDataPacket packet = dataQueue.front();
            dataQueue.pop();
            lock.unlock();

            validateAndStore(packet);
        }
    }

private:
    void validateAndStore(const SensorDataPacket& packet) {
        // Add validation logic here
        std::cout << "Processing: " << packet.SENSOR_ID << ", " << packet.TIME_STAMP << ", " << packet.DATA_VALUE << std::endl;
        storeInDatabase(packet);
    }

    void storeInDatabase(const SensorDataPacket& packet) {
        // Choose a cloud-based storage solution here
        std::ofstream file("sensor_data.csv", std::ios::app);
        if (file.is_open()) {
            file << packet.SENSOR_ID << "," << packet.TIME_STAMP << "," << packet.DATA_VALUE << "\n";
            file.close();
        } else {
            std::cerr << "Unable to open file for writing" << std::endl;
        }
    }

    std::queue<SensorDataPacket> dataQueue;
    std::mutex dataMutex;
    std::condition_variable dataCond;
};

int main() {
    DataProcessor processor;

    std::thread consumer([&processor] {
        while (true) {
            processor.processBatch();
        }
    });

    // Simulate sensor data ingestion
    for (int i = 0; i < 100; ++i) {
        SensorDataPacket packet;
        packet.SENSOR_ID = "sensor" + std::to_string(i);
        packet.TIME_STAMP = "2023-04-01T" + std::to_string(i * 60); // Simulated timestamp
        packet.DATA_VALUE = static_cast<double>(i) / 10.0; // Simulated data value

        processor.ingestData(packet);
    }

    consumer.join();
    return 0;
}
```

