function renderFooterScripts(scriptObjects) {
    return new Promise((resolve, reject) => {
        const maxConcurrentScripts = 5;
        let currentScripts = 0;
        let scriptsLoaded = 0;
        let minifiedHTML = '';

        function loadScript(scriptObject) {
            if (scriptObject.type && scriptObject.code) {
                return new Promise((resolve, reject) => {
                    const scriptElement = document.createElement('script');
                    scriptElement.type = scriptObject.type;
                    scriptElement.textContent = scriptObject.code;
                    scriptElement.onload = () => resolve();
                    scriptElement.onerror = () => reject(new Error(`Failed to load script: ${scriptObject.code}`));
                    document.body.appendChild(scriptElement);
                });
            } else {
                return Promise.reject(new Error('Invalid script object'));
            }
        }

        function fetchScriptObjects() {
            // Simulate fetching script objects from an API
            return new Promise((resolve, reject) => {
                setTimeout(() => {
                    resolve([
                        { type: 'text/javascript', code: 'console.log("Script 1");' },
                        { type: 'text/javascript', code: 'console.log("Script 2");' }
                    ]);
                }, 500);
            });
        }

        async function processScripts() {
            try {
                const scriptObjects = await fetchScriptObjects();
                for (const scriptObject of scriptObjects) {
                    if (currentScripts < maxConcurrentScripts) {
                        currentScripts++;
                        loadScript(scriptObject)
                            .then(() => {
                                currentScripts--;
                                scriptsLoaded++;
                                updateProgress();
                            })
                            .catch((error) => {
                                console.error(error);
                                currentScripts--;
                                updateProgress();
                            });
                    } else {
                        await new Promise(resolve => setTimeout(resolve, 100)); // Wait for a slot
                        processScripts();
                    }
                }
            } catch (error) {
                reject(error);
            }
        }

        function updateProgress() {
            if (scriptsLoaded === scriptObjects.length) {
                minifiedHTML = '<footer><script>console.log("Footer scripts loaded");</script></footer>';
                resolve(minifiedHTML);
            }
        }

        processScripts();
    });
}
