// Function to compute MD5 hash of a given string
std::string computeMD5(const std::string& input) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, input.c_str(), input.size());
    MD5_Final(digest, &md5);

    std::stringstream ss;
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        ss << std::hex << std::setw(2) << std::setfill('0') << (int)digest[i];
    }
    return ss.str();
}

// Highly concurrent, thread-safe function to populate NFAPI CRC Indication Array
void populateNfapiCrcIndicationArray(NFAPI_CRC_INDICATION_PDU_T* array, int& size, int capacity) {
    static std::mutex mtx;
    std::lock_guard<std::mutex> lock(mtx);

    if (size >= capacity) {
        // Resize the array dynamically
        capacity *= 2; // Double the capacity
        NFAPI_CRC_INDICATION_PDU_T* new_array = new NFAPI_CRC_INDICATION_PDU_T[capacity];
        std::copy(array, array + size, new_array);
        delete[] array;
        array = new_array;
    }

    for (int i = 0; i < capacity - size; ++i) {
        array[size + i].RX_UE_INFORMATION_TAG = generateRandomTag();
        array[size + i].RNTI = generateRandomRNTI();
        array[size + i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    size += capacity - size;
}

