                fetch_product_catalog()
    return product_cache

# Route to handle product requests
@app.route('/product/<int:product_id>', methods=['GET'])
def get_product(product_id):
    catalog = get_product_catalog()
    product_info = catalog.get(str(product_id))
    if product_info:
        return jsonify(product_info), 200
    else:
        return jsonify({"error": "Product not found"}), 404

# Start the background thread for updating product catalog
threading.Thread(target=update_product_catalog).start()

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
```

This code snippet demonstrates a basic Flask application that integrates with an external product catalog service to fetch and cache product data. It includes a background thread for periodically updating the catalog during maintenance windows, ensuring minimal disruption to users.']

