    double DATA_VALUE;
};

// Define a class to handle sensor data processing
class SensorDataProcessor {
private:
    std::queue<SensorDataPacket> dataQueue;
    std::mutex queueMutex;
    std::condition_variable dataCondVar;
    bool running;

public:
    SensorDataProcessor() : running(true) {}

    void startProcessing() {
        std::thread([this]() {
            while (running) {
                std::unique_lock<std::mutex> lock(queueMutex);
                dataCondVar.wait(lock, [this] { return !dataQueue.empty() || !running; });
                if (!running && dataQueue.empty()) break;

                SensorDataPacket packet = dataQueue.front();
                dataQueue.pop();

                // Process the sensor data here
                processSensorData(packet);
            }
        }).detach();
    }

    void stopProcessing() {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            running = false;
        }
        dataCondVar.notify_all();
    }

    void addData(const SensorDataPacket& packet) {
        std::lock_guard<std::mutex> lock(queueMutex);
        dataQueue.push(packet);
        dataCondVar.notify_one();
    }

private:
    void processSensorData(const SensorDataPacket& packet) {
        // Example processing: validate and log the data
        if (packet.DATA_VALUE < 0 || packet.DATA_VALUE > 100) {
            std::cerr << "Invalid data value for sensor ID " << packet.SENSOR_ID << std::endl;
