        std::cout << "Processing data for sensor ID " << packet.SENSOR_ID 
                  << " at time " << std::chrono::system_clock::to_time_t(packet.TIME_STAMP) 
                  << ": Value = " << packet.DATA_VALUE << std::endl;

        // Implement further processing logic here
    }
};

