        if (outfile.is_open()) {
            outfile << "Sensor ID: " << packet.SENSOR_ID 
                   << ", Time Stamp: " << std::chrono::system_clock::to_time_t(packet.TIME_STAMP) 
                   << ", Data Value: " << packet.DATA_VALUE << std::endl;
            outfile.close();
        } else {
            std::cerr << "Unable to open file for writing" << std::endl;
        }
    }

    // Implement additional persistence strategies as needed
};

// Define a class to handle real-time alerting and notification systems
class AlertManager {
public:
    void sendAlert(const std::string& message, const std::string& channel) {
        if (channel == "email") {
            std::cout << "Sending email alert: " << message << std::endl;
        } else if (channel == "sms") {
            std::cout << "Sending SMS alert: " << message << std::endl;
        } else if (channel == "push_notification") {
            std::cout << "Sending push notification: " << message << std::endl;
        }
    }

    // Implement additional notification channels as needed
};

int main() {
    SensorDataProcessor processor;
    DataStorageManager storageManager;
    AlertManager alertManager;

    processor.startProcessing();

    // Simulate receiving sensor data
    for (int i = 0; i < 10; ++i) {
        SensorDataPacket packet = {i, std::chrono::system_clock::now(), static_cast<double>(rand() % 100)};
        processor.addData(packet);
        storageManager.storeData(packet);

        // Example of real-time alerting
        if (packet.DATA_VALUE > 80 || packet.DATA_VALUE < 20) {
            alertManager.sendAlert("Sensor " + std::to_string(i) + " data out of range: " + std::to_string(packet.DATA_VALUE), "email");
        }
    }

    processor.stopProcessing();

    return 0;
}
