#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node for doubly linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

// Doubly linked list structure
typedef struct LinkedList {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} LinkedList;

// Initialize the linked list
void initLinkedList(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to insert a new node at the end of the list
void insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock); // Lock before modifying the list
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    newNode->data = data;
    newNode->next = NULL;

    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        newNode->prev = list->tail;
        list->tail = newNode;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

// Function to delete the entire list
void deleteList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
}

// Function to traverse the list and print data
void printList(LinkedList* list) {
    pthread_mutex_lock(&list->lock); // Lock before reading the list
    Node* current = list->head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %hu, CRCFLAG: %hhu\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRCFLAG);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    LinkedList list;
    initLinkedList(&list);

    // Insert nodes into the linked list
    NFAPI_CRC_INDICATION_PDU_T data1 = {1, 200, 0};
    insertNode(&list, data1);

    NFAPI_CRC_INDICATION_PDU_T data2 = {2, 300, 1};
    insertNode(&list, data2);

    // Print the linked list
    printList(&list);

    // Delete the entire list
    deleteList(&list);

    return 0;
}
