#include <queue>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <thread>
#include <functional>
#include <memory>

class Task {
public:
    using TaskId = int;
    enum class Priority { High, Medium, Low };

    Task(TaskId id, Priority priority, std::function<void()> task) 
        : id_(id), priority_(priority), task_(task) {}

    TaskId getId() const { return id_; }
    Priority getPriority() const { return priority_; }

    void execute() const {
        task_();
    }

private:
    TaskId id_;
    Priority priority_;
    std::function<void()> task_;
};

class PriorityQueue {
public:
    using Lock = std::unique_lock<std::mutex>;

    void addTask(const Task& task) {
        {
            Lock lock(mutex_);
            tasks_.push(task);
        }
        condition_.notify_one();
    }

    void run() {
        while (true) {
            Task currentTask;
            {
                Lock lock(mutex_);
                condition_.wait(lock, [this] { return !tasks_.empty(); });
                currentTask = std::move(tasks_.front());
                tasks_.pop();
            }
            currentTask.execute();
        }
    }

private:
    std::priority_queue<Task, std::vector<Task>, 
                        [](const Task& a, const Task& b) {
                            if (a.getPriority() == b.getPriority())
                                return a.getId() > b.getId(); // Ensure FIFO for same priority
                            return a.getPriority() < b.getPriority();
                        }> tasks_;
    mutable std::mutex mutex_;
    std::condition_variable condition_;
};

int main() {
    PriorityQueue queue;
    std::vector<std::thread> workers;

    for (int i = 0; i < 4; ++i) {
        workers.emplace_back(&PriorityQueue::run, &queue);
    }

    // Example tasks
    queue.addTask(Task(1, Task::Priority::High, []() { std::cout << "High Priority Task\n"; }));
    queue.addTask(Task(2, Task::Priority::Medium, []() { std::cout << "Medium Priority Task\n"; }));
    queue.addTask(Task(3, Task::Priority::Low, []() { std::cout << "Low Priority Task\n"; }));

    for (auto& worker : workers) {
        worker.join();
    }

    return 0;
}
