    if (list == NULL) {
        perror("Failed to allocate memory for the list");
        return NULL;
    }
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    return list;
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) {
