#include <cmath>

// Define DataPoint structure
struct DataPoint {
    int id;
    double value;

    DataPoint(int i, double v) : id(i), value(v) {}
};

// Custom memory pool allocator for DataPoint
class DataPointAllocator {
public:
    DataPoint* allocate(size_t n);
    void deallocate(DataPoint* p, size_t n);

private:
    std::vector<DataPoint> pool;
};

DataPoint* DataPointAllocator::allocate(size_t n) {
    if (pool.size() < n) {
        // Allocate more memory
        pool.resize(n * 2);
    }
    return &pool[n];
}

void DataPointAllocator::deallocate(DataPoint* p, size_t n) {
    // Do nothing for simplicity
}

// Modular C++ library module
class DataManager {
public:
    DataManager(size_t maxInstances = 1000000)
        : allocator(maxInstances), nextId(0), garbageCollectorThread(&DataManager::runGarbageCollector, this) {}

    ~DataManager() {
        stopGarbageCollector();
        garbageCollectorThread.join();
    }

    DataPoint* createDataPoint(double value) {
        std::lock_guard<std::mutex> lock(mutex);
        if (nextId >= maxInstances) {
            throw std::runtime_error("Maximum number of instances reached");
        }
        return allocator.allocate(nextId++);
    }

    void updateDataPoint(DataPoint* dp, double newValue) {
        dp->value = newValue;
    }

    void garbageCollect() {
        // Mark for garbage collection
        garbageCollectFlag.store(true);
    }

private:
    DataPointAllocator allocator;
    std::mutex mutex;
    size_t nextId;
    std::atomic<bool> garbageCollectFlag;
    std::thread garbageCollectorThread;

    void runGarbageCollector() {
        while (true) {
            if (garbageCollectFlag.load()) {
                garbageCollectFlag.store(false);
                // Perform garbage collection
                std::cout << "Running garbage collector..." << std::endl;
                // Simulate garbage collection
                std::this_thread::sleep_for(std::chrono::seconds(1));
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }

    void stopGarbageCollector() {
        garbageCollectFlag.store(true);
    }
};

// Test cases
int main() {
    DataManager manager;
    DataPoint* dp = manager.createDataPoint(3.14);
    manager.updateDataPoint(dp, 2.718);

    std::cout << "Data Point ID: " << dp->id << ", Value: " << dp->value << std::endl;

    manager.garbageCollect();

    return 0;
}
