import asyncio
import aiohttp
import hashlib
import os
from urllib.parse import urlparse
from concurrent.futures import ThreadPoolExecutor
import threading

class FileHasher:
    def __init__(self):
        self.executor = ThreadPoolExecutor(max_workers=5)
        self.lock = threading.Lock()

    async def hash_url(self, url: str, start_byte: int = 0, length: int = None) -> str:
        async with aiohttp.ClientSession() as session:
            try:
                async with session.get(url, timeout=30) as response:
                    if response.status == 200:
                        content = await response.read()
                        return self.hash_data(content, start_byte, length)
                    else:
                        raise Exception(f"Failed to fetch URL: {response.status}")
            except (aiohttp.ClientError, asyncio.TimeoutError):
                raise Exception("Network error or timeout")

    def hash_file(self, file_path: str, start_byte: int = 0, length: int = None) -> str:
        if os.path.isfile(file_path):
            with open(file_path, 'rb') as file:
                return self.hash_data(file.read(), start_byte, length)
        else:
            raise Exception("File not found")

    def hash_data(self, data: bytes, start_byte: int = 0, length: int = None) -> str:
        hasher = hashlib.sha256()
        if length is not None:
            data = data[start_byte:start_byte + length]
        hasher.update(data)
        return hasher.hexdigest()

class ExternalLogger:
    def __init__(self, url: str):
        self.url = url

    async def log(self, message: str) -> None:
        try:
            async with aiohttp.ClientSession() as session:
                await session.post(self.url, json={"message": message})
        except (aiohttp.ClientError, asyncio.TimeoutError):
            raise Exception("Failed to log message")

class HasherManager:
    def __init__(self):
        self.file_hasher = FileHasher()
        self.external_logger = ExternalLogger("https://example.com/log")

    async def hash_and_log(self, file_path: str, start_byte: int = 0, length: int = None) -> None:
        try:
            result = await self.file_hasher.hash_file(file_path, start_byte, length)
            await self.external_logger.log(f"Hash of {file_path}: {result}")
        except Exception as e:
            await self.external_logger.log(f"Error: {e}")

# Example usage
manager = HasherManager()
asyncio.run(manager.hash_and_log("https://example.com/large-file.zip", start_byte=0, length=1024))
