#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <atomic>

class ImageProcessor {
public:
    void addImage(const std::string& imageFile) {
        std::lock_guard<std::mutex> lock(mutex_);
        images_.push(imageFile);
        cv_.notify_one();
    }

    void startProcessing() {
        running_ = true;
        for (size_t i = 0; i < numThreads_; ++i) {
            threads_.emplace_back(&ImageProcessor::processImages, this);
        }
    }

    void stopProcessing() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            running_ = false;
        }
        cv_.notify_all();
        for (auto& thread : threads_) {
            thread.join();
        }
    }

private:
    void processImages() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return !running_ || !images_.empty(); });
            if (!running_ && images_.empty()) break;

            std::string imageFile = images_.front();
            images_.pop();
            lock.unlock();

            processImage(imageFile);
        }
    }

    void processImage(const std::string& imageFile) {
        // Image processing logic here
        std::cout << "Processing image: " << imageFile << std::endl;
    }

    std::mutex mutex_;
    std::condition_variable cv_;
    std::queue<std::string> images_;
    std::vector<std::thread> threads_;
    size_t numThreads_ = 4; // Number of worker threads
    std::atomic<bool> running_{false};
};

int main() {
    ImageProcessor processor;
    processor.startProcessing();

    // Simulate adding images to the queue
    for (int i = 0; i < 100; ++i) {
        processor.addImage("image" + std::to_string(i) + ".jpg");
    }

    // Stop processing after a while
    std::this_thread::sleep_for(std::chrono::seconds(5));
    processor.stopProcessing();

    return 0;
}
