class StreamDataCollector {
    constructor(stream) {
        this.stream = stream;
        this.buffer = [];
        this.paused = false;
        this.errorHandler = () => {};
        this.retryDelay = 1000; // 1 second initial delay
        this.maxRetries = 5;
        this.currentRetryCount = 0;

        this.collectData();
    }

    collectData() {
        if (this.paused) return;

        this.stream.on('data', data => {
            this.buffer.push(data);
        });

        this.stream.on('end', () => {
            this.processBuffer();
        });

        this.stream.on('error', error => {
            this.errorHandler(error);
            if (!this.paused && this.currentRetryCount < this.maxRetries) {
                setTimeout(() => {
                    this.currentRetryCount++;
                    this.collectData();
                }, this.retryDelay * Math.pow(2, this.currentRetryCount));
            }
        });
    }

    pause() {
        this.paused = true;
    }

    resume() {
        this.paused = false;
        this.collectData();
    }

    setErrorHandler(handler) {
        this.errorHandler = handler;
    }

    processBuffer() {
        // Implement data processing logic here
        console.log('Processing collected data:', this.buffer);
        this.buffer = [];
    }
}

// Example usage:
const readableStream = /* create your stream */;
