// NetworkServiceManager.cpp
#include "NetworkServiceManager.h"
#include <iostream>

NetworkServiceManager::NetworkServiceManager(int initialPoolSize) : currentPoolSize(initialPoolSize), SLA(99.9) {
    connectionPool.reserve(initialPoolSize);
}

NetworkServiceManager::~NetworkServiceManager() {}

void NetworkServiceManager::addConnection(const std::string& connectionDetails) {
    std::lock_guard<std::mutex> lock(poolMutex);
    if (connectionPool.size() < currentPoolSize * 2) { // Example resizing condition
        connectionPool.push_back(connectionDetails);
        cv.notify_one();
    }
}

void NetworkServiceManager::removeConnection(const std::string& connectionDetails) {
    std::lock_guard<std::mutex> lock(poolMutex);
    auto it = std::find(connectionPool.begin(), connectionPool.end(), connectionDetails);
    if (it != connectionPool.end()) {
        connectionPool.erase(it);
    }
}

void NetworkServiceManager::updateSLA(double newSLA) {
    std::lock_guard<std::mutex> lock(poolMutex);
    SLA = newSLA;
}
