// Define a linked list node using the custom allocator
template <typename T, typename Allocator = std::allocator<T>>
class Node {
public:
    T data;
    Node* next;

    Node(const T& value, Node* n = nullptr) : data(value), next(n) {}
};

// Define a thread-safe linked list class
template <typename T, typename Allocator = HighLoadAllocator>
class ThreadSafeLinkedList {
private:
    std::mutex mutex_;
    Node<T>* head;
    Allocator allocator;

public:
    ThreadSafeLinkedList() : head(nullptr) {}

    ~ThreadSafeLinkedList() {
        clear();
    }

    void push(const T& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        Node<T>* newNode = new (allocator.allocate(sizeof(Node<T>))) Node<T>(value, head);
        head = newNode;
    }

    void pop(T& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (head == nullptr) return;

        Node<T>* temp = head;
        value = temp->data;
        head = temp->next;
        allocator.deallocate(temp, sizeof(Node<T>));
    }

    void clear() {
        while (!empty()) {
            T value;
            pop(value);
        }
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return head == nullptr;
    }
};

