#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

#define MAX_RECORD_SIZE 1024

typedef struct {
    char data[MAX_RECORD_SIZE];
} NetworkRecord;

typedef struct {
    pthread_mutex_t lock;
    int file_fd;
    char* file_path;
} FileHandler;

typedef struct {
    FileHandler file_handler;
    NetworkRecord records[1024];
    int record_count;
} ProcessingQueue;

void* read_file(void* arg) {
    ProcessingQueue* queue = (ProcessingQueue*)arg;
    FileHandler* handler = &queue->file_handler;

    while (1) {
        pthread_mutex_lock(&handler->lock);

        if ((queue->record_count == 0) && 
            (read(handler->file_fd, &queue->records[0], sizeof(NetworkRecord)) != sizeof(NetworkRecord))) {
            pthread_mutex_unlock(&handler->lock);
            break;
        }

        queue->record_count++;

        pthread_mutex_unlock(&handler->lock);
    }

    return NULL;
}

void* process_records(void* arg) {
    ProcessingQueue* queue = (ProcessingQueue*)arg;

    while (1) {
        pthread_mutex_lock(&queue->file_handler.lock);

        if (queue->record_count == 0) {
            pthread_mutex_unlock(&queue->file_handler.lock);
            break;
        }

        NetworkRecord record = queue->records[queue->record_count - 1];
        queue->record_count--;

        pthread_mutex_unlock(&queue->file_handler.lock);

        // Process the record
        printf("Processing record: %s\n", record.data);
    }

    return NULL;
}

int main() {
    ProcessingQueue queue = {{PTHREAD_MUTEX_INITIALIZER, -1, "network_traffic.csv"}, {0}};

    if ((queue.file_handler.file_fd = open(queue.file_handler.file_path, O_RDONLY)) == -1) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    pthread_t read_thread, process_thread;

    if (pthread_create(&read_thread, NULL, read_file, &queue) != 0) {
        perror("Failed to create read thread");
        close(queue.file_handler.file_fd);
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&process_thread, NULL, process_records, &queue) != 0) {
        perror("Failed to create process thread");
        pthread_join(read_thread, NULL);
        close(queue.file_handler.file_fd);
        exit(EXIT_FAILURE);
    }

    pthread_join(read_thread, NULL);
    pthread_join(process_thread, NULL);

    close(queue.file_handler.file_fd);
    return 0;
}
