void* create_and_populate_list(void* arg) {
    // Cast the argument to get N (number of elements)
    int n = *(int*)arg;

    // Allocate memory for the linked list head
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T** current = &head;

    // Populate the linked list with random data or default values
    for (int i = 0; i < n; ++i) {
        *current = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (*current == NULL) {
            // Handle memory allocation failure
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        (*current)->RX_UE_INFORMATION_TAG = rand() % 1000;
        (*current)->RNTI = rand() % 65536;
        (*current)->CRC_INDICATION_REL8_TAG = (rand() % 2 == 0) ? true : false;

        current = &((*current)->next);
    }

    // Return the head of the linked list
    return head;
}

// Function to free the memory allocated for the linked list
void free_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
}

// Function to simulate external API calls with retries and circuit breaker
NFAPI_CRC_INDICATION_PDU_T* call_external_api(NFAPI_CRC_INDICATION_PDU_T* head) {
    // Simulate intermittent failures with exponential backoff and circuit breaker
    int attempts = 0;
    bool is_circuit_breaker_open = false;

    while (attempts < MAX_ATTEMPTS) {
        if (is_circuit_breaker_open) {
            sleep(1 << attempts); // Exponential backoff
        } else {
            // Call the external API and handle errors
            if (api_call_successful(head)) {
                is_circuit_breaker_open = false;
                return head;
            } else {
                attempts++;
                if (attempts == MAX_ATTEMPTS / 2) {
                    is_circuit_breaker_open = true; // Open circuit breaker after half the attempts
                }
            }
        }
    }

    // Handle unrecoverable error
    fprintf(stderr, "Failed to call external API after multiple attempts\n");
    exit(EXIT_FAILURE);
}

// Function to simulate a successful API call
bool api_call_successful(NFAPI_CRC_INDICATION_PDU_T* head) {
    // Simulate random failure
    return (rand() % 2 == 0) ? true : false;
}

// Asynchronous logging function
void log_async(const char* message) {
    // Implement asynchronous logging here
    printf("Log: %s\n", message);
}

