    NFAPI_CRC_INDICATION_PDU_T* head = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (head == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
