typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_linked_list(int n) {
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
