        new_node->rx_ue_info_tag.RNTI = rand() % 1000; // Example random RNTI
        new_node->crc_indication_rel8_tag.CRCFLAG = (rand() % 2 == 0) ? 1 : 0; // Random CRCFLAG
        new_node->next = NULL;

        if (!head) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }
    return head;
}

void free_linked_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    while (head) {
        NFAPI_CRC_INDICATION_PDU_T *temp = head;
        head = head->next;
        free(temp);
    }
}

