```c
// oauth2_token_generator.c
#include "oauth2_token_generator.h"
#include <openssl/sha.h>
#include <openssl/rand.h>

#define SECRET_KEY "your_secret_key_here"

OAuth2Token generate_access_token() {
    OAuth2Token token;
    time_t current_time = time(NULL);
    char input[512];

    // Generate a unique ID using current time and random values
    snprintf(input, sizeof(input), "%ld", current_time);
    RAND_bytes((unsigned char *)input + 16, sizeof(input) - 16);

    // Hash the input to generate a secure token
    SHA256_CTX sha256;
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, input, strlen(input));
    SHA256_Final(hash, &sha256);

    // Convert the hash to a base64 string
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        snprintf(token.access_token + i * 2, 3, "%02x", hash[i]);
    }

    token.expiration_time = current_time + 3600; // Token expires in 1 hour

    return token;
}

int validate_access_token(const OAuth2Token *token) {
    time_t current_time = time(NULL);
    if (current_time > token->expiration_time) {
        return 0; // Token expired
    }
    return 1; // Token valid
}
```

