    def __init__(self):
        self.storage_services = {
            'AWS_S3': AWS_S3,
            'GoogleCloudStorage': GoogleCloudStorage,
            'AzureBlobStorage': AzureBlobStorage
        }

    def add_storage_service(self, name, credentials):
        if name in self.storage_services:
            self.storage_services[name] = self.storage_services[name](**credentials)

    def backup_data(self, data, destination, storage_type):
