#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <curl/curl.h>

#define N 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T array[N];
sem_t lock;

void* create_and_populate_array(void* arg) {
    for (int i = 0; i < N; i++) {
        sem_wait(&lock);
        // Populate the structure with valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
        array[i].RX_UE_INFORMATION_TAG = i;
        array[i].RNTI = i * 2;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
        sem_post(&lock);
    }
    return NULL;
}

void* interface_with_api(void* arg) {
    CURL* curl;
    CURLcode res;

    for (int i = 0; i < N; i++) {
        sem_wait(&lock);
        // Interact with the external REST API
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if(curl) {
            curl_easy_setopt(curl, CURLOPT_URL, "http://api.example.com/data");
            res = curl_easy_perform(curl);
            if(res != CURLE_OK)
                fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            curl_easy_cleanup(curl);
        }
        sem_post(&lock);
    }

    curl_global_cleanup();
    return NULL;
}

int main() {
    pthread_t thread1, thread2;

    sem_init(&lock, 0, 1);

    // Create and populate array
    pthread_create(&thread1, NULL, create_and_populate_array, NULL);

    // Interface with API
    pthread_create(&thread2, NULL, interface_with_api, NULL);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    sem_destroy(&lock);

    return 0;
}
```

