#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    void (*log_debug)(const char* message);
    int (*network_check)(const char* service_url);
    int (*storage_store)(const char* data, size_t length);
    int (*storage_retrieve)(const char* key, char** data, size_t* length);
    int (*scheduler_execute)(int task_id, time_t execution_time, const char* timezone);
} SystemConfig;

typedef enum {
    INIT_SUCCESS = 0,
    INIT_LOGGER_ERROR = -1,
    INIT_NETWORK_ERROR = -2,
    INIT_STORAGE_ERROR = -3,
    INIT_SCHEDULER_ERROR = -4
} InitializationStatus;

int init_system(SystemConfig* config) {
    if (config == NULL || 
        config->log_debug == NULL || 
        config->network_check == NULL || 
        config->storage_store == NULL || 
        config->storage_retrieve == NULL || 
        config->scheduler_execute == NULL) {
        return INIT_LOGGER_ERROR;
    }

    // Asynchronous logging
    pthread_t log_thread;
    if (pthread_create(&log_thread, NULL, (void*)config->log_debug, "System initialized") != 0) {
        return INIT_LOGGER_ERROR;
    }
    pthread_detach(log_thread);

    // Network health checks with retry logic and rate-limiting
    int max_attempts = 5;
    for (int attempt = 1; attempt <= max_attempts; ++attempt) {
        if (config->network_check("service_url") == 0) {
            break;
        }
        if (attempt == max_attempts) {
            return INIT_NETWORK_ERROR;
        }
        // Exponential backoff
        usleep((1 << attempt) * 100000);
    }

    // Storage operations with checksum validation
    char* data = "test_data";
    size_t length = strlen(data);
    if (config->storage_store(data, length) != 0) {
        return INIT_STORAGE_ERROR;
    }
    char* retrieved_data;
    size_t retrieved_length;
    if (config->storage_retrieve("test_key", &retrieved_data, &retrieved_length) != 0 || 
        strcmp(retrieved_data, data) != 0) {
        free(retrieved_data);
        return INIT_STORAGE_ERROR;
    }
    free(retrieved_data);

    // Scheduler execution and auto-scaling
    if (config->scheduler_execute(1, time(NULL), "UTC") != 0 ||
        config->scheduler_execute(2, time(NULL), "EST") != 0) {
        return INIT_SCHEDULER_ERROR;
    }

    // Set readiness flag and provide metrics
    printf("System initialized successfully.\n");

    return INIT_SUCCESS;
}

// Example usage:
int main() {
    SystemConfig config = {
        .log_debug = log_message,
        .network_check = check_network_service,
        .storage_store = store_data,
        .storage_retrieve = retrieve_data,
        .scheduler_execute = execute_task
    };

    int status = init_system(&config);
    if (status != INIT_SUCCESS) {
        printf("Initialization failed with error code: %d\n", status);
    }

    return 0;
}
```

This code snippet defines a function `init_system` that takes a pointer to a `SystemConfig` structure as input and initializes the system's operational readiness. It checks each service for initialization and performs specific operations like asynchronous logging, network health checks with retry logic, storage operations with checksum validation, and scheduler execution. Error handling is included to return detailed error codes in case of failures. The example usage demonstrates how to call this function with a configuration structure.']

