using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class WeatherService
{
    private readonly HttpClient _httpClient;
    private readonly string[] _apiKeys;
    private static readonly Dictionary<string, DateTime> _cache = new Dictionary<string, DateTime>();
    private static readonly object _lock = new object();

    public WeatherService(string[] apiKeys)
    {
        _httpClient = new HttpClient();
        _apiKeys = apiKeys;
    }

    public async Task<WeatherData> GetWeatherAsync(string location)
    {
        lock (_lock)
        {
            if (_cache.ContainsKey(location) && DateTime.Now < _cache[location])
                return await FetchFromCacheAsync(location);
        }

        var weatherData = await FetchFromApiAsync(location);
        lock (_lock)
        {
            _cache[location] = DateTime.UtcNow.AddSeconds(60); // Cache for 1 minute
        }
        return weatherData;
    }

    private async Task<WeatherData> FetchFromCacheAsync(string location)
    {
        var json = await File.ReadAllTextAsync($"{location}.json");
        return JsonConvert.DeserializeObject<WeatherData>(json);
    }

    private async Task<WeatherData> FetchFromApiAsync(string location)
    {
        var apiKey = _apiKeys[new Random().Next(_apiKeys.Length)];
        var response = await _httpClient.GetAsync($"https://api.weather.com/data?location={location}&key={apiKey}");
        if (!response.IsSuccessStatusCode)
            throw new Exception("Failed to fetch weather data");

        var json = await response.Content.ReadAsStringAsync();
        return JsonConvert.DeserializeObject<WeatherData>(json);
    }
}

public class WeatherData
{
    public double Temperature { get; set; }
    public int Humidity { get; set; }
    public double WindSpeed { get; set; }
    public double Precipitation { get; set; }
}

public class GreenhouseController
{
    private readonly WeatherService _weatherService;

    public GreenhouseController(WeatherService weatherService)
    {
        _weatherService = weatherService;
    }

    public async Task OptimizePlantGrowthAsync(string location)
    {
        var weatherData = await _weatherService.GetWeatherAsync(location);
        // Logic to optimize plant growth based on weather data
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        var apiKeys = new[] { "apiKey1", "apiKey2" };
        var weatherService = new WeatherService(apiKeys);
        var greenhouseController = new GreenhouseController(weatherService);

        await greenhouseController.OptimizePlantGrowthAsync("New York");
    }
}
