<?php

class OAuth2TokenGenerator {
    private $consulClient;
    private $logger;

    public function __construct($consulConfig, $logFile) {
        $this->consulClient = new ConsulClient($consulConfig);
        $this->logger = new Logger($logFile);
    }

    public function generateAccessToken($userId, $scopes) {
        try {
            $tokenData = [
                'user_id' => $userId,
                'scopes' => $scopes,
                'expiry_time' => time() + 3600 // Token expires in 1 hour
            ];

            $consulConfig = $this->consulClient->getOAuth2Config();
            $tokenKey = hash('sha256', $userId . $scopes);

            if ($this->consulClient->isConnected()) {
                $this->consulClient->storeToken($tokenKey, $tokenData);
            } else {
                // Fallback mechanism using local cache
                file_put_contents('/tmp/oauth_tokens/' . $tokenKey, json_encode($tokenData));
            }

            return [
                'access_token' => base64_encode(json_encode($tokenData)),
                'expires_in' => 3600
            ];
        } catch (Exception $e) {
            $this->logger->logError('Token generation failed: ' . $e->getMessage());
            throw $e;
        }
    }

    public function validateAccessToken($token) {
        try {
            $decodedToken = json_decode(base64_decode($token), true);
            if (time() > $decodedToken['expiry_time']) {
                return false;
            }

            $consulConfig = $this->consulClient->getOAuth2Config();
            $tokenKey = hash('sha256', $decodedToken['user_id'] . implode(',', $decodedToken['scopes']));
            if ($this->consulClient->isConnected()) {
                return $this->consulClient->getToken($tokenKey) === json_encode($decodedToken);
            } else {
                // Fallback mechanism using local cache
                $localToken = file_get_contents('/tmp/oauth_tokens/' . $tokenKey);
                return $localToken !== false && $localToken === json_encode($decodedToken);
            }
        } catch (Exception $e) {
            $this->logger->logError('Token validation failed: ' . $e->getMessage());
            return false;
        }
    }
}

class ConsulClient {
    private $config;
    private $client;

    public function __construct($config) {
        $this->config = $config;
        $this->client = new \ConsulAPI\Client($config);
    }

    public function isConnected() {
        try {
            $status = $this->client->Agent()->NodeName();
            return !empty($status);
        } catch (\Exception $e) {
            return false;
        }
    }

    public function getOAuth2Config() {
        if ($this->isConnected()) {
            $config = $this->client->KV()->Get('oauth2/config', []);
            return $config ? json_decode(base64_decode($config['Value']), true) : [];
        } else {
            // Fallback mechanism using local cache
            return json_decode(file_get_contents('/tmp/oauth2_config.json'), true);
        }
    }

    public function storeToken($tokenKey, $tokenData) {
        if ($this->isConnected()) {
            $this->client->KV()->Put(['Key' => $tokenKey, 'Value' => base64_encode(json_encode($tokenData))], []);
        } else {
            // Fallback mechanism using local cache
            file_put_contents('/tmp/oauth_tokens/' . $tokenKey, json_encode($tokenData));
        }
    }

    public function getToken($tokenKey) {
        if ($this->isConnected()) {
            $token = $this->client->KV()->Get($tokenKey, []);
            return $token ? base64_decode($token['Value']) : null;
        } else {
            // Fallback mechanism using local cache
            return file_get_contents('/tmp/oauth_tokens/' . $tokenKey);
        }
    }
}

class Logger {
    private $file;

    public function __construct($file) {
        $this->file = $file;
    }

    public function logError($message) {
        error_log(date('Y-m-d H:i:s') . ' - ERROR: ' . $message, 3, $this->file);
    }
}

// Example usage:
$consulConfig = ['Address' => 'http://localhost:8500'];
$logFile = '/var/log/oauth2.log';
$tokenGenerator = new OAuth2TokenGenerator($consulConfig, $logFile);

$accessToken = $tokenGenerator->generateAccessToken('user123', ['read', 'write']);
$isValid = $tokenGenerator->validateAccessToken($accessToken['access_token']);

echo "Access Token: " . json_encode($accessToken) . "\n";
echo "Token Valid: " . ($isValid ? 'true' : 'false') . "\n";

?>
