import threading

class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG):
        self.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG
        self.RNTI = RNTI
        self.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG
        self.CRCFLAG = CRCFLAG

class MemoryPool:
    def __init__(self, size, block_size):
        self.pool = bytearray(size * block_size)
        self.size = size
        self.block_size = block_size
        self.count = 0
        self.lock = threading.Lock()

    def alloc(self):
        with self.lock:
            if self.count < self.size:
                block = self.pool[self.block_size * self.count:self.block_size * (self.count + 1)]
                self.count += 1
            else:
                # Handle allocation failure
                block = None
            return block

    def free(self, block):
        with self.lock:
            index = (block - self.pool) // self.block_size
            if index >= self.count or index < 0:
                # Handle invalid free
            else:
                self.count -= 1

    def destroy(self):
        self.pool = None
