typedef struct WorkerPool {
    pthread_t* workers;
    size_t capacity;
    sem_t not_full;
    sem_t not_empty;
} WorkerPool;

WorkerPool* create_worker_pool(size_t capacity) {
    WorkerPool* pool = (WorkerPool*)malloc(sizeof(WorkerPool));
    pool->workers = (pthread_t*)malloc(capacity * sizeof(pthread_t));
    pool->capacity = capacity;
    sem_init(&pool->not_full, 0, capacity);
    sem_init(&pool->not_empty, 0, 0);
    return pool;
}

void enqueue_worker_pool(WorkerPool* pool, void (*task_func)(void*), void* arg) {
    sem_wait(&pool->not_full);
    pthread_create(pool->workers + (pool->capacity - pool->count - 1), NULL, (void *(*)(void*))task_func, arg);
    sem_post(&pool->not_empty);
}

void wait_for_worker_pool(WorkerPool* pool) {
    while (sem_getvalue(&pool->not_full, NULL) != pool->capacity) {
        // Wait for all workers to complete
        sleep(1);
    }
}

void destroy_worker_pool(WorkerPool* pool) {
    free(pool->workers);
    sem_destroy(&pool->not_full);
    sem_destroy(&pool->not_empty);
    free(pool);
}
