import threading

class ThreadSafeMemoryPool:
    def __init__(self, capacity, block_size):
        self.capacity = capacity
        self.block_size = block_size
        self.pool = bytearray(capacity * block_size)
        self.free_list = list(range(capacity))
        self.lock = threading.Lock()

    def alloc(self):
        with self.lock:
            if not self.free_list:
                # Handle no available blocks
                return None
            index = self.free_list.pop()
        return (self.pool[index * self.block_size:(index + 1) * self.block_size], index)

    def free(self, block, index):
        with self.lock:
            self.pool[index * self.block_size:(index + 1) * self.block_size] = bytearray(block)
            self.free_list.append(index)

    def destroy(self):
        pass
