        element = queue->elements[queue->front];
        queue->front = (queue->front + 1) % queue->capacity;
        queue->count--;
    } else {
        // Handle empty queue
        element = NFAPI_CRC_INDICATION_PDU_T(); // Return a default value or handle the error
    }
    pthread_mutex_unlock(&queue->lock);
    sem_post(&stack->not_full);
    return element;
}

void destroy_thread_safe_queue_with_size_and_capacity(ThreadSafeQueueWithSizeAndCapacity* queue) {
    free(queue->elements);
    pthread_mutex_destroy(&queue->lock);
    sem_destroy(&queue->not_full);
    sem_destroy(&queue->not_empty);
    free(queue);
}
