class ThreadSafeStackWithSizeAndCapacity:
    def __init__(self, capacity):
        self.capacity = capacity
        self.stack = [None] * capacity
        self.count = 0
        self.lock = threading.Lock()

    def push(self, element):
        with self.lock:
            if self.count < self.capacity:
                self.stack[self.count] = element
                self.count += 1
            else:
                # Handle no available space
                pass

    def pop(self):
        with self.lock:
            if self.count > 0:
                self.count -= 1
                return self.stack[self.count]
            else:
                # Handle empty stack
                return None # Return a default value or handle the error

