using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;

public class WeatherDataFetcher
{
    private readonly ConcurrentDictionary<string, HttpClient> _clients = new();
    private readonly string[] _apiEndpoints =
    {
        "https://api.weatherapi.com/v1/current.json?key=your_api_key&q=London",
        "https://api.openweathermap.org/data/2.5/weather?q=New York&appid=your_api_key"
    };

    public async Task<WeatherData> FetchWeatherAsync()
    {
        var tasks = _apiEndpoints.Select(endpoint => FetchFromApiAsync(endpoint)).ToArray();
        var results = await Task.WhenAll(tasks);

        return MergeWeatherData(results);
    }

    private async Task<WeatherData> FetchFromApiAsync(string endpoint)
    {
        using (var client = _clients.GetOrAdd(endpoint, key => new HttpClient()))
        {
            try
            {
                var response = await client.GetAsync(endpoint, HttpCompletionOption.ResponseHeadersRead);
                response.EnsureSuccessStatusCode();
                return JsonSerializer.Deserialize<WeatherData>(await response.Content.ReadAsStringAsync());
            }
            catch (HttpRequestException ex)
            {
                Console.WriteLine($"Error fetching weather data from {endpoint}: {ex.Message}");
                throw;
            }
        }
    }

    private WeatherData MergeWeatherData(WeatherData[] results)
    {
        var merged = new WeatherData
        {
            Temperature = Math.Ceiling((results.Select(r => r.Temperature).Average() * 9 / 5) + 32),
            Humidity = (int)Math.Round(results.Average(r => r.Humidity)),
            WindSpeed = Math.Ceiling(results.Average(r => r.WindSpeed)),
            PrecipitationLevel = results.Max(r => r.PrecipitationLevel)
        };
        return merged;
    }
}

public class WeatherData
{
    public double Temperature { get; set; }
    public int Humidity { get; set; }
    public double WindSpeed { get; set; }
    public double PrecipitationLevel { get; set; }
}
