import java.io.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.Properties;

public class StateManager {
    private static final ConcurrentHashMap<String, Object> cache = new ConcurrentHashMap<>();
    private static Properties config = new Properties();

    static {
        loadConfig();
    }

    public static void loadState(String key) throws IOException, ClassNotFoundException {
        String filePath = getFilePath(key);
        if (cache.containsKey(key)) {
            return;
        }
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            cache.put(key, ois.readObject());
        } catch (FileNotFoundException e) {
            handleFileNotFound(key, filePath);
        }
    }

    public static void unloadState(String key) {
        cache.remove(key);
    }

    public static Object getState(String key) {
        return cache.get(key);
    }

    private static String getFilePath(String key) {
        // Implement dynamic file path resolution based on runtime environment variables
        return config.getProperty("state.file.path") + "/" + key;
    }

    private static void loadConfig() {
        try (InputStream is = StateManager.class.getClassLoader().getResourceAsStream("config.properties")) {
            if (is != null) {
                config.load(is);
            } else {
                throw new IllegalArgumentException("Configuration file not found");
            }
        } catch (IOException e) {
            throw new RuntimeException("Failed to load configuration", e);
        }
    }

    private static void handleFileNotFound(String key, String filePath) {
        // Implement fallback strategy and logging for corrupted or incompatible state objects
        System.err.println("State object not found at: " + filePath);
        cache.put(key, null); // Optionally provide a default value or throw an exception
    }
}
