void* process_file(void* arg) {
    int index = *(int*)arg;
    pthread_mutex_lock(&mutex);
    if (index < file_count && files[index].is_validated == 0) {
        // Simulate file processing and validation
        printf("Processing file: %s\n", files[index].file_path);
        sleep(1); // Simulate processing time
        files[index].is_validated = 1;
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void* read_files(void* arg) {
    int dir_index = *(int*)arg;
    while (1) {
        // Simulate reading files from a directory
        for (int i = 0; i < MAX_CONCURRENT_FILES; i++) {
            pthread_mutex_lock(&mutex);
            if (file_count < MAX_CONCURRENT_FILES && index_of_next_file_to_process() != -1) {
                files[file_count].file_path = get_next_file_path();
                file_count++;
            }
            pthread_mutex_unlock(&mutex);

            if (file_count == 0) {
                sleep(1); // No files to process
            } else {
                pthread_t thread;
                int *arg = malloc(sizeof(int));
                *arg = index_of_next_file_to_process();
                pthread_create(&thread, NULL, process_file, arg);
                pthread_detach(thread);
            }
        }
    }
}

int main() {
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < MAX_DIRS; i++) {
        pthread_t thread;
        int *arg = malloc(sizeof(int));
        *arg = i;
        pthread_create(&thread, NULL, read_files, arg);
        pthread_detach(thread);
    }

    // Main loop to keep the service running
    while (1) {
        sleep(1); // Keep the main thread alive
    }

    pthread_mutex_destroy(&mutex);
    return 0;
}
