#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

// Define the NFAPI CRC INDICATION PDU structure
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node in the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the linked list structure
typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} LinkedList;

// Initialize the linked list
void initLinkedList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

// Add a PDU to the linked list
bool addPDU(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }
    newNode->data = pdu;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

// Generate up to N PDUs and add them to the linked list
bool generateAndAddPDUs(LinkedList* list, int N) {
    if (N < 0) {
        printf("Error: Invalid number of PDUs\n");
        return false;
    }
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // Generate random values for the PDU
        // Verify CRC against a pre-defined polynomial with a specified seed value
        if (!addPDU(list, pdu)) {
            printf("Error: Failed to add PDU to list\n");
            return false;
        }
    }
    return true;
}

// Serialize the linked list to a binary file
bool serializeList(LinkedList* list, const char* filename) {
    pthread_mutex_lock(&list->mutex);
    FILE* file = fopen(filename, "wb");
    if (!file) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }
    Node* current = list->head;
    while (current) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    fclose(file);
    pthread_mutex_unlock(&list->mutex);
    return true;
}

// Deserialize the linked list from a binary file
bool deserializeList(LinkedList* list, const char* filename) {
    pthread_mutex_lock(&list->mutex);
    FILE* file = fopen(filename, "rb");
    if (!file) {
        pthread_mutex_unlock(&list->mutex);
        return false;
    }
    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        addPDU(list, pdu);
    }
    fclose(file);
    pthread_mutex_unlock(&list->mutex);
    return true;
}

// Clean up the linked list
void cleanupLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
}

// Example usage
int main() {
    LinkedList list;
    initLinkedList(&list);

    int N = 100; // Number of PDUs to generate
    if (!generateAndAddPDUs(&list, N)) {
        printf("Failed to generate and add PDUs\n");
        cleanupLinkedList(&list);
        return 1;
    }

    if (!serializeList(&list, "pdus.bin")) {
        printf("Failed to serialize list\n");
        cleanupLinkedList(&list);
        return 1;
    }

    LinkedList new_list;
    initLinkedList(&new_list);

    if (!deserializeList(&new_list, "pdus.bin")) {
        printf("Failed to deserialize list\n");
        cleanupLinkedList(&new_list);
        return 1;
    }

    cleanupLinkedList(&list);
    cleanupLinkedList(&new_list);
    return 0;
}
