#include <iostream>
#include <vector>
#include <mutex>
#include <random>

struct LTE_ENB_MME_MESSAGE {
    std::string IMSI;
    int MME_ID;
    int EPS_BEARER_ID;
    struct ENB_STATUS {
        int STATUS_CODE;
        int REASON_CODE;
    } status;
};

class MessageManager {
private:
    static constexpr int MAX_MESSAGES = 1000000; // Up to 1M messages
    std::vector<LTE_ENB_MME_MESSAGE> messages;
    std::mutex mtx;

public:
    void addMessage(const LTE_ENB_MME_MESSAGE& msg) {
        std::lock_guard<std::mutex> lock(mtx);
        if (messages.size() < MAX_MESSAGES) {
            messages.push_back(msg);
        }
    }

    LTE_ENB_MME_MESSAGE* getMessage(int index) {
        std::lock_guard<std::mutex> lock(mtx);
        if (index >= 0 && index < messages.size()) {
            return &messages[index];
        }
        return nullptr;
    }

    void removeMessage(int index) {
        std::lock_guard<std::mutex> lock(mtx);
        if (index >= 0 && index < messages.size()) {
            messages.erase(messages.begin() + index);
        }
    }
};

int main() {
    MessageManager manager;
    LTE_ENB_MME_MESSAGE msg = {"1234567890", 1, 101, {1, 2}};
    manager.addMessage(msg);

    LTE_ENB_MME_MESSAGE* retrievedMsg = manager.getMessage(0);
    if (retrievedMsg) {
        std::cout << "Retrieved Message: IMSI=" << retrievedMsg->IMSI 
                  << ", MME_ID=" << retrievedMsg->MME_ID 
                  << ", EPS_BEARER_ID=" << retrievedMsg->EPS_BEARER_ID 
                  << ", STATUS_CODE=" << retrievedMsg->status.STATUS_CODE
                  << ", REASON_CODE=" << retrievedMsg->status.REASON_CODE << std::endl;
    }

    manager.removeMessage(0);

    return 0;
}
