int list_size = 0;

// Mutex for thread-safe access
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Circuit breaker state
typedef enum {
    CLOSED,
    OPEN,
    HALF_OPEN
} CircuitBreakerState;

CircuitBreakerState cb_state = CLOSED;
time_t cb_open_time = 0;

// Error logging function
void logError(const char *message, int errorCode) {
    // Asynchronous logging implementation here
}

// Function to populate the list with data from external API
int populateList() {
    pthread_mutex_lock(&lock);
    if (list_size >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&lock);
        return -1; // List is full
    }

    int tag = rand();
    int rnti;
    int crcFlag;

    while (getUEInformation(tag, &rnti) != 0) {
        if (cb_state == OPEN) {
            pthread_mutex_unlock(&lock);
            return -1; // API is unavailable
        }

        // Retry with exponential backoff and circuit breaker pattern
        sleep(1); // Simplified for example

        // Check circuit breaker state again after retry
        if (time(NULL) - cb_open_time > 60) {
            cb_state = CLOSED;
        }
    }

    crcFlag = rand() % 2; // Randomly set CRC flag

    list[list_size].RX_UE_INFORMATION_TAG = tag;
    list[list_size].RNTI = rnti;
    list[list_size].CRC_INDICATION_REL8_TAG = crcFlag;
    list_size++;

    pthread_mutex_unlock(&lock);
    return 0;
}

// Function to send the list using the external API
int sendList() {
    if (list_size == 0) {
        return -1; // List is empty
    }

    int result = sendJSONList(list, list_size);
    if (result != 0) {
        logError("Failed to send JSON list", result);
        cb_state = OPEN;
        cb_open_time = time(NULL);
    }

    pthread_mutex_lock(&lock);
    memset(list, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list_size);
    list_size = 0;
    pthread_mutex_unlock(&lock);

    return result;
}

// Function to create and populate the linked list
int createAndPopulateList(int numElements) {
    if (numElements > MAX_ELEMENTS) {
        return -1; // Too many elements requested
    }

    list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * numElements);
    if (!list) {
        logError("Memory allocation failed", -2);
        return -2;
    }

    int successfulCreations = 0;
    int failedCreations = 0;

    for (int i = 0; i < numElements; i++) {
        if (populateList() == 0) {
            successfulCreations++;
        } else {
            failedCreations++;
        }

        // Check if list is full and send
        if (list_size >= numElements / 10) {
            int result = sendList();
            if (result != 0) {
                logError("Failed to send JSON list after partial creation", result);
            }
        }
    }

    if (list_size > 0) {
        sendList();
    }

    logError("Successfully created and sent list", successfulCreations - failedCreations);

    free(list);
    return 0;
}

// Main function to demonstrate usage
