    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to create and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
void* create_and_populate_list(int N) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = NULL;

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&mutex);
        NFAPI_CRC_INDICATION_PDU_T* new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_node == NULL) {
            printf("Memory allocation failed\n");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        new_node->RX_UE_INFORMATION_TAG = i; // Example value
        new_node->RNTI = i * 10; // Example value
        new_node->CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG

        if (head == NULL) {
            head = new_node;
            current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
        pthread_mutex_unlock(&mutex);
    }

    return (void*)head;
}

// Function to free the linked list
void free_list(void* list) {
    NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)list;
    while (node != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next_node = node->next;
        free(node);
        node = next_node;
    }
}

int main() {
    int N = 1000; // Number of elements in the linked list
    void* list = create_and_populate_list(N);

    if (list != NULL) {
        printf("Linked list created and populated successfully\n");
        free_list(list);
    } else {
        printf("Failed to create and populate linked list\n");
    }

    return 0;
}
