const axios = require('axios');
const Ajv = require('ajv');
const { promisify } = require('util');

const ajv = new Ajv();
const validateSchema = promisify(ajv.compile);

class ConfigService {
  constructor(apiUrl, defaultConfig) {
    this.apiUrl = apiUrl;
    this.defaultConfig = defaultConfig;
    this.configCache = {};
    this.validationSchemas = {};
  }

  async fetchConfig(environment) {
    try {
      const response = await axios.get(`${this.apiUrl}/${environment}`);
      return response.data;
    } catch (error) {
      console.error(`Failed to fetch config for environment ${environment}:`, error);
      throw error;
    }
  }

  async validateConfig(config, schemaKey) {
    if (!this.validationSchemas[schemaKey]) {
      const schemaResponse = await axios.get(`${this.apiUrl}/schemas/${schemaKey}`);
      this.validationSchemas[schemaKey] = await validateSchema(schemaResponse.data);
    }

    const isValid = this.validationSchemas[schemaKey](config);
    if (!isValid) {
      console.error('Validation error:', this.validationSchemas[schemaKey].errors);
      throw new Error('Configuration does not meet validation requirements');
    }
  }

  async resolveCircularReferences(config, path = []) {
    return Object.fromEntries(
      await Promise.all(Object.entries(config).map(async ([key, value]) => {
        if (typeof value === 'object' && value !== null) {
          const newPath = [...path, key];
          if (newPath.includes(key)) {
            console.warn(`Circular reference detected at ${newPath.join('.')}`);
            return [key, {}]; // or throw an error based on your requirement
          }
          return [key, await this.resolveCircularReferences(value, newPath)];
        }
        return [key, value];
      }))
    );
  }

  async getConfigWithDefaults(environment) {
    let config = await this.fetchConfig(environment);
    config = { ...this.defaultConfig, ...config };
    config = await this.resolveCircularReferences(config);
    await this.validateConfig(config, 'defaultSchema'); // Assuming 'defaultSchema' is the key for default schema
    return config;
  }

  async updateValidationSchema(schemaKey, schema) {
    const response = await axios.put(`${this.apiUrl}/schemas/${schemaKey}`, schema);
    this.validationSchemas[schemaKey] = await validateSchema(response.data);
    console.log(`Validation schema updated for ${schemaKey}`);
  }
}

// Usage
const configService = new ConfigService('https://api.config.com', { defaultSetting: 'default' });
configService.getConfigWithDefaults('production').then(config => {
  console.log('Loaded config:', config);
}).catch(error => {
  console.error('Failed to load config:', error);
});
