const backoffStrategy = { initialDelay: 1000, maxDelay: 60000 };

app.use(express.json());

async function fetchConfig() {
    try {
        const response = await axios.get(apiURL);
        return response.data;
    } catch (error) {
        console.error('Error fetching config:', error);
        throw error;
    }
}

async function applyConfig(config) {
    // Logic to dynamically load and execute JavaScript modules
    console.log('Applying new config:', config);
    // ...
}

async function updateConfig() {
    try {
        const config = await fetchConfig();
        await client.setAsync(configCacheKey, JSON.stringify(config));
        await applyConfig(config);
    } catch (error) {
        setTimeout(updateConfig, backoffStrategy.initialDelay);
    }
}

app.get('/status', async (req, res) => {
