        "data_sources": ["source1", "source2"],
        "processors": {"type1": Processor1(), "type2": Processor2()}
    }
    processor = RealtimeDataProcessor(config)
    for source_config in config["data_sources"]:
        source = DataSource(source_config)
        processor.add_data_source(source)

    for data_type, processor in config["processors"].items():
        processor = DataProcessor(processor)
        processor.add_processor(data_type, processor)

    processor.start_processing()
