typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

Node* create_node(int rx_tag, int rnti, int crc_flag) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    new_node->data.RX_UE_INFORMATION_TAG = rx_tag;
    new_node->data.RNTI = rnti;
    new_node->data.CRC_INDICATION_REL8_TAG = crc_flag;
    new_node->next = NULL;
    return new_node;
}

Node* create_linked_list(int N) {
    Node* head = NULL;
    for (int i = 0; i < N; i++) {
        int rx_tag = rand() % 1000; // Random RX_UE_INFORMATION_TAG
        int rnti = rand() % 256;   // Random RNTI
        int crc_flag = rand() % 2; // Random CRC_INDICATION_REL8_TAG
        Node* new_node = create_node(rx_tag, rnti, crc_flag);
        if (new_node == NULL) {
            // Handle memory allocation failure
            while (head != NULL) {
                Node* temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }
        new_node->next = head;
        head = new_node;
    }
    return head;
}

int main() {
    srand(time(NULL));
    int N = 10; // Number of elements in the linked list
    Node* list_head = create_linked_list(N);
    if (list_head != NULL) {
        // Use the linked list as needed
        while (list_head != NULL) {
            printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n",
                   list_head->data.RX_UE_INFORMATION_TAG,
                   list_head->data.RNTI,
                   list_head->data.CRC_INDICATION_REL8_TAG);
            Node* temp = list_head;
            list_head = list_head->next;
            free(temp);
        }
    } else {
        // Handle failure
    }
    return 0;
}
