typedef struct {
    const char *name;
    EVP_MD *(*impl)();
} CryptoFunction;

// Function to get available hash functions and block ciphers
CryptoFunction* getAvailableCryptos(int *count) {
    // Array of cryptographic functions (hashes and ciphers)
    static CryptoFunction cryptos[] = {
        {"MD5", EVP_md5},
        {"SHA1", EVP_sha1},
        {"SHA256", EVP_sha256},
        {"AES-128-CBC", EVP_aes_128_cbc}
    };

    // Set the count of available cryptos
    *count = sizeof(cryptos) / sizeof(cryptos[0]);

    // Return the array of cryptos
    return cryptos;
}

// Example usage
int main() {
    int count;
    CryptoFunction *cryptos = getAvailableCryptos(&count);

    printf("Available cryptographic functions:\n");
    for (int i = 0; i < count; i++) {
        printf("%s\n", cryptos[i].name);
    }

    return 0;
}
