        for (int i = 0; i < NUM_UEs; ++i) {
            NFAPI_CRC_INDICATION_PDU_T indication;
            indication.ue_info_tag = generateUEInformationTag(i);
            indication.rnti = generateRNTI();
            indication.crc_indication = generateCRCIndication();

            indications.push_back(indication);
        }

        return indications;
    }

private:
