    RX_UE_INFORMATION_TAG generateUEInformationTag(int ue_id) {
        // Generate a unique UE information tag for each user equipment
        RX_UE_INFORMATION_TAG tag;
        // Logic to populate the tag with unique values based on ue_id
        return tag;
    }

    RNTI generateRNTI() {
        // Generate a random RNTI (Radio Network Temporary Identifier)
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_int_distribution<> dis(0, 65535);
        return static_cast<RNTI>(dis(gen));
    }

    CRC_INDICATION_REL8_TAG generateCRCIndication() {
        // Generate a random CRC indication for the UE
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_int_distribution<> dis(0, 1);
        return static_cast<CRC_INDICATION_REL8_TAG>(dis(gen));
