<?php

use Firebase\JWT\JWT;

function authenticateUser($clientId, $clientSecret) {
    $url = "https://oauth.example.com/token";
    $data = [
        'grant_type' => 'client_credentials',
        'client_id' => $clientId,
        'client_secret' => $clientSecret
    ];

    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $url);
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($data));
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

    $response = curl_exec($ch);
    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);

    if ($httpCode == 200) {
        $tokenData = json_decode($response, true);
        return JWT::decode($tokenData['access_token'], $clientSecret, ['HS256']);
    } else {
        throw new Exception("Authentication failed", 401);
    }
}

function getUserInfo($jwtToken, $userEndpoint) {
    $headers = [
        'Authorization: Bearer ' . JWT::decode($jwtToken)
    ];

    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $userEndpoint);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);

    $response = curl_exec($ch);
    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);

    if ($httpCode == 200) {
        return json_decode($response, true);
    } else {
        throw new Exception("Failed to retrieve user information", 404);
    }
}
?>
