using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace EncryptionApp
{
    public class DecryptionService
    {
        private readonly ConcurrentDictionary<string, (byte[], byte[])> _cache = new();
        private readonly HttpClient _httpClient;
        private readonly string _encryptionServiceUrl;

        public DecryptionService(string encryptionServiceUrl)
        {
            _encryptionServiceUrl = encryptionServiceUrl;
            _httpClient = new HttpClient();
        }

        public async Task<byte[]> DecryptAsync(string base64Message, CancellationToken cancellationToken = default)
        {
            if (_cache.TryGetValue(base64Message, out var cachedValues))
                return TripleDES.Create().Decrypt(cachedValues.Item1, cachedValues.Item2);

            var response = await _httpClient.GetAsync($"{_encryptionServiceUrl}/decrypt?message={base64Message}", cancellationToken);
            if (response.IsSuccessStatusCode)
            {
                var decryptionParams = await response.Content.ReadAsStringAsync();
                var (key, iv) = ParseDecryptionParameters(decryptionParams);
                _cache.TryAdd(base64Message, (key, iv));
                return TripleDES.Create().Decrypt(key, iv);
            }

            throw new Exception("Failed to decrypt message from service.");
        }

        private (byte[], byte[]) ParseDecryptionParameters(string decryptionParams)
        {
            // Implement parsing logic here
            var parts = decryptionParams.Split(',');
            var key = Convert.FromBase64String(parts[0]);
            var iv = Convert.FromBase64String(parts[1]);
            return (key, iv);
        }
    }

    public class Program
    {
        static async Task Main(string[] args)
        {
            var decryptionService = new DecryptionService("https://api.example.com/decrypt");
            var messages = new List<string> { "base64EncodedMessage1", "base64EncodedMessage2" };

            var tasks = messages.Select(message => decryptionService.DecryptAsync(message)).ToList();
            var results = await Task.WhenAll(tasks);

            foreach (var result in results)
            {
                // Process decrypted data
                Console.WriteLine(Encoding.UTF8.GetString(result));
            }
        }
    }
}
