use clap::{App, Arg};
use tokio::sync::mpsc;
use reqwest::Client;
use std::time::Duration;
use md5::{Md5, Digest};
use futures::stream::FuturesUnordered;

#[derive(Debug)]
enum ProcessingType {
    GenerateMD5,
    FilterData,
}

async fn fetch_user_data(url: &str) -> Result<String, reqwest::Error> {
    Client::new()
        .get(url)
        .send()
        .await?
        .text()
        .await
}

async fn process_data(data: String, processing_type: ProcessingType) -> Result<String, Box<dyn std::error::Error>> {
    match processing_type {
        ProcessingType::GenerateMD5 => {
            let mut hasher = Md5::new();
            hasher.update(data);
            Ok(format!("{:x}", hasher.finalize()))
        }
        ProcessingType::FilterData => {
            // Implement filtering logic here
            unimplemented!()
        }
    }
}

async fn worker(id: usize, client: Client, url: String, processing_type: ProcessingType, tx: mpsc::Sender<String>) -> Result<(), Box<dyn std::error::Error>> {
    loop {
        match fetch_user_data(&url).await {
            Ok(data) => {
                let result = process_data(data, processing_type).await?;
                if tx.send(result).is_err() {
                    return Err("Failed to send data".into());
                }
            }
            Err(e) => {
                // Implement exponential backoff here
                eprintln!("Worker {}: Failed to fetch data: {}", id, e);
            }
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let matches = App::new("User Data Processor")
        .arg(Arg::with_name("processing_type")
            .short('p')
            .long("processing-type")
            .value_name("TYPE")
            .takes_value(true)
            .help("Specify the type of data processing (md5 or filter)"))
        .get_matches();

    let processing_type = match matches.value_of("processing_type").unwrap() {
        "md5" => ProcessingType::GenerateMD5,
        "filter" => ProcessingType::FilterData,
        _ => return Err("Invalid processing type".into()),
    };

    let url = "https://api.example.com/users"; // Replace with actual API URL
    let client = Client::new();
    let (tx, mut rx) = mpsc::channel(32);

    for i in 0..4 { // Adjust number of workers as needed
        tokio::spawn(worker(i, client.clone(), url.to_string(), processing_type.clone(), tx.clone()));
    }

    while let Some(result) = rx.recv().await {
        println!("Processed data: {}", result);
    }

    Ok(())
}
