using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Polly;
using Polly.Retry;

public class LogAggregationService
{
    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _memoryCache;
    private readonly AsyncRetryPolicy _retryPolicy;

    public LogAggregationService(HttpClient httpClient, IMemoryCache memoryCache)
    {
        _httpClient = httpClient;
        _memoryCache = memoryCache;
        _retryPolicy = Policy
            .Handle<HttpRequestException>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));
    }

    public async Task ProcessLogs(IEnumerable<string> logEntries)
    {
        var bufferedLogs = await BufferLogs(logEntries);
        foreach (var batch in bufferedLogs.Chunk(100))
        {
            await SendLogsToExternalPlatform(batch);
        }
    }

    private async Task<List<string>> BufferLogs(IEnumerable<string> logEntries)
    {
        var bufferKey = "LogBuffer";
        if (!_memoryCache.TryGetValue(bufferKey, out List<string> buffer))
        {
            buffer = new List<string>();
            _memoryCache.Set(bufferKey, buffer, new MemoryCacheEntryOptions
            {
                SlidingExpirationRelativeToNow = TimeSpan.FromMinutes(5)
            });
        }

        buffer.AddRange(logEntries);
        return buffer;
    }

    private async Task SendLogsToExternalPlatform(IEnumerable<string> logBatch)
    {
        await _retryPolicy.ExecuteAsync(async () =>
        {
            var response = await _httpClient.PostAsJsonAsync("https://externalloggingplatform.com/logs", logBatch);
            if (!response.IsSuccessStatusCode)
            {
                throw new HttpRequestException($"Failed to send logs: {response.StatusCode}");
            }
        });
    }

    public async Task<IEnumerable<string>> GetLogs()
    {
        var bufferKey = "LogBuffer";
        _memoryCache.TryGetValue(bufferKey, out List<string> buffer);
        return buffer;
    }
}

public static class EnumerableExtensions
{
    public static IEnumerable<List<T>> Chunk<T>(this IEnumerable<T> source, int size)
    {
        using (var enumerator = source.GetEnumerator())
        {
            while (enumerator.MoveNext())
            {
                yield return source.Skip(enumerator.CurrentIndex).Take(size).ToList();
            }
        }
    }

    public static int CurrentIndex(this IEnumerator enumerator)
    {
        var fieldInfo = typeof(IEnumerator).GetField("_position", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
        if (fieldInfo != null && fieldInfo.FieldType == typeof(int))
        {
            return Convert.ToInt32(fieldInfo.GetValue(enumerator));
        }
        throw new InvalidOperationException("CurrentIndex not supported for this enumerator.");
    }
}
