import asyncio
from typing import Any, Callable, Dict, List

class EventProcessor:
    def __init__(self):
        self.event_queue = asyncio.Queue()
        self.tenant_resources = {}

    async def process_event(self, tenant_id: str, event: Any) -> None:
        await self.event_queue.put((tenant_id, event))

    async def allocate_resources(self):
        while True:
            await asyncio.sleep(1)
            for tenant_id, resource_usage in self.tenant_resources.items():
                if resource_usage > 80:  # Example threshold
                    self.adjust_resource_allocation(tenant_id, -10)  # Reduce resources
                elif resource_usage < 30 and len(self.event_queue) > 10:
                    self.adjust_resource_allocation(tenant_id, 10)  # Increase resources

    def adjust_resource_allocation(self, tenant_id: str, adjustment: int):
        if tenant_id in self.tenant_resources:
            new_usage = self.tenant_resources[tenant_id] + adjustment
            self.tenant_resources[tenant_id] = max(0, min(new_usage, 100))  # Clamp between 0 and 100%
        else:
            self.tenant_resources[tenant_id] = 50  # Default allocation

class EventTransformer:
    def __init__(self):
        self.transformers = {}

    def register_transformer(self, event_type: str, transformer: Callable[[Any], Any]):
        self.transformers[event_type] = transformer

    async def transform_event(self, tenant_id: str, event_type: str, event_data: Any) -> Any:
        if event_type in self.transformers:
            return await asyncio.to_thread(self.transformers[event_type], event_data)
        else:
            raise ValueError(f"No transformer registered for event type {event_type}")

class EventAggregator:
    def __init__(self):
        self.aggregations = {}

    async def aggregate_event(self, tenant_id: str, key: Any, value: Any) -> None:
        if key in self.aggregations:
            self.aggregations[key] += value
        else:
            self.aggregations[key] = value

    def get_aggregation_results(self):
        return self.aggregations

# Example usage
async def main():
    processor = EventProcessor()
    transformer = EventTransformer()
    aggregator = EventAggregator()

    async def handle_event(tenant_id, event):
        # Simulate resource allocation
        await asyncio.sleep(0.1)
        await processor.process_event(tenant_id, event)

    async def process_transformed_event(tenant_id, event_type, transformed_event):
        await asyncio.sleep(0.1)
        await aggregator.aggregate_event(tenant_id, event_type, transformed_event)

    # Register transformers
    transformer.register_transformer("example", lambda x: x * 2)

    # Simulate processing events
    tasks = []
    for i in range(10):
        tenant_id = f"tenant_{i % 3}"
        event_type = "example"
        event_data = {"value": i}

        task = asyncio.create_task(handle_event(tenant_id, (event_type, event_data)))
        tasks.append(task)

        transformed_event = await transformer.transform_event(tenant_id, event_type, event_data)
        transform_task = asyncio.create_task(process_transformed_event(tenant_id, event_type, transformed_event))
        tasks.append(transform_task)

    await asyncio.gather(*tasks)

    print("Aggregation Results:", aggregator.get_aggregation_results())

asyncio.run(main())
