#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct State {
    int id;
    void (*onEntry)(void);
    void (*onExit)(void);
} State;

typedef struct Transition {
    int fromState;
    int toState;
    void (*action)(void);
} Transition;

typedef struct FSA {
    State states[10];
    Transition transitions[20];
    int currentStateId;
    pthread_mutex_t mutex;
    // Add more fields as needed
} FSA;

FSA* createFSA() {
    FSA* fsa = (FSA*)malloc(sizeof(FSA));
    pthread_mutex_init(&fsa->mutex, NULL);
    return fsa;
}

void destroyFSA(FSA* fsa) {
    pthread_mutex_destroy(&fsa->mutex);
    free(fsa);
}

void setState(FSA* fsa, int stateId) {
    pthread_mutex_lock(&fsa->mutex);
    fsa->currentStateId = stateId;
    // Call the entry function of the new state
    if (stateId >= 0 && stateId < 10) {
        fsa->states[stateId].onEntry();
    }
    pthread_mutex_unlock(&fsa->mutex);
}

void addTransition(FSA* fsa, int fromState, int toState, void (*action)(void)) {
    static int transitionCount = 0;
    if (transitionCount < 20) {
        fsa->transitions[transitionCount].fromState = fromState;
        fsa->transitions[transitionCount].toState = toState;
        fsa->transitions[transitionCount].action = action;
        transitionCount++;
    }
}

void processEvent(FSA* fsa, int event) {
    pthread_mutex_lock(&fsa->mutex);
    for (int i = 0; i < 20; i++) {
        if (fsa->currentStateId == fsa->transitions[i].fromState && event == i) {
            // Call the action function of the transition
            fsa->transitions[i].action();
            setState(fsa, fsa->transitions[i].toState);
            break;
        }
    }
    pthread_mutex_unlock(&fsa->mutex);
}

// Example usage
void onState1Entry() {
    printf("Entering State 1\n");
}

void onState2Entry() {
    printf("Entering State 2\n");
}

void transitionAction() {
    printf("Transition action executed\n");
}

int main() {
    FSA* fsa = createFSA();

    // Define states
    State state1 = {1, onState1Entry, NULL};
    State state2 = {2, onState2Entry, NULL};
    fsa->states[0] = state1;
    fsa->states[1] = state2;

    // Add transitions
    addTransition(fsa, 0, 1, transitionAction);
    addTransition(fsa, 1, 0, transitionAction);

    // Set initial state and process events
    setState(fsa, 0); // Enter State 1
    processEvent(fsa, 0); // Trigger transition to State 2
    processEvent(fsa, 1); // Trigger transition back to State 1

    destroyFSA(fsa);
    return 0;
}
