class FSA {
    constructor() {
        this.states = [];
        this.transitions = [];
        this.currentStateId = null;
        this.mutex = new Mutex();
    }

    setState(stateId) {
        if (this.mutex.isLocked()) {
            throw new Error("Mutex is already locked");
        }
        this.mutex.lock();
        this.currentStateId = stateId;
        // Call the entry function of the new state
        if (stateId >= 0 && stateId < this.states.length) {
            this.states[stateId].onEntry();
        }
        this.mutex.unlock();
    }

    addTransition(fromState, toState, action) {
        if (this.transitions.length < 20) {
            this.transitions.push({fromState, toState, action});
        } else {
            throw new Error("Too many transitions");
        }
    }

    processEvent(event) {
        if (this.mutex.isLocked()) {
            throw new Error("Mutex is already locked");
        }
        this.mutex.lock();
        for (let i = 0; i < this.transitions.length; i++) {
            const transition = this.transitions[i];
            if (this.currentStateId === transition.fromState && event === i) {
                // Call the action function of the transition
                transition.action();
                this.setState(transition.toState);
                break;
            }
        }
        this.mutex.unlock();
    }

    // Example usage
    static onState1Entry() {
        console.log("Entering State 1");
    }

    static onState2Entry() {
        console.log("Entering State 2");
    }

    static transitionAction() {
        console.log("Transition action executed");
    }
}

// Initialize FSA and use it
const fsa = new FSA();
fsa.states.push(FSA.onState1Entry);
fsa.states.push(FSA.onState2Entry);

// Add transitions
fsa.addTransition(0, 1, FSA.transitionAction);
fsa.addTransition(1, 0, FSA.transitionAction);

// Set initial state and process events
fsa.setState(0); // Enter State 1
fsa.processEvent(0); // Trigger transition to State 2
fsa.processEvent(1); // Trigger transition back to State 1

