<?php

// oauthAuthenticationService.php

require_once 'vendor/autoload.php';

use League\OAuth2\Client\Provider\GenericProvider;
use Monolog\Logger;
use Monolog\Handler\StreamHandler;

class OAuth2Config {
    public static function getConfig() {
        return [
            'clientId' => 'your_client_id',
            'clientSecret' => 'your_client_secret',
            'redirectUri' => 'http://yourdomain.com/callback.php',
            'urlAuthorize' => 'https://oauthprovider.com/oauth/authorize',
            'urlAccessToken' => 'https://oauthprovider.com/oauth/token',
            'urlResourceOwnerDetails' => 'https://oauthprovider.com/userinfo',
        ];
    }
}

class OAuth2AuthenticationService {
    private $provider;
    private $sessionStore;
    private $cache;
    private $logger;

    public function __construct() {
        $config = OAuth2Config::getConfig();
        $this->provider = new GenericProvider($config);
        $this->sessionStore = new SessionStore();
        $this->cache = new CacheAdapter(new FilesystemCache());
        $this->logger = new Logger('oauth_service');
        $this->logger->pushHandler(new StreamHandler(__DIR__ . '/logs/oauth.log', Logger::DEBUG));
    }

    public function authenticate($code) {
        try {
            $token = $this->provider->getAccessToken('authorization_code', [
                'code' => $code,
            ]);

            if ($token->hasExpired()) {
                throw new Exception("Token has expired.");
            }

            $userDetails = $this->getUserDetails($token);
            $this->sessionStore->setToken($userDetails['id'], $token);

            return $userDetails;
        } catch (Exception $e) {
            $this->logger->error($e->getMessage());
            throw $e;
        }
    }

    private function getUserDetails($accessToken) {
        try {
            $response = $this->provider->getAuthenticatedClient()->request('GET', OAuth2Config::getConfig()['urlResourceOwnerDetails'], [
                'headers' => ['Authorization' => 'Bearer ' . $accessToken->getToken()],
            ]);

            return json_decode($response->getBody(), true);
        } catch (Exception $e) {
            $this->logger->error($e->getMessage());
            throw $e;
        }
    }

    public function getAccessToken($userId) {
        if ($this->cache->hasItem($userId)) {
            return $this->cache->getItem($userId)->get();
        }

        $token = $this->sessionStore->getToken($userId);
        if ($token->hasExpired()) {
            throw new Exception("Token has expired.");
        }

        $this->cache->setItem($userId, $token, 3600); // Cache for 1 hour
        return $token;
    }
}

class SessionStore {
    public function setToken($key, $value) {
        session_start();
        $_SESSION[$key] = $value;
    }

    public function getToken($key) {
        session_start();
        return isset($_SESSION[$key]) ? $_SESSION[$key] : null;
    }
}

class CacheAdapter {
    private $cache;

    public function __construct(CacheItemPoolInterface $cache) {
        $this->cache = $cache;
    }

    public function hasItem($key) {
        return $this->cache->hasItem($key);
    }

    public function getItem($key) {
        return $this->cache->getItem($key);
    }

    public function setItem($key, $value, $ttl = null) {
        $item = $this->cache->getItem($key);
        $item->set($value);

        if ($ttl !== null) {
            $item->expiresAfter($ttl);
        }

        return $this->cache->save($item);
    }
}

// oauth.php

require_once 'oauthAuthenticationService.php';

$service = new OAuth2AuthenticationService();

if (isset($_GET['code'])) {
    try {
        $userDetails = $service->authenticate($_GET['code']);
        echo json_encode($userDetails);
    } catch (Exception $e) {
        http_response_code(500);
        echo json_encode(['error' => $e->getMessage()]);
    }
} else {
    // Redirect to OAuth provider
}
?>
```

