int initialize_service(ServiceType type, int id) {
    services[id].id = id;
    sem_init(&services[id].semaphore, 0, 1);
    switch (type) {
        case SERVICE_LOGGER:
            pthread_create(&services[id].thread_id, NULL, service_logger, &services[id]);
            break;
        case SERVICE_NETWORK_CLIENT:
            pthread_create(&services[id].thread_id, NULL, service_network_client, &services[id]);
            break;
        case SERVICE_STORAGE_HANDLER:
            pthread_create(&services[id].thread_id, NULL, service_storage_handler, &services[id]);
            break;
        case SERVICE_SCHEDULER:
            pthread_create(&services[id].thread_id, NULL, service_scheduler, &services[id]);
            break;
        case SERVICE_MONITORING:
            pthread_create(&services[id].thread_id, NULL, service_monitoring, &services[id]);
            break;
        case SERVICE_SECURITY:
            pthread_create(&services[id].thread_id, NULL, service_security, &services[id]);
            break;
        default:
            return -1; // Invalid service type
    }
    return 0;
}

int verify_and_initialize_system() {
    for (int i = 0; i < NUM_SERVICES; i++) {
        if (initialize_service((ServiceType)i, i) != 0) {
            printf("Failed to initialize service %d\n", i);
            return -1;
        }
        sem_wait(&services[i].semaphore); // Simulate initialization check
    }
    readiness_flag = 1;
    printf("System initialized successfully\n");
    return 0;
}

int main() {
    if (verify_and_initialize_system() != 0) {
        printf("Initialization failed\n");
    } else {
        // System is ready for operation
    }
    return 0;
}
```

