    public interface IDatabasePoolManager
    {
        DbConnection GetConnection(string connectionString);
        void ReleaseConnection(DbConnection connection);
    }

    public class DatabasePoolManager : IDatabasePoolManager
    {
        private readonly Dictionary<string, Stack<DbConnection>> _connectionPools = new Dictionary<string, Stack<DbConnection>>();
        private readonly ILogger<DatabasePoolManager> _logger;

        public DatabasePoolManager(ILogger<DatabasePoolManager> logger)
        {
            _logger = logger;
        }

        public DbConnection GetConnection(string connectionString)
        {
            if (!_connectionPools.ContainsKey(connectionString))
                _connectionPools[connectionString] = new Stack<DbConnection>();

            var connectionPool = _connectionPools[connectionString];
            if (connectionPool.Count > 0)
                return connectionPool.Pop();

            try
            {
                var factory = DbProviderFactories.GetFactory("System.Data.SqlClient");
                return factory.CreateConnection() { ConnectionString = connectionString };
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to create database connection.");
                throw;
            }
        }

        public void ReleaseConnection(DbConnection connection)
        {
            var connectionString = connection.ConnectionString;
            if (_connectionPools.ContainsKey(connectionString))
            {
                var connectionPool = _connectionPools[connectionString];
                if (connectionPool.Count < 10) // Example threshold
                    connectionPool.Push(connection);
            }
        }
    }

