// C# Library: DatabaseConnectionManager

using System;
using System.Collections.Generic;
using System.Data.Common;
using System.Threading.Tasks;

public class DatabaseConnectionPool
{
    private readonly Dictionary<string, Queue<DbConnection>> _pool;
    private readonly Dictionary<string, int> _currentSize;
    private readonly Dictionary<string, int> _maxSize;

    public DatabaseConnectionPool()
    {
        _pool = new Dictionary<string, Queue<DbConnection>>();
        _currentSize = new Dictionary<string, int>();
        _maxSize = new Dictionary<string, int>();
    }

    public void Initialize(string connectionString, int initialSize, int maxSize)
    {
        if (!_pool.ContainsKey(connectionString))
        {
            _pool[connectionString] = new Queue<DbConnection>();
        }
        _currentSize[connectionString] = initialSize;
        _maxSize[connectionString] = maxSize;

        for (int i = 0; i < initialSize; i++)
        {
            var connection = CreateConnection(connectionString);
            _pool[connectionString].Enqueue(connection);
        }
    }

    public async Task<DbConnection> GetConnectionAsync(string connectionString)
    {
        while (_currentSize[connectionString] == 0 && !await IsPoolHealthyAsync(connectionString))
        {
            await Task.Delay(100); // Wait for a bit before retrying
        }

        if (_pool[connectionString].Count > 0)
        {
            _currentSize[connectionString]--;
            return _pool[connectionString].Dequeue();
        }
        else
        {
            var newConnection = CreateConnection(connectionString);
            _currentSize[connectionString]++;
            return newConnection;
        }
    }

    public void ReturnConnection(string connectionString, DbConnection connection)
    {
        if (_currentSize[connectionString] < _maxSize[connectionString])
        {
            _pool[connectionString].Enqueue(connection);
            _currentSize[connectionString]++;
        }
        else
        {
            connection.Dispose();
        }
    }

    private async Task<bool> IsPoolHealthyAsync(string connectionString)
    {
        // Implement health check logic here, e.g., ping the database
        return true; // Placeholder
    }

    private DbConnection CreateConnection(string connectionString)
    {
        var factory = DbProviderFactories.GetFactory("System.Data.SqlClient");
        return factory.CreateConnection() { ConnectionString = connectionString };
    }
}

