using System;
using System.IO;
using SixLabors.ImageSharp;
using SixLabors.ImageSharp.Formats.Jpeg;
using SixLabors.ImageSharp.Processing;

public class MultimediaFileProcessor
{
    public static ImageMetadata ProcessImage(string filePath, int? thumbnailWidth = null)
    {
        using (var image = Image.Load(filePath))
        {
            var metadata = new ImageMetadata
            {
                Dimensions = new System.Drawing.Size(image.Width, image.Height),
                CompressionType = "Jpeg"
            };

            if (thumbnailWidth.HasValue && thumbnailWidth.Value < image.Width)
            {
                image.Mutate(x => x.Resize(thumbnailWidth.Value));
                metadata.Thumbnail = Convert.ToBase64String(image.ToByteArray(new JpegEncoder()));
            }

            return metadata;
