ConnectionPool* create_connection_pool(int initial_size, int max_size) {
    ConnectionPool *pool = malloc(sizeof(ConnectionPool));
    pool->count = 0;
    pool->connections = malloc(max_size * sizeof(sqlite3 *));
    for (int i = 0; i < initial_size; i++) {
        sqlite3 *conn;
        if (sqlite3_open("example.db", &conn) != SQLITE_OK) {
            // Handle error
            return NULL;
        }
        pool->connections[pool->count++] = conn;
    }
    return pool;
}

sqlite3* get_connection(ConnectionPool *pool) {
    if (pool->count == 0) {
        // Wait for a bit before retrying
        sqlite3_sleep(100);
        return get_connection(pool);
    }
    sqlite3 *conn = pool->connections[--pool->count];
    return conn;
}

void return_connection(ConnectionPool *pool, sqlite3 *conn) {
    if (pool->count < pool->max_size) {
        pool->connections[pool->count++] = conn;
    } else {
        sqlite3_close(conn);
    }
}

