// Define a base class for log parsers
class LogParser {
public:
    virtual void parse(const std::string& data) = 0;
    virtual ~LogParser() {}
};

// Implement specific parsers for JSON, XML, and custom protocols
class JsonLogParser : public LogParser {
public:
    void parse(const std::string& data) override {
        // Parse JSON data
        std::cout << "Parsing JSON log: " << data << std::endl;
    }
};

class XmlLogParser : public LogParser {
public:
    void parse(const std::string& data) override {
        // Parse XML data
        std::cout << "Parsing XML log: " << data << std::endl;
    }
};

class CustomProtocolParser : public LogParser {
public:
    void parse(const std::string& data) override {
        // Parse custom protocol data
        std::cout << "Parsing custom protocol log: " << data << std::endl;
    }
};

// Define a class for the log processing pipeline
class LogPipeline {
private:
    std::vector<std::unique_ptr<LogParser>> parsers;
    std::thread worker;
    std::mutex queue_mutex;
    std::condition_variable queue_cv;
    bool running;

public:
    LogPipeline() : running(true) {
        // Initialize parsers based on configuration
        parsers.push_back(std::make_unique<JsonLogParser>());
        parsers.push_back(std::make_unique<XmlLogParser>());
        parsers.push_back(std::make_unique<CustomProtocolParser>());

        worker = std::thread(&LogPipeline::process, this);
    }

    ~LogPipeline() {
        running = false;
        queue_cv.notify_all();
        worker.join();
    }

    void process() {
        while (running) {
            std::unique_lock<std::mutex> lock(queue_mutex);
            queue_cv.wait(lock, [this] { return !running || !log_queue.empty(); });
            if (!running && log_queue.empty()) break;

            std::string data = log_queue.front();
            log_queue.pop();

            lock.unlock();
            for (auto& parser : parsers) {
                parser->parse(data);
            }
        }
    }

    void addLog(const std::string& data) {
        std::lock_guard<std::mutex> lock(queue_mutex);
        log_queue.push(data);
        queue_cv.notify_one();
    }

private:
    std::queue<std::string> log_queue;
};

int main() {
    LogPipeline pipeline;

    // Simulate adding logs
    for (int i = 0; i < 10; ++i) {
        std::string log_data = "Log entry " + std::to_string(i);
        pipeline.addLog(log_data);
    }

    return 0;
}
```

