#include <condition_variable>
#include <future>
#include <memory>
#include <atomic>

class DeviceConfigNode {
public:
    std::string deviceID;
    std::string parameterName;
    int version;
    std::string value;

    DeviceConfigNode(std::string deviceID, std::string parameterName, int version, std::string value)
        : deviceID(deviceID), parameterName(parameterName), version(version), value(value) {}
};

class ConfigManager {
public:
    struct NodeHandle {
        std::shared_ptr<DeviceConfigNode> node;
        bool isValid() const { return node != nullptr; }
        NodeHandle(std::shared_ptr<DeviceConfigNode> n) : node(n) {}
    };

    NodeHandle getDeviceConfig(const std::string& deviceID, const std::string& parameterName, int version);
    void updateDeviceConfig(const std::string& deviceID, const std::string& parameterName, int version, const std::string& newValue);

private:
    struct ConfigKey {
        std::string deviceID;
        std::string parameterName;
        int version;

        bool operator==(const ConfigKey& other) const {
            return deviceID == other.deviceID && parameterName == other.parameterName && version == other.version;
        }
    };

    struct HashFunction {
        size_t operator()(const ConfigKey& key) const {
            return std::hash<std::string>()(key.deviceID) ^ std::hash<std::string>()(key.parameterName) ^
                   std::hash<int>()(key.version);
        }
    };

    std::unordered_map<ConfigKey, std::shared_ptr<DeviceConfigNode>, HashFunction> configMap;
    std::mutex mapMutex;
    std::condition_variable cv;

    NodeHandle doGetDeviceConfig(const ConfigKey& key);
    void doUpdateDeviceConfig(const ConfigKey& key, const std::string& newValue);

    struct PoolAllocator {
        static std::shared_ptr<DeviceConfigNode> allocate(const std::string& deviceID, const std::string& parameterName, int version, const std::string& value) {
            return std::make_shared<DeviceConfigNode>(deviceID, parameterName, version, value);
        }
    };
};

ConfigManager::NodeHandle ConfigManager::getDeviceConfig(const std::string& deviceID, const std::string& parameterName, int version) {
    std::lock_guard<std::mutex> lock(mapMutex);
    return doGetDeviceConfig(ConfigKey{deviceID, parameterName, version});
}

void ConfigManager::updateDeviceConfig(const std::string& deviceID, const std::string& parameterName, int version, const std::string& newValue) {
    std::lock_guard<std::mutex> lock(mapMutex);
    doUpdateDeviceConfig(ConfigKey{deviceID, parameterName, version}, newValue);
}

ConfigManager::NodeHandle ConfigManager::doGetDeviceConfig(const ConfigKey& key) {
    auto it = configMap.find(key);
    if (it != configMap.end()) {
        return NodeHandle(it->second);
    }
    // Fetch from external storage or API
    return NodeHandle(PoolAllocator::allocate("default", "default", 0, "default"));
}

void ConfigManager::doUpdateDeviceConfig(const ConfigKey& key, const std::string& newValue) {
    auto it = configMap.find(key);
    if (it != configMap.end()) {
        it->second->value = newValue;
    } else {
        // Add new node from external storage or API
        configMap[key] = PoolAllocator::allocate("default", "default", 0, newValue);
    }
}

int main() {
    ConfigManager manager;
    auto node1 = manager.getDeviceConfig("device1", "param1", 1);
    if (node1.isValid()) {
        std::cout << "Value: " << node1.node->value << std::endl;
    }

    manager.updateDeviceConfig("device1", "param1", 1, "new_value");
    return 0;
}
