import com.hazelcast.config.Config;
import com.hazelcast.config.EvictionPolicy;
import com.hazelcast.config.InMemoryFormat;
import com.hazelcast.core.HazelcastInstance;
import com.hazelcast.core.IMap;
import com.hazelcast.map.MapNearCacheConfig;

public class DistributedCacheService {

    private final HazelcastInstance hazelcastInstance;

    public DistributedCacheService() {
        Config config = new Config();
        config.setClusterName("ecommerce-cache-cluster");

        // In-memory caching with persistence
        MapNearCacheConfig nearCacheConfig = new MapNearCacheConfig();
        nearCacheConfig.setName("inventory-near-cache")
                         .setInvalidateOnChange(true)
                         .setMaxSize(100000);

        IMap<String, Object> inventoryCache = config.getMapConfig("inventory")
                                                   .setInMemoryFormat(InMemoryFormat.BINARY)
                                                   .setEvictionPolicy(EvictionPolicy.LRU)
                                                   .setMaxSizeConfig(nearCacheConfig.getMaxSizeAsLong())
                                                   .setNearCacheConfig(nearCacheConfig);

        IMap<String, Object> userProfileCache = config.getMapConfig("user-profile")
                                                     .setInMemoryFormat(InMemoryFormat.OBJECT)
                                                     .setEvictionPolicy(EvictionPolicy.LRU)
                                                     .setMaxSize(50000);

        IMap<String, Object> paymentProcessingCache = config.getMapConfig("payment-processing")
                                                          .setInMemoryFormat(InMemoryFormat.BINARY)
                                                          .setEvictionPolicy(EvictionPolicy.LFU)
                                                          .setMaxSize(20000);

        hazelcastInstance = Hazelcast.newHazelcastInstance(config);
    }

    public Object getInventory(String productId) {
        return hazelcastInstance.getMap("inventory").get(productId);
    }

    public void setInventory(String productId, Object inventory) {
        hazelcastInstance.getMap("inventory").put(productId, inventory);
    }

    public Object getUserProfile(String userId) {
        return hazelcastInstance.getMap("user-profile").get(userId);
    }

    public void setUserProfile(String userId, Object userProfile) {
        hazelcastInstance.getMap("user-profile").put(userId, userProfile);
    }

    public Object getPaymentProcessingData(String transactionId) {
        return hazelcastInstance.getMap("payment-processing").get(transactionId);
    }

    public void setPaymentProcessingData(String transactionId, Object paymentData) {
        hazelcastInstance.getMap("payment-processing").put(transactionId, paymentData);
    }
}
