    ~DeviceConfigNode();

    void updateValue(const std::string& newValue);
    std::string getValue() const;

private:
    std::string deviceID;
    std::string parameterName;
    int version;
    std::string value;
    mutable std::mutex mutex;
};

// ConfigManager.h
#pragma once

#include <vector>
#include <unordered_map>

class ConfigManager {
public:
    void addNode(const DeviceConfigNode& node);
    bool removeNode(const std::string& deviceID, const std::string& parameterName, int version);
    std::string getNodeValue(const std::string& deviceID, const std::string& parameterName, int version);

private:
    std::unordered_map<std::tuple<std::string, std::string, int>, DeviceConfigNode*, std::hash<std::tuple<std::string, std::string, int>>> nodeMap;
};

// ConfigManager.cpp
#include "ConfigManager.h"

void ConfigManager::addNode(const DeviceConfigNode& node) {
    auto key = std::make_tuple(node.deviceID, node.parameterName, node.version);
    nodeMap[key] = const_cast<DeviceConfigNode*>(&node);
}

bool ConfigManager::removeNode(const std::string& deviceID, const std::string& parameterName, int version) {
    auto key = std::make_tuple(deviceID, parameterName, version);
    if (nodeMap.find(key) != nodeMap.end()) {
        nodeMap.erase(key);
        return true;
    }
    return false;
}

std::string ConfigManager::getNodeValue(const std::string& deviceID, const std::string& parameterName, int version) {
    auto key = std::make_tuple(deviceID, parameterName, version);
    if (nodeMap.find(key) != nodeMap.end()) {
        return nodeMap[key]->getValue();
    }
    return "";
}

// DeviceConfigNode.cpp
#include "DeviceConfigNode.h"

DeviceConfigNode::DeviceConfigNode(const std::string& deviceID, const std::string& parameterName, int version)
    : deviceID(deviceID), parameterName(parameterName), version(version) {}

DeviceConfigNode::~DeviceConfigNode() {}

void DeviceConfigNode::updateValue(const std::string& newValue) {
    std::lock_guard<std::mutex> lock(mutex);
    value = newValue;
}

std::string DeviceConfigNode::getValue() const {
    std::lock_guard<std::mutex> lock(mutex);
    return value;
}
