class DeviceConfigNode {
public:
    std::string deviceID;
    std::string parameterName;
    int version;
    // Other fields and methods

private:
    static std::unordered_map<std::tuple<std::string, std::string, int>, DeviceConfigNode*, std::hash<std::tuple<std::string, std::string, int>>> nodeMap;
    static std::mutex nodeMutex;

    DeviceConfigNode(const std::string& deviceID, const std::string& parameterName, int version) 
        : deviceID(deviceID), parameterName(parameterName), version(version) {}

public:
    static DeviceConfigNode* createNode(const std::string& deviceID, const std::string& parameterName, int version) {
        std::lock_guard<std::mutex> lock(nodeMutex);
        auto key = std::make_tuple(deviceID, parameterName, version);
        if (nodeMap.find(key) != nodeMap.end()) return nullptr;
        DeviceConfigNode* newNode = new DeviceConfigNode(deviceID, parameterName, version);
        nodeMap[key] = newNode;
        return newNode;
    }

    static void deleteNode(const std::string& deviceID, const std::string& parameterName, int version) {
        std::lock_guard<std::mutex> lock(nodeMutex);
        auto key = std::make_tuple(deviceID, parameterName, version);
        if (nodeMap.find(key) != nodeMap.end()) {
            delete nodeMap[key];
            nodeMap.erase(key);
        }
    }

    static DeviceConfigNode* getNode(const std::string& deviceID, const std::string& parameterName, int version) {
        std::lock_guard<std::mutex> lock(nodeMutex);
        auto key = std::make_tuple(deviceID, parameterName, version);
        if (nodeMap.find(key) != nodeMap.end()) return nodeMap[key];
        return nullptr;
    }
};

std::unordered_map<std::tuple<std::string, std::string, int>, DeviceConfigNode*, std::hash<std::tuple<std::string, std::string, int>>> DeviceConfigNode::nodeMap;
std::mutex DeviceConfigNode::nodeMutex;

int main() {
    // Example usage
    DeviceConfigNode* node = DeviceConfigNode::createNode("device1", "param1", 1);
    if (node) {
        std::cout << "Node created successfully" << std::endl;
    } else {
        std::cout << "Node already exists" << std::endl;
    }

    DeviceConfigNode* retrievedNode = DeviceConfigNode::getNode("device1", "param1", 1);
    if (retrievedNode) {
        std::cout << "Node retrieved successfully" << std::endl;
    } else {
        std::cout << "Node not found" << std::endl;
    }

    DeviceConfigNode::deleteNode("device1", "param1", 1);

    return 0;
}
