#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#define MAX_RETRIES 10
#define BACKOFF_FACTOR 2

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_pdu(int tag, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    pdu->RX_UE_INFORMATION_TAG = tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    return pdu;
}

void free_nfa_pi_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu != NULL) {
        free(pdu);
    }
}

int send_to_api(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Simulate sending to API with potential failures
    if ((rand() % 10) < 2) { // 20% failure rate
        printf("API call failed\n");
        return -1;
    }
    printf("Data sent to API: RX_UE_INFO_TAG=%d, RNTI=%d, CRC_INDICATION=%d\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG);
    return 0;
}

int send_with_retries(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (send_to_api(pdu) == 0) {
            return 0; // Success
        }
        sleep(BACKOFF_FACTOR * (1 << retries)); // Exponential backoff
        retries++;
    }
    printf("Failed to send data after %d retries\n", MAX_RETRIES);
    return -1;
}

int main() {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* pdu = create_nfa_pi_pdu(123, 456);
    if (pdu != NULL) {
        send_with_retries(pdu);
        free_nfa_pi_pdu(pdu);
    }
    return 0;
}
