#include <iostream>
#include <vector>
#include <mutex>
#include <thread>
#include <condition_variable>
#include <memory>
#include <random>

// Define CUSTOMER_TRANSACTION_RECORD structure
struct CUSTOMER_TRANSACTION_RECORD {
    int TRANSACTION_ID;
    int CUSTOMER_ID;
    double TRANSACTION_AMOUNT;
    std::string PAYMENT_METHOD;
    // Dynamically allocated TRANSACTION_STATUS tag with a randomly set STATUS_CODE and REASON_CODE
    struct TRANSACTION_STATUS {
        int STATUS_CODE;
        std::string REASON_CODE;
    };
    std::unique_ptr<TRANSACTION_STATUS> status;
};

// Define the library class
class CustomerTransactionManager {
public:
    CustomerTransactionManager(int seed) : rng(seed), transaction_id_counter(0) {}

    void addTransaction(const CUSTOMER_TRANSACTION_RECORD& record) {
        std::lock_guard<std::mutex> lock(mutex);
        transactions.push_back(record);
        transaction_id_counter++;
    }

    void processTransactions() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !transactions.empty(); });
            CUSTOMER_TRANSACTION_RECORD record = transactions.back();
            transactions.pop_back();
            lock.unlock();

            // Simulate transaction processing
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
            processTransaction(record);
        }
    }

private:
    std::vector<CUSTOMER_TRANSACTION_RECORD> transactions;
    std::mutex mutex;
    std::condition_variable condition;
    std::mt19937 rng;
    int transaction_id_counter;

    void processTransaction(const CUSTOMER_TRANSACTION_RECORD& record) {
        // Simulate transaction status generation
        std::uniform_int_distribution<> dist(0, 1);
        bool success = (dist(rng) == 0);

        if (success) {
            std::cout << "Transaction ID: " << record.TRANSACTION_ID << " processed successfully." << std::endl;
        } else {
            std::cout << "Transaction ID: " << record.TRANSACTION_ID << " failed." << std::endl;
        }

        // Log the transaction status
        logTransactionStatus(record);
    }

    void logTransactionStatus(const CUSTOMER_TRANSACTION_RECORD& record) {
        if (record.status) {
            std::cout << "STATUS_CODE: " << record.status->STATUS_CODE << ", REASON_CODE: " << record.status->REASON_CODE << std::endl;
        } else {
            std::cout << "No status available." << std::endl;
        }
    }
};

int main() {
    // Seed value for random number generation
    int seed = 42;

    CustomerTransactionManager manager(seed);

    // Simulate adding transactions
    for (int i = 0; i < 100; ++i) {
        CUSTOMER_TRANSACTION_RECORD record;
        record.TRANSACTION_ID = i + 1;
        record.CUSTOMER_ID = i % 100;
        record.TRANSACTION_AMOUNT = static_cast<double>(i * 10);
        record.PAYMENT_METHOD = "Credit Card";
        record.status = std::make_unique<CUSTOMER_TRANSACTION_RECORD::TRANSACTION_STATUS>();
        record.status->STATUS_CODE = 200; // Simulated success
        record.status->REASON_CODE = "Transaction processed successfully.";

        manager.addTransaction(record);
    }

    // Process transactions in a separate thread
    std::thread processor(&CustomerTransactionManager::processTransactions, &manager);

    processor.join();

    return 0;
}
```

