    private readonly Dictionary<string, IApiGateway> apiGateways;
    private readonly IMetricsCollector metricsCollector;
    private readonly IConfigurationService configService;
    private readonly IDependencyResolver dependencyResolver;

    public ApiGatewayManager(IAuthService authService, IMetricsCollector metricsCollector, IConfigurationService configService, IDependencyResolver dependencyResolver)
    {
        if (authService == null) throw new DependencyResolutionException("AuthService cannot be null");
        if (apiGateways == null) throw new DependencyResolutionException("ApiGateways dictionary cannot be null");
        if (metricsCollector == null) throw new DependencyResolutionException("MetricsCollector cannot be null");
        if (configService == null) throw new DependencyResolutionException("ConfigService cannot be null");
        if (dependencyResolver == null) throw new DependencyResolutionException("DependencyResolver cannot be null");

        this.authService = authService;
        this.apiGateways = new Dictionary<string, IApiGateway>();
        this.metricsCollector = metricsCollector;
        this.configService = configService;
        this.dependencyResolver = dependencyResolver;
    }

    public void RegisterGateway(string gatewayName, IApiGateway gateway)
    {
        if (apiGateways.ContainsKey(gatewayName))
            throw new ArgumentException("Gateway already registered");

        // Implement rate limiting logic here
        apiGateways[gatewayName] = gateway;
    }

    public async Task UnregisterGatewayAsync(string gatewayName)
    {
        if (!apiGateways.ContainsKey(gatewayName))
            return;

        var gateway = apiGateways[gatewayName];
        apiGateways.Remove(gatewayName);

        // Asynchronously handle unregistration
        _ = Task.Run(async () =>
        {
            try
            {
                await gateway.HandleRequestAsync("Unregister request");
                // Shift traffic to alternative services if needed
            }
            catch (Exception ex)
            {
                // Log the exception and provide a rollback mechanism
            }
        });
    }

    // Additional methods for handling requests, routing, etc.
}
