#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SESSION_ID_LENGTH 128
#define MAX_USER_IP_LENGTH 45

typedef struct SessionNode {
    char session_id[MAX_SESSION_ID_LENGTH];
    char user_ip[MAX_USER_IP_LENGTH];
    time_t expiration_timestamp;
    // Additional metadata can be added here
    struct SessionNode* prev;
    struct SessionNode* next;
} SessionNode;

SessionNode* create_session_node(const char* session_id, const char* user_ip, time_t expiration_timestamp) {
    SessionNode* new_node = (SessionNode*)malloc(sizeof(SessionNode));
    if (new_node == NULL) {
        return NULL; // Memory allocation failed
    }
    strncpy(new_node->session_id, session_id, MAX_SESSION_ID_LENGTH);
    strncpy(new_node->user_ip, user_ip, MAX_USER_IP_LENGTH);
    new_node->expiration_timestamp = expiration_timestamp;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void insert_session_node(SessionNode** head, SessionNode* new_node) {
    if (*head == NULL) {
        *head = new_node;
    } else {
        new_node->next = *head;
        (*head)->prev = new_node;
        *head = new_node;
    }
}

void delete_session_node(SessionNode** head, SessionNode* node) {
    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        *head = node->next;
    }
    if (node->next != NULL) {
        node->next->prev = node->prev;
    }
    free(node);
}

void clean_expired_sessions(SessionNode** head, time_t current_time) {
    SessionNode* current = *head;
    while (current != NULL) {
        if (current->expiration_timestamp < current_time) {
            SessionNode* next = current->next;
            delete_session_node(head, current);
            current = next;
        } else {
            current = current->next;
        }
    }
}

int main() {
    // Example usage
    SessionNode* head = NULL;

    time_t now = time(NULL);
    time_t expiration_time = now + 3600; // Expires in 1 hour

    SessionNode* new_node = create_session_node("12345", "192.168.1.1", expiration_time);
    if (new_node != NULL) {
        insert_session_node(&head, new_node);
    }

    clean_expired_sessions(&head, now);

    return 0;
}
