logging.basicConfig(level=logging.INFO)

REQUEST_COUNT = Counter('request_count_total', 'Total request count')

@app.before_request
def before_request():
    REQUEST_COUNT.inc()

@retry(stop_max_attempt_number=3, wait_fixed=1000)
def fetch_auth_token(user_id):
    response = requests.get(f'https://auth-provider.com/api/auth/{user_id}')
    if response.status_code != 200:
        raise Exception("Failed to fetch auth token")
    return response.json()['token']

@retry(stop_max_attempt_number=3, wait_fixed=1000)
def process_payment(token, amount):
    response = requests.post(f'https://payment-gateway.com/api/pay', json={'token': token, 'amount': amount})
    if response.status_code != 200:
        raise Exception("Failed to process payment")

@app.route('/session/<user_id>', methods=['POST'])
def create_session(user_id):
    try:
        auth_token = fetch_auth_token(user_id)
        session_data = {'auth_token': auth_token, 'last_accessed': time.time()}
        redis_client.set(user_id, jsonify(session_data))
        return jsonify({'message': 'Session created successfully'}), 201
    except Exception as e:
        logger.error(f"Error creating session for user {user_id}: {e}")
        return jsonify({'error': str(e)}), 500

@app.route('/session/<user_id>', methods=['PUT'])
def update_session(user_id):
    try:
        auth_token = fetch_auth_token(user_id)
        amount = request.json['amount']
        process_payment(auth_token, amount)
        session_data = {'auth_token': auth_token, 'last_accessed': time.time()}
        redis_client.set(user_id, jsonify(session_data))
        return jsonify({'message': 'Session updated successfully'}), 200
    except Exception as e:
        logger.error(f"Error updating session for user {user_id}: {e}")
        return jsonify({'error': str(e)}), 500

@app.route('/session/<user_id>', methods=['DELETE'])
def delete_session(user_id):
    try:
        redis_client.delete(user_id)
        return jsonify({'message': 'Session deleted successfully'}), 200
    except Exception as e:
        logger.error(f"Error deleting session for user {user_id}: {e}")
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    start_http_server(8000)
    app.run(host='0.0.0.0', port=5000, threaded=True)
