#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <memory>
#include <future>
#include <stdexcept>

class TaskQueue {
public:
    void enqueue(std::function<void()> task) {
        std::unique_lock<std::mutex> lock(mutex_);
        tasks_.push(task);
        condition_.notify_one();
    }

    std::function<void()> dequeue() {
        std::unique_lock<std::mutex> lock(mutex_);
        condition_.wait(lock, [this] { return !tasks_.empty(); });
        auto task = tasks_.front();
        tasks_.pop();
        return task;
    }

private:
    std::queue<std::function<void()>> tasks_;
    std::mutex mutex_;
    std::condition_variable condition_;
};

class Worker {
public:
    Worker(TaskQueue& queue) : queue_(queue), running_(true) {
        thread_ = std::thread(&Worker::run, this);
    }

    ~Worker() {
        {
            std::unique_lock<std::mutex> lock(queue_.mutex_);
            running_ = false;
        }
        queue_.condition_.notify_all();
        thread_.join();
    }

private:
    void run() {
        while (true) {
            auto task = queue_.dequeue();
            if (!running_) break;
            task();
        }
    }

    TaskQueue& queue_;
    std::thread thread_;
    bool running_;
};

class ThreadPool {
public:
    ThreadPool(size_t num_threads) : queue_(), workers_(num_threads) {
        for (size_t i = 0; i < num_threads; ++i) {
            workers_.emplace_back(queue_);
        }
    }

    ~ThreadPool() {}

    void enqueue(std::function<void()> task) {
        queue_.enqueue(task);
    }

private:
    TaskQueue queue_;
    std::vector<Worker> workers_;
};

int main() {
    ThreadPool pool(4);

    // Example usage
    for (int i = 0; i < 8; ++i) {
        pool.enqueue([i] {
            std::cout << "Task " << i << " is running on thread " << std::this_thread::get_id() << std::endl;
        });
    }

    return 0;
}
```

This code provides a basic implementation of a thread pool using a worker queue. Each worker dequeues tasks and executes them in parallel. The `ThreadPool` class manages the workers and the task queue, ensuring that tasks are distributed among available threads. This example can be expanded to include more features such as a circuit breaker pattern, resilient communication with cloud storage, event-driven architecture, health monitoring, and adaptive algorithms for thread scaling.']

