        executorService.submit(() -> {
            try {
                if (dataFormatIsJSON(data)) {
                    processDataFromJSON(data);
                } else if (dataFormatIsXML(data)) {
                    processDataFromXML(data);
                } else if (isBatchData(data)) {
                    processBatchData(data);
