    void processFile(const std::string& filePath, size_t batchSize, size_t numThreads) {
        // Open file and read lines
        std::ifstream file(filePath);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open file");
        }

        std::vector<std::thread> threads(numThreads);
        std::atomic<size_t> lineCount(0);

        for (size_t i = 0; i < numThreads; ++i) {
            threads[i] = std::thread([this, &file, batchSize, &lineCount]() {
                while (true) {
                    size_t linesProcessed = 0;
                    for (; linesProcessed < batchSize && !file.eof(); ++linesProcessed) {
                        SensorReading reading = parseLine(file);
                        if (!reading.values.empty()) {
                            std::lock_guard<std::mutex> lock(mutex_);
                            aggregateData(reading);
                        }
                    }

                    if (linesProcessed == 0) break; // No more lines to process
                }
            });
        }

        for (auto& thread : threads) {
            thread.join();
        }

        file.close();
    }

private:
