    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

// Function to create a new node
ListNode* createNode(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (newNode == NULL) {
        return NULL; // Handle memory allocation failure
    }
    newNode->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->data.RNTI = RNTI;
    newNode->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newNode->next = NULL;
    return newNode;
}

// Function to insert a node at the end of the list
void appendNode(ListNode** head, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    ListNode* newNode = createNode(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);
    if (newNode == NULL) {
        return; // Handle memory allocation failure
    }
    if (*head == NULL) {
        *head = newNode;
    } else {
        ListNode* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

// Function to free the entire list
void freeList(ListNode** head) {
    ListNode* current = *head;
    ListNode* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

// Function to generate random CRC flag
int generateRandomCRCFlag() {
    return rand() % 2; // Randomly choose between 0 and 1
}

// Function to simulate external API call with retries and circuit breaker pattern
void callExternalAPI(ListNode* head) {
    static int failedAttempts = 0;
    static int lastSuccessTime = 0;
    const int maxRetries = 3;
    const int backoffFactor = 2;
    const int failureThreshold = 5;

    if (failedAttempts >= failureThreshold) {
        time_t currentTime = time(NULL);
        if ((currentTime - lastSuccessTime) < 60) { // Circuit breaker open
            return;
        }
    }

    // Simulate API call
    ListNode* temp = head;
    while (temp != NULL) {
        // Process each node (e.g., send to external system)
        printf("Processing node with RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n",
               temp->data.RX_UE_INFORMATION_TAG, temp->data.RNTI, temp->data.CRC_INDICATION_REL8_TAG);
        temp = temp->next;
    }

    // Reset failed attempts and update last success time
    failedAttempts = 0;
    lastSuccessTime = time(NULL);
}

// Main function to create and process linked list of NFapi structures
int main() {
    srand(time(NULL)); // Seed random number generator
    ListNode* head = NULL;

    // Populate the linked list with NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < 10; i++) {
        appendNode(&head, i, rand() % 1000, generateRandomCRCFlag());
    }

    // Call external API
    callExternalAPI(head);

    // Free the linked list
    freeList(&head);

    return 0;
}
```

