from typing import Dict, Any, Union
import json
import logging
from threading import Lock
import requests
from abc import ABC, abstractmethod

class ConfigSchema(ABC):
    @abstractmethod
    def validate(self, config: Dict[str, Any]) -> bool:
        pass

class DevelopmentSchema(ConfigSchema):
    def validate(self, config: Dict[str, Any]) -> bool:
        required_keys = ["db_url", "debug_mode"]
        return all(key in config for key in required_keys)

class StagingSchema(ConfigSchema):
    def validate(self, config: Dict[str, Any]) -> bool:
        required_keys = ["db_url", "api_key"]
        return all(key in config for key in required_keys)

class ProductionSchema(ConfigSchema):
    def validate(self, config: Dict[str, Any]) -> bool:
        required_keys = ["db_url", "secret_key"]
        return all(key in config for key in required_keys)

class ConfigManager:
    def __init__(self, environment: str, schema: ConfigSchema):
        self.environment = environment
        self.schema = schema
        self.lock = Lock()
        self.config = {}
        self.load_config()

    def load_config(self) -> None:
        # Load configuration from a file or database based on the environment
        pass

    def update_config(self, new_config: Dict[str, Any]) -> None:
        with self.lock:
            if self.schema.validate(new_config):
                self.config = new_config
                self.save_config()
            else:
                raise ValueError("Invalid configuration")

    def save_config(self) -> None:
        # Save the configuration to a file or database
        pass

class DataFetcher:
    @abstractmethod
    async def fetch_data(self) -> Dict[str, Any]:
        pass

class APIDataFetcher(DataFetcher):
    async def fetch_data(self) -> Dict[str, Any]:
        response = await requests.get("https://api.example.com/config")
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception("Failed to fetch data")

class ConfigService:
    def __init__(self, config_manager: ConfigManager):
        self.config_manager = config_manager

    async def update_config_with_data(self) -> None:
        fetcher = APIDataFetcher()
        try:
            new_data = await fetcher.fetch_data()
            self.config_manager.update_config(new_data)
        except Exception as e:
            logging.error(f"Failed to update config with data: {e}")

# Example usage
if __name__ == "__main__":
    schema_mapping = {
        "development": DevelopmentSchema(),
        "staging": StagingSchema(),
        "production": ProductionSchema()
    }

    env = "development"
    config_manager = ConfigManager(env, schema_mapping[env])
    service = ConfigService(config_manager)
    import asyncio
    asyncio.run(service.update_config_with_data())
```

