class IoTDataProcessor {
public:
    void startProcessing() {
        // Start worker threads for processing
        for (size_t i = 0; i < numWorkers; ++i) {
            workers.emplace_back(&IoTDataProcessor::workerThread, this);
        }
    }

    void stopProcessing() {
        // Stop all worker threads and wait for them to finish
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void enqueueData(const std::string& data) {
        // Enqueue new data to be processed
        {
            std::unique_lock<std::mutex> lock(mutex);
            queue.push(data);
        }
        condition.notify_one();
    }

private:
    std::vector<std::thread> workers;
    std::queue<std::string> queue;
    std::mutex mutex;
    std::condition_variable condition;
    bool stop = false;
    size_t numWorkers = 4; // Adjust based on system capabilities

    void workerThread() {
        while (true) {
            std::string data;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condition.wait(lock, [this] { return !queue.empty() || stop; });
                if (stop && queue.empty()) {
                    break;
                }
                data = queue.front();
                queue.pop();
            }

            // Process the data
            processData(data);
        }
    }

    void processData(const std::string& data) {
        // Implement data processing logic here
        std::cout << "Processing data: " << data << std::endl;
    }
};

int main() {
    IoTDataProcessor processor;
    processor.startProcessing();

    // Simulate enqueuing data
    for (size_t i = 0; i < 10000; ++i) {
        std::string data = "Sensor" + std::to_string(i) + ",Value," + std::to_string(rand() % 100);
        processor.enqueueData(data);
    }

    processor.stopProcessing();
    return 0;
}
