void insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& insertStr) {
    auto it = list.begin();
    bool found = false;

    while (it != list.end()) {
        if (*it == target) {
            found = true;
            ++it; // Move to the next element after the target
            list.insert_after(prev(it), insertStr); // Insert before moving forward
            break;
        }
        ++it;
    }

    if (!found) {
        std::cout << "Target string not found." << std::endl;
    }
}

int main() {
