class TCPConnectionPool {
public:
    void AddConnection(int id, const std::string& remote_addr, const std::string& local_addr) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (connections_.find(id) != connections_.end()) {
            // Handle duplicate entry using retry logic with backoff
            for (int i = 0; i < MAX_RETRIES; ++i) {
                auto result = AddConnectionWithRetry(id, remote_addr, local_addr);
                if (result) {
                    return;
                }
                std::this_thread::sleep_for(std::chrono::seconds(BACKOFF_MULTIPLIER * i));
            }
            // Handle max retries exceeded
            std::cerr << "Failed to add connection after " << MAX_RETRIES << " retries." << std::endl;
        } else {
            connections_[id] = {id, remote_addr, local_addr, std::chrono::system_clock::now()};
        }
    }

private:
    std::unordered_map<int, TCP_CONNECTION_RECORD> connections_;
    std::mutex mutex_;
    const int MAX_RETRIES = 5;
    const int BACKOFF_MULTIPLIER = 2;

    bool AddConnectionWithRetry(int id, const std::string& remote_addr, const std::string& local_addr) {
        // Simulate API call with potential failure
        if (std::rand() % 10 < 3) { // 30% chance of failure for demonstration purposes
            return false;
        }
        connections_[id] = {id, remote_addr, local_addr, std::chrono::system_clock::now()};
        return true;
    }
};

