public:
    TCPConnectionManager(int max_connections) : max_connections_(max_connections), backoff_factor_(2) {}

    bool addConnection(const TCP_CONNECTION_RECORD& record) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (connections_.find(record.CONN_ID) != connections_.end()) {
            return false;
        }
        connections_[record.CONN_ID] = record;
        return true;
    }

    void removeConnection(const std::string& conn_id) {
        std::lock_guard<std::mutex> lock(mutex_);
        connections_.erase(conn_id);
    }

    TCP_CONNECTION_RECORD* getConnection(const std::string& conn_id) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = connections_.find(conn_id);
        if (it != connections_.end()) {
            return &it->second;
        }
        return nullptr;
    }

private:
    int max_connections_;
    double backoff_factor_;
    std::unordered_map<std::string, TCP_CONNECTION_RECORD> connections_;
    std::mutex mutex_;
};

