LTE_Dynamic_Array* lte_dynamic_array_init(size_t initial_capacity) {
    LTE_Dynamic_Array* array = malloc(sizeof(LTE_Dynamic_Array));
    if (!array) return NULL;

    array->messages = malloc(initial_capacity * sizeof(LTE_Uplink_NAS_Message));
    if (!array->messages) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->mutex, NULL);
    array->log_file = fopen("operation_stats.log", "w");
    if (!array->log_file) {
        perror("Failed to open log file");
    }

    return array;
}

void lte_dynamic_array_free(LTE_Dynamic_Array* array) {
    pthread_mutex_lock(&array->mutex);
    free(array->messages);
    fclose(array->log_file);
    pthread_mutex_unlock(&array->mutex);
    free(array);
}

int lte_dynamic_array_append(LTE_Dynamic_Array* array, LTE_Uplink_NAS_Message msg) {
    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_Uplink_NAS_Message* new_messages = realloc(array->messages, new_capacity * sizeof(LTE_Uplink_NAS_Message));
        if (!new_messages) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }
        array->messages = new_messages;
        array->capacity = new_capacity;
    }

    array->messages[array->size++] = msg;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

