        fprintf(stderr, "Cannot prepare statement: %s\n", sqlite3_errmsg(manager->db));
        return -1;
    }
    while ((rc = sqlite3_step(stmt)) == SQLITE_ROW) {
        Record *record = allocate_record(manager);
        if (record) {
            record->id = sqlite3_column_int(stmt, 0);
            strncpy(record->name, (char*)sqlite3_column_text(stmt, 1), BUFFER_SIZE - 1);
            // Process the record
            manager->records[manager->count++] = *record;
        }
    }
    if (rc != SQLITE_DONE) {
        fprintf(stderr, "Cannot load records: %s\n", sqlite3_errmsg(manager->db));
        return -1;
    }
