#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/rand.h>

#define MAX_RECORDS 100000000

typedef struct {
    int value;
    char* metadata;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} record_pool;

record_pool* create_record_pool(size_t max_records) {
    record_pool* pool = (record_pool*)malloc(sizeof(record_pool));
    if (!pool) return NULL;

    pool->size = 0;
    pool->capacity = max_records;
    pool->offsets = (long*)malloc(max_records * sizeof(long));
    pool->keys = (int*)malloc(max_records * sizeof(int));
    pool->records = (record**)malloc(max_records * sizeof(record*));
    if (!pool->offsets || !pool->keys || !pool->records) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->mutex, NULL);

    return pool;
}

void destroy_record_pool(record_pool* pool) {
    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->records[i]->metadata) free(pool->records[i]->metadata);
        free(pool->records[i]);
    }
    pthread_mutex_destroy(&pool->mutex);
    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    free(pool);
}

int init_record(record_pool* pool, int key, char* metadata) {
    if (pool->size >= pool->capacity) return -1;

    record* rec = (record*)malloc(sizeof(record));
    if (!rec) return -1;
    rec->value = rand();
    rec->metadata = strdup(metadata);

