#include <stdlib.h>
#include <string.h>
#include <sqlite3.h>

typedef struct Record {
    int id;
    char name[100];
    // Add other fields as needed
} Record;

typedef struct RecordManager {
    sqlite3 *db;
    void (*record_validator)(Record*);
} RecordManager;

void record_validator_default(Record* record) {
    if (record->id <= 0 || strlen(record->name) == 0) {
        fprintf(stderr, "Invalid record: ID must be positive and name cannot be empty.\n");
        exit(EXIT_FAILURE);
    }
}

RecordManager* record_manager_init(const char* db_path) {
    RecordManager *rm = (RecordManager*)malloc(sizeof(RecordManager));
    if (!sqlite3_open(db_path, &rm->db)) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(rm->db));
        exit(EXIT_FAILURE);
    }
    rm->record_validator = record_validator_default;
    return rm;
}

void record_manager_insert(RecordManager *rm, Record* record) {
    rm->record_validator(record);

    char *sql = "INSERT INTO records (id, name) VALUES (?, ?)";
    sqlite3_stmt *stmt;
    if (sqlite3_prepare_v2(rm->db, sql, -1, &stmt, 0) != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare statement: %s\n", sqlite3_errmsg(rm->db));
        exit(EXIT_FAILURE);
    }

    sqlite3_bind_int(stmt, 1, record->id);
    sqlite3_bind_text(stmt, 2, record->name, -1, SQLITE_STATIC);

    if (sqlite3_step(stmt) != SQLITE_DONE) {
        fprintf(stderr, "Failed to insert record: %s\n", sqlite3_errmsg(rm->db));
        exit(EXIT_FAILURE);
    }

    sqlite3_finalize(stmt);
}

void record_manager_free(RecordManager *rm) {
    sqlite3_close(rm->db);
    free(rm);
}
```

