#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define record structure
typedef struct {
    int value;
    char* metadata;
} Record;

// Define dynamic collection structure
typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicCollection;

// Function to initialize dynamic collection
DynamicCollection* init_dynamic_collection(size_t max_records) {
    DynamicCollection* collection = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    if (!collection) return NULL;

    collection->capacity = max_records;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);

    collection->offsets = (long*)malloc(max_records * sizeof(long));
    collection->keys = (int*)malloc(max_records * sizeof(int));
    collection->records = (Record**)malloc(max_records * sizeof(Record*));

    if (!collection->offsets || !collection->keys || !collection->records) {
        free(collection);
        return NULL;
    }

    memset(collection->offsets, 0, max_records * sizeof(long));
    memset(collection->keys, 0, max_records * sizeof(int));
    memset(collection->records, 0, max_records * sizeof(Record*));

    return collection;
}

// Function to add record to dynamic collection
int add_record(DynamicCollection* collection, int key, Record* record) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->size >= collection->capacity) {
        pthread_mutex_unlock(&collection->mutex);
        return -1; // Collection is full
    }

    collection->keys[collection->size] = key;
    collection->records[collection->size] = record;
    collection->offsets[collection->size] = (long)(record - collection->records);
    collection->size++;
    pthread_mutex_unlock(&collection->mutex);

    return 0; // Success
}

// Function to get record from dynamic collection by key
Record* get_record(DynamicCollection* collection, int key) {
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->size; i++) {
        if (collection->keys[i] == key) {
            Record* record = collection->records[i];
            pthread_mutex_unlock(&collection->mutex);
            return record;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
    return NULL; // Record not found
}

// Function to free dynamic collection
void free_dynamic_collection(DynamicCollection* collection) {
    for (size_t i = 0; i < collection->size; i++) {
        free(collection->records[i]->metadata);
        free(collection->records[i]);
    }
    free(collection->offsets);
    free(collection->keys);
    free(collection->records);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}
