// Include necessary headers
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure for records
typedef struct {
    int id;
    char name[100];
} Record;

// Define a structure for the record manager
typedef struct {
    Record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordManager;

// Initialize the record manager
RecordManager* record_manager_init(size_t initial_capacity) {
    RecordManager *rm = (RecordManager*)malloc(sizeof(RecordManager));
    if (!rm) return NULL;
    rm->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!rm->records) {
        free(rm);
        return NULL;
    }
    rm->capacity = initial_capacity;
    rm->size = 0;
    pthread_mutex_init(&rm->lock, NULL);
    return rm;
}

// Add a record to the manager
int record_manager_add(RecordManager *rm, Record record) {
    pthread_mutex_lock(&rm->lock);
    if (rm->size >= rm->capacity) {
        size_t new_capacity = rm->capacity * 2;
        Record *new_records = (Record*)realloc(rm->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&rm->lock);
            return -1; // Memory allocation failure
        }
        rm->records = new_records;
        rm->capacity = new_capacity;
    }
    rm->records[rm->size++] = record;
    pthread_mutex_unlock(&rm->lock);
    return 0;
}

// Get a record by index
Record* record_manager_get(RecordManager *rm, size_t index) {
    if (index >= rm->size) return NULL; // Invalid index
    return &rm->records[index];
}

// Free the record manager and its records
void record_manager_free(RecordManager *rm) {
    free(rm->records);
    pthread_mutex_destroy(&rm->lock);
    free(rm);
}
