#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000000000

typedef struct {
    int id;
    char data[128];
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    int count;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection collection;

void init_collection() {
    memset(&collection, 0, sizeof(collection));
    pthread_mutex_init(&collection.lock, NULL);
}

void add_record(int id, const char* data) {
    pthread_mutex_lock(&collection.lock);
    if (collection.count < MAX_RECORDS) {
        Record* record = &collection.records[collection.count++];
        record->id = id;
        strncpy(record->data, data, sizeof(record->data) - 1);
    } else {
        printf("Collection is full!\n");
    }
    pthread_mutex_unlock(&collection.lock);
}

void get_record(int id, char* buffer) {
    pthread_mutex_lock(&collection.lock);
    for (int i = 0; i < collection.count; ++i) {
        if (collection.records[i].id == id) {
            strncpy(buffer, collection.records[i].data, sizeof(buffer));
            break;
        }
    }
    pthread_mutex_unlock(&collection.lock);
}

void* process_records(void* arg) {
    int thread_id = *(int*)arg;
    for (int i = thread_id; i < MAX_RECORDS; i += 10) {
        char buffer[128];
        get_record(i, buffer);
        // Process the record
        printf("Thread %d processed record %d: %s\n", thread_id, i, buffer);
    }
    return NULL;
}

int main() {
    init_collection();

    for (int i = 0; i < MAX_RECORDS; ++i) {
        add_record(i, "Sample data");
    }

    pthread_t threads[10];
    int thread_ids[10];

    for (int i = 0; i < 10; ++i) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, process_records, &thread_ids[i]);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

