    char data[1024];
} Record;

// Define a structure for the database
typedef struct {
    Record* records;
    size_t count;
    size_t capacity;
} Database;

// Function to initialize the database
Database* db_init(size_t initial_capacity) {
    Database* db = (Database*)malloc(sizeof(Database));
    if (!db) return NULL;

    db->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!db->records) {
        free(db);
        return NULL;
    }

    db->count = 0;
    db->capacity = initial_capacity;
    return db;
}

// Function to insert a record into the database
int db_insert(Database* db, Record record) {
    if (db->count >= db->capacity) {
        size_t new_capacity = db->capacity * 2;
        Record* new_records = (Record*)realloc(db->records, new_capacity * sizeof(Record));
        if (!new_records) return -1;

        db->records = new_records;
        db->capacity = new_capacity;
    }

    db->records[db->count++] = record;
    return 0;
}

// Function to free the database
void db_free(Database* db) {
    if (db) {
        free(db->records);
        free(db);
    }
}
