['```python
import logging
from collections import deque
import threading
import time
import json
from abc import ABC, abstractmethod
import os

class LogEvent:
    def __init__(self, level, message, context=None):
        self.level = level
        self.message = message
        self.context = context or {}

class Logger(ABC):
    @abstractmethod
    def log(self, event: LogEvent) -> None:
        pass

class ConsoleLogger(Logger):
    def log(self, event: LogEvent) -> None:
        print(f"{event.level}: {event.message} - {event.context}")

class FileLogger(Logger):
    def __init__(self, file_path):
        self.file_path = file_path
        self.queue = deque()

    def log(self, event: LogEvent) -> None:
        self.queue.append(event)
        if len(self.queue) > 100:
            self._flush_to_file()

    def _flush_to_file(self):
        with open(self.file_path, 'a') as file:
            for event in self.queue:
                file.write(json.dumps({
                    "level": event.level,
                    "message": event.message,
                    "context": event.context
                }) + '\n')
            self.queue.clear()

class AsyncLogger(Logger):
    def __init__(self, logger: Logger):
        self.logger = logger
        self.queue = deque()
        self.thread = threading.Thread(target=self._worker)
        self.thread.start()

    def log(self, event: LogEvent) -> None:
        self.queue.append(event)

    def _worker(self):
        while True:
            if self.queue:
                event = self.queue.popleft()
                self.logger.log(event)
            time.sleep(0.1)

class LoggerManager:
    def __init__(self, logger: Logger):
        self.logger = logger

    def log(self, level, message, context=None) -> None:
        event = LogEvent(level, message, context)
        self.logger.log(event)

def setup_logging():
    logger = ConsoleLogger()
    # Uncomment the following line to use a file logger
    # logger = FileLogger('logs.txt')
    async_logger = AsyncLogger(logger)
    return LoggerManager(async_logger)

# Usage example
logger_manager = setup_logging()

# Log some events
logger_manager.log(logging.INFO, "User logged in", {"user_id": 123})
logger_manager.log(logging.ERROR, "Database connection failed")
```

This code provides a basic implementation of a scalable and modular logging framework in Python. It includes different types of loggers (ConsoleLogger, FileLogger) and an asynchronous logger to handle real-time log ingestion without blocking the application threads. The LoggerManager class allows for easy configuration and usage of the logging system.']

