from abc import ABC, abstractmethod
import json
import os
import time
from datetime import datetime

class LogEvent:
    def __init__(self, level, message, context):
        self.level = level
        self.message = message
        self.context = context

class Logger(ABC):
    @abstractmethod
    def log(self, event: LogEvent) -> None:
        pass

class ConsoleLogger(Logger):
    def log(self, event: LogEvent) -> None:
        print(f"{event.level}: {event.message}")

class FileLogger(Logger):
    def __init__(self, filename):
        self.filename = filename

    def log(self, event: LogEvent) -> None:
        with open(self.filename, 'a') as file:
            file.write(json.dumps(event.__dict__))  # Simplified for demonstration

class CloudStorageLogger(Logger):
    def log(self, event: LogEvent) -> None:
        # Implement cloud storage integration
        pass

class LogPolicy(ABC):
    @abstractmethod
    def should_log(self, event: LogEvent) -> bool:
        pass

class TimeOfDayLogPolicy(LogPolicy):
    def should_log(self, event: LogEvent) -> bool:
        current_hour = datetime.now().hour
        return 9 <= current_hour < 17  # Log during office hours

class UserIDLogPolicy(LogPolicy):
    def should_log(self, event: LogEvent) -> bool:
        user_id = event.context.get('user_id')
        return user_id in ['admin', 'support']  # Log for specific users

class ApplicationStateLogPolicy(LogPolicy):
    def should_log(self, event: LogEvent) -> bool:
        state = event.context.get('application_state')
        return state == 'production'  # Log only in production

class GeoLocationLogPolicy(LogPolicy):
    def should_log(self, event: LogEvent) -> bool:
        location = event.context.get('geographical_location')
        return location.startswith('US')  # Log for users in the US

class LoggerPipeline:
    def __init__(self, loggers: list, policies: list):
        self.loggers = loggers
        self.policies = policies

    def add_logger(self, logger: Logger) -> None:
        self.loggers.append(logger)

    def add_policy(self, policy: LogPolicy) -> None:
        self.policies.append(policy)

    def log_event(self, event: LogEvent) -> None:
        if all(policy.should_log(event) for policy in self.policies):
            for logger in self.loggers:
                logger.log(event)

class AsyncLoggerPipeline(LoggerPipeline):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        # Implement asynchronous processing

# Usage example
logger_pipeline = LoggerPipeline(
    loggers=[ConsoleLogger(), FileLogger('app.log'), CloudStorageLogger()],
    policies=[TimeOfDayLogPolicy(), UserIDLogPolicy()]
)

event = LogEvent(level='INFO', message='Application started', context={'user_id': 'admin', 'geographical_location': 'US'})
logger_pipeline.log_event(event)
