    public SensorDataController(SensorDataService sensorDataService) {
        this.sensorDataService = sensorDataService;
    }

    @Post(value = "/", consumes = MediaType.APPLICATION_JSON)
    public HttpResponse<String> processSensorData(HttpRequest<InputStream> request) {
        try (InputStream inputStream = request.getBody().orElseThrow(() -> new IllegalArgumentException("No data provided"))) {
            sensorDataService.processData(inputStream);
            return HttpResponse.ok("Data processed successfully");
        } catch (Exception e) {
            return HttpResponse.serverError(e.getMessage());
        }
    }
}
