#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <stdio.h>

void encrypt_data(const char *password, const unsigned char *data, size_t data_len, unsigned char **encrypted_data, int *encrypted_len) {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32], iv[16];
    unsigned char salt[16];
    int outlen;

    // Generate a random salt
    if (!RAND_bytes(salt, sizeof(salt))) {
        fprintf(stderr, "Failed to generate salt\n");
        return;
    }

    // Derive the 32-byte AES key using PBKDF2 with SHA-256 and the random salt
    if (PKCS5_PBKDF2_HMAC(password, strlen(password), salt, sizeof(salt), 10000, EVP_sha256(), sizeof(key), key) != 1) {
        fprintf(stderr, "Failed to derive AES key\n");
        return;
    }

    // Generate a random IV
    if (!RAND_bytes(iv, sizeof(iv))) {
        fprintf(stderr, "Failed to generate IV\n");
        return;
    }

    *encrypted_data = malloc(data_len + EVP_CIPHER_block_size(EVP_aes_256_cbc()));
    if (!*encrypted_data) {
        fprintf(stderr, "Failed to allocate memory for encrypted data\n");
        return;
    }

    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create encryption context\n");
        free(*encrypted_data);
        return;
    }

    // Initialize the AES-256-CBC cipher with the derived key and IV
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Failed to initialize encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        free(*encrypted_data);
        return;
    }

    // Encrypt the data
    if (1 != EVP_EncryptUpdate(ctx, *encrypted_data, &outlen, data, data_len)) {
        fprintf(stderr, "Failed to encrypt data\n");
        EVP_CIPHER_CTX_free(ctx);
        free(*encrypted_data);
        return;
    }
    *encrypted_len = outlen;

    // Finalize the encryption
    if (1 != EVP_EncryptFinal_ex(ctx, (*encrypted_data + outlen), &outlen)) {
        fprintf(stderr, "Failed to finalize encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        free(*encrypted_data);
        return;
    }
    *encrypted_len += outlen;

    // Clean up resources
    EVP_CIPHER_CTX_free(ctx);
}
