#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <vector>
#include <atomic>

class IoTDataProcessor {
private:
    std::queue<std::string> dataQueue;
    std::mutex queueMutex;
    std::condition_variable queueCond;
    std::atomic<bool> running;
    int numThreads;

public:
    IoTDataProcessor(int threads) : numThreads(threads), running(true) {}

    void start() {
        for (int i = 0; i < numThreads; ++i) {
            std::thread(&IoTDataProcessor::processData, this).detach();
        }
    }

    void stop() {
        running.store(false);
        queueCond.notify_all();
    }

    void addData(const std::string& data) {
        std::lock_guard<std::mutex> lock(queueMutex);
        dataQueue.push(data);
        queueCond.notify_one();
    }

private:
    void processData() {
        while (running.load()) {
            std::unique_lock<std::mutex> lock(queueMutex);
            queueCond.wait(lock, [this] { return !dataQueue.empty() || !running.load(); });

            if (!running.load()) break;

            std::string data = dataQueue.front();
            dataQueue.pop();
            lock.unlock();

            // Process data (e.g., aggregation, filtering)
            processSingleData(data);
        }
    }

    void processSingleData(const std::string& data) {
        // Example processing logic
        std::cout << "Processing data: " << data << std::endl;
    }
};

int main() {
    IoTDataProcessor processor(4);

    processor.start();

    // Simulate adding data to the system
    for (int i = 0; i < 100; ++i) {
        std::string data = "SensorData_" + std::to_string(i);
        processor.addData(data);
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }

    std::this_thread::sleep_for(std::chrono::seconds(2));

    processor.stop();

    return 0;
}
```

