// Thread function for concurrent ingestion and processing
void* threadFunction(void* arg) {
    char** batch = (char**)customAllocator(RECORD_BATCH_SIZE * sizeof(char*));
    int batchSize = 0;

    while (1) {
        // Simulate data ingestion from a high-throughput stream
        char* newData = (char*)customAllocator(1024); // Assume each record is up to 1KB
        if (validateData(newData)) {
            batch[batchSize++] = newData;
            if (batchSize == RECORD_BATCH_SIZE) {
                // Process and store the batch of records
                for (int i = 0; i < batchSize; i++) {
                    processData(batch[i]);
                    storeData(batch[i]);
                    customFree(batch[i]);
                }
                batchSize = 0;
            }
