        }

        // Sleep or yield to other threads
        sched_yield();
    }

    // Free any remaining batch records
    for (int i = 0; i < batchSize; i++) customFree(batch[i]);
    customFree(batch);

    return NULL;
}

// Main function to create and manage threads
