    pthread_t threads[MAX_CONCURRENT_THREADS];

    // Create threads for concurrent ingestion and processing
    for (int i = 0; i < MAX_CONCURRENT_THREADS; i++) {
        if (pthread_create(&threads[i], NULL, threadFunction, NULL) != 0) {
