#define GROWTH_FACTOR 2

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    size_t capacity;
} CRCIndicationsArray;

void initialize_crc_array(CRCIndicationsArray *array) {
    array->count = 0;
    array->capacity = INITIAL_CAPACITY;
    array->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void free_crc_array(CRCIndicationsArray *array) {
    free(array->data);
    array->count = 0;
    array->capacity = 0;
    array->data = NULL;
}

bool resize_crc_array(CRCIndicationsArray *array, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        return false;
    }
    array->data = new_data;
    array->capacity = new_capacity;
    return true;
}

bool populate_crc_indications(CRCIndicationsArray *array) {
    srand(time(NULL)); // Seed for random number generation
    if (array->count == array->capacity && !resize_crc_array(array, array->capacity * GROWTH_FACTOR)) {
        return false; // Resize failed
