    List<Activity> findByTimestampRange(@Param("startTime") Date startTime, @Param("endTime") Date endTime);
}

// Define the client for interacting with third-party analytics platform
@Service
public class ThirdPartyAnalyticsClient {

    private final RestTemplate restTemplate;

    @Autowired
    public ThirdPartyAnalyticsClient(RestTemplate restTemplate) {
        this.restTemplate = restTemplate;
    }

    public void sendData(Activity activity) throws RateLimitException, ServiceUnavailableException {
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        HttpEntity<String> request = new HttpEntity<>(new ObjectMapper().writeValueAsString(activity), headers);

        try {
            ResponseEntity<String> response = restTemplate.postForEntity("https://thirdpartyapi.com/analytics", request, String.class);
            if (response.getStatusCode() == HttpStatus.TOO_MANY_REQUESTS) {
                throw new RateLimitException();
            } else if (!response.getStatusCode().is2xxSuccessful()) {
                throw new ServiceUnavailableException();
            }
        } catch (RestClientResponseException e) {
            if (e.getStatusCode() == HttpStatus.TOO_MANY_REQUESTS) {
                throw new RateLimitException();
            } else if (e.getStatusCode() == HttpStatus.SERVICE_UNAVAILABLE || e.getStatusCode() == HttpStatus.GATEWAY_TIMEOUT) {
                throw new ServiceUnavailableException();
            }
        }
    }
}

// Define custom exceptions for handling API rate limits and outages
class RateLimitException extends RuntimeException {}

class ServiceUnavailableException extends RuntimeException {}
