#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>

class CombatSystem {
public:
    CombatSystem(size_t numThreads) : stop(false), workerThreads(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            workerThreads[i] = std::thread(&CombatSystem::worker, this);
        }
    }

    ~CombatSystem() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        for (auto& thread : workerThreads) {
            thread.join();
        }
    }

    void addTask(const std::function<void()>& task) {
        {
            std::unique_lock<std::mutex> lock(mutex);
            tasks.push(task);
        }
        condition.notify_one();
    }

private:
    void worker() {
        while (true) {
            std::function<void()> task;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condition.wait(lock, [this] { return stop || !tasks.empty(); });
                if (stop && tasks.empty()) {
                    return;
                }
                task = std::move(tasks.front());
                tasks.pop();
            }
            task();
        }
    }

    bool stop;
    std::vector<std::thread> workerThreads;
    std::queue<std::function<void()>> tasks;
    std::mutex mutex;
    std::condition_variable condition;
};

int main() {
    CombatSystem combatSystem(4);

    // Add tasks to the system
    for (int i = 0; i < 10; ++i) {
        combatSystem.addTask([i] {
            std::cout << "Processing task " << i << std::endl;
        });
    }

    return 0;
}
