#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <functional>
#include <chrono>
#include <atomic>

class NetworkEventDispatcher {
public:
    using Event = std::function<void()>;
    using Listener = std::function<void(const Event& event)>;

    NetworkEventDispatcher(size_t maxEvents) : maxEvents(maxEvents), stop(false) {}

    void subscribe(Listener listener, const std::vector<int>& eventTypes) {
        std::unique_lock<std::mutex> lock(mutex);
        listeners[listener] = eventTypes;
        cv.notify_one();
    }

    void unsubscribe(Listener listener) {
        std::unique_lock<std::mutex> lock(mutex);
        listeners.erase(listener);
        cv.notify_one();
    }

    void dispatchEvent(const Event& event, int eventType) {
        std::unique_lock<std::mutex> lock(mutex);
        events.push({event, eventType});
        if (events.size() == maxEvents) {
            cv.notify_all();
        }
    }

    void run() {
        std::thread([this]() {
            while (!stop) {
                std::unique_lock<std::mutex> lock(mutex);
                cv.wait(lock, [this] { return !events.empty() || stop; });
                if (stop && events.empty()) break;

                Event event;
                int eventType;
                std::tie(event, eventType) = events.front();
                events.pop();

                lock.unlock();
                processEvent(event, eventType);
            }
        }).detach();
    }

    void stopRunning() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        cv.notify_all();
    }

private:
    struct EventInfo {
        Event event;
        int eventType;
    };

    std::queue<EventInfo> events;
    std::unordered_map<Listener, std::vector<int>> listeners;
    std::mutex mutex;
    std::condition_variable cv;
    size_t maxEvents;
    std::atomic<bool> stop;

    void processEvent(const Event& event, int eventType) {
        for (const auto& [listener, types] : listeners) {
            if (std::find(types.begin(), types.end(), eventType) != types.end()) {
                listener(event);
            }
        }
    }
};

int main() {
    NetworkEventDispatcher dispatcher(100);

    dispatcher.subscribe([](const NetworkEventDispatcher::Event& event) {
        std::cout << "Listener 1 received event" << std::endl;
    }, {1, 2});

    dispatcher.subscribe([](const NetworkEventDispatcher::Event& event) {
        std::cout << "Listener 2 received event" << std::endl;
    }, {3});

    dispatcher.run();

    dispatcher.dispatchEvent([]{ std::cout << "Event 1" << std::endl; }, 1);
    dispatcher.dispatchEvent([]{ std::cout << "Event 2" << std::endl; }, 2);
    dispatcher.dispatchEvent([]{ std::cout << "Event 3" << std::endl; }, 3);

    dispatcher.stopRunning();
    return 0;
}
