#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <functional>

class NetworkEventDispatcher {
public:
    NetworkEventDispatcher() : running(true), leader(false) {}

    ~NetworkEventDispatcher() {
        stop();
    }

    void addListener(std::function<void(int)> listener, int eventTypes) {
        std::lock_guard<std::mutex> lock(mutex);
        listeners.push_back({listener, eventTypes});
    }

    void removeListener(const std::function<void(int)>& listener) {
        std::lock_guard<std::mutex> lock(mutex);
        listeners.erase(std::remove_if(listeners.begin(), listeners.end(),
                                       [listener](const Listener& l) { return &l.listener == &listener; }),
                         listeners.end());
    }

    void dispatchEvent(int event) {
        std::unique_lock<std::mutex> lock(mutex);
        events.push(event);
        lock.unlock();
        cv.notify_one();
    }

    void start() {
        for (int i = 0; i < numThreads; ++i) {
            workers.emplace_back([this]() { workerThread(); });
        }
    }

    void stop() {
        running = false;
        cv.notify_all();
        for (std::thread& w : workers) {
            w.join();
        }
    }

private:
    struct Listener {
        std::function<void(int)> listener;
        int eventTypes;
    };

    std::vector<Listener> listeners;
    std::queue<int> events;
    std::mutex mutex;
    std::condition_variable cv;
    std::vector<std::thread> workers;
    bool running;
    bool leader;

    void workerThread() {
        while (true) {
            int event;
            {
                std::unique_lock<std::mutex> lock(mutex);
                cv.wait(lock, [this]() { return !running || !events.empty(); });
                if (!running && events.empty()) {
                    break;
                }
                event = events.front();
                events.pop();
            }

            for (const auto& listener : listeners) {
                if ((listener.eventTypes & (1 << event)) != 0) {
                    listener.listener(event);
                }
            }
        }
    }
};
