#include <thread>
#include <mutex>
#include <queue>
#include <condition_variable>
#include <fstream>
#include <zlib.h>

class Logger {
public:
    void log(const std::string& message) {
        std::lock_guard<std::mutex> lock(mutex_);
        logs_.push(message);
        cv_.notify_one();
    }

    std::string getLog() {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this] { return !logs_.empty(); });
        std::string message = logs_.front();
        logs_.pop();
        return message;
    }

private:
    std::queue<std::string> logs_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

class LogProcessor {
public:
    void processLog(const std::string& log) {
        if (log.empty()) return;

        // Parse the log
        std::string parsedLog = parseLog(log);

        // Compress the log
        std::string compressedLog = compressLog(parsedLog);

        // Index the log
        indexLog(compressedLog);
    }

private:
    std::string parseLog(const std::string& log) {
        // Logic to parse log based on format (JSON, YAML, text)
        return log;
    }

    std::string compressLog(const std::string& log) {
        z_stream stream;
        stream.zalloc = Z_NULL;
        stream.zfree = Z_NULL;
        stream.opaque = Z_NULL;

        deflateInit(&stream, Z_DEFAULT_COMPRESSION);
        stream.next_in = (Bytef*)log.c_str();
        stream.avail_in = log.size();

        std::vector<unsigned char> output(log.size() + 12);
        stream.next_out = (Bytef*)&output[0];
        stream.avail_out = output.size();

        deflate(&stream, Z_FINISH);
        deflateEnd(&stream);

        return std::string((char*)&output[0], output.size() - stream.avail_out);
    }

    void indexLog(const std::string& log) {
        // Logic to index log
    }
};

class LogManager {
public:
    static LogManager* getInstance() {
        if (instance_ == nullptr) {
            instance_ = new LogManager();
        }
        return instance_;
    }

    void startProcessing() {
        for (int i = 0; i < numThreads_; ++i) {
            threads_.emplace_back(&LogManager::processLogs, this);
        }
    }

    void stopProcessing() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            running_ = false;
        }
        cv_.notify_all();
        for (std::thread& thread : threads_) {
            thread.join();
        }
    }

    void addLog(const std::string& log) {
        logger_.log(log);
    }

private:
    LogManager() : numThreads_(4), running_(true) {}

    static LogManager* instance_;
    Logger logger_;
    std::vector<std::thread> threads_;
    int numThreads_;
    bool running_;

    void processLogs() {
        while (running_) {
            std::string log = logger_.getLog();
            if (!log.empty()) {
                processor_.processLog(log);
            }
        }
    }

    LogProcessor processor_;
};

LogManager* LogManager::instance_ = nullptr;

int main() {
    LogManager::getInstance()->startProcessing();

    // Simulate log ingestion
    for (int i = 0; i < 100; ++i) {
        std::string log = "Log entry " + std::to_string(i);
        LogManager::getInstance()->addLog(log);
    }

    // Stop processing
    LogManager::getInstance()->stopProcessing();

    return 0;
}
```

