using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading.Tasks;

public class DynamicRandomSequenceGenerator : IDisposable
{
    private readonly IConfigApi _configApi;
    private readonly IRngService _rngService;
    private readonly ConcurrentDictionary<string, (double min, double max)> _ranges;
    private readonly ConcurrentBag<double> _cache;
    private bool _disposed = false;

    public DynamicRandomSequenceGenerator(IConfigApi configApi, IRngService rngService)
    {
        _configApi = configApi ?? throw new ArgumentNullException(nameof(configApi));
        _rngService = rngService ?? throw new ArgumentNullException(nameof(rngService));

        _ranges = new ConcurrentDictionary<string, (double min, double max)>();
        _cache = new ConcurrentBag<double>();

        Task.Run(() => LoadConfig());
    }

    private async Task LoadConfig()
    {
        var config = await _configApi.GetConfigurationAsync();
        foreach (var range in config.Ranges)
        {
            _ranges.TryAdd(range.Key, (range.Min, range.Max));
        }
    }

    public T Generate<T>()
    {
        if (typeof(T) == typeof(float))
            return (T)(object)GenerateFloat();
        else if (typeof(T) == typeof(int))
            return (T)(object)GenerateInt();
        else if (typeof(T) == typeof(Vector3))
            return (T)(object)GenerateVector3();
        else if (typeof(T) == typeof(Vector2))
            return (T)(object)GenerateVector2();
        else
            throw new NotSupportedException($"Type {typeof(T)} is not supported.");
    }

    private float GenerateFloat()
    {
        var minMax = _ranges["FloatRange"];
        lock (_cache)
        {
            if (_cache.TryPeek(out double cached))
                return (float)cached;

            var randomValue = _rngService.NextDouble(minMax.min, minMax.max);
            _cache.Add(randomValue);
            return (float)randomValue;
        }
    }

    private int GenerateInt()
    {
        var minMax = _ranges["IntRange"];
        lock (_cache)
        {
            if (_cache.TryPeek(out double cached))
                return (int)cached;

            var randomValue = _rngService.Next((int)Math.Ceiling(minMax.min), (int)Math.Floor(minMax.max));
            _cache.Add(randomValue);
            return (int)randomValue;
        }
    }

    private Vector3 GenerateVector3()
    {
        var minMax = _ranges["Vector3Range"];
        lock (_cache)
        {
            if (_cache.TryPeek(out double cached))
                return new Vector3((float)cached);

            var randomX = _rngService.NextDouble(minMax.min, minMax.max);
            var randomY = _rngService.NextDouble(minMax.min, minMax.max);
            var randomZ = _rngService.NextDouble(minMax.min, minMax.max);
            var randomValue = new Vector3((float)randomX, (float)randomY, (float)randomZ);
            _cache.Add(randomValue.X);
            return randomValue;
        }
    }

    private Vector2 GenerateVector2()
    {
        var minMax = _ranges["Vector2Range"];
        lock (_cache)
        {
            if (_cache.TryPeek(out double cached))
                return new Vector2((float)cached);

            var randomX = _rngService.NextDouble(minMax.min, minMax.max);
            var randomY = _rngService.NextDouble(minMax.min, minMax.max);
            var randomValue = new Vector2((float)randomX, (float)randomY);
            _cache.Add(randomValue.X);
            return randomValue;
        }
    }

    public T[] GenerateSequence<T>(int length)
    {
        if (length <= 0)
            throw new ArgumentException("Length must be greater than zero.");

        var sequence = new T[length];
        for (int i = 0; i < length; i++)
            sequence[i] = Generate<T>();
        return sequence;
    }

    public void Dispose()
    {
        _disposed = true;
        // Clean up resources if needed
    }
}
```

