#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <future>
#include <chrono>

class JobQueue {
public:
    void enqueue(std::function<void()> job) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(job);
        lock.unlock();
        condition_.notify_one();
    }

    std::future<void> dequeue() {
        std::unique_lock<std::mutex> lock(mutex_);
        condition_.wait(lock, [this] { return !queue_.empty(); });
        auto job = std::move(queue_.front());
        queue_.pop();
        lock.unlock();
        return std::async(std::launch::async, std::move(job));
    }

private:
    std::mutex mutex_;
    std::condition_variable condition_;
    std::queue<std::function<void()>> queue_;
};

class JobManager {
public:
    JobManager(size_t numThreads) : stop_(false), threadCount_(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers_.emplace_back([this] {
                while (true) {
                    auto job = queue_.dequeue();
                    if (!job.valid())
                        break;
                    job.get(); // Execute the job
                }
            });
        }
    }

    ~JobManager() {
        stop_ = true;
        for (auto& worker : workers_)
            worker.join();
    }

    void submitJob(std::function<void()> job) {
        queue_.enqueue(job);
    }

private:
    JobQueue queue_;
    std::vector<std::thread> workers_;
    std::atomic<bool> stop_;
    size_t threadCount_;
};

int main() {
    JobManager manager(4);

    for (size_t i = 0; i < 10; ++i) {
        manager.submitJob([i] {
            std::cout << "Processing job " << i << std::endl;
            std::this_thread::sleep_for(std::chrono::seconds(i % 2 + 1));
            std::cout << "Finished job " << i << std::endl;
        });
    }

    return 0;
}
