// Import necessary libraries
const express = require('express');
const redis = require('redis');
const axios = require('axios');

// Initialize Express app
const app = express();
app.use(express.json());

// Connect to Redis for session storage
const client = redis.createClient({
  url: 'redis://session_redis'
});

client.on('error', (err) => {
  console.error('Redis error:', err);
});

// Middleware to load and execute JavaScript files
function loadJavaScriptFile(filePath) {
  return new Promise((resolve, reject) => {
    const fs = require('fs');
    fs.readFile(filePath, 'utf8', (err, data) => {
      if (err) return reject(err);
      try {
        eval(data); // Execute the JavaScript code
        resolve();
      } catch (execErr) {
        reject(execErr);
      }
    });
  });
}

// Route to handle session management
app.post('/session', async (req, res) => {
  const sessionId = req.body.sessionId;

  try {
    // Attempt to retrieve session from cache
    let sessionData = await client.getAsync(sessionId);

    if (!sessionData) {
      // If not found in cache, fetch data from database or external APIs
      sessionData = await fetchDataFromDBOrAPI(sessionId);

      // Store the new session data in Redis with an expiration time
      await client.setexAsync(sessionId, 3600, JSON.stringify(sessionData));
    }

    // Load and execute JavaScript files
    try {
      await loadJavaScriptFile('path/to/required/file.js');
    } catch (jsErr) {
      console.error('JavaScript file error:', jsErr);
    }

    res.json({ success: true, sessionData });
  } catch (err) {
    console.error('Session management error:', err);
    res.status(500).json({ success: false, message: 'Internal server error' });
  }
});

// Function to fetch data from database or external APIs
async function fetchDataFromDBOrAPI(sessionId) {
  try {
    // Example API call using axios
    const response = await axios.get(`https://api.example.com/data/${sessionId}`);
    return response.data;
  } catch (apiErr) {
    console.error('API fetch error:', apiErr);
    throw new Error('Failed to fetch data');
  }
}

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
