public class PokemonWeaknessService {
    // Configuration properties and dependencies
    private final ExternalApiService externalApiService;
    private final DistributedCache cache;
    private final RuleEngine ruleEngine;
    private final HealthCheck healthCheck;
    private final Logger logger;

    public PokemonWeaknessService(ExternalApiService externalApiService, 
                                   DistributedCache cache, 
                                   RuleEngine ruleEngine, 
                                   HealthCheck healthCheck, 
                                   Logger logger) {
        this.externalApiService = externalApiService;
        this.cache = cache;
        this.ruleEngine = ruleEngine;
        this.healthCheck = healthCheck;
        this.logger = logger;
    }

    // Endpoint to retrieve Pokémon weaknesses
    public ResponseEntity<String> getPokemonWeaknesses(String pokemonName) {
        try {
            // Check cache first
            String cachedData = cache.get(pokemonName);
            if (cachedData != null) {
                return ResponseEntity.ok(cachedData);
            }

            // Fetch data from external APIs
            List<WeaknessInfo> weaknesses = externalApiService.fetchWeaknesses(pokemonName);

            // Apply business logic and prioritize data sources
            WeaknessInfo consolidatedWeaknesses = ruleEngine.applyBusinessLogic(weaknesses);

            // Store result in cache
            cache.put(pokemonName, consolidatedWeaknesses.toJson());

            return ResponseEntity.ok(consolidatedWeaknesses.toJson());
        } catch (Exception e) {
            logger.error("Error retrieving Pokémon weaknesses: ", e);
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).build();
        }
    }

    // Health check endpoint
    public ResponseEntity<String> healthCheck() {
        if (healthCheck.isHealthy()) {
            return ResponseEntity.ok("Service is healthy");
        } else {
            return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE).body("Service is unhealthy");
        }
    }
}
