    virtual ~EventListener() = default;
};

class NetworkEventDispatcher {
private:
    struct ListenerInfo {
        std::shared_ptr<EventListener> listener;
        std::vector<NetworkEvent::Type> subscribedTypes;
    };

    std::vector<ListenerInfo> listeners;
    std::queue<NetworkEvent> eventQueue;
    std::mutex queueMutex;
    std::condition_variable queueCondVar;
    std::atomic<bool> running;
    int maxListeners;

public:
    NetworkEventDispatcher(int maxListeners) : maxListeners(maxListeners), running(false) {}

    void start() {
        running = true;
        for (int i = 0; i < std::min(maxListeners, 4); ++i) { // Example: Start with 1-4 threads
            std::thread([this]() {
                while (running) {
                    NetworkEvent event;
                    {
                        std::unique_lock<std::mutex> lock(queueMutex);
                        queueCondVar.wait(lock, [this] { return !eventQueue.empty() || !running; });
                        if (!running) break;
                        event = std::move(eventQueue.front());
                        eventQueue.pop();
                    }
                    dispatchEventToListeners(event);
                }
            }).detach();
        }
    }

    void stop() {
        running = false;
        queueCondVar.notify_all();
    }

    void subscribe(std::shared_ptr<EventListener> listener, const std::vector<NetworkEvent::Type>& types) {
        if (listeners.size() < maxListeners) {
            listeners.push_back({listener, types});
        } else {
            throw std::runtime_error("Too many listeners");
        }
    }

    void unsubscribe(const std::shared_ptr<EventListener>& listener) {
        listeners.erase(std::remove_if(listeners.begin(), listeners.end(),
                                       [listener](const ListenerInfo& li) { return li.listener == listener; }),
                       listeners.end());
    }

    void dispatchEventToListeners(const NetworkEvent& event) {
        for (const auto& li : listeners) {
            if (std::find(li.subscribedTypes.begin(), li.subscribedTypes.end(), event.type) != li.subscribedTypes.end()) {
                li.listener->onEvent(event);
            }
        }
    }

    void enqueueEvent(const NetworkEvent& event) {
        std::unique_lock<std::mutex> lock(queueMutex);
        eventQueue.push(event);
        queueCondVar.notify_one();
    }
};

class ExampleListener : public EventListener {
public:
    void onEvent(const NetworkEvent& event) override {
        std::cout << "Received event: " << event.type << " with data: " << event.data << std::endl;
    }
};

int main() {
    NetworkEventDispatcher dispatcher(2);
    dispatcher.start();

    auto listener1 = std::make_shared<ExampleListener>();
    auto listener2 = std::make_shared<ExampleListener>();

    dispatcher.subscribe(listener1, {NetworkEvent::Type::TYPE_A});
    dispatcher.subscribe(listener2, {NetworkEvent::Type::TYPE_B});

    dispatcher.enqueueEvent(NetworkEvent(NetworkEvent::Type::TYPE_A, "Data for Type A"));
    dispatcher.enqueueEvent(NetworkEvent(NetworkEvent::Type::TYPE_B, "Data for Type B"));

    std::this_thread::sleep_for(std::chrono::seconds(2));

    dispatcher.unsubscribe(listener1);
    dispatcher.stop();

    return 0;
}
```

This code provides a basic structure for the `NetworkEventDispatcher` class. It includes methods for starting and stopping the event processing, subscribing and unsubscribing listeners, enqueuing events, and dispatching events to listeners based on their subscription preferences. The main function demonstrates how to use this class with an example listener.']

